/* HK4 · Đọc-Viết 4 (thư mục học kì 4): bài khóa gốc, từ vựng, ngữ pháp theo ghi chép của bạn, kèm bài tập nâng cao. */
(function (C) {
  var hk4 = null; C.semesters.forEach(function (s) { if (s.id === 'hk4') hk4 = s; });
  hk4.locked = false; hk4.stage = 'Đại học năm 2 · kì 2'; hk4.age = 20; hk4.face = '🧑‍🎓';
  hk4.book = '汉语阅读教程 · Đọc-Viết 4';
  hk4.intro = 'Bài đọc học thuật dài: nhân vật lịch sử, văn hóa, xã hội, khoa học. Đọc hiểu đoạn văn, ngữ pháp văn viết (之所以……是因为、为……所……、即便……也……), thảo luận và viết câu.';
  hk4.lessons = [{"id": "hk4-l1", "no": 1, "day": "HK4 · Bài 1", "time": "09:00", "scene": "library", "room": "library", "cast": ["prof", "lee", "tianfang", "edward"], "vi": "Nhà hình học Trần Tỉnh Thân", "zh": "几何学家陈省身", "py": "Jǐhéxuéjiā chénshěngshēn", "shop": {"label": "数学书屋", "sub": "Hiệu sách toán", "icon": "📐"}, "vocab": [["出生", "chūshēng", "sinh ra", ""], ["书香世家", "shūxiāng shìjiā", "gia đình truyền thống hiếu học", ""], ["崭露头角", "zhǎnlù tóujiǎo", "bộc lộ tài năng", ""], ["规规矩矩", "guīguījǔjǔ", "khuôn phép, đúng mực", ""], ["老老实实", "lǎolǎoshishí", "thành thật, ngoan ngoãn", ""], ["分数", "fēnshù", "điểm số", ""], ["功课", "gōngkè", "môn học", ""], ["参考书", "cānkǎo shū", "sách tham khảo", ""], ["录取", "lùqǔ", "tuyển nhận", ""], ["攻读", "gōngdú", "học (lên cao)", ""], ["硕士学位", "shuòshì xuéwèi", "bằng thạc sĩ", ""], ["资助", "zīzhù", "tài trợ, cấp tiền", ""], ["选派", "xuǎnpài", "chọn cử, chọn phái", ""], ["对象", "duìxiàng", "đối tượng", ""], ["师从", "shīcóng", "theo học (ai)", ""], ["几何学家", "jǐhéxuéjiā", "nhà hình học", ""], ["弟子", "dìzǐ", "học trò", ""], ["论文", "lùnwén", "bài báo khoa học, luận văn", ""], ["漏洞", "lòudòng", "sơ hở, lỗ hổng", ""], ["又惊又喜", "yòu jīng yòu xǐ", "vừa ngạc nhiên vừa mừng", ""], ["大为欣赏", "dàwéi xīnshǎng", "rất quý trọng, rất hài lòng", ""], ["博士学位", "bóshì xuéwèi", "bằng tiến sĩ", ""], ["前往", "qiánwǎng", "đến, đi tới", ""], ["追随", "zhuīsuí", "theo đuổi, theo học", ""], ["终身受用", "zhōngshēn shòuyòng", "dùng cả đời, có ích suốt đời", ""], ["友谊", "yǒuyì", "tình bạn", ""], ["学术访问", "xuéshù fǎngwèn", "chuyến thăm học thuật", ""], ["出色", "chūsè", "xuất sắc", ""], ["发表", "fābiǎo", "công bố", ""], ["数学界", "shùxuéjiè", "giới toán học", ""], ["理论", "lǐlùn", "lý thuyết", ""], ["从事", "cóngshì", "làm (công việc)", ""], ["功成身退", "gōngchéng shēn tuì", "khi đã thành công thì rút lui", ""], ["为期", "wéiqī", "kéo dài (thời gian)", ""], ["国际", "guójì", "quốc tế", ""], ["研讨", "yántǎo", "thảo luận, nghiên cứu", ""], ["敬意", "jìngyì", "lòng kính trọng", ""], ["声誉", "shēngyù", "thanh danh, uy tín", ""], ["如日中天", "rú rì zhōng tiān", "như mặt trời giữa trưa (rất thịnh vượng)", ""], ["怀念", "huáiniàn", "nhớ, hoài niệm", ""]], "story": [{"c": "panda", "vi": "HK4 · Nhà hình học Trần Tỉnh Thân. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "lee", "zh": "1911年，陈省身出生于浙江的一个书香世家。中学时代，陈省身的数学天才已经崭露头角。他说：“我学习数学感到特别容易。我不是一个规规矩矩、老老实实念书的学生。我的数学分数总很好，其他功课平常非常。我喜欢去图书馆看书，什么书都是拿来就着。除了数学方面的书，我也喜欢看历史、文学等方面的书，时常一待就几个钟头。”他习惯自己主动地去看书学习，而不只是看老师指定的参考书。由于成绩特别好，他15岁时就被南开大学理学院录取。1930年，陈省身从南开大学毕业，被清华大学录取攻读硕士学位，清华大学校方每年都资助学习成绩好的学生出国留学，陈省身成为了选派对象。", "py": "1911 nián, Chén Xǐngshēn chūshēng yú Zhèjiāng de yīgè shūxiāng shìjiā. Zhōngxué shídài, Chén Xǐngshēn de shùxué tiāncái yǐjīng zhǎnlù tóujiǎo. Tā shuō: “Wǒ xuéxí shùxué gǎndào tèbié róngyì. Wǒ bùshì yīgè guīguījǔjǔ, lǎolǎoshishí niànshū de xuéshēng. Wǒ de shùxué fēnshù zǒng hěn hǎo, qítā gōngkè píngcháng fēicháng. Wǒ xǐhuān qù túshūguǎn kàn shū, shénme shū dōu shì nálái jiù zhe. Chúle shùxué fāngmiàn de shū, wǒ yě xǐhuān kàn lìshǐ, wénxué děng fāngmiàn de shū, shícháng yī dài jiù jǐ gè zhōngtóu.” Tā xíguàn zìjǐ zhǔdòng de qù kàn shū xuéxí, ér bù zhǐshì kàn lǎoshī zhǐdìng de cānkǎo shū. Yóuyú chéngjī tèbié hǎo, tā 15 suì shí jiù bèi Nánkāi Dàxué Lǐxuéyuàn lùqǔ. 1930 nián, Chén Xǐngshēn cóng Nánkāi Dàxué bìyè, bèi Qīnghuá Dàxué lùqǔ gōngdú shuòshì xuéwèi, Qīnghuá Dàxué xiàofāng měi nián dōu zīzhù xuéxí chéngjī hǎo de xuéshēng chūguó liúxué, Chén Xǐngshēn chéngwéi le xuǎnpài duìxiàng.", "vi": "Năm 1911, Trần Tỉnh Thân sinh ra tại Chiết Giang trong một gia đình gia thế hiếu học. Thời trung học, thiên tài toán học của ông đã bắt đầu bộc lộ. Ông nói: “Tôi học toán cảm thấy rất dễ dàng. Tôi không phải là một học sinh học hành câu nệ, khuôn phép. Điểm toán của tôi luôn rất tốt, các môn khác thì bình thường. Tôi thích đến thư viện đọc sách, sách gì tôi cũng cầm lên đọc. Ngoài sách toán, tôi cũng thích đọc sách lịch sử, văn học..., thường ngồi đó cả mấy giờ.” Ông có thói quen chủ động tự học, chứ không chỉ đọc sách tham khảo do giáo viên chỉ định. Vì thành tích đặc biệt tốt, ông được nhận vào Học viện Khoa học Tự nhiên của Đại học Nam Khai năm 15 tuổi. Năm 1930, ông tốt nghiệp Đại học Nam Khai, được nhận vào Đại học Thanh Hoa học thạc sĩ. Hàng năm, trường Thanh Hoa đều tài trợ cho sinh viên có thành tích tốt đi du học, và Trần Tỉnh Thân đã trở thành ứng viên được chọn."}, {"c": "prof", "zh": "中学时代陈省身是一个什么样的学生？", "py": "Zhōngxué shídài chénshěngshēn shì yíge shénmeyàng de xuéshēng?", "vi": "Thời trung học Trần Tỉnh Thân là học sinh thế nào?"}, {"me": "Giỏi toán, thích tự đọc sách, không chỉ đọc sách thầy chỉ định.", "opts": [["数学特别好，喜欢自己主动看书，不只看老师指定的参考书。", "Shùxué tèbié hǎo, xǐhuan zìjǐ zhǔdòng kànshū, bù zhǐ kàn lǎoshī zhǐdìng de cānkǎoshū.", "Giỏi toán, thích tự đọc sách, không chỉ đọc sách thầy chỉ định."], ["每门功课都非常好，从不去图书馆。", "Měimén gōngkè dōu fēicháng hǎo, cóngbú qù túshūguǎn.", "(chưa đúng với bài)"], ["只看老师指定的参考书。", "Zhǐ kàn lǎoshī zhǐdìng de cānkǎoshū.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "1934年9月，陈省身到达汉堡。在那里，陈省身师从德国几何学家布拉施克。布拉施克第一次见到自己的中国弟子，就给了他一大叠自己最新的论文。但这位德国老师怎么也没想到，一个来自中国的青年学生，一下子就发现了其中一篇论文中的漏洞。布拉施克感到又惊又喜，对陈省身大为欣赏。在德国不到一年半，陈省身就拿到了博士学位。1936年，陈省身前往法国巴黎大学，追随几何学家嘉当进行研究。在10个月的研究过程中，陈省身学到的东西使他终身受用，他与嘉当也结下了终生的友谊。", "py": "1934 nián 9 yuè, Chén Xǐngshēn dàodá Hànbǎo. Zài nàli, Chén Xǐngshēn shīcóng Déguó jǐhéxuéjiā Bùlāshīkè. Bùlāshīkè dì yī cì jiàndào zìjǐ de Zhōngguó dìzǐ, jiù gěile tā yī dàdié zìjǐ zuìxīn de lùnwén. Dàn zhè wèi Déguó lǎoshī zěnme yě méi xiǎngdào, yīgè láizì Zhōngguó de qīngnián xuéshēng, yīxiàzi jiù fāxiànle qízhōng yī piān lùnwén zhōng de lòudòng. Bùlāshīkè gǎndào yòu jīng yòu xǐ, duì Chén Xǐngshēn dàwéi xīnshǎng. Zài Déguó bù dào yī nián bàn, Chén Xǐngshēn jiù nádàole bóshì xuéwèi. 1936 nián, Chén Xǐngshēn qiánwǎng Fǎguó Bālí Dàxué, zhuīsuí jǐhéxuéjiā Jiādāng jìnxíng yánjiū. Zài 10 gè yuè de yánjiū guòchéng zhōng, Chén Xǐngshēn xué dào de dōngxi shǐ tā zhōngshēn shòuyòng, tā yǔ Jiādāng yě jiéxiàle zhōngshēng de yǒuyì.", "vi": "Tháng 9 năm 1934, Trần Tỉnh Thân đến Hamburg. Tại đó, ông theo học nhà hình học người Đức Blaschke. Lần đầu gặp người học trò Trung Quốc của mình, Blaschke đã đưa cho ông một tập dày các bài báo mới nhất của mình. Nhưng vị giáo sư Đức này không ngờ rằng, một sinh viên trẻ đến từ Trung Quốc lại ngay lập tức phát hiện ra một lỗ hổng trong một bài báo. Blaschke vừa ngạc nhiên vừa mừng rỡ, rất quý trọng Trần Tỉnh Thân. Chưa đầy một năm rưỡi ở Đức, ông đã lấy được bằng tiến sĩ. Năm 1936, ông sang Đại học Paris, theo học nhà hình học Cartan nghiên cứu. Trong 10 tháng nghiên cứu, những gì ông học được đã giúp ích cho ông suốt đời, và ông cũng kết thân với Cartan."}, {"c": "prof", "zh": "陈省身第一次见德国老师时发生了什么？", "py": "Chénshěngshēn dìyīcì jiàn déguó lǎoshī shí fāshēng le shénme?", "vi": "Lần đầu gặp thầy người Đức đã xảy ra chuyện gì?"}, {"me": "Ông lập tức phát hiện lỗ hổng trong một bài luận của thầy.", "opts": [["他一下子就发现了老师一篇论文中的漏洞。", "Tā yíxiàzi jiù fāxiàn le lǎoshī yìpiān lùnwén zhōng de lòudòng.", "Ông lập tức phát hiện lỗ hổng trong một bài luận của thầy."], ["老师让他回国学习。", "Lǎoshī ràng tā huíguó xuéxí.", "(chưa đúng với bài)"], ["他把老师的论文都弄丢了。", "Tā bǎ lǎoshī de lùnwén dōu nòng diū le.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "1943年，陈省身受美国普林斯顿大学数学研究所的邀请，到那里作学术访问。在那里，他完成了一生中最出色的工作，发表了数篇在数学界有重大影响的论文，其中包括现在被称为“陈类”的理论。1960年，陈省身前住美国加州大学伯克利分校从事教学研究，一直到退休。当陈省身68岁功成身退的时候，加州大学为他举行了为期5天的国际几何学会议。300多位数学家在伯克利校园聚会，共同研讨数学问题，也表示对陈先生的敬意。", "py": "1943 nián, Chén Xǐngshēn shòu Měiguó Pǔlǐnsītùn Dàxué Shùxué Yánjiūsuǒ de yāoqǐng, dào nàli zuò xuéshù fǎngwèn. Zài nàli, tā wánchéngle yīshēng zhōng zuì chūsè de gōngzuò, fābiǎole shù piān zài shùxuéjiè yǒu zhòngdà yǐngxiǎng de lùnwén, qízhōng bāokuò xiànzài bèi chēng wéi “Chén lèi” de lǐlùn. 1960 nián, Chén Xǐngshēn qiánwǎng Měiguó Jiāzhōu Dàxué Bókèlì fēnxiào cóngshì jiàoxué yánjiū, yīzhí dào tuìxiū. Dāng Chén Xǐngshēn 68 suì gōngchéng shēn tuì de shíhòu, Jiāzhōu Dàxué wèi tā jǔxíngle wéiqī 5 tiān de guójì jǐhéxué huìyì. 300 duō wèi shùxuéjiā zài Bókèlì xiàoyuán jùhuì, gòngtóng yántǎo shùxué wèntí, yě biǎoshì duì Chén xiānshēng de jìngyì.", "vi": "Năm 1943, Trần Tỉnh Thân được Viện Nghiên cứu Toán học Đại học Princeton mời đến thăm và nghiên cứu. Tại đó, ông hoàn thành công trình xuất sắc nhất đời mình, công bố nhiều bài báo có ảnh hưởng lớn trong giới toán học, trong đó có lý thuyết ngày nay được gọi là “lớp Trần” (Chen class). Năm 1960, ông đến Đại học California tại Berkeley giảng dạy và nghiên cứu cho đến khi nghỉ hưu. Năm 68 tuổi, khi ông rời vị trí, Đại học California đã tổ chức một hội nghị hình học quốc tế kéo dài 5 ngày. Hơn 300 nhà toán học tụ họp tại khuôn viên Berkeley, cùng thảo luận các vấn đề toán học và bày tỏ lòng kính trọng với ông."}, {"c": "prof", "zh": "陈省身退休时，加州大学怎样表达敬意？", "py": "Chénshěngshēn tuìxiū shí, jiāzhōudàxué zěnyàng biǎodá jìngyì?", "vi": "Khi ông nghỉ hưu, ĐH California bày tỏ lòng kính trọng thế nào?"}, {"me": "Tổ chức hội nghị hình học quốc tế kéo dài 5 ngày.", "opts": [["举行了为期5天的国际几何学会议。", "Jǔxíng le wéiqī5 tiān de guójì jǐhéxué huìyì.", "Tổ chức hội nghị hình học quốc tế kéo dài 5 ngày."], ["送给他一辆汽车。", "Sònggěi tā yíliàng qìchē.", "(chưa đúng với bài)"], ["请他再工作十年。", "Qǐng tā zài gōngzuò shínián.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "陈省身在国际上的学术声誉如日中天，但他十分怀念祖国。1972年，陈省身带着夫人与孩子回到离别24年的祖国。此后的30多年，他数十次回到中国，并利用自己在国际数学界的广泛影响，不断加强中国和国际数学界的交流。当今世界数学界，由以色列沃尔夫基金会颁发的沃尔夫奖举世瞩目。1983年，陈省身先生荣获沃尔夫奖，成为唯一获得世界数学界最高荣誉“沃尔夫奖”的华人。", "py": "Chén Xǐngshēn zài guójì shàng de xuéshù shēngyù rú rì zhōng tiān, dàn tā shífēn huáiniàn zǔguó. 1972 nián, Chén Xǐngshēn dàizhe fūren yǔ háizi huí dào líbié 24 nián de zǔguó. Cǐhòu de 30 duō nián, tā shùshí cì huí dào Zhōngguó, bìng lìyòng zìjǐ zài guójì shùxuéjiè de guǎngfàn yǐngxiǎng, bùduàn jiāqiáng Zhōngguó hé guójì shùxuéjiè de jiāoliú. Dāngjīn shìjiè shùxuéjiè, yóu Yǐsèliè Wò'ěrfú Jījīnhuì bānfā de Wò'ěrfú jiǎng jǔshì zhǔmù. 1983 nián, Chén Xǐngshēn xiānshēng róng huò Wò'ěrfú jiǎng, chéngwéi wéiyī huòdé shìjiè shùxuéjiè zuìgāo róngyù “Wò'ěrfú jiǎng” de Huárén.", "vi": "Danh tiếng học thuật của Trần Tỉnh Thân trên trường quốc tế đang lên như mặt trời giữa trưa, nhưng ông rất nhớ quê hương. Năm 1972, ông cùng vợ và con trở về tổ quốc sau 24 năm xa cách. Trong hơn 30 năm sau đó, ông đã về Trung Quốc hàng chục lần, và tận dụng ảnh hưởng rộng lớn của mình trong giới toán học quốc tế để không ngừng tăng cường giao lưu giữa Trung Quốc và thế giới. Trong giới toán học thế giới hiện nay, giải Wolf do Quỹ Wolf của Israel trao tặng rất được chú ý. Năm 1983, ông được trao giải Wolf, trở thành người Hoa duy nhất đạt được vinh dự cao nhất của giới toán học thế giới."}, {"c": "prof", "zh": "1983年陈省身获得了什么荣誉？", "py": "1983 nián chénshěngshēn huòdé le shénme róngyù?", "vi": "Năm 1983 ông nhận vinh dự gì?"}, {"me": "Giải Wolf, ông là người Hoa duy nhất nhận giải này.", "opts": [["沃尔夫奖，他是唯一获得这个奖的华人。", "Wòěrfū jiǎng, tā shì wéiyí huòdé zhège jiǎng de huárén.", "Giải Wolf, ông là người Hoa duy nhất nhận giải này."], ["诺贝尔奖。", "Nuòbèiěrjiǎng.", "(chưa đúng với bài)"], ["美国数学界的一个小奖。", "Měiguó shùxuéjiè de yíge xiǎojiǎng.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "2004年10月28日，陈省身度过了他的93岁寿辰。第二天，他来到南开数学研究所，作了一场学术报告，没想到仅一个月之后，这位国际数学大师就悄然离开了这个世界。人的生命是有限的，但陈省身对数学领域的深远影响却是永存的。", "py": "2004 nián 10 yuè 28 rì, Chén Xǐngshēn dùguòle tā de 93 suì shòuchén. Dì èr tiān, tā lái dào Nánkāi Shùxué Yánjiūsuǒ, zuòle yī chǎng xuéshù bàogào, méi xiǎngdào jǐn yīgè yuè zhīhòu, zhè wèi guójì shùxué dàshī jiù qiǎorán líkāile zhège shìjiè. Rén de shēngmìng shì yǒuxiàn de, dàn Chén Xǐngshēn duì shùxué lǐngyù de shēnyuǎn yǐngxiǎng què shì yǒngcún de.", "vi": "Ngày 28 tháng 10 năm 2004, ông tròn 93 tuổi. Hôm sau, ông đến Viện Nghiên cứu Toán học Nam Khai và trình bày một báo cáo học thuật. Không ngờ chỉ một tháng sau, vị đại sư toán học quốc tế này đã lặng lẽ rời xa thế giới. Sự sống của con người là hữu hạn, nhưng ảnh hưởng sâu xa của Trần Tỉnh Thân đối với lĩnh vực toán học thì còn mãi."}, {"c": "prof", "zh": "陈省身去世前一个月做了什么？", "py": "Chénshěngshēn qùshì qián yígeyuè zuò le shénme?", "vi": "Một tháng trước khi mất, ông đã làm gì?"}, {"me": "Thuyết trình học thuật tại Viện Toán Nam Khai.", "opts": [["在南开数学研究所作了一场学术报告。", "Zài nán kāi shù xué yán jiū suǒ zuò le yìcháng xuéshùbàogào.", "Thuyết trình học thuật tại Viện Toán Nam Khai."], ["去法国旅游。", "Qù fǎguólǚyóu.", "(chưa đúng với bài)"], ["停止了所有研究。", "Tíngzhǐ le suǒyǒu yánjiū.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“被” (bị/được)", "d": "Chủ ngữ + 被 + tác nhân + động từ", "ex": [["他被南开大学录取。", "Tā bèi nánkāidàxué lùqǔ.", "Anh ấy được Đại học Nam Khai nhận."]]}, {"t": "“把” (đưa/lấy)", "d": "Chủ ngữ + 把 + tân ngữ + động từ", "ex": [["他把书放在桌子上。", "Tā bǎ shū fàngzài zhuōzi shàng.", "Anh ấy đặt sách lên bàn."]]}, {"t": "“除了...还/也...” (ngoài... còn...)", "d": "除了 A，还/也 B = Ngoài A ra, còn B", "ex": [["除了数学，我也喜欢历史。", "Chúle shùxué, wǒ yě xǐhuan lìshǐ.", "Ngoài toán, tôi cũng thích lịch sử."]]}, {"t": "“对... (感到/表示)...” (đối với...)", "d": "对 + danh từ/đại từ + biểu thị cảm xúc/hành động", "ex": [["我对这件事很感兴趣。", "Wǒ duì zhèjiàn shì hěngǎnxìngqù.", "Tôi rất hứng thú với việc này."]]}, {"t": "“不仅...也/还...” (không những... mà còn...)", "d": "", "ex": [["他不仅聪明，也很努力。", "Tā bùjǐn cōngmíng, yě hěn nǔlì.", "Anh ấy không những thông minh mà còn rất chăm chỉ."]]}, {"t": "“...之一” (một trong những...)", "d": "", "ex": [["他是中国最著名的数学家之一。", "Tā shì zhōngguó zuì zhùmíng de shùxuéjiā zhīyī.", "Ông ấy là một trong những nhà toán học nổi tiếng nhất Trung Quốc."]]}, {"t": "“当...的时候” (khi...)", "d": "当 + mệnh đề + 的时候 = Khi...", "ex": [["当陈省身68岁的时候，他退休了。", "Dāng chénshěngshēn68 suì de shíhou, tā tuìxiū le.", "Khi Trần Tỉnh Thân 68 tuổi, ông nghỉ hưu."]]}, {"t": "“由...颁发” (do... trao tặng)", "d": "由 + tổ chức/cá nhân + 颁发 = do... trao tặng", "ex": [["该奖项由政府颁发。", "Gāi jiǎngxiàng yóu zhèngfǔ bānfā.", "Giải thưởng này do chính phủ trao tặng."]]}], "order": [], "u": {"gq": [{"s": "被 + tác nhân + V", "d": "Câu bị động: chủ ngữ là người chịu tác động.", "ok": "他15岁时就被南开大学理学院录取。", "vi": "Năm 15 tuổi ông đã được Học viện Khoa học ĐH Nam Khai nhận.", "bad": ["他15岁时就南开大学被理学院录取。", "他15岁时就被录取南开大学理学院。"]}, {"s": "除了……也……", "d": "Ngoài… ra, cũng… (bổ sung).", "ok": "除了数学方面的书，我也喜欢看历史、文学等方面的书。", "vi": "Ngoài sách toán, tôi cũng thích đọc sách lịch sử, văn học.", "bad": ["除了数学方面的书，我就喜欢看历史、文学等方面的书。", "我也除了数学方面的书，喜欢看历史、文学的书。"]}, {"s": "当……的时候", "d": "Khi… (mốc thời gian, văn viết).", "ok": "当陈省身68岁功成身退的时候，加州大学为他举行了国际会议。", "vi": "Khi ông 68 tuổi công thành thân thoái, ĐH California tổ chức hội nghị quốc tế cho ông.", "bad": ["当陈省身68岁功成身退，的时候加州大学为他举行了国际会议。", "陈省身当68岁的时候功成身退时，加州大学举行了国际会议。"]}, {"s": "由……颁发", "d": "Do… trao tặng.", "ok": "沃尔夫奖由以色列沃尔夫基金会颁发。", "vi": "Giải Wolf do Quỹ Wolf Israel trao tặng.", "bad": ["沃尔夫奖颁发由以色列沃尔夫基金会。", "沃尔夫奖由以色列沃尔夫基金会被颁发。"]}, {"s": "……之一", "d": "Một trong những….", "ok": "他是世界上最著名的数学家之一。", "vi": "Ông là một trong những nhà toán học nổi tiếng nhất thế giới.", "bad": ["他是之一世界上最著名的数学家。", "他是世界上最著名的之一数学家。"]}], "disc": [{"q": "陈省身的成功给你什么启发？", "py": "Chénshěngshēn de chénggōng gěi nǐ shénme qǐfā?", "vi": "Thành công của Trần Tỉnh Thân gợi cho bạn điều gì?", "keys": ["除了……也|除了……还", "由于|因为", "不仅……也|不仅……还|不仅……而且"], "sample": "陈省身的成功告诉我，学习要主动。除了老师指定的书，我们也应该自己多看书。由于他对数学有兴趣，所以他不仅学得好，还能发现别人的问题。", "spy": "Chénshěngshēn de chénggōng gàosu wǒ, xuéxí yào zhǔdòng. Chúle lǎoshī zhǐdìng de shū, wǒmen yě yīnggāi zìjǐ duō kànshū. Yóuyú tā duì shùxué yǒu xìngqù, suǒyǐ tā bùjǐn xuédé hǎo, hái néng fāxiàn biérén de wèntí."}], "comp": [{"vi": "Ngoài tiếng Trung, tôi cũng thích học lịch sử. (除了……也……)", "keys": ["除了", "也|还"], "model": "除了汉语，我也喜欢学历史。", "mpy": "Chúle hànyǔ, wǒ yě xǐhuan xué lìshǐ."}, {"vi": "Cô ấy được Đại học Bắc Kinh nhận vào học. (被)", "keys": ["被", "录取"], "model": "她被北京大学录取了。", "mpy": "Tā bèi běijīngdàxué lùqǔ le."}, {"vi": "Khi tôi 18 tuổi, tôi lần đầu đi du học. (当……的时候)", "keys": ["当", "的时候"], "model": "当我18岁的时候，我第一次出国留学。", "mpy": "Dāng wǒ18 suì de shíhou, wǒ dìyīcì chūguó liúxué."}], "ex": [{"q": "中学时代陈省身是一个什么样的学生？", "qvi": "Thời trung học Trần Tỉnh Thân là học sinh thế nào?", "a": "数学特别好，喜欢自己主动看书，不只看老师指定的参考书。", "avi": "Giỏi toán, thích tự đọc sách, không chỉ đọc sách thầy chỉ định.", "bad": ["每门功课都非常好，从不去图书馆。", "只看老师指定的参考书。"], "p": 0}, {"q": "陈省身第一次见德国老师时发生了什么？", "qvi": "Lần đầu gặp thầy người Đức đã xảy ra chuyện gì?", "a": "他一下子就发现了老师一篇论文中的漏洞。", "avi": "Ông lập tức phát hiện lỗ hổng trong một bài luận của thầy.", "bad": ["老师让他回国学习。", "他把老师的论文都弄丢了。"], "p": 1}, {"q": "陈省身退休时，加州大学怎样表达敬意？", "qvi": "Khi ông nghỉ hưu, ĐH California bày tỏ lòng kính trọng thế nào?", "a": "举行了为期5天的国际几何学会议。", "avi": "Tổ chức hội nghị hình học quốc tế kéo dài 5 ngày.", "bad": ["送给他一辆汽车。", "请他再工作十年。"], "p": 2}, {"q": "1983年陈省身获得了什么荣誉？", "qvi": "Năm 1983 ông nhận vinh dự gì?", "a": "沃尔夫奖，他是唯一获得这个奖的华人。", "avi": "Giải Wolf, ông là người Hoa duy nhất nhận giải này.", "bad": ["诺贝尔奖。", "美国数学界的一个小奖。"], "p": 3}, {"q": "陈省身去世前一个月做了什么？", "qvi": "Một tháng trước khi mất, ông đã làm gì?", "a": "在南开数学研究所作了一场学术报告。", "avi": "Thuyết trình học thuật tại Viện Toán Nam Khai.", "bad": ["去法国旅游。", "停止了所有研究。"], "p": 4}]}}, {"id": "hk4-l2", "no": 2, "day": "HK4 · Bài 2", "time": "10:30", "scene": "office", "room": "office", "cast": ["prof", "zhangdong", "roland", "lee"], "vi": "Họ của người Trung Quốc", "zh": "中国人的姓", "py": "Zhōngguó rén de xìng", "shop": {"label": "刻章店", "sub": "Tiệm khắc dấu", "icon": "🏮"}, "vocab": [["三皇五帝", "Sān Huáng Wǔ Dì", "Tam Hoàng Ngũ Đế", ""], ["距今", "jù jīn", "cách nay", ""], ["母系社会", "mǔxì shèhuì", "xã hội mẫu hệ", ""], ["组成", "zǔchéng", "cấu thành", ""], ["说明", "shuōmíng", "chứng tỏ, nói rõ", ""], ["居住", "jūzhù", "cư trú", ""], ["部族", "bùzú", "bộ lạc", ""], ["君主", "jūnzhǔ", "quân chủ, vua", ""], ["封", "fēng", "phong (đất)", ""], ["赐", "cì", "ban cho", ""], ["爵位", "juéwèi", "tước vị", ""], ["官职", "guānzhí", "chức quan", ""], ["贵族", "guìzú", "quý tộc", ""], ["平民", "píngmín", "bình dân", ""], ["通婚", "tōnghūn", "kết hôn (giao hôn)", ""], ["官员", "guānyuán", "quan lại, viên chức", ""], ["记录", "jìlù", "ghi chép", ""], ["旧时", "jiùshí", "thời xưa", ""], ["流行", "liúxíng", "thịnh hành, phổ biến", ""], ["收集", "shōují", "thu thập", ""], ["单姓", "dānxìng", "họ đơn (một chữ)", ""], ["复姓", "fùxìng", "họ kép (hai chữ)", ""], ["实际", "shíjì", "thực tế", ""], ["应用", "yìngyòng", "ứng dụng, sử dụng", ""], ["说法", "shuōfǎ", "cách nói, thuyết", ""], ["历史悠久", "lìshǐ yōujiǔ", "lịch sử lâu đời", ""], ["分布", "fēnbù", "phân bố", ""], ["广泛", "guǎngfàn", "rộng rãi", ""], ["皇帝", "huángdì", "hoàng đế", ""], ["统计", "tǒngjì", "thống kê", ""], ["恐怕", "kǒngpà", "e rằng, sợ rằng", ""], ["史学家", "shǐxuéjiā", "nhà sử học", ""], ["发表", "fābiǎo", "công bố, đăng", ""], ["杂志", "zázhì", "tạp chí", ""], ["论文", "lùnwén", "bài luận, luận văn", ""], ["指出", "zhǐchū", "chỉ ra", ""], ["人口", "rénkǒu", "dân số", ""], ["占", "zhàn", "chiếm (tỷ lệ)", ""], ["约", "yuē", "khoảng", ""], ["以上", "yǐshàng", "trở lên", ""]], "story": [{"c": "panda", "vi": "HK4 · Họ của người Trung Quốc. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "zhangdong", "zh": "中国人在三皇五帝以前（距今约五千年）就有了姓。那时是母系社会，人们只知有母，不知有父，所以“姓”是“女”和“生”组成，这说明最早的姓，是跟母亲的姓。夏、商、周的时候，人们有姓也有氏。“姓”是从居住的村子或者所属的部族名称而来。“氏”是从君主所封的地、所赐的爵位、所任的官职而来。所以贵族有姓、有名也有氏；平民有姓，有名，没有氏。同氏的男女可以通婚，同姓的男女却不可以通婚。", "py": "Zhōngguó rén zài Sān Huáng Wǔ Dì yǐqián (jù jīn yuē wǔqiān nián) jiù yǒule xìng. Nà shí shì mǔxì shèhuì, rénmen zhǐ zhī yǒu mǔ, bù zhī yǒu fù, suǒyǐ “xìng” shì “nǚ” hé “shēng” zǔchéng, zhè shuōmíng zuìzǎo de xìng, shì gēn mǔqīn de xìng. Xià, Shāng, Zhōu de shíhou, rénmen yǒu xìng yě yǒu shì. “Xìng” shì cóng jūzhù de cūnzi huòzhě suǒshǔ de bùzú míngchēng ér lái. “Shì” shì cóng jūnzhǔ suǒ fēng de dì, suǒ cì de juéwèi, suǒ rèn de guānzhí ér lái. Suǒyǐ guìzú yǒu xìng, yǒu míng yě yǒu shì; píngmín yǒu xìng, yǒu míng, méiyǒu shì. Tóng shì de nánnǚ kěyǐ tōnghūn, tóng xìng de nánnǚ què bù kěyǐ tōnghūn.", "vi": "Người Trung Quốc đã có họ từ thời Tam Hoàng Ngũ Đế (cách nay khoảng 5.000 năm). Lúc đó là xã hội mẫu hệ, người ta chỉ biết có mẹ, không biết có cha, vì vậy chữ “họ” (姓) được cấu tạo từ chữ “nữ” (女) và “sinh” (生), điều này cho thấy họ sớm nhất là theo họ mẹ. Vào thời Hạ, Thương, Chu, người ta có cả họ (xìng) và thị (shì). “Họ” (xìng) bắt nguồn từ tên làng nơi cư trú hoặc bộ lạc thuộc về. “Thị” (氏) bắt nguồn từ đất được vua phong, tước vị được ban, hoặc chức quan được giao. Vì thế quý tộc có họ, có tên và có thị; bình dân có họ, có tên nhưng không có thị. Nam nữ cùng thị có thể kết hôn, nhưng nam nữ cùng họ thì không được kết hôn."}, {"c": "prof", "zh": "为什么“姓”字由“女”和“生”组成？", "py": "Wèishénme “Xìng” zì yóu “Nǚ” hé “Shēng” zǔchéng?", "vi": "Vì sao chữ 姓 do 女 và 生 tạo thành?"}, {"me": "Vì khi ấy là xã hội mẫu hệ, họ sớm nhất theo họ mẹ.", "opts": [["因为那时是母系社会，最早的姓跟母亲的姓。", "Yīnwèi nàshí shì mǔxìshèhuì, zuìzǎo de xìng gēn mǔqīn de xìng.", "Vì khi ấy là xã hội mẫu hệ, họ sớm nhất theo họ mẹ."], ["因为女人比男人多。", "Yīnwèi nǚrén bǐ nánrén duō.", "(chưa đúng với bài)"], ["因为皇帝喜欢这个字。", "Yīnwèi huángdì xǐhuan zhège zì.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "古代贵族和平民有什么不同？", "py": "Gǔdài guìzú hé píngmín yǒu shénme bùtóng?", "vi": "Quý tộc và bình dân thời xưa khác nhau thế nào?"}, {"me": "Quý tộc có họ, tên và thị; bình dân không có thị.", "opts": [["贵族有姓、有名也有氏，平民没有氏。", "Guìzú yǒuxìng, yǒumíng yě yǒu shì, píngmín méiyǒu shì.", "Quý tộc có họ, tên và thị; bình dân không có thị."], ["平民没有姓。", "Píngmín méiyǒu xìng.", "(chưa đúng với bài)"], ["贵族没有名。", "Guìzú méiyǒu míng.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "唐太宗的时候——公元627年，有个叫高士廉的官员，把民间的“姓”记录下来，写成一本书叫《氏族志》。中国旧时流行的《百家姓》是北宋（公元960年）的时候写的，里面一共收集了单姓408个，复姓30个，一共438个。姓发展到后来，据说有4000到6000个，但是实际应用的，只有1000个左右。", "py": "Táng Tàizōng de shíhou — gōngyuán 627 nián, yǒu gè jiào Gāo Shìlián de guānyuán, bǎ mínjiān de “xìng” jìlù xiàlái, xiě chéng yī běn shū jiào 《Shìzú Zhì》. Zhōngguó jiùshí liúxíng de 《Bǎijiā Xìng》 shì Běi Sòng (gōngyuán 960 nián) de shíhou xiě de, lǐmiàn yīgòng shōujíle dānxìng 408 gè, fùxìng 30 gè, yīgòng 438 gè. Xìng fāzhǎn dào hòulái, jùshuō yǒu 4000 dào 6000 gè, dànshì shíjì yìngyòng de, zhǐyǒu 1000 gè zuǒyòu.", "vi": "Dưới thời Đường Thái Tông – năm 627, có một viên quan tên là Cao Sĩ Liêm đã ghi chép lại các “họ” trong dân gian và viết thành một cuốn sách gọi là 《Thị tộc chí》. Cuốn 《Bách gia tính》 (Trăm họ) thịnh hành ở Trung Quốc xưa được viết vào thời Bắc Tống (năm 960), trong đó thu thập tổng cộng 408 họ đơn, 30 họ kép, tổng cộng 438 họ. Về sau, theo truyền thuyết có khoảng 4000 đến 6000 họ, nhưng trên thực tế được sử dụng chỉ khoảng 1000 họ."}, {"c": "prof", "zh": "《百家姓》一共收集了多少个姓？", "py": "«Bǎijiāxìng» yígòng shōují le duōshao ge xìng?", "vi": "《百家姓》 thu thập tổng cộng bao nhiêu họ?"}, {"me": "438 họ: 408 họ đơn, 30 họ kép.", "opts": [["438个：单姓408个，复姓30个。", "438 ge: Shànxìng408 ge, fùxìng30 ge.", "438 họ: 408 họ đơn, 30 họ kép."], ["100个。", "100 ge.", "(chưa đúng với bài)"], ["6000个。", "6000 ge.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "世界各国都有“三大姓”的说法，如，美国是：Smith，Johnson，Carson；法国是：Martin，Bernard，Dupont；中国呢？有张、王、李、赵，四个大姓。这四个大姓历史悠久，分布广泛，而且古代都是皇帝赐姓。根据最新统计，单是姓张的，就有一亿人，这恐怕是世界上最大的姓了吧。1977年，史学家李栋明在《东方杂志》上发表过一篇有关“姓”的论文，文中指出：", "py": "Shìjiè gèguó dōu yǒu “sān dà xìng” de shuōfǎ, rú, Měiguó shì: Smith, Johnson, Carson; Fǎguó shì: Martin, Bernard, Dupont; Zhōngguó ne? Yǒu Zhāng, Wáng, Lǐ, Zhào, sì gè dà xìng. Zhè sì gè dà xìng lìshǐ yōujiǔ, fēnbù guǎngfàn, érqiě gǔdài dōu shì huángdì cì xìng. Gēnjù zuìxīn tǒngjì, dān shì xìng Zhāng de, jiù yǒu yī yì rén, zhè kǒngpà shì shìjiè shàng zuì dà de xìng le ba. 1977 nián, shǐxuéjiā Lǐ Dōngmíng zài 《Dōngfāng Zázhì》 shàng fābiǎoguo yī piān yǒuguān “xìng” de lùnwén, wén zhōng zhǐchū:", "vi": "Các nước trên thế giới đều có thuyết “ba họ lớn”, ví dụ: Mỹ là Smith, Johnson, Carson; Pháp là Martin, Bernard, Dupont; còn Trung Quốc thì có bốn họ lớn là Trương, Vương, Lý, Triệu. Bốn họ lớn này có lịch sử lâu đời, phân bố rộng rãi, và thời xưa đều do hoàng đế ban họ. Theo thống kê mới nhất, riêng họ Trương đã có một trăm triệu người, e rằng đây là họ lớn nhất thế giới. Năm 1977, nhà sử học Lý Đống Minh đã đăng trên tạp chí Phương Đông một bài luận về “họ”, trong đó chỉ ra:"}, {"c": "prof", "zh": "中国的四大姓是哪几个？", "py": "Zhōngguó de sìdà xìng shì nǎjǐge?", "vi": "Bốn họ lớn của Trung Quốc là những họ nào?"}, {"me": "Trương, Vương, Lý, Triệu.", "opts": [["张、王、李、赵。", "Zhāng, wáng, lǐ, zhào.", "Trương, Vương, Lý, Triệu."], ["陈、杨、吴、刘。", "Chén, yáng, wú, liú.", "(chưa đúng với bài)"], ["徐、朱、林、孙。", "Xú, zhū, lín, sūn.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "华人最大的十个姓是：张、王、李、赵、陈、杨、吴、刘、黄、周，这十个姓占华人人口的40%，约四亿人。第二大的十个姓是：徐、朱、林、孙、马、高、胡、郑、郭、萧，占华人人口的10%以上。第三大的十个姓是：谢、何、许、宋、沈、罗、韩、邓、梁、叶，占华人人口的10%。接下来的15个大姓是：方、崔、程、潘、曹、冯、汪、蔡、袁、卢、唐、钱、杜、彭、陆，加起来也占华人人口的10%。换句话说，在中国十多亿人口中，有七亿人的姓是这45个大姓。", "py": "Huárén zuì dà de shí gè xìng shì: Zhāng, Wáng, Lǐ, Zhào, Chén, Yáng, Wú, Liú, Huáng, Zhōu, zhè shí gè xìng zhàn Huárén rénkǒu de 40%, yuē sì yì rén. Dì èr dà de shí gè xìng shì: Xú, Zhū, Lín, Sūn, Mǎ, Gāo, Hú, Zhèng, Guō, Xiāo, zhàn Huárén rénkǒu de 10% yǐshàng. Dì sān dà de shí gè xìng shì: Xiè, Hé, Xǔ, Sòng, Shěn, Luó, Hán, Dèng, Liáng, Yè, zhàn Huárén rénkǒu de 10%. Jiē xiàlái de 15 gè dà xìng shì: Fāng, Cuī, Chéng, Pān, Cáo, Féng, Wāng, Cài, Yuán, Lú, Táng, Qián, Dù, Péng, Lù, jiā qǐlái yě zhàn Huárén rénkǒu de 10%. Huàn jù huà shuō, zài Zhōngguó shí duō yì rénkǒu zhōng, yǒu qī yì rén de xìng shì zhè 45 gè dà xìng.", "vi": "Mười họ lớn nhất của người Hoa là: Trương, Vương, Lý, Triệu, Trần, Dương, Ngô, Lưu, Hoàng, Châu, mười họ này chiếm 40% dân số người Hoa, khoảng 400 triệu người. Mười họ lớn thứ hai là: Từ, Chu, Lâm, Tôn, Mã, Cao, Hồ, Trịnh, Quách, Tiêu, chiếm hơn 10% dân số người Hoa. Mười họ lớn thứ ba là: Tạ, Hà, Hứa, Tống, Thẩm, La, Hàn, Đặng, Lương, Diệp, chiếm 10% dân số người Hoa. 15 họ lớn tiếp theo là: Phương, Thôi, Trình, Phan, Tào, Phùng, Uông, Thái, Viên, Lư, Đường, Tiền, Đỗ, Bành, Lục, cộng lại cũng chiếm 10% dân số người Hoa. Nói cách khác, trong hơn một tỷ dân Trung Quốc, có 700 triệu người mang 45 họ lớn này."}, {"c": "prof", "zh": "45个大姓占中国人口的多少？", "py": "45 ge dàxìng zhàn zhōngguó rénkǒu de duōshao?", "vi": "45 họ lớn chiếm bao nhiêu dân số Trung Quốc?"}, {"me": "Khoảng 700 triệu trong hơn một tỷ người.", "opts": [["十多亿人口中，有七亿人。", "Shíduōyì rénkǒu zhōng, yǒu qīyìrén.", "Khoảng 700 triệu trong hơn một tỷ người."], ["一亿人。", "Yíyìrén.", "(chưa đúng với bài)"], ["四亿人。", "Sìyìrén.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“从...而来” (từ... mà đến/bắt nguồn từ)", "d": "从 + danh từ + 而来 = bắt nguồn từ", "ex": [["“姓”是从居住的村子而来。", "“Xìng” shìcóng jūzhù de cūnzi ér lái.", "Họ bắt nguồn từ làng nơi cư trú."]]}, {"t": "“所 + động từ” (làm cho động từ trở thành bị động/mệnh đề danh từ hóa)", "d": "所 + V = điều được V / cái mà...", "ex": [["君主所封的地", "Jūnzhǔ suǒfēng de dì", "vùng đất được vua phong"]]}, {"t": "“有...也有...” và “有...没有...” (có... cũng có... / có... không có...)", "d": "Quý tộc có họ, có tên và cũng có thị; bình dân có họ, có tên nhưng không có thị.", "ex": [["贵族有姓、有名也有氏；平民有姓，有名，没有氏。", "Guìzú yǒuxìng, yǒumíng yě yǒu shì; píngmín yǒuxìng, yǒumíng, méiyǒu shì.", ""]]}, {"t": "“却” (nhưng, lại – biểu thị sự ngược lại)", "d": "Mệnh đề A，却 + mệnh đề B (ý trái ngược) Cùng thị thì có thể, nhưng cùng họ thì lại không thể.", "ex": [["同氏的男女可以通婚，同姓的男女却不可以通婚。", "Tóngshì de nánnǚ kěyǐ tōnghūn, tóngxìng de nánnǚ què bù kěyǐ tōnghūn.", ""]]}, {"t": "“把 + tân ngữ + động từ” (đưa/lấy cái gì đó làm gì)", "d": "Chủ ngữ + 把 + vật + động từ", "ex": [["高士廉把民间的“姓”记录下来。", "Gāoshìlián bǎ mínjiān de “Xìng” jìlùxiàlái.", "Cao Sĩ Liêm đã ghi chép lại các họ trong dân gian."]]}, {"t": "“据说” (nghe nói, theo lời kể)", "d": "", "ex": [["据说有4000到6000个姓。", "Jùshuō yǒu4000 dào6000 ge xìng.", "Nghe nói có 4000 đến 6000 họ."]]}, {"t": "“单是...就...” (riêng... đã...)", "d": "单是 + A + 就 + B = Riêng A thôi đã B", "ex": [["单是姓张的，就有一亿人。", "Dānshì xìngzhāng de, jiù yǒu yíyìrén.", "Riêng họ Trương đã có 100 triệu người."]]}, {"t": "“在...上” (trong/trên lĩnh vực/phương diện)", "d": "", "ex": [["在《东方杂志》上发表", "Zài «Dōngfāng zázhì» shàng fābiǎo", "đăng trên tạp chí Phương Đông."]]}], "order": [], "u": {"gq": [{"s": "从……而来", "d": "Bắt nguồn từ….", "ok": "“姓”是从居住的村子或者所属的部族名称而来。", "vi": "“Họ” bắt nguồn từ tên làng cư trú hoặc bộ tộc.", "bad": ["“姓”是从居住的村子或者所属的部族名称来而。", "“姓”而来是从居住的村子或者所属的部族名称。"]}, {"s": "所 + V", "d": "Danh từ hóa: cái mà… (văn viết).", "ok": "“氏”是从君主所封的地、所赐的爵位而来。", "vi": "“Thị” bắt nguồn từ đất vua phong, tước vị vua ban.", "bad": ["“氏”是从君主封所的地、赐所的爵位而来。", "“氏”是从所君主封的地、所赐的爵位而来。"]}, {"s": "却", "d": "Nhưng, lại (trái ngược), đứng sau chủ ngữ.", "ok": "同氏的男女可以通婚，同姓的男女却不可以通婚。", "vi": "Cùng thị thì lấy nhau được, cùng họ lại không được.", "bad": ["同氏的男女可以通婚，却同姓的男女不可以通婚。", "同氏的男女可以通婚，同姓的男女不可以却通婚。"]}, {"s": "单是……就……", "d": "Riêng… thôi đã….", "ok": "单是姓张的，就有一亿人。", "vi": "Riêng người họ Trương đã có một trăm triệu.", "bad": ["单是姓张的，才有一亿人。", "就是姓张的，单有一亿人。"]}, {"s": "换句话说", "d": "Nói cách khác (diễn đạt lại).", "ok": "换句话说，有七亿人的姓是这45个大姓。", "vi": "Nói cách khác, 700 triệu người mang 45 họ lớn này.", "bad": ["换话句说，有七亿人的姓是这45个大姓。", "换句话说的，有七亿人的姓是这45个大姓。"]}], "disc": [{"q": "越南人的姓和中国人的姓有什么相同和不同？", "py": "Yuènánrén de xìng hé zhōngguó rén de xìng yǒu shénme xiāngtóng hé bùtóng?", "vi": "Họ của người Việt và người Trung Quốc giống và khác nhau thế nào?", "keys": ["据说|根据", "单是……就", "换句话说|也就是说"], "sample": "越南人的姓和中国人的姓很像，比如阮、陈、黎都来自汉字。据说单是姓阮的，就占越南人口的百分之四十左右。换句话说，越南的大姓比中国更集中。", "spy": "Yuènánrén de xìng hé zhōngguó rén de xìng hěn xiàng, bǐrú ruǎn, chén, lídōu láizì hànzì. Jùshuō dānshì xìng ruǎn de, jiù zhàn yuènán rénkǒu de bǎi fēn zhī sì shí zuǒyòu. Huànjùhuàshuō, yuènán de dàxìng bǐ zhōngguó gèng jízhōng."}], "comp": [{"vi": "Nghe nói tiếng Việt có khoảng một nghìn họ. (据说)", "keys": ["据说"], "model": "据说越南语里有一千个左右的姓。", "mpy": "Jùshuō yuènányǔ lǐ yǒu yìqiānge zuǒyòu de xìng."}, {"vi": "Riêng lớp tôi đã có năm người họ Nguyễn. (单是……就……)", "keys": ["单是", "就"], "model": "单是我们班，就有五个人姓阮。", "mpy": "Dānshì wǒmen bān, jiù yǒu wǔge rénxìng ruǎn."}, {"vi": "Nói cách khác, chúng ta phải học chăm hơn. (换句话说)", "keys": ["换句话说"], "model": "换句话说，我们要更努力地学习。", "mpy": "Huànjùhuàshuō, wǒmen yào gèng nǔlì dì xuéxí."}], "ex": [{"q": "为什么“姓”字由“女”和“生”组成？", "qvi": "Vì sao chữ 姓 do 女 và 生 tạo thành?", "a": "因为那时是母系社会，最早的姓跟母亲的姓。", "avi": "Vì khi ấy là xã hội mẫu hệ, họ sớm nhất theo họ mẹ.", "bad": ["因为女人比男人多。", "因为皇帝喜欢这个字。"], "p": 0}, {"q": "古代贵族和平民有什么不同？", "qvi": "Quý tộc và bình dân thời xưa khác nhau thế nào?", "a": "贵族有姓、有名也有氏，平民没有氏。", "avi": "Quý tộc có họ, tên và thị; bình dân không có thị.", "bad": ["平民没有姓。", "贵族没有名。"], "p": 0}, {"q": "《百家姓》一共收集了多少个姓？", "qvi": "《百家姓》 thu thập tổng cộng bao nhiêu họ?", "a": "438个：单姓408个，复姓30个。", "avi": "438 họ: 408 họ đơn, 30 họ kép.", "bad": ["100个。", "6000个。"], "p": 1}, {"q": "中国的四大姓是哪几个？", "qvi": "Bốn họ lớn của Trung Quốc là những họ nào?", "a": "张、王、李、赵。", "avi": "Trương, Vương, Lý, Triệu.", "bad": ["陈、杨、吴、刘。", "徐、朱、林、孙。"], "p": 2}, {"q": "45个大姓占中国人口的多少？", "qvi": "45 họ lớn chiếm bao nhiêu dân số Trung Quốc?", "a": "十多亿人口中，有七亿人。", "avi": "Khoảng 700 triệu trong hơn một tỷ người.", "bad": ["一亿人。", "四亿人。"], "p": 3}]}}, {"id": "hk4-l3", "no": 3, "day": "HK4 · Bài 3", "time": "14:00", "scene": "classroom", "room": "classroom", "cast": ["prof", "edward", "tianfang", "zhangdong"], "vi": "Tài nguyên thiên nhiên Trung Quốc", "zh": "中国的自然资源", "py": "Zhōngguó de zìránzīyuán", "shop": {"label": "地图书店", "sub": "Tiệm bản đồ", "icon": "🗺️"}, "vocab": [["土地资源", "tǔdì zīyuán", "tài nguyên đất đai", ""], ["特点", "tèdiǎn", "đặc điểm", ""], ["一多三少", "yī duō sān shǎo", "một nhiều ba ít", ""], ["总量", "zǒngliàng", "tổng lượng", ""], ["人均", "rénjūn", "bình quân đầu người", ""], ["耕地", "gēngdì", "đất canh tác", ""], ["高质量", "gāo zhìliàng", "chất lượng cao", ""], ["可开发", "kě kāifā", "có thể khai thác/phát triển", ""], ["备用资源", "bèiyòng zīyuán", "tài nguyên dự trữ", ""], ["面积", "miànjī", "diện tích", ""], ["居", "jū", "đứng ở (vị trí)", ""], ["列", "liè", "xếp (thứ hạng)", ""], ["排", "pái", "xếp hạng", ""], ["有限", "yǒuxiàn", "có hạn", ""], ["缺乏", "quēfá", "thiếu", ""], ["水源", "shuǐyuán", "nguồn nước", ""], ["保证", "bǎozhèng", "đảm bảo", ""], ["水土流失", "shuǐtǔ liúshī", "xói mòn đất", ""], ["污染", "wūrǎn", "ô nhiễm", ""], ["严重", "yánzhòng", "nghiêm trọng", ""], ["比例", "bǐlì", "tỷ lệ", ""], ["后备资源", "hòubèi zīyuán", "tài nguyên dự trữ", ""], ["亩", "mǔ", "mẫu (đơn vị diện tích Trung Quốc ≈ 667m²)", ""], ["可开垦", "kě kāikěn", "có thể khai hoang", ""], ["考虑", "kǎolǜ", "cân nhắc", ""], ["生态保护", "shēngtài bǎohù", "bảo vệ sinh thái", ""], ["严格限制", "yángé xiànzhì", "hạn chế nghiêm ngặt", ""], ["今后", "jīnhòu", "từ nay về sau", ""], ["补充", "bǔchōng", "bổ sung", ""], ["矿产资源", "kuàngchǎn zīyuán", "tài nguyên khoáng sản", ""], ["占有量", "zhànyǒu liàng", "lượng sở hữu", ""], ["不足", "bùzú", "không đủ", ""], ["水平", "shuǐpíng", "trình độ, mức độ", ""], ["突出", "tūchū", "nổi bật, nổi cộm", ""], ["问题", "wèntí", "vấn đề", ""], ["支柱性", "zhīzhù xìng", "tính trụ cột", ""], ["石油", "shíyóu", "dầu mỏ", ""], ["天然气", "tiānránqì", "khí tự nhiên", ""], ["储量", "chǔliàng", "trữ lượng", ""], ["矿床", "kuàngchuáng", "mỏ quặng", ""]], "story": [{"c": "panda", "vi": "HK4 · Tài nguyên thiên nhiên Trung Quốc. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "edward", "zh": "中国土地资源的特点是“一多三少”，即总量多，人均耕地少，高质量的耕地少，可开发的备用资源少。虽然中国现有土地面积居世界第三位，但是人均仅及世界人均的1/3；耕地面积列世界第二位，而人均排在世界第67位。在这有限的耕地上，缺乏水源保证、水土流失、污染严重的耕地占了相当大的比例。后备资源2亿亩，其中可开垦成耕地的仅1.2亿亩。考虑到生态保护的要求，耕地后备资源开发受到严格限制，今后通过后备资源开发补充的耕地十分有限。", "py": "Zhōngguó tǔdì zīyuán de tèdiǎn shì “yī duō sān shǎo”, jí zǒngliàng duō, rénjūn gēngdì shǎo, gāo zhìliàng de gēngdì shǎo, kě kāifā de bèiyòng zīyuán shǎo. Suīrán Zhōngguó xiànyǒu tǔdì miànjī jū shìjiè dì sān wèi, dànshì rénjūn jǐn jí shìjiè rénjūn de 1/3; gēngdì miànjī liè shìjiè dì èr wèi, ér rénjūn pái zài shìjiè dì 67 wèi. Zài zhè yǒuxiàn de gēngdì shàng, quēfá shuǐyuán bǎozhèng, shuǐtǔ liúshī, wūrǎn yánzhòng de gēngdì zhànle xiāngdāng dà de bǐlì. Hòubèi zīyuán 2 yì mǔ, qízhōng kě kāikěn chéng gēngdì de jǐn 1.2 yì mǔ. Kǎolǜ dào shēngtài bǎohù de yāoqiú, gēngdì hòubèi zīyuán kāifā shòudào yángé xiànzhì, jīnhòu tōngguò hòubèi zīyuán kāifā bǔchōng de gēngdì shífēn yǒuxiàn.", "vi": "Đặc điểm tài nguyên đất đai Trung Quốc là “một nhiều, ba ít”, tức là tổng lượng nhiều, nhưng đất canh tác bình quân đầu người ít, đất canh tác chất lượng cao ít, và tài nguyên dự trữ có thể khai thác ít. Mặc dù diện tích đất hiện có của Trung Quốc đứng thứ ba thế giới, nhưng bình quân đầu người chỉ bằng 1/3 mức trung bình thế giới; diện tích đất canh tác đứng thứ hai thế giới, nhưng bình quân đầu người xếp thứ 67. Trên diện tích đất canh tác có hạn này, đất thiếu nguồn nước đảm bảo, bị xói mòn, ô nhiễm nghiêm trọng chiếm một tỷ lệ khá lớn. Tài nguyên dự trữ là 200 triệu mẫu Anh, trong đó chỉ có 120 triệu mẫu có thể khai hoang thành đất canh tác. Cân nhắc đến yêu cầu bảo vệ sinh thái, việc khai thác tài nguyên đất dự trữ bị hạn chế nghiêm ngặt, trong tương lai, diện tích đất canh tác được bổ sung qua khai thác tài nguyên dự trữ sẽ rất hạn chế."}, {"c": "prof", "zh": "中国土地资源的“一多三少”是什么意思？", "py": "Zhōngguó tǔdì zīyuán de “Yìduōsānshǎo” shì shénme yìsi?", "vi": "“一多三少” của tài nguyên đất nghĩa là gì?"}, {"me": "Tổng lượng nhiều; đất canh tác bình quân, đất tốt và đất dự trữ đều ít.", "opts": [["总量多，人均耕地、高质量耕地和备用资源少。", "Zǒngliàng duō, rénjūn gēngdì, gāozhìliàng gēngdì hé bèiyòng zīyuán shǎo.", "Tổng lượng nhiều; đất canh tác bình quân, đất tốt và đất dự trữ đều ít."], ["人口多，土地少，水少，山少。", "Rénkǒu duō, tǔdì shǎo, shuǐshǎo, shānshǎo.", "(chưa đúng với bài)"], ["耕地多，城市少。", "Gēngdì duō, chéngshì shǎo.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "中国的矿产资源总量丰富，但人均占有量不足，仅为世界人均水平的58%。同时存在三个突出问题：一是支柱性的矿产（如石油、天然气等）后备储量不足，而储量较多的则是部分用量不大的矿产；二是小矿床多，大型特大型矿床少；支柱性矿产贫矿和难选冶矿多，富矿少，开采利用难度很大；三是资源分布与生产力布局不匹配。未来20-30年内，中国矿产品的需求量将大大增加，而矿产储量的增长速度远远低于矿产消耗的增长速度。据预测，2010年中国45种主要矿产品中，关系国计民生的矿产将难以保证需求。", "py": "Zhōngguó de kuàngchǎn zīyuán zǒngliàng fēngfù, dàn rénjūn zhànyǒu liàng bùzú, jǐn wéi shìjiè rénjūn shuǐpíng de 58%. Tóngshí cúnzài sān gè tūchū wèntí: yī shì zhīzhù xìng de kuàngchǎn (rú shíyóu, tiānránqì děng) hòubèi chǔliàng bùzú, ér chǔliàng jiào duō de zé shì bùfen yòngliàng bù dà de kuàngchǎn; èr shì xiǎo kuàngchuáng duō, dàxíng tè dàxíng kuàngchuáng shǎo; zhīzhù xìng kuàngchǎn pínkuàng hé nán xuǎnyě kuàng duō, fùkuàng shǎo, kāicǎi lìyòng nándù hěn dà; sān shì zīyuán fēnbù yǔ shēngchǎnlì bùjú bù pǐpèi. Wèilái 20-30 nián nèi, Zhōngguó kuàngchǎnpǐn de xūqiú liàng jiāng dàdà zēngjiā, ér kuàngchǎn chǔliàng de zēngzhǎng sùdù yuǎnyuǎn dīyú kuàngchǎn xiāohào de zēngzhǎng sùdù. Jù yùcè, 2010 nián Zhōngguó 45 zhǒng zhǔyào kuàngchǎnpǐn zhōng, guānxì guójì mínshēng de kuàngchǎn jiāng nányǐ bǎozhèng xūqiú.", "vi": "Tài nguyên khoáng sản Trung Quốc tổng lượng phong phú, nhưng sở hữu bình quân đầu người không đủ, chỉ bằng 58% mức trung bình thế giới. Đồng thời tồn tại ba vấn đề nổi cộm: Thứ nhất, trữ lượng dự trữ của các khoáng sản trụ cột (như dầu mỏ, khí tự nhiên...) không đủ, trong khi những loại có trữ lượng nhiều lại là các khoáng sản không được sử dụng nhiều; Thứ hai, mỏ nhỏ nhiều, mỏ lớn và đặc lớn ít; khoáng sản trụ cột có nhiều quặng nghèo và quặng khó tuyển luyện, quặng giàu ít, khó khai thác và sử dụng; Thứ ba, phân bố tài nguyên không phù hợp với bố cục năng lực sản xuất. Trong 20-30 năm tới, nhu cầu về sản phẩm khoáng sản của Trung Quốc sẽ tăng mạnh, nhưng tốc độ tăng trưởng trữ lượng khoáng sản thấp hơn nhiều so với tốc độ tăng tiêu thụ. Theo dự báo, vào năm 2010, trong số 45 loại sản phẩm khoáng sản chính của Trung Quốc, các khoáng sản liên quan đến quốc kế dân sinh sẽ khó đáp ứng nhu cầu."}, {"c": "prof", "zh": "中国矿产资源人均占有量是世界人均的多少？", "py": "Zhōngguó kuàngchǎnzīyuán rénjūn zhànyǒuliàng shì shìjiè rénjūn de duōshao?", "vi": "Khoáng sản bình quân đầu người bằng bao nhiêu so với thế giới?"}, {"me": "Chỉ 58%.", "opts": [["只有58%。", "Zhǐyǒu58%.", "Chỉ 58%."], ["是世界人均的两倍。", "Shì shìjiè rénjūn de liǎngbèi.", "(chưa đúng với bài)"], ["是世界第一。", "Shì shìjiè dìyī.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "中国矿产资源有哪些突出问题？", "py": "Zhōngguó kuàngchǎnzīyuán yǒu nǎxiē tūchū wèntí?", "vi": "Khoáng sản Trung Quốc có những vấn đề nổi bật nào?"}, {"me": "Khoáng sản chủ chốt thiếu, mỏ lớn ít, phân bố không khớp với sản xuất.", "opts": [["支柱性矿产储量不足、大矿少、分布与生产力布局不匹配。", "Zhīzhùxìng kuàngchǎn chǔliàng bùzú, dàkuàngshǎo, fēnbù yǔ shēngchǎnlì bùjú bù pǐpèi.", "Khoáng sản chủ chốt thiếu, mỏ lớn ít, phân bố không khớp với sản xuất."], ["矿产太多，用不完。", "Kuàngchǎn tài duō, yòngbùwán.", "(chưa đúng với bài)"], ["只有石油，没有别的矿产。", "Zhǐyǒu shíyóu, méiyǒu biéde kuàngchǎn.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "中国是海洋大国，漫长的海岸线长达18,000多公里，加上岛屿岸线则达32,000多公里。大陆沿岸的海域面积广阔，海区面积470多万平方公里，海洋渔场面积42亿亩，海水可养殖面积73万亩。自然条件优越，海洋资源十分丰富，鱼类5000多种，虾、蟹等有千余种，中国海域有记载的生物可达万余种。", "py": "Zhōngguó shì hǎiyáng dàguó, mànmàn de hǎi'ànxiàn cháng dá 18,000 duō gōnglǐ, jiāshàng dǎoyǔ ànxiàn zé dá 32,000 duō gōnglǐ. Dàlù yán'àn de hǎiyù miànjī guǎngkuò, hǎiqū miànjī 470 duō wàn píngfāng gōnglǐ, hǎiyáng yúchǎng miànjī 42 yì mǔ, hǎishuǐ kě yǎngzhí miànjī 73 wàn mǔ. Zìrán tiáojiàn yōuyuè, hǎiyáng zīyuán shífēn fēngfù, yúlèi 5000 duō zhǒng, xiā, xiè děng yǒu qiān yú zhǒng, Zhōngguó hǎiyù yǒu jìzǎi de shēngwù kě dá wàn yú zhǒng.", "vi": "Trung Quốc là một nước biển lớn, đường bờ biển dài hơn 18.000 km, cộng với đường bờ biển của các đảo thì lên tới hơn 32.000 km. Vùng biển ven đất liền rất rộng lớn, diện tích vùng biển hơn 4,7 triệu km², diện tích ngư trường biển là 420 triệu mẫu, diện tích nuôi trồng thủy sản là 730.000 mẫu. Điều kiện tự nhiên thuận lợi, tài nguyên biển rất phong phú, có hơn 5.000 loài cá, hơn 1.000 loài tôm, cua... Các sinh vật được ghi nhận trong vùng biển Trung Quốc có thể lên tới hơn 10.000 loài."}, {"c": "prof", "zh": "中国海岸线加上岛屿岸线有多长？", "py": "Zhōngguó hǎiànxiàn jiāshàng dǎoyǔ ànxiàn yǒu duōzhǎng?", "vi": "Đường bờ biển cộng bờ đảo dài bao nhiêu?"}, {"me": "Hơn 32.000 km.", "opts": [["32,000多公里。", "32,000 duōgōnglǐ.", "Hơn 32.000 km."], ["18,000公里。", "18,000 gōnglǐ.", "(chưa đúng với bài)"], ["5,000公里。", "5,000 gōnglǐ.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "中国海洋资源中不仅生物资源繁多，还有大量的矿产资源、动力资源和海水资源。近海石油储量估计可达50-150亿吨，其他海洋资源的总蕴藏量约有9亿千瓦，沿岸含有多种价值极高的原料。海水中还含有盐、钾、钠等多种化学资源。", "py": "Zhōngguó hǎiyáng zīyuán zhōng bùjǐn shēngwù zīyuán fánduō, hái yǒu dàliàng de kuàngchǎn zīyuán, dònglì zīyuán hé hǎishuǐ zīyuán. Jìnhǎi shíyóu chǔliàng gūjì kě dá 50-150 yì dūn, qítā hǎiyáng zīyuán de zǒng yùncáng liàng yuē yǒu 9 yì qiānwǎ, yán'àn hányǒu duō zhǒng jiàzhí jí gāo de yuánliào. Hǎishuǐ zhōng hái hányǒu yán, jiǎ, nà děng duō zhǒng huàxué zīyuán.", "vi": "Trong tài nguyên biển của Trung Quốc, không chỉ có tài nguyên sinh vật đa dạng, mà còn có nhiều tài nguyên khoáng sản, tài nguyên năng lượng và tài nguyên nước biển. Trữ lượng dầu mỏ ven biển ước tính có thể đạt 5-15 tỷ tấn, tổng trữ lượng tiềm năng của các tài nguyên biển khác khoảng 900 triệu kilowatt, ven biển chứa nhiều loại nguyên liệu có giá trị rất cao. Nước biển còn chứa nhiều tài nguyên hóa học như muối, kali, natri,..."}, {"c": "prof", "zh": "海洋资源除了生物资源还有什么？", "py": "Hǎiyángzīyuán chúle shēngwùzīyuán háiyǒu shénme?", "vi": "Ngoài sinh vật, biển còn có tài nguyên gì?"}, {"me": "Khoáng sản, năng lượng và tài nguyên nước biển.", "opts": [["矿产资源、动力资源和海水资源。", "Kuàngchǎnzīyuán, dònglì zīyuán hé hǎishuǐ zīyuán.", "Khoáng sản, năng lượng và tài nguyên nước biển."], ["只有鱼和虾。", "Zhǐyǒu yú hé xiā.", "(chưa đúng với bài)"], ["只有盐。", "Zhǐyǒu yán.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“即” (tức là)", "d": "A，即 B = A, tức là B (dùng để giải thích) Dùng 即 để liệt kê, giải thích cụ thể cho nhận định trước đó.", "ex": [["“一多三少”，即总量多，人均耕地少...", "“Yìduōsānshǎo”, jí zǒngliàng duō, rénjūn gēngdì shǎo...", ""]]}, {"t": "“虽然...但是...” (mặc dù... nhưng...)", "d": "虽然 + A，但是 + B Biểu thị quan hệ nhượng bộ – đối lập.", "ex": [["虽然中国土地面积居世界第三位，但是人均仅及世界人均的1/3。", "Suīrán zhōngguó tǔdì miànjī jū shìjiè dìsānwèi, dànshì rénjūn jǐn jí shìjiè rénjūn de1/3.", ""]]}, {"t": "“仅及 / 仅为” (chỉ bằng / chỉ là)", "d": "Dùng để so sánh mức độ, tỷ lệ.", "ex": [["人均仅及世界人均的1/3；仅为世界人均水平的58%。", "Rénjūn jǐn jí shìjiè rénjūn de1/3; jǐnwèi shìjiè rénjūn shuǐpíng de58%.", ""]]}, {"t": "“占...比例” (chiếm tỷ lệ...)", "d": "A + 占 + B + 的 + 比例 Để chỉ phần trăm, tỷ lệ chiếm.", "ex": [["污染严重的耕地占了相当大的比例。", "Wūrǎn yánzhòng de gēngdì zhàn le xiāngdāng dà de bǐlì.", ""]]}, {"t": "bị động với “受到” (bị/được)", "d": "Chủ thể + 受到 + tác động", "ex": [["耕地后备资源开发受到严格限制。", "Gēngdì hòubèi zīyuán kāifā shòudào yángé xiànzhì.", "Việc khai thác tài nguyên đất dự trữ bị hạn chế nghiêm ngặt."]]}, {"t": "“一是...二是...三是...” (thứ nhất là... thứ hai là... thứ ba là...)", "d": "Cách dùng: Liệt kê các ý một cách có thứ tự.", "ex": [["一是支柱性的矿产后备储量不足；二是小矿床多；三是资源分布与生产力布局不匹配。", "Yíshì zhīzhùxìng de kuàngchǎn hòubèi chǔliàng bùzú; èrshì xiǎo kuàngchuáng duō; sānshì zīyuán fēnbù yǔ shēngchǎnlì bùjú bù pǐpèi.", ""]]}, {"t": "“如...等” (như... v.v.)", "d": "Dùng để đưa ra ví dụ điển hình trong một danh sách.", "ex": [["支柱性的矿产（如石油、天然气等）", "Zhīzhùxìng de kuàngchǎn (Rú shíyóu, tiānránqì děng)", ""]]}, {"t": "“远远低于” (thấp hơn xa, thấp hơn nhiều)", "d": "A + 远远低于 + B So sánh mức độ chênh lệch lớn.", "ex": [["矿产储量的增长速度远远低于矿产消耗的增长速度。", "Kuàngchǎn chǔliàng de zēngzhǎngsùdù yuǎnyuǎn dīyú kuàngchǎn xiāohào de zēngzhǎngsùdù.", ""]]}], "order": [], "u": {"gq": [{"s": "即", "d": "Tức là (giải thích, văn viết).", "ok": "中国土地资源的特点是“一多三少”，即总量多，人均耕地少。", "vi": "Đặc điểm đất đai TQ là “một nhiều ba ít”, tức là tổng lượng nhiều, đất canh tác bình quân ít.", "bad": ["中国土地资源的特点即是“一多三少”，总量多，人均耕地少即。", "中国土地资源的特点是“一多三少”，即是说即总量多。"]}, {"s": "虽然……但是……", "d": "Tuy… nhưng….", "ok": "虽然中国现有土地面积居世界第三位，但是人均仅及世界人均的1/3。", "vi": "Tuy diện tích đất đứng thứ ba thế giới nhưng bình quân chỉ bằng 1/3 thế giới.", "bad": ["虽然中国现有土地面积居世界第三位，所以人均仅及世界人均的1/3。", "中国虽然现有土地面积居世界第三位，但是虽然人均仅及1/3。"]}, {"s": "受到 + 限制/关注", "d": "Bị động văn viết: chịu…, được….", "ok": "耕地后备资源开发受到严格限制。", "vi": "Việc khai thác đất dự trữ bị hạn chế nghiêm ngặt.", "bad": ["耕地后备资源开发受到限制严格。", "耕地后备资源开发严格受到被限制。"]}, {"s": "不仅……还……", "d": "Không những… mà còn….", "ok": "中国海洋资源中不仅生物资源繁多，还有大量的矿产资源。", "vi": "Biển TQ không những nhiều sinh vật mà còn nhiều khoáng sản.", "bad": ["中国海洋资源中不仅生物资源繁多，但有大量的矿产资源。", "不仅中国海洋资源中生物资源繁多，还而且有大量矿产。"]}, {"s": "据 + V (据预测)", "d": "Theo (dự đoán/thống kê)….", "ok": "据预测，主要矿产将难以保证需求。", "vi": "Theo dự đoán, khoáng sản chủ yếu sẽ khó đáp ứng nhu cầu.", "bad": ["预测据，主要矿产将难以保证需求。", "据预测的，主要矿产将难以保证需求。"]}], "disc": [{"q": "越南的自然资源有什么特点？和中国比一比。", "py": "Yuènán de zìránzīyuán yǒu shénme tèdiǎn? Hé zhōngguó bǐyìbǐ.", "vi": "Tài nguyên thiên nhiên Việt Nam có đặc điểm gì? So với Trung Quốc.", "keys": ["虽然……但是|虽然……但", "不仅……还|不仅……而且", "即|也就是说"], "sample": "越南虽然面积不大，但是海岸线很长，有三千多公里。越南不仅有丰富的海洋资源，还有石油和煤。和中国一样，越南的人均耕地也不多，即人口多、土地少。", "spy": "Yuènán suīrán miànjī bú dà, dànshì hǎiànxiàn hěnzhǎng, yǒu sānqiānduō gōnglǐ. Yuènán bùjǐn yǒu fēngfù de hǎiyángzīyuán, háiyǒu shíyóu hé méi. Hé zhōngguó yíyàng, yuènán de rénjūn gēngdì yě bù duō, jí rénkǒu duō, tǔdì shǎo."}], "comp": [{"vi": "Tuy nước này rộng lớn nhưng đất canh tác bình quân rất ít. (虽然……但是……)", "keys": ["虽然", "但是|但"], "model": "虽然这个国家面积很大，但是人均耕地很少。", "mpy": "Suīrán zhège guójiā miànjī hěndà, dànshì rénjūn gēngdì hěnshǎo."}, {"vi": "Theo thống kê, dân số thành phố đã vượt mười triệu. (据统计)", "keys": ["据"], "model": "据统计，这个城市的人口已经超过一千万了。", "mpy": "Jùtǒngjì, zhège chéngshì de rénkǒu yǐjīng chāoguò yìqiānwàn le."}, {"vi": "Biển không những có cá mà còn có dầu mỏ. (不仅……还……)", "keys": ["不仅", "还|而且"], "model": "大海里不仅有鱼，还有石油。", "mpy": "Dà hǎilǐ bùjǐn yǒuyú, háiyǒu shíyóu."}], "ex": [{"q": "中国土地资源的“一多三少”是什么意思？", "qvi": "“一多三少” của tài nguyên đất nghĩa là gì?", "a": "总量多，人均耕地、高质量耕地和备用资源少。", "avi": "Tổng lượng nhiều; đất canh tác bình quân, đất tốt và đất dự trữ đều ít.", "bad": ["人口多，土地少，水少，山少。", "耕地多，城市少。"], "p": 0}, {"q": "中国矿产资源人均占有量是世界人均的多少？", "qvi": "Khoáng sản bình quân đầu người bằng bao nhiêu so với thế giới?", "a": "只有58%。", "avi": "Chỉ 58%.", "bad": ["是世界人均的两倍。", "是世界第一。"], "p": 1}, {"q": "中国矿产资源有哪些突出问题？", "qvi": "Khoáng sản Trung Quốc có những vấn đề nổi bật nào?", "a": "支柱性矿产储量不足、大矿少、分布与生产力布局不匹配。", "avi": "Khoáng sản chủ chốt thiếu, mỏ lớn ít, phân bố không khớp với sản xuất.", "bad": ["矿产太多，用不完。", "只有石油，没有别的矿产。"], "p": 1}, {"q": "中国海岸线加上岛屿岸线有多长？", "qvi": "Đường bờ biển cộng bờ đảo dài bao nhiêu?", "a": "32,000多公里。", "avi": "Hơn 32.000 km.", "bad": ["18,000公里。", "5,000公里。"], "p": 2}, {"q": "海洋资源除了生物资源还有什么？", "qvi": "Ngoài sinh vật, biển còn có tài nguyên gì?", "a": "矿产资源、动力资源和海水资源。", "avi": "Khoáng sản, năng lượng và tài nguyên nước biển.", "bad": ["只有鱼和虾。", "只有盐。"], "p": 3}]}}, {"id": "hk4-l4", "no": 4, "day": "HK4 · Bài 4", "time": "15:30", "scene": "office", "room": "office", "cast": ["prof", "manager", "lee", "roland"], "vi": "USB bảo mật", "zh": "安全U盘", "py": "Ānquán Upán", "shop": {"label": "电脑城", "sub": "Khu máy tính", "icon": "💾"}, "vocab": [["电脑", "diànnǎo", "máy tính", ""], ["几乎", "jīhū", "gần như", ""], ["不可缺少", "bùkě quēshǎo", "không thể thiếu", ""], ["工具", "gōngjù", "công cụ", ""], ["移动存储设备", "yídòng cúnchú shèbèi", "thiết bị lưu trữ di động", ""], ["普及", "pǔjí", "phổ biến, phổ cập", ""], ["体积", "tǐjī", "thể tích, kích thước", ""], ["小巧", "xiǎoqiǎo", "nhỏ nhắn, xinh xắn", ""], ["携带", "xiédài", "mang theo", ""], ["方便", "fāngbiàn", "tiện lợi", ""], ["然而", "rán'ér", "tuy nhiên", ""], ["便利", "biànlì", "tiện lợi", ""], ["同时", "tóngshí", "đồng thời", ""], ["丢失", "diūshī", "đánh mất", ""], ["数据", "shùjù", "dữ liệu", ""], ["概率", "gàilǜ", "xác suất", ""], ["本身", "běnshēn", "bản thân", ""], ["值钱", "zhíqián", "có giá trị (tiền bạc)", ""], ["无价", "wújià", "vô giá", ""], ["个人资料", "gèrén zīliào", "thông tin cá nhân, tài liệu cá nhân", ""], ["客户", "kèhù", "khách hàng", ""], ["商业机密", "shāngyè jīmì", "bí mật thương mại", ""], ["难以衡量", "nányǐ héngliáng", "khó đo lường", ""], ["发生", "fāshēng", "xảy ra", ""], ["遗失", "yíshī", "thất lạc", ""], ["致使", "zhìshǐ", "khiến cho, dẫn đến", ""], ["泄露", "xièlòu", "rò rỉ, lộ", ""], ["事件", "shìjiàn", "sự việc", ""], ["发布", "fābù", "phát hành, công bố", ""], ["解决", "jiějué", "giải quyết", ""], ["机密", "jīmì", "bí mật, cơ mật", ""], ["乃至", "nǎizhì", "thậm chí, cho đến", ""], ["加密", "jiāmì", "mã hóa", ""], ["关注", "guānzhù", "quan tâm", ""], ["市场", "shìchǎng", "thị trường", ""], ["提供", "tígōng", "cung cấp", ""], ["功能", "gōngnéng", "chức năng", ""], ["软件", "ruǎnjiàn", "phần mềm", ""], ["芯片", "xīnpiàn", "chip, vi mạch", ""], ["完成", "wánchéng", "hoàn thành", ""]], "story": [{"c": "panda", "vi": "HK4 · USB bảo mật. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "manager", "zh": "现在，电脑几乎是人们生活中不可缺少的工具。而U盘等移动存储设备也早已普及。很多人在工作和生活中都会用到U盘。U盘体积小巧、携带方便，然而带来这些便利的同时，使用U盘也增加了丢失数据的概率。U盘本身虽然不值钱，但是存储在U盘内的数据却是无价的。存储其中的个人资料、客户信息或是商业机密，其价值难以衡量。就在今年3月，某医院就发生了由于U盘遗失致使47名病人信息泄露的事件。", "py": "Xiànzài, diànnǎo jīhū shì rénmen shēnghuó zhōng bùkě quēshǎo de gōngjù. Ér U pán děng yídòng cúnchú shèbèi yě zǎoyǐ pǔjí. Hěnduō rén zài gōngzuò hé shēnghuó zhōng dōu huì yòng dào U pán. U pán tǐjī xiǎoqiǎo, xiédài fāngbiàn, rán'ér dàilái zhèxiē biànlì de tóngshí, shǐyòng U pán yě zēngjiāle diūshī shùjù de gàilǜ. U pán běnshēn suīrán bù zhíqián, dànshì cúnchú zài U pán nèi de shùjù què shì wújià de. Cúnchú qízhōng de gèrén zīliào, kèhù xìnxī huòshì shāngyè jīmì, qí jiàzhí nányǐ héngliáng. Jiù zài jīnnián 3 yuè, mǒu yīyuàn jiù fāshēngle yóuyú U pán yíshī zhìshǐ 47 míng bìngrén xìnxī xièlòu de shìjiàn.", "vi": "Ngày nay, máy tính gần như là công cụ không thể thiếu trong cuộc sống của con người. Và các thiết bị lưu trữ di động như USB cũng đã trở nên phổ biến từ lâu. Rất nhiều người dùng USB trong công việc và cuộc sống. USB có kích thước nhỏ nhắn, tiện lợi khi mang theo. Tuy nhiên, bên cạnh những tiện lợi này, việc sử dụng USB cũng làm tăng khả năng mất dữ liệu. Bản thân chiếc USB tuy không đáng giá bao nhiêu, nhưng dữ liệu được lưu trữ bên trong thì vô giá. Những thông tin cá nhân, dữ liệu khách hàng hay bí mật thương mại được lưu trong đó, giá trị của chúng khó có thể đo đếm được. Ngay trong tháng 3 năm nay, một bệnh viện đã xảy ra sự việc khiến thông tin của 47 bệnh nhân bị rò rỉ do làm mất USB."}, {"c": "prof", "zh": "U盘有什么优点和缺点？", "py": "Upán yǒu shénme yōudiǎn hé quēdiǎn?", "vi": "USB có ưu điểm và nhược điểm gì?"}, {"me": "Nhỏ, tiện mang theo, nhưng dễ mất dữ liệu.", "opts": [["体积小、携带方便，但容易丢失数据。", "Tǐjīxiǎo, xiédàifāngbiàn, dàn róngyì diūshī shùjù.", "Nhỏ, tiện mang theo, nhưng dễ mất dữ liệu."], ["价格很贵，但存储很快。", "Jiàgé hěn guì, dàn cúnchǔ hěnkuài.", "(chưa đúng với bài)"], ["很重，不方便携带。", "Hěn zhòng, bù fāngbiàn xiédài.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "某医院发生了什么事？", "py": "Mǒu yīyuàn fāshēng le shénme shì?", "vi": "Ở một bệnh viện đã xảy ra chuyện gì?"}, {"me": "Vì mất USB, thông tin 47 bệnh nhân bị lộ.", "opts": [["因为U盘遗失，47名病人的信息泄露了。", "Yīnwèi Upán yíshī, 47 míng bìngrén de xìnxī xièlòu le.", "Vì mất USB, thông tin 47 bệnh nhân bị lộ."], ["医院买了47个新U盘。", "Yīyuàn mǎi le47 ge xīn Upán.", "(chưa đúng với bài)"], ["医生把电脑弄坏了。", "Yīshēng bǎ diànnǎo nònghuàile.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "最近，“成功者”电子公司发布了一种新U盘，能解决机密数据随U盘遗失的问题。其实，在中国，乃至世界，信息加密的问题早就受到关注，市场上已经有很多U盘提供了数据加密功能。然而，其中很多U盘的加密是通过软件或外加芯片来完成的，写入芯片的数据并未进行加密，只是限制了数据的读取，如果通过一些技术手段很容易破解。", "py": "Zuìjìn, “Chénggōngzhě” diànzǐ gōngsī fābùle yī zhǒng xīn U pán, néng jiějué jīmì shùjù suí U pán yíshī de wèntí. Qíshí, zài Zhōngguó, nǎizhì shìjiè, xìnxī jiāmì de wèntí zǎo jiù shòudào guānzhù, shìchǎng shàng yǐjīng yǒu hěnduō U pán tígōngle shùjù jiāmì gōngnéng. Rán'ér, qízhōng hěnduō U pán de jiāmì shì tōngguò ruǎnjiàn huò wàijiā xīnpiàn lái wánchéng de, xiěrù xīnpiàn de shùjù bìng wèi jìnxíng jiāmì, zhǐshì xiànzhìle shùjù de dúqǔ, rúguǒ tōngguò yīxiē jìshù shǒuduàn hěn róngyì pòjiě.", "vi": "Gần đây, công ty điện tử \"Người Thành Công\" đã ra mắt một loại USB mới, có thể giải quyết vấn đề dữ liệu mật bị rò rỉ theo USB bị thất lạc. Thực tế, ở Trung Quốc, thậm chí trên thế giới, vấn đề mã hóa thông tin từ lâu đã được quan tâm. Trên thị trường đã có rất nhiều USB cung cấp chức năng mã hóa dữ liệu. Tuy nhiên, trong số đó, nhiều USB thực hiện mã hóa thông qua phần mềm hoặc chip bổ sung. Dữ liệu ghi vào chip chưa được mã hóa, mà chỉ hạn chế quyền đọc dữ liệu. Nếu sử dụng một số thủ thuật kỹ thuật, rất dễ dàng để giải mã."}, {"c": "prof", "zh": "市场上很多加密U盘有什么问题？", "py": "Shìchǎng shàng hěnduō jiāmì Upán yǒu shénme wèntí?", "vi": "Nhiều USB mã hóa trên thị trường có vấn đề gì?"}, {"me": "Dữ liệu ghi vào chip không được mã hóa, dễ bị bẻ khóa.", "opts": [["写入芯片的数据并未加密，用技术手段很容易破解。", "Xiěrù xīnpiàn de shùjù bìngwèi jiāmì, yòng jìshùshǒuduàn hěn róngyì pòjiě.", "Dữ liệu ghi vào chip không được mã hóa, dễ bị bẻ khóa."], ["它们太贵了。", "Tāmen tàiguì le.", "(chưa đúng với bài)"], ["它们不能存数据。", "Tāmen bùnéng cún shùjù.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "与普通具有加密功能的U盘相比，“成功者”安全U盘具有与众不同的特点：它的认证主体是主控芯片本身，口令判断在主控芯片内完成；“成功者”安全U盘的使用非常简单，插入电脑后输入正确的密码，即可像正常U盘一样存储数据了。为了方便用户与他人共享数据，“成功者”安全U盘设有公共区和加密区。公共区是不需要密码即可读写的，用户可以将其备份到他人共享的资料放在该区内，而将重要的机密资料保存在加密区内。如果U盘丢失，不知道密码的人在输错10次密码之后，U盘将被自动锁定，无法再对其进行任何操作。即便是专业人员，也无法通过各种技术手段来破解存储的保密数据。", "py": "Yǔ pǔtōng jùyǒu jiāmì gōngnéng de U pán xiāngbǐ, “Chénggōngzhě” ānquán U pán jùyǒu yǔzhòng bùtóng de tèdiǎn: tā de rènzhèng zhǔtǐ shì zhǔkòng xīnpiàn běnshēn, kǒulìng pànduàn zài zhǔkòng xīnpiàn nèi wánchéng; “Chénggōngzhě” ānquán U pán de shǐyòng fēicháng jiǎndān, chārù diànnǎo hòu shūrù zhèngquè de mìmǎ, jí kě xiàng zhèngcháng U pán yīyàng cúnchú shùjùle. Wèile fāngbiàn yònghù yǔ tārén gòngxiǎng shùjù, “Chénggōngzhě” ānquán U pán shèyǒu gōnggòng qū hé jiāmì qū. Gōnggòng qū shì bù xūyào mìmǎ jí kě dúxiě de, yònghù kěyǐ jiāng qí bèifèn dào tārén gòngxiǎng de zīliào fàng zài gāi qū nèi, ér jiāng zhòngyào de jīmì zīliào bǎocún zài jiāmì qū nèi. Rúguǒ U pán diūshī, bù zhīdào mìmǎ de rén zài shūcuò 10 cì mìmǎ zhīhòu, U pán jiāng bèi zìdòng suǒdìng, wúfǎ zài duì qí jìnxíng rènhé cāozuò. Jíbiàn shì zhuānyè rényuán, yě wúfǎ tōngguò gè zhǒng jìshù shǒuduàn lái pòjiě cúnchú de bǎomì shùjù.", "vi": "So với USB mã hóa thông thường, USB an toàn \"Người Thành Công\" có những đặc điểm khác biệt: chủ thể xác thực là chính con chip điều khiển chính, việc kiểm tra mật khẩu được hoàn thành ngay bên trong chip điều khiển chính; USB an toàn \"Người Thành Công\" sử dụng rất đơn giản, sau khi cắm vào máy tính và nhập đúng mật khẩu, bạn có thể lưu trữ dữ liệu như USB bình thường. Để tiện cho người dùng chia sẻ dữ liệu với người khác, USB an toàn \"Người Thành Công\" được thiết kế với khu vực công cộng và khu vực mã hóa. Khu vực công cộng có thể đọc và ghi mà không cần mật khẩu. Người dùng có thể đặt các tài liệu cần sao lưu và chia sẻ với người khác vào khu vực này, đồng thời lưu trữ các tài liệu mật quan trọng trong khu vực mã hóa. Nếu USB bị mất, những người không biết mật khẩu sau khi nhập sai 10 lần, USB sẽ tự động bị khóa, không thể thực hiện bất kỳ thao tác nào trên đó nữa. Ngay cả các chuyên gia kỹ thuật cũng không thể thông qua bất kỳ phương tiện kỹ thuật nào để giải mã dữ liệu bảo mật đã lưu."}, {"c": "prof", "zh": "“成功者”安全U盘的公共区和加密区有什么不同？", "py": "“Chénggōngzhě” ānquán Upán de gōnggòng qū hé jiāmì qūyǒu shénme bùtóng?", "vi": "Vùng chung và vùng mã hóa khác nhau thế nào?"}, {"me": "Vùng chung không cần mật khẩu; vùng mã hóa lưu tài liệu mật.", "opts": [["公共区不需要密码，加密区用来保存重要的机密资料。", "Gōnggòng qū bù xūyào mìmǎ, jiāmì qū yònglái bǎocún zhòngyào de jīmì zīliào.", "Vùng chung không cần mật khẩu; vùng mã hóa lưu tài liệu mật."], ["公共区要输两次密码。", "Gōnggòng qūyào shū liǎngcì mìmǎ.", "(chưa đúng với bài)"], ["两个区完全一样。", "Liǎngge qū wánquán yíyàng.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "输错10次密码以后会怎么样？", "py": "Shūcuò10 cì mìmǎ yǐhòu huì zěnmeyàng?", "vi": "Nhập sai mật khẩu 10 lần thì sao?"}, {"me": "USB tự động bị khóa, không thao tác được nữa.", "opts": [["U盘将被自动锁定，无法再进行任何操作。", "Upán jiāng bèi zìdòng suǒdìng, wúfǎ zài jìnxíng rènhé cāozuò.", "USB tự động bị khóa, không thao tác được nữa."], ["U盘会自动打开。", "Upán huì zìdòng dǎkāi.", "(chưa đúng với bài)"], ["U盘会给主人打电话。", "Upán huì gěi zhǔrén dǎdiànhuà.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“几乎” (gần như)", "d": "", "ex": [["电脑几乎是人们生活中不可缺少的工具。", "Diànnǎo jīhū shì rénmen shēnghuó zhōng bùkě quēshǎo de gōngjù.", ""]]}, {"t": "“而...也...” (còn... cũng...)", "d": "而 dùng để nối tiếp ý, thêm thông tin mới; 等 nghĩa là \"v.v.\"", "ex": [["U盘等移动存储设备也早已普及。", "Upán děng yídòng cúnchǔshèbèi yě zǎoyǐ pǔjí.", ""]]}, {"t": "“虽然...但是...” (mặc dù... nhưng...)", "d": "Cách dùng: Biểu thị quan hệ nhượng bộ – đối lập.", "ex": [["U盘本身虽然不值钱，但是存储在U盘内的数据却是无价的。", "Upán běnshēn suīrán bùzhíqián, dànshì cúnchǔ zài Upán nèi de shùjù quèshì wújià de.", ""]]}, {"t": "“然而...同时...” (tuy nhiên... đồng thời...)", "d": "然而 = tuy nhiên; 同时 = đồng thời, nối hai ý bổ sung cho nhau.", "ex": [["然而带来这些便利的同时，使用U盘也增加了丢失数据的概率。", "Ránér dàilái zhèxiē biànlì de tóngshí, shǐyòng Upán yě zēngjiā le diūshī shùjù de gàilǜ.", ""]]}, {"t": "“由于” (do, bởi vì)", "d": "由于 + nguyên nhân + 致使 + kết quả", "ex": [["由于U盘遗失致使47名病人信息泄露。", "Yóuyú Upán yíshī zhìshǐ47 míng bìngrén xìnxī xièlòu.", ""]]}, {"t": "“通过...来...” (thông qua... để...)", "d": "Cách dùng: Chỉ phương thức, cách thức thực hiện hành động.", "ex": [["通过软件或外加芯片来完成的；通过一些技术手段很容易破解。", "Tōngguò ruǎnjiàn huò wàijiā xīnpiàn lái wánchéng de; tōngguò yìxiē jìshùshǒuduàn hěn róngyì pòjiě.", ""]]}, {"t": "“并未” (vẫn chưa, không hề)", "d": "", "ex": [["写入芯片的数据并未进行加密。", "Xiěrù xīnpiàn de shùjù bìngwèi jìnxíng jiāmì.", ""]]}, {"t": "“与...相比” (so với...)", "d": "与 + A + 相比，B + ... Cách dùng: Cấu trúc so sánh đối chiếu.", "ex": [["与普通具有加密功能的U盘相比，“成功者”安全U盘具有与众不同的特点。", "Yǔ pǔtōng jùyǒu jiāmì gōngnéng de Upán xiāngbǐ, “Chénggōngzhě” ānquán Upán jùyǒu yǔzhòngbùtóng de tèdiǎn.", ""]]}], "order": [], "u": {"gq": [{"s": "虽然……但是……却……", "d": "Tuy… nhưng… lại….", "ok": "U盘本身虽然不值钱，但是存储在U盘内的数据却是无价的。", "vi": "USB tuy không đáng tiền nhưng dữ liệu bên trong lại vô giá.", "bad": ["U盘本身虽然不值钱，所以存储在U盘内的数据却是无价的。", "U盘本身虽然不值钱，但是却存储在U盘内的数据是无价的。"]}, {"s": "由于……致使……", "d": "Do… dẫn đến… (kết quả xấu).", "ok": "由于U盘遗失致使47名病人信息泄露。", "vi": "Do mất USB dẫn đến lộ thông tin 47 bệnh nhân.", "bad": ["由于U盘遗失所以致使47名病人信息泄露了吗。", "致使U盘遗失由于47名病人信息泄露。"]}, {"s": "与……相比", "d": "So với….", "ok": "与普通的加密U盘相比，“成功者”U盘与众不同。", "vi": "So với USB mã hóa thường, USB “Thành Công” rất khác biệt.", "bad": ["与普通的加密U盘比相，“成功者”U盘与众不同。", "相比与普通的加密U盘，“成功者”U盘与众不同。"]}, {"s": "即便是……也……", "d": "Ngay cả… cũng….", "ok": "即便是专业人员，也无法破解存储的数据。", "vi": "Ngay cả chuyên gia cũng không thể bẻ khóa dữ liệu.", "bad": ["即便是专业人员，就无法破解存储的数据。", "即便是专业人员，才无法破解存储的数据。"]}, {"s": "为了……", "d": "Để… (mục đích, đứng đầu câu).", "ok": "为了方便用户共享数据，U盘设有公共区。", "vi": "Để tiện người dùng chia sẻ dữ liệu, USB có vùng chung.", "bad": ["为了方便用户共享数据，所以U盘设有为公共区。", "U盘设有公共区为了，方便用户共享数据。"]}], "disc": [{"q": "你怎么保护自己的个人信息？", "py": "Nǐ zěnme bǎohù zìjǐ de gerénxìnxī?", "vi": "Bạn bảo vệ thông tin cá nhân của mình thế nào?", "keys": ["为了", "即便是……也|即使……也", "与……相比"], "sample": "为了保护个人信息，我的手机和电脑都设了密码。即便是好朋友，我也不告诉他们我的密码。与以前相比，现在网上的风险更大，所以要更小心。", "spy": "Wèile bǎohù gerénxìnxī, wǒ de shǒujī hé diànnǎo dōu shè le mìmǎ. Jíbiàn shì hǎo péngyou, wǒ yě bú gàosu tāmen wǒ de mìmǎ. Yǔ yǐqián xiāngbǐ, xiànzài wǎngshàng de fēngxiǎn gèngdà, suǒyǐ yào gèng xiǎoxīn."}], "comp": [{"vi": "Để bảo vệ dữ liệu, chúng ta nên đặt mật khẩu. (为了)", "keys": ["为了"], "model": "为了保护数据，我们应该设密码。", "mpy": "Wèile bǎohù shùjù, wǒmen yīnggāi shè mìmǎ."}, {"vi": "Ngay cả thầy giáo cũng không trả lời được câu hỏi này. (即便是……也……)", "keys": ["即便", "也"], "model": "即便是老师，也回答不了这个问题。", "mpy": "Jíbiàn shì lǎoshī, yě huídá bùliǎo zhège wèntí."}, {"vi": "So với năm ngoái, năm nay lạnh hơn. (与……相比)", "keys": ["与", "相比"], "model": "与去年相比，今年更冷。", "mpy": "Yǔ qùnián xiāngbǐ, jīnnián gèng lěng."}], "ex": [{"q": "U盘有什么优点和缺点？", "qvi": "USB có ưu điểm và nhược điểm gì?", "a": "体积小、携带方便，但容易丢失数据。", "avi": "Nhỏ, tiện mang theo, nhưng dễ mất dữ liệu.", "bad": ["价格很贵，但存储很快。", "很重，不方便携带。"], "p": 0}, {"q": "某医院发生了什么事？", "qvi": "Ở một bệnh viện đã xảy ra chuyện gì?", "a": "因为U盘遗失，47名病人的信息泄露了。", "avi": "Vì mất USB, thông tin 47 bệnh nhân bị lộ.", "bad": ["医院买了47个新U盘。", "医生把电脑弄坏了。"], "p": 0}, {"q": "市场上很多加密U盘有什么问题？", "qvi": "Nhiều USB mã hóa trên thị trường có vấn đề gì?", "a": "写入芯片的数据并未加密，用技术手段很容易破解。", "avi": "Dữ liệu ghi vào chip không được mã hóa, dễ bị bẻ khóa.", "bad": ["它们太贵了。", "它们不能存数据。"], "p": 1}, {"q": "“成功者”安全U盘的公共区和加密区有什么不同？", "qvi": "Vùng chung và vùng mã hóa khác nhau thế nào?", "a": "公共区不需要密码，加密区用来保存重要的机密资料。", "avi": "Vùng chung không cần mật khẩu; vùng mã hóa lưu tài liệu mật.", "bad": ["公共区要输两次密码。", "两个区完全一样。"], "p": 2}, {"q": "输错10次密码以后会怎么样？", "qvi": "Nhập sai mật khẩu 10 lần thì sao?", "a": "U盘将被自动锁定，无法再进行任何操作。", "avi": "USB tự động bị khóa, không thao tác được nữa.", "bad": ["U盘会自动打开。", "U盘会给主人打电话。"], "p": 2}]}}, {"id": "hk4-l5", "no": 5, "day": "HK4 · Bài 5", "time": "09:30", "scene": "hall", "room": "hall", "cast": ["prof", "manager", "zhangdong", "tianfang"], "vi": "Lời khuyên của Khổng Tử", "zh": "孔子的忠告", "py": "Kǒngzi de zhōnggào", "shop": {"label": "孔子学堂", "sub": "Học đường Khổng Tử", "icon": "🏯"}, "vocab": [["孔子", "Kǒngzǐ", "Khổng Tử", ""], ["忠告", "zhōnggào", "lời khuyên trung thực, lời khuyên chân thành", ""], ["出任", "chūrèn", "nhận chức, nhậm chức", ""], ["地方官", "dìfāngguān", "quan địa phương", ""], ["智者", "zhìzhě", "người trí tuệ, bậc trí giả", ""], ["管理", "guǎnlǐ", "quản lý", ""], ["先有司", "xiān yǒu sī", "trước hết phải làm gương (có nghĩa là người quản lý phải làm tốt việc của mình trước)", ""], ["赦小过", "shè xiǎo guò", "tha thứ lỗi nhỏ", ""], ["举贤才", "jǔ xián cái", "tiến cử / trọng dụng người hiền tài", ""], ["表率", "biǎoshuài", "gương mẫu, làm gương", ""], ["出色", "chūsè", "xuất sắc", ""], ["专业", "zhuānyè", "chuyên nghiệp", ""], ["职业精神", "zhíyè jīngshén", "tinh thần nghề nghiệp", ""], ["下属", "xiàshǔ", "cấp dưới", ""], ["忠诚", "zhōngchéng", "trung thành", ""], ["追随", "zhuīsuí", "theo đuổi, đi theo", ""], ["胜任", "shèngrèn", "đảm nhiệm, có năng lực đảm nhận", ""], ["缺乏", "quēfá", "thiếu hụt, thiếu", ""], ["效力", "xiàolì", "phục vụ, làm việc cho (ai)", ""], ["要义", "yàoyì", "ý nghĩa quan trọng, yếu chỉ", ""], ["金无足赤，人无完人", "jīn wú zú chì, rén wú wán rén", "Vàng không có đủ, người không ai hoàn hảo (tương đương “nhân vô thập toàn”)", ""], ["选用", "xuǎnyòng", "chọn dùng", ""], ["大局", "dàjú", "đại cục, tổng thể, toàn cảnh", ""], ["总体", "zǒngtǐ", "tổng thể", ""], ["细节", "xìjié", "chi tiết", ""], ["宽容", "kuānróng", "khoan dung, rộng lượng", ""], ["缺点", "quēdiǎn", "khuyết điểm", ""], ["严格", "yángé", "nghiêm khắc", ""], ["宽松", "kuānsōng", "nới lỏng, thoải mái", ""], ["平衡", "pínghéng", "cân bằng", ""], ["艺术", "yìshù", "nghệ thuật", ""], ["重用", "zhòngyòng", "trọng dụng", ""], ["标准", "biāozhǔn", "tiêu chuẩn", ""], ["才能", "cáinéng", "tài năng, năng lực", ""], ["品德", "pǐndé", "phẩm đức, đạo đức", ""], ["德才兼备", "dé cái jiān bèi", "đức và tài đều có, vẹn cả đức lẫn tài", ""], ["技能", "jìnéng", "kỹ năng", ""], ["经验", "jīngyàn", "kinh nghiệm", ""], ["职业道德", "zhíyè dàodé", "đạo đức nghề nghiệp", ""], ["团队精神", "tuánduì jīngshén", "tinh thần đồng đội", ""]], "story": [{"c": "panda", "vi": "HK4 · Lời khuyên của Khổng Tử. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "manager", "zh": "孔子的一位朋友要去出任地方官了，就跑来问孔子：“先生，您是一位智者，您说我这个地方官该怎么当啊？”孔子说：“搞管理既可以很容易，也可以很不容易，我只能告诉你九个字：先有司，赦小过，举贤才。”", "py": "Kǒngzǐ de yí wèi péngyou yào qù chūrèn dìfāngguān le, jiù pǎo lái wèn Kǒngzǐ: “Xiānsheng, nín shì yí wèi zhìzhě, nín shuō wǒ zhège dìfāngguān gāi zěnme dāng a?” Kǒngzǐ shuō: “Gǎo guǎnlǐ jì kěyǐ hěn róngyì, yě kěyǐ hěn bù róngyì, wǒ zhǐ néng gàosu nǐ jiǔ gè zì: Xiān yǒu sī, shè xiǎo guò, jǔ xián cái.”", "vi": "Một người bạn của Khổng Tử sắp đi nhậm chức quan địa phương, liền chạy đến hỏi Khổng Tử: “Thưa tiên sinh, ngài là bậc trí giả, xin ngài cho biết tôi nên làm quan địa phương thế nào ạ?” Khổng Tử nói: “Làm quản lý thì có thể rất dễ, cũng có thể rất không dễ, tôi chỉ có thể nói với anh chín chữ: Tiên hữu ti, xá tiểu quá, cử hiền tài (Trước hết phải làm gương, tha thứ lỗi nhỏ, tiến cử người hiền tài).”"}, {"c": "prof", "zh": "孔子告诉朋友的九个字是什么？", "py": "Kǒngzi gàosu péngyou de jiǔge zì shì shénme?", "vi": "Chín chữ Khổng Tử nói với bạn là gì?"}, {"me": "Tiên hữu ti, xá tiểu quá, cử hiền tài.", "opts": [["先有司，赦小过，举贤才。", "Xiānyǒusī, shèxiǎoguò, jǔxián cái.", "Tiên hữu ti, xá tiểu quá, cử hiền tài."], ["学而时习之，不亦说乎。", "Xuéér shíxí zhī, bú yì shuōhū.", "(chưa đúng với bài)"], ["己所不欲，勿施于人。", "Jǐsuǒbúyù, wùshīyúrén.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "什么叫“先有司”呢？先有司，用今天的话来说，就是首先自己要做好表率。这里至少有两个意思：第一是自己要出色地、专业地完成自己的工作；第二是要在工作状态和职业精神上给下属带好头。这是做管理工作的基本要求。", "py": "Shénme jiào “xiān yǒu sī” ne? Xiān yǒu sī, yòng jīntiān de huà lái shuō, jiùshì shǒuxiān zìjǐ yào zuò hǎo biǎoshuài. Zhèlǐ zhìshǎo yǒu liǎng ge yìsi: Dì-yī shì zìjǐ yào chūsè de, zhuānyè de wánchéng zìjǐ de gōngzuò; dì-èr shì yào zài gōngzuò zhuàngtài hé zhíyè jīngshén shàng gěi xiàshǔ dài hǎo tóu. Zhè shì zuò guǎnlǐ gōngzuò de jīběn yāoqiú.", "vi": "“Tiên hữu ti” nghĩa là gì? Nói theo ngày nay, trước hết bản thân phải làm gương tốt. Ở đây ít nhất có hai ý: Thứ nhất, bản thân phải hoàn thành công việc một cách xuất sắc và chuyên nghiệp; thứ hai, phải làm gương cho cấp dưới về tác phong làm việc và tinh thần nghề nghiệp. Đó là yêu cầu cơ bản của công tác quản lý."}, {"c": "prof", "zh": "“先有司”用今天的话说是什么意思？", "py": "“Xiānyǒusī” yòng jīntiān dehuà shuō shì shénme yìsi?", "vi": "“先有司” nói theo ngày nay nghĩa là gì?"}, {"me": "Trước hết bản thân phải làm gương tốt.", "opts": [["首先自己要做好表率。", "Shǒuxiān zìjǐ yào zuòhǎo biǎoshuài.", "Trước hết bản thân phải làm gương tốt."], ["先找一个好秘书。", "Xiānzhǎo yíge hǎo mìshū.", "(chưa đúng với bài)"], ["先把下属管严。", "Xiān bǎ xiàshǔ guǎnyán.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "哪个下属会忠诚地追随一个不能胜任自己工作的领导呢？哪个下属会为一个缺乏职业精神的领导效力呢？所以，孔子说的“先有司”，是做好管理工作的第一要义。从一定意义上讲，有什么样的领导就有什么样的下属，有什么样的老板就有什么样的员工。", "py": "Nǎ ge xiàshǔ huì zhōngchéng de zhuīsuí yí ge bùnéng shèngrèn zìjǐ gōngzuò de lǐngdǎo ne? Nǎ ge xiàshǔ huì wèi yí ge quēfá zhíyè jīngshén de lǐngdǎo xiàolì ne? Suǒyǐ, Kǒngzǐ shuō de “xiān yǒu sī”, shì zuò hǎo guǎnlǐ gōngzuò de dì-yī yàoyì. Cóng yídìng yìyì shàng jiǎng, yǒu shénme yàng de lǐngdǎo jiù yǒu shénme yàng de xiàshǔ, yǒu shénme yàng de lǎobǎn jiù yǒu shénme yàng de yuángōng.", "vi": "Cấp dưới nào lại trung thành theo đuổi một người lãnh đạo không đủ năng lực làm việc của mình? Cấp dưới nào lại phục vụ cho một người lãnh đạo thiếu tinh thần nghề nghiệp? Vì vậy, điều Khổng Tử nói “tiên hữu ti” là nghĩa quan trọng đầu tiên để làm tốt công tác quản lý. Nói theo một nghĩa nhất định, có kiểu lãnh đạo nào thì có kiểu cấp dưới đó, có ông chủ nào thì có nhân viên đó."}, {"c": "manager", "zh": "什么叫“赦小过”呢？孔子的意思是说：金无足赤，人无完人，选用人才要看大局。如果一个人总体上能够胜任你安排的工作职位，那么在一些细节问题上，就应该宽容一些。没有哪个人没有缺点。所以，管理人要做到该严格的地方要严格，该宽松的地方要宽松。管理是一门平衡的艺术，谁不能宽容别人，也就不能很好地领导别人。", "py": "Shénme jiào “shè xiǎo guò” ne? Kǒngzǐ de yìsi shì shuō: Jīn wú zú chì, rén wú wán rén, xuǎnyòng réncái yào kàn dàjú. Rúguǒ yí ge rén zǒngtǐ shàng nénggòu shèngrèn nǐ ānpái de gōngzuò zhíwèi, nàme zài yìxiē xìjié wèntí shàng, jiù yīnggāi kuānróng yìxiē. Méiyǒu nǎ ge rén méiyǒu quēdiǎn. Suǒyǐ, guǎnlǐ rén yào zuò dào gāi yángé de dìfang yào yángé, gāi kuān sōng de dìfang yào kuān sōng. Guǎnlǐ shì yì mén pínghéng de yìshù, shuí bùnéng kuānróng biérén, yě jiù bùnéng hěn hǎo de lǐngdǎo biérén.", "vi": "“Xá tiểu quá” nghĩa là gì? Ý Khổng Tử là: Vàng không có đủ, người không ai hoàn hảo, chọn dùng nhân tài phải nhìn vào đại cục. Nếu một người về tổng thể có thể đảm nhiệm được vị trí công việc bạn sắp xếp, thì trong một số vấn đề chi tiết, nên khoan dung một chút. Không ai không có khuyết điểm. Vì vậy, người quản lý phải làm được chỗ nào cần nghiêm khắc thì nghiêm khắc, chỗ nào cần nới lỏng thì nới lỏng. Quản lý là một nghệ thuật cân bằng, ai không thể khoan dung với người khác thì cũng không thể lãnh đạo người khác tốt được."}, {"c": "prof", "zh": "“赦小过”是什么意思？", "py": "“Shèxiǎoguò” shì shénme yìsi?", "vi": "“赦小过” nghĩa là gì?"}, {"me": "Khoan dung với lỗi nhỏ, chọn người phải nhìn đại cục.", "opts": [["在细节问题上要宽容，选人要看大局。", "Zài xìjié wèntí shàngyào kuānróng, xuǎnrén yào kàn dàjú.", "Khoan dung với lỗi nhỏ, chọn người phải nhìn đại cục."], ["什么错误都不能原谅。", "Shénme cuòwù dōu bùnéng yuánliàng.", "(chưa đúng với bài)"], ["只用没有缺点的人。", "Zhǐyòng méiyǒu quēdiǎn de rén.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "什么是“举贤才”呢？就是要重用人才。贤才至少应该符合两个标准，第一是有才能，第二是有品德。真正的人才应该做到德才兼备，一方面具有胜任一个职位的知识、技能和经验，另一方面具有良好的职业道德，有团队精神。汉代第一位皇帝刘邦曾经说，搞战略，我不如张良；搞销售，开拓市场，我不如韩信；管行政，我不如萧何。这三个人都是杰出人才，而我能够用他们。国家兴起就是靠着这样的人才啊！", "py": "Shénme shì “jǔ xián cái” ne? Jiùshì yào zhòngyòng réncái. Xián cái zhìshào yīnggāi fúhé liǎng ge biāozhǔn, dì-yī shì yǒu cáinéng, dì-èr shì yǒu pǐndé. Zhēnzhèng de réncái yīnggāi zuò dào dé cái jiān bèi, yì fāngmiàn jùyǒu shèngrèn yí ge zhíwèi de zhīshi, jìnéng hé jīngyàn, lìng yì fāngmiàn jùyǒu liánghǎo de zhíyè dàodé, yǒu tuánduì jīngshén. Hàn dài dì-yī wèi huángdì Liú Bāng céngjīng shuō, gǎo zhànlüè, wǒ bùrú Zhāng Liáng; gǎo xiāoshòu, kāituò shìchǎng, wǒ bùrú Hán Xìn; guǎn xíngzhèng, wǒ bùrú Xiāo Hé. Zhè sān ge rén dōu shì jiéchū réncái, ér wǒ nénggòu yòng tāmen. Guójiā xīngqǐ jiùshì kàozhe zhèyàng de réncái a!", "vi": "“Cử hiền tài” là gì? Là trọng dụng nhân tài. Người hiền tài ít nhất phải đáp ứng hai tiêu chuẩn: thứ nhất là có tài năng, thứ hai là có phẩm đức. Nhân tài thực sự phải đạt được cả đức lẫn tài, một mặt có kiến thức, kỹ năng và kinh nghiệm để đảm nhiệm một vị trí, mặt khác có đạo đức nghề nghiệp tốt và tinh thần đồng đội. Vị hoàng đế đầu tiên của nhà Hán là Lưu Bang từng nói: Về chiến lược, tôi không bằng Trương Lương; về tiêu thụ, mở rộng thị trường, tôi không bằng Hàn Tín; về quản lý hành chính, tôi không bằng Tiêu Hà. Ba người này đều là nhân tài xuất chúng, mà tôi có thể sử dụng họ. Đất nước hưng thịnh chính là nhờ những nhân tài như vậy đó!"}, {"c": "prof", "zh": "刘邦为什么能成功？", "py": "Liúbāng wèishénme néng chénggōng?", "vi": "Vì sao Lưu Bang thành công?"}, {"me": "Vì ông dùng được những nhân tài như Trương Lương, Hàn Tín, Tiêu Hà.", "opts": [["因为他能用张良、韩信、萧何这样的杰出人才。", "Yīnwèi tā néng yòng zhāngliáng, hánxìn, xiāohé zhèyàng de jiéchūréncái.", "Vì ông dùng được những nhân tài như Trương Lương, Hàn Tín, Tiêu Hà."], ["因为他自己什么都会。", "Yīnwèi tā zìjǐ shénme dōu huì.", "(chưa đúng với bài)"], ["因为他不需要人才。", "Yīnwèi tā bù xūyào réncái.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "一流的人才造就一流的公司，二流的人才造就二流的公司。管理者遇到公司管理问题时，不妨先看看自己的左右：我们到底拥有什么样的人才？“先有司，赦小过，举贤才”，这三条忠告是两千多年前孔子说的，直到今日仍然对管理者有警示作用。", "py": "Yīliú de réncái zàojiù yīliú de gōngsī, èrliú de réncái zàojiù èrliú de gōngsī. Guǎnlǐzhě yù dào gōngsī guǎnlǐ wèntí shí, bùfáng xiān kànkan zìjǐ de zuǒyòu: wǒmen dàodǐ yōngyǒu shénme yàng de réncái? “Xiān yǒu sī, shè xiǎo guò, jǔ xián cái”, zhè sān tiáo zhōnggào shì liǎng qiān duō nián qián Kǒngzǐ shuō de, zhí dào jīnrì réngrán duì guǎnlǐzhě yǒu jǐngshì zuòyòng.", "vi": "Nhân tài hạng nhất tạo nên công ty hạng nhất, nhân tài hạng nhì tạo nên công ty hạng nhì. Khi người quản lý gặp vấn đề trong quản lý công ty, chẳng hãy nhìn xung quanh mình trước: chúng ta rốt cuộc có loại nhân tài nào? “Tiên hữu ti, xá tiểu quá, cử hiền tài” – ba lời khuyên này là của Khổng Tử cách đây hơn hai nghìn năm, đến nay vẫn có tác dụng cảnh tỉnh đối với người quản lý."}, {"c": "prof", "zh": "作者认为管理者遇到问题时应该先做什么？", "py": "Zuòzhě rènwéi guǎnlǐzhě yùdào wèntí shí yīnggāi xiān zuò shénme?", "vi": "Tác giả cho rằng nhà quản lý gặp vấn đề nên làm gì trước?"}, {"me": "Xem lại những người bên cạnh, thực sự có nhân tài nào.", "opts": [["先看看自己的左右，到底拥有什么样的人才。", "Xiān kànkan zìjǐ de zuǒyòu, dàodǐ yōngyǒu shénmeyàng de réncái.", "Xem lại những người bên cạnh, thực sự có nhân tài nào."], ["马上换一个公司。", "Mǎshàng huàn yíge gōngsī.", "(chưa đúng với bài)"], ["先批评所有的员工。", "Xiān pīpíng suǒyǒu de yuángōng.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“既……也……” (jì... yě...)", "d": "Vừa... cũng... (diễn tả hai trạng thái cùng tồn tại) Phân tích: Gǎo guǎnlǐ jì kěyǐ hěn róngyì, yě kěyǐ hěn bù róngyì.", "ex": [["搞管理既可以很容易，也可以很不容易。", "Gǎo guǎnlǐ jì kěyǐ hěn róngyì, yě kěyǐ hěn bù róngyì.", ""]]}, {"t": "“用今天的话来说” (yòng jīntiān de huà lái shuō)", "d": "Nói theo cách nói ngày hôm nay / nói một cách hiện đại 用 + [cách nói] + 来说 = dùng cách nói... để mà nói", "ex": [["先有司，用今天的话来说，就是首先自己要做好表率。", "Xiānyǒusī, yòng jīntiān dehuà láishuō, jiùshì shǒuxiān zìjǐ yào zuòhǎo biǎoshuài.", ""]]}, {"t": "“哪个……呢？” (nǎ ge... ne?)", "d": "Câu hỏi tu từ (rhetorical question): \"Có ... nào ... đâu?\"", "ex": [["哪个下属会忠诚地追随一个不能胜任自己工作的领导呢？", "Nǎge xiàshǔ huì zhōngchéng dì zhuīsuí yíge bùnéng shèngrèn zìjǐ gōngzuò de lǐngdǎo ne?", ""]]}, {"t": "“有什么样的……就有什么样的……” (yǒu shénme yàng de... jiù yǒu shénme yàng de...)", "d": "Có kiểu ... nào thì có kiểu ... ấy (quan hệ nhân quả / tương ứng)", "ex": [["有什么样的领导就有什么样的下属，有什么样的老板就有什么样的员工。", "Yǒu shénmeyàng de lǐngdǎo jiù yǒu shénmeyàng de xiàshǔ, yǒu shénmeyàng de lǎobǎn jiù yǒu shénmeyàng de yuángōng.", ""]]}, {"t": "“没有……没有……” (méiyǒu... méiyǒu...) – dạng nhấn mạnh", "d": "Không có ... nào mà không ...", "ex": [["没有哪个人没有缺点。", "Méiyǒu nǎge rén méiyǒu quēdiǎn.", "Ai cũng có khuyết điểm"]]}, {"t": "“谁不……，也就不能……” (shuí bù..., yě jiù bùnéng...)", "d": "Ai không ... thì cũng không thể ...", "ex": [["谁不能宽容别人，也就不能很好地领导别人。", "Shuí bùnéng kuānróng biérén, yě jiù bùnéng hěn hǎo dì lǐngdǎo biérén.", ""]]}, {"t": "“一方面……另一方面……” (yì fāngmiàn... lìng yì fāngmiàn...)", "d": "Một mặt..., mặt khác...", "ex": [["一方面具有胜任一个职位的知识、技能和经验，另一方面具有良好的职业道德，有团队精神。", "Yìfāngmiàn jùyǒu shèngrèn yíge zhíwèi de zhīshí, jìnéng hé jīngyàn, lìngyìfāngmiàn jùyǒu liánghǎo de zhíyèdàodé, yǒu tuánduìjīngshén.", ""]]}, {"t": "“不如” (bùrú)", "d": "Không bằng / thua kém", "ex": [["搞战略，我不如张良。", "Gǎo zhànlüè, wǒ bùrú zhāngliáng.", ""]]}], "order": [], "u": {"gq": [{"s": "既……也……", "d": "Vừa… cũng… (hai khả năng cùng tồn tại).", "ok": "搞管理既可以很容易，也可以很不容易。", "vi": "Làm quản lý vừa có thể rất dễ, cũng có thể rất không dễ.", "bad": ["搞管理既可以很容易，又也可以很不容易。", "搞管理也可以很容易，既可以很不容易。"]}, {"s": "有什么样的……就有什么样的……", "d": "Có… thế nào thì có… thế ấy.", "ok": "有什么样的领导就有什么样的下属。", "vi": "Có lãnh đạo thế nào thì có cấp dưới thế ấy.", "bad": ["有什么样的领导才有什么样的下属。", "什么样的领导有就有什么样的下属。"]}, {"s": "哪个……呢？(phản vấn)", "d": "Câu hỏi tu từ: có ai… đâu?", "ok": "哪个下属会忠诚地追随一个不能胜任工作的领导呢？", "vi": "Cấp dưới nào lại trung thành theo lãnh đạo không làm nổi việc?", "bad": ["哪个下属会忠诚地追随一个不能胜任工作的领导吗呢？", "下属哪个会忠诚地追随呢一个不能胜任工作的领导？"]}, {"s": "谁不……，也就不能……", "d": "Ai không… thì cũng không thể….", "ok": "谁不能宽容别人，也就不能很好地领导别人。", "vi": "Ai không khoan dung người khác thì cũng không lãnh đạo tốt được.", "bad": ["谁不能宽容别人，就也不能很好地领导别人。", "谁不能宽容别人，也就能很好地领导别人。"]}, {"s": "不妨", "d": "Chẳng ngại gì, cứ thử… (gợi ý nhẹ).", "ok": "管理者遇到问题时，不妨先看看自己的左右。", "vi": "Nhà quản lý gặp vấn đề thì cứ thử xem lại người bên cạnh.", "bad": ["管理者遇到问题时，先不妨不看看自己的左右。", "管理者遇到问题时，不妨了先看看自己的左右。"]}], "disc": [{"q": "你同意“有什么样的领导就有什么样的下属”吗？", "py": "Nǐ tóngyì “Yǒu shénmeyàng de lǐngdǎo jiù yǒu shénmeyàng de xiàshǔ” ma?", "vi": "Bạn có đồng ý “lãnh đạo thế nào thì cấp dưới thế ấy” không?", "keys": ["既……也|既……又", "如果……就|如果……那么", "不妨"], "sample": "我同意。领导既要专业，也要有职业精神。如果领导自己做不好，下属就不会忠诚地追随他。我们当班长的时候，也不妨先做好表率。", "spy": "Wǒ tóngyì. Lǐngdǎo jì yào zhuānyè, yě yào yǒu zhíyè jīngshén. Rúguǒ lǐngdǎo zìjǐ zuò bùhǎo, xiàshǔ jiù búhuì zhōngchéng dì zhuīsuí tā. Wǒmen dāng bānzhǎng de shíhou, yě bùfáng xiān zuòhǎo biǎoshuài."}], "comp": [{"vi": "Học tiếng Trung vừa có thể rất thú vị, cũng có thể rất khó. (既……也……)", "keys": ["既", "也"], "model": "学汉语既可以很有意思，也可以很难。", "mpy": "Xué hànyǔ jì kěyǐ hěn yǒu yìsi, yě kěyǐ hěnnán."}, {"vi": "Nếu chưa hiểu, bạn cứ thử hỏi thầy giáo. (不妨)", "keys": ["不妨"], "model": "如果不懂，你不妨问问老师。", "mpy": "Rúguǒ bù dǒng, nǐ bùfáng wènwèn lǎoshī."}, {"vi": "Có thầy giáo thế nào thì có học sinh thế ấy. (有什么样的……就有什么样的……)", "keys": ["有什么样的", "就有什么样的"], "model": "有什么样的老师，就有什么样的学生。", "mpy": "Yǒu shénmeyàng de lǎoshī, jiù yǒu shénmeyàng de xuéshēng."}], "ex": [{"q": "孔子告诉朋友的九个字是什么？", "qvi": "Chín chữ Khổng Tử nói với bạn là gì?", "a": "先有司，赦小过，举贤才。", "avi": "Tiên hữu ti, xá tiểu quá, cử hiền tài.", "bad": ["学而时习之，不亦说乎。", "己所不欲，勿施于人。"], "p": 0}, {"q": "“先有司”用今天的话说是什么意思？", "qvi": "“先有司” nói theo ngày nay nghĩa là gì?", "a": "首先自己要做好表率。", "avi": "Trước hết bản thân phải làm gương tốt.", "bad": ["先找一个好秘书。", "先把下属管严。"], "p": 1}, {"q": "“赦小过”是什么意思？", "qvi": "“赦小过” nghĩa là gì?", "a": "在细节问题上要宽容，选人要看大局。", "avi": "Khoan dung với lỗi nhỏ, chọn người phải nhìn đại cục.", "bad": ["什么错误都不能原谅。", "只用没有缺点的人。"], "p": 3}, {"q": "刘邦为什么能成功？", "qvi": "Vì sao Lưu Bang thành công?", "a": "因为他能用张良、韩信、萧何这样的杰出人才。", "avi": "Vì ông dùng được những nhân tài như Trương Lương, Hàn Tín, Tiêu Hà.", "bad": ["因为他自己什么都会。", "因为他不需要人才。"], "p": 4}, {"q": "作者认为管理者遇到问题时应该先做什么？", "qvi": "Tác giả cho rằng nhà quản lý gặp vấn đề nên làm gì trước?", "a": "先看看自己的左右，到底拥有什么样的人才。", "avi": "Xem lại những người bên cạnh, thực sự có nhân tài nào.", "bad": ["马上换一个公司。", "先批评所有的员工。"], "p": 5}]}}, {"id": "hk4-l6", "no": 6, "day": "HK4 · Bài 6", "time": "16:00", "scene": "living", "room": "living", "cast": ["prof", "roland", "lee", "edward"], "vi": "Không so bì mới là quý", "zh": "不比为贵", "py": "Bùbǐwèi guì", "shop": {"label": "心理咨询室", "sub": "Phòng tư vấn tâm lý", "icon": "🧘"}, "vocab": [["不比为贵", "bù bǐ wéi guì", "Không so bề là quý (không so sánh mới là quý)", ""], ["心态", "xīntài", "tâm thế, tâm trạng, thái độ tâm lý", ""], ["攀比", "pānbǐ", "so sánh (theo hướng ganh đua, hơn thua)", ""], ["接受", "jiēshòu", "tiếp nhận, chấp nhận", ""], ["满足", "mǎnzú", "hài lòng, thỏa mãn", ""], ["如意", "rúyì", "như ý, vừa ý", ""], ["客观", "kèguān", "khách quan", ""], ["条件", "tiáojiàn", "điều kiện", ""], ["引起", "yǐnqǐ", "gây ra, dẫn đến", ""], ["心理平衡", "xīnlǐ pínghéng", "cân bằng tâm lý", ""], ["俗话说", "súhuà shuō", "tục ngữ nói", ""], ["气死人", "qì sǐ rén", "tức chết người (nghĩa bóng)", ""], ["享受", "xiǎngshòu", "hưởng thụ, tận hưởng", ""], ["文史", "wénshǐ", "văn học sử học", ""], ["长寿秘诀", "chángshòu mìjué", "bí quyết sống lâu / trường thọ", ""], ["财富", "cáifù", "của cải, tài sản", ""], ["地位", "dìwèi", "địa vị", ""], ["遗憾", "yíhàn", "tiếc nuối, hối tiếc", ""], ["体验", "tǐyàn", "trải nghiệm, thể nghiệm", ""], ["尽管", "jǐnguǎn", "mặc dù", ""], ["坎坷", "kǎnkě", "gian truân, gập ghềnh", ""], ["坦然", "tǎnrán", "thản nhiên, bình thản", ""], ["乐观", "lèguān", "lạc quan", ""], ["办报", "bàn bào", "làm báo, xuất bản báo", ""], ["著述", "zhùshù", "trước tác, viết sách", ""], ["高龄", "gāolíng", "tuổi cao, thọ", ""], ["著名", "zhùmíng", "nổi tiếng", ""], ["命运", "mìngyùn", "số phận", ""], ["不幸", "bùxìng", "bất hạnh, không may", ""], ["口不能言", "kǒu bùnéng yán", "miệng không nói được", ""], ["思维", "sīwéi", "tư duy, suy nghĩ", ""], ["终生", "zhōngshēng", "cả đời, trọn đời", ""], ["追求", "zhuīqiú", "theo đuổi", ""], ["理想", "lǐxiǎng", "lý tưởng", ""], ["病痛缠身", "bìngtòng chánshēn", "bệnh tật giày vò, quấn thân", ""], ["充实", "chōngshí", "phong phú, đầy đủ, dồi dào", ""], ["传奇色彩", "chuánqí sècǎi", "màu sắc huyền thoại, tính chất truyền kỳ", ""], ["脚踏实地", "jiǎotàshídì", "thực tế, vững vàng (đi đứng trên đất thực)", ""], ["好高骛远", "hàogāowùyuǎn", "thích viển vông, cao xa, không thực tế", ""], ["调整", "tiáozhěng", "điều chỉnh", ""]], "story": [{"c": "panda", "vi": "HK4 · Không so bì mới là quý. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "roland", "zh": "生活中要有“不比为贵”的心态，也就是不和人攀比。学会接受自己，满足于自己从生活中所得到的。有些人总感到这不如意那不如意，并不是客观条件太差，而是由于攀比引起的心理不平衡。俗话说：人比人，气死人。因此，要想享受人生的欢乐与幸福，还有很重要的一点就是要学习“不比为贵”的心态。", "py": "Shēnghuó zhōng yào yǒu “bù bǐ wéi guì” de xīntài, yě jiùshì bù hé rén pānbǐ. Xuéhuì jiēshòu zìjǐ, mǎnzú yú zìjǐ cóng shēnghuó zhōng suǒ dédào de. Yǒuxiē rén zǒng gǎndào zhè bùrúyì nà bùrúyì, bìng bùshì kèguān tiáojiàn tài chà, ér shì yóuyú pānbǐ yǐnqǐ de xīnlǐ bù pínghéng. Súhuà shuō: Rén bǐ rén, qì sǐ rén. Yīncǐ, yào xiǎng xiǎngshòu rénshēng de huānlè yǔ xìngfú, hái yǒu hěn zhòngyào de yì diǎn jiùshì yào xuéxí “bù bǐ wéi guì” de xīntài.", "vi": "Trong cuộc sống cần có tâm thế \"không so bề là quý\", tức là không so sánh với người khác. Học cách chấp nhận bản thân, hài lòng với những gì mình có được từ cuộc sống. Có những người luôn cảm thấy chỗ này không vừa ý, chỗ kia không như ý, thực ra không phải vì điều kiện khách quan quá kém, mà là do tâm lý mất cân bằng gây ra bởi sự so sánh. Tục ngữ có câu: \"Người so với người, tức chết người\". Vì vậy, để tận hưởng niềm vui và hạnh phúc của cuộc sống, có một điểm rất quan trọng là phải học tâm thế \"không so bề là quý\"."}, {"c": "prof", "zh": "“不比为贵”是什么意思？", "py": "“Bùbǐwèi guì” shì shénme yìsi?", "vi": "“不比为贵” nghĩa là gì?"}, {"me": "Không so bì với người khác, hài lòng với những gì mình có.", "opts": [["不和别人攀比，满足于自己从生活中得到的。", "Bù hé biérén pānbǐ, mǎnzú yú zìjǐ cóng shēnghuó zhōng dédào de.", "Không so bì với người khác, hài lòng với những gì mình có."], ["什么东西都不比较便宜。", "Shénme dōngxi dōu bù bǐjiào piányi.", "(chưa đúng với bài)"], ["一定要比别人强。", "Yídìng yào bǐ biérén qiáng.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "文史作家郑逸梅先生的长寿秘诀便是“不比为贵”。郑先生常对人说：我不去跟人家比什么财富地位，也不会为缺少这些感到遗憾。我体验过自己的工作、生活的快乐，非常满足。正因为郑老有这样良好的心态，尽管他经历坎坷，却能始终保持坦然、乐观的精神。他一生办报，著述丰富，活到了90多岁高龄。", "py": "Wénshǐ zuòjiā Zhèng Yìméi xiānsheng de chángshòu mìjué biàn shì “bù bǐ wéi guì”. Zhèng xiānsheng cháng duì rén shuō: Wǒ bú qù gēn rénjia bǐ shénme cáifù dìwèi, yě bú huì wèi quēshǎo zhèxiē gǎndào yíhàn. Wǒ tǐyàn guò zìjǐ de gōngzuò, shēnghuó de kuàilè, fēicháng mǎnzú. Zhèng yīnwèi Zhèng lǎo yǒu zhèyàng liánghǎo de xīntài, jǐnguǎn tā jīnglì kǎnkě, què néng shǐzhōng bǎochí tǎnrán, lèguān de jīngshén. Tā yīshēng bàn bào, zhùshù fēngfù, huó dào le 90 duō suì gāolíng.", "vi": "Bí quyết trường thọ của nhà văn sử học Trịnh Dật Mai chính là \"không so bề là quý\". Ông Trịnh thường nói với mọi người: Tôi không đi so sánh với người khác về giàu sang, địa vị, cũng không vì thiếu những thứ đó mà cảm thấy tiếc nuối. Tôi đã trải nghiệm niềm vui trong công việc và cuộc sống của mình, rất hài lòng. Chính vì cụ Trịnh có tâm thế tốt như vậy, mặc dù trải qua nhiều gian truân, nhưng ông vẫn luôn giữ được tinh thần thản nhiên, lạc quan. Cả đời ông làm báo, trước tác phong phú, sống tới hơn 90 tuổi cao."}, {"c": "prof", "zh": "郑逸梅先生长寿的秘诀是什么？", "py": "Zhèngyìméi xiānsheng chángshòu de mìjué shì shénme?", "vi": "Bí quyết sống lâu của Trịnh Dật Mai là gì?"}, {"me": "Không so tiền tài địa vị, hài lòng với niềm vui công việc và cuộc sống.", "opts": [["不跟人家比财富地位，满足于工作和生活的快乐。", "Bù gēn rénjiā bǐ cáifù dìwèi, mǎnzú yú gōngzuò hé shēnghuó de kuàilè.", "Không so tiền tài địa vị, hài lòng với niềm vui công việc và cuộc sống."], ["每天运动三个小时。", "Měitiān yùndòng sānge xiǎoshí.", "(chưa đúng với bài)"], ["只吃素菜。", "Zhǐ chī sùcài.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "著名科学家斯蒂芬·霍金的命运很不幸：口不能言，腿不能站，身不能动。可霍金却说：“我的手指还能活动；我的大脑还能思维；我有终生追求的理想；有我爱和爱我的亲人和朋友。”他病痛缠身仍感到充实而快乐，而他的健康心态使他成为当今最具传奇色彩的科学家。", "py": "Zhùmíng kēxuéjiā Sīdìfēn·Huòjīn de mìngyùn hěn bùxìng: kǒu bùnéng yán, tuǐ bùnéng zhàn, shēn bùnéng dòng. Kě Huòjīn què shuō: “Wǒ de shǒuzhǐ hái néng huódòng; wǒ de dànǎo hái néng sīwéi; wǒ yǒu zhōngshēng zhuīqiú de lǐxiǎng; yǒu wǒ ài hé ài wǒ de qīnrén hé péngyou.” Tā bìngtòng chánshēn réng gǎndào chōngshí ér kuàilè, ér tā de jiànkāng xīntài shǐ tā chéngwéi dāngjīn zuì jù chuánqí sècǎi de kēxuéjiā.", "vi": "Số phận của nhà khoa học nổi tiếng Stephen Hawking rất bất hạnh: miệng không nói được, chân không đứng được, thân không cử động được. Nhưng Hawking lại nói: \"Ngón tay tôi vẫn còn hoạt động được; não tôi vẫn còn suy nghĩ được; tôi có lý tưởng theo đuổi cả đời; có người thân và bạn bè mà tôi yêu và yêu tôi.\" Ông bị bệnh tật giày vò nhưng vẫn cảm thấy phong phú và vui vẻ, và tâm thế lành mạnh của ông đã khiến ông trở thành nhà khoa học có màu sắc huyền thoại nhất hiện nay."}, {"c": "prof", "zh": "霍金为什么仍然感到充实而快乐？", "py": "Huòjīn wèishénme réngrán gǎndào chōngshí ér kuàilè?", "vi": "Vì sao Hawking vẫn thấy đầy đủ và vui vẻ?"}, {"me": "Ông thấy mình còn tư duy được, có lý tưởng, có người thân bạn bè yêu thương.", "opts": [["他看到自己还能思维，有理想，有爱他的亲人朋友。", "Tā kàndào zìjǐ hái néng sīwéi, yǒu lǐxiǎng, yǒu ài tā de qīnrén péngyou.", "Ông thấy mình còn tư duy được, có lý tưởng, có người thân bạn bè yêu thương."], ["因为他很有钱。", "Yīnwèi tā hěn yǒuqián.", "(chưa đúng với bài)"], ["因为他的病好了。", "Yīnwèi tā de bìng hǎo le.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "研究发现，脚踏实地的人往往比那些好高骛远的人快乐。因此，要想生活快乐，就要学会根据自己的实际情况来调整目标。虽然财富可以带给人幸福感，但并不是财富越多越幸福。研究表明，一旦人的基本生存需要得到满足后，财富的增加对幸福本身都不再具有任何特殊意义。另外，幸福的人总是不断地为自己树立一些目标，而目标的实现也能给我们带来幸福的感受。", "py": "Yánjiū fāxiàn, jiǎotàshídì de rén wǎngwǎng bǐ nàxiē hàogāowùyuǎn de rén kuàilè. Yīncǐ, yào xiǎng shēnghuó kuàilè, jiù yào xuéhuì gēnjù zìjǐ de shíjì qíngkuàng lái tiáozhěng mùbiāo. Suīrán cáifù kěyǐ dài gěi rén xìngfú gǎn, dàn bìng bùshì cáifù yuè duō yuè xìngfú. Yánjiū biǎomíng, yídàn rén de jīběn shēngcún xūyào dédào mǎnzú hòu, cáifù de zēngjiā duì xìngfú běnshēn dōu bú zài jùyǒu rènhé tèshū yìyì. Lìngwài, xìngfú de rén zǒngshì búduàn de wèi zìjǐ shùlì yìxiē mùbiāo, ér mùbiāo de shíxiàn yě néng gěi wǒmen dài lái xìngfú de gǎnshòu.", "vi": "Nghiên cứu phát hiện rằng, những người thực tế, vững vàng thường vui vẻ hơn những người thích viển vông, cao xa. Vì vậy, muốn sống vui vẻ, phải học cách điều chỉnh mục tiêu dựa trên tình hình thực tế của bản thân. Tuy giàu sang có thể mang lại cho con người cảm giác hạnh phúc, nhưng không phải càng nhiều tiền thì càng hạnh phúc. Nghiên cứu chỉ ra rằng, một khi nhu cầu sinh tồn cơ bản của con người được đáp ứng, thì sự gia tăng của cải không còn mang ý nghĩa đặc biệt nào đối với bản thân hạnh phúc nữa. Ngoài ra, người hạnh phúc luôn không ngừng đặt ra cho mình một số mục tiêu, và việc đạt được mục tiêu cũng mang lại cho chúng ta cảm giác hạnh phúc."}, {"c": "prof", "zh": "研究发现财富和幸福有什么关系？", "py": "Yánjiū fāxiàn cáifù hé xìngfú yǒu shénme guānxi?", "vi": "Nghiên cứu cho thấy tài sản và hạnh phúc liên quan thế nào?"}, {"me": "Khi nhu cầu cơ bản được đáp ứng, thêm tiền không còn ý nghĩa đặc biệt với hạnh phúc.", "opts": [["基本需要满足以后，财富增加对幸福不再有特殊意义。", "Jīběn xūyào mǎnzú yǐhòu, cáifù zēngjiā duì xìngfú búzài yǒu tèshū yìyì.", "Khi nhu cầu cơ bản được đáp ứng, thêm tiền không còn ý nghĩa đặc biệt với hạnh phúc."], ["财富越多越幸福。", "Cáifù yuèduōyuè xìngfú.", "(chưa đúng với bài)"], ["没有钱的人最幸福。", "Méiyǒu qián de rén zuì xìngfú.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "美国华裔数学家王章程，就读于美国加州大学。毕业后，他的同学多数去了大财团、大公司，只有王章程一头扎进了研究室，一干就是十年。十年中，他的生活收入一直很低，而不少同学都成了收入不菲的大老板。而王先生从来不羡慕别人的财富，只对自己的事业感兴趣。35岁的时候，他攻克了两道世界级数学难题，从此研究成果不断出现，成为世界数学界的新星。面对荣誉，他十分平静，继续以自己的研究中得到满足。", "py": "Měiguó Huáyì shùxuéjiā Wáng Zhāngchéng, jiùdú yú Měiguó Jiāzhōu Dàxué. Bìyè hòu, tā de tóngxué duōshù qù le dà cáituán, dà gōngsī, zhǐyǒu Wáng Zhāngchéng yì tóu zhā jìn le yánjiūshì, yí gàn jiù shì shí nián. Shí nián zhōng, tā de shēnghuó shōurù yìzhí hěn dī, ér bùshǎo tóngxué dōu chéng le shōurù bùfěi de dà lǎobǎn. Ér Wáng xiānsheng cónglái bù xiànmù biérén de cáifù, zhǐ duì zìjǐ de shìyè gǎn xìngqù. 35 suì de shíhou, tā gōngkè le liǎng dào shìjiè jí shùxué nántí, cóngcǐ yánjiū chéngguǒ búduàn chūxiàn, chéngwéi shìjiè shùxuéjiè de xīnxīng. Miànduì róngyù, tā shífēn píngjìng, jìxù yǐ zìjǐ de yánjiū zhōng dédào mǎnzú.", "vi": "Nhà toán học người Mỹ gốc Hoa Vương Chương Trình, theo học tại Đại học California (Mỹ). Sau khi tốt nghiệp, phần lớn bạn cùng lớp của ông đã vào các tập đoàn tài chính lớn, công ty lớn, chỉ có Vương Chương Trình một đầu lao vào phòng nghiên cứu, làm liền mười năm. Trong mười năm đó, thu nhập cuộc sống của ông luôn rất thấp, trong khi không ít bạn cùng lớp đã trở thành những ông chủ lớn có thu nhập cao. Nhưng ông Vương chưa bao giờ ngưỡng mộ tài sản của người khác, chỉ quan tâm đến sự nghiệp của mình. Năm 35 tuổi, ông đã giải được hai bài toán khó cấp thế giới, từ đó thành quả nghiên cứu liên tục xuất hiện, trở thành ngôi sao mới trong giới toán học thế giới. Đối diện với vinh dự, ông rất bình tĩnh, tiếp tục tìm thấy sự hài lòng từ nghiên cứu của mình."}, {"c": "prof", "zh": "王章程毕业后选择了什么？", "py": "Wáng zhāngchéng bìyè hòu xuǎnzé le shénme?", "vi": "Sau khi tốt nghiệp, Vương Chương Trình chọn gì?"}, {"me": "Vào phòng nghiên cứu mười năm, không ghen tị tiền của bạn.", "opts": [["进研究室做了十年研究，不羡慕同学的财富。", "Jìn yánjiūshì zuò le shínián yánjiū, bú xiànmù tóngxué de cáifù.", "Vào phòng nghiên cứu mười năm, không ghen tị tiền của bạn."], ["去大公司当老板。", "Qù dà gōngsī dāng lǎobǎn.", "(chưa đúng với bài)"], ["回国开了一个饭馆。", "Huíguó kāi le yíge fànguǎn.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "生活中常常打扰我们，让我们感到不安的，往往是别人的生活方式。如果心中总是跟别人比来比去，羡慕别人的生活，就会给自己带来烦恼和迷茫，甚至失去自我。要珍惜自己获得的，过好自己的生活，脚踏实地地追求自己的人生理想，一定能享受到属于自己的快乐。", "py": "Shēnghuó zhōng chángcháng dǎrǎo wǒmen, ràng wǒmen gǎndào bù'ān de, wǎngwǎng shì biérén de shēnghuó fāngshì. Rúguǒ xīnzhōng zǒng shì gēn biérén bǐ lái bǐ qù, xiànmù biérén de shēnghuó, jiù huì gěi zìjǐ dài lái fánnǎo hé míwáng, shènzhì shīqù zìwǒ. Yào zhēnxī zìjǐ huòdé de, guò hǎo zìjǐ de shēnghuó, jiǎotàshídì de zhuīqiú zìjǐ de rénshēng lǐxiǎng, yídìng néng xiǎngshòu dào shǔyú zìjǐ de kuàilè.", "vi": "Những điều thường quấy rầy chúng ta và khiến chúng ta bất an trong cuộc sống, thường là cách sống của người khác. Nếu trong lòng cứ so sánh với người khác, ngưỡng mộ cuộc sống của người khác, thì sẽ mang lại cho mình phiền não và mê mang, thậm chí đánh mất bản thân. Hãy trân trọng những gì mình có được, sống tốt cuộc sống của mình, theo đuổi lý tưởng cuộc đời một cách thực tế và vững chắc, nhất định sẽ được tận hưởng niềm vui thuộc về mình."}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“也就是” (yě jiùshì) → Cũng chính là / tức là", "d": "Trong cuộc sống cần có tâm thế \"không so bề là quý\", tức là không so sánh với người khác.", "ex": [["生活中要有“不比为贵”的心态，也就是不和人攀比。", "Shēnghuó zhōngyào yǒu “Bùbǐwèi guì” de xīntài, yě jiùshì bù hé rén pānbǐ.", ""]]}, {"t": "“并不是……，而是……” (bìng bùshì..., ér shì...) → Không phải là..., mà là...", "d": "Không phải vì điều kiện khách quan quá kém, mà là do tâm lý mất cân bằng gây ra bởi sự so sánh.", "ex": [["并不是客观条件太差，而是由于攀比引起的心理不平衡。", "Bìng búshì kèguāntiáojiàn tàichà, érshì yóuyú pānbǐ yǐnqǐ de xīnlǐ bù pínghéng.", ""]]}, {"t": "“俗话说” (súhuà shuō) → Tục ngữ nói", "d": "Tục ngữ nói: Người so với người, tức chết người.", "ex": [["俗话说：人比人，气死人。", "Súhuàshuō: Rénbǐrén, qìsǐrén.", ""]]}, {"t": "“要想……” (yào xiǎng...) → Muốn... (thì)", "d": "Muốn tận hưởng niềm vui và hạnh phúc của cuộc sống, thì còn một điểm rất quan trọng là...", "ex": [["要想享受人生的欢乐与幸福，还有很重要的一点就是...", "Yào xiǎng xiǎngshòu rénshēng de huānlè yǔ xìngfú, háiyǒu hěn zhòngyào de yìdiǎn jiùshì...", ""]]}, {"t": "“正因为……，尽管……，却……” (zhèng yīnwèi..., jǐnguǎn..., què...)", "d": "Chính vì..., mặc dù..., nhưng... Chính vì cụ Trịnh có tâm thế tốt như vậy, mặc dù trải qua nhiều gian truân, nhưng vẫn luôn giữ được tinh thần thản nhiên, lạc quan.", "ex": [["正因为郑老有这样良好的心态，尽管他经历坎坷，却能始终保持坦然、乐观的精神。", "Zhèng yīnwèi zhènglǎoyǒu zhèyàng liánghǎo de xīntài, jǐnguǎn tā jīnglì kǎnkě, què néng shǐzhōngbǎochí tǎnrán, lèguān de jīngshén.", ""]]}, {"t": "“可……却……” (kě... què...) → Nhưng... lại... (nhấn mạnh sự trái ngược)", "d": "Nhưng Hawking lại nói:...", "ex": [["可霍金却说：...", "Kě huòjīn quèshuō:...", ""]]}, {"t": "“越来越……” (yuè lái yuè...) → Càng ngày càng...", "d": "Không phải càng nhiều của cải thì càng hạnh phúc.(Ở đây dùng cấu trúc: 越 + A + 越 + B = càng... càng...)", "ex": [["并不是财富越多越幸福。", "Bìng búshì cáifù yuèduōyuè xìngfú.", ""]]}, {"t": "“一旦……，就/都……” (yídàn..., jiù/dōu...) → Một khi..., thì...", "d": "Một khi nhu cầu sinh tồn cơ bản của con người được đáp ứng, thì sự gia tăng của cải không còn mang ý nghĩa đặc biệt nào với hạnh phúc nữa.", "ex": [["一旦人的基本生存需要得到满足后，财富的增加对幸福本身都不再具有任何特殊意义。", "Yídàn rén de jīběn shēngcún xūyào dédào mǎnzú hòu, cáifù de zēngjiā duì xìngfú běnshēn dōu búzài jùyǒu rènhé tèshū yìyì.", ""]]}], "order": [], "u": {"gq": [{"s": "并不是……而是……", "d": "Không phải… mà là….", "ok": "这并不是客观条件太差，而是由于攀比引起的心理不平衡。", "vi": "Đây không phải do điều kiện quá kém, mà là do so bì gây mất cân bằng tâm lý.", "bad": ["这并不是客观条件太差，但是由于攀比引起的心理不平衡。", "这而是客观条件太差，并不是由于攀比引起的。"]}, {"s": "尽管……却……", "d": "Mặc dù… nhưng vẫn….", "ok": "尽管他经历坎坷，却能始终保持乐观的精神。", "vi": "Dù trải qua nhiều trắc trở, ông vẫn luôn lạc quan.", "bad": ["尽管他经历坎坷，所以能始终保持乐观的精神。", "他却尽管经历坎坷，能始终保持乐观的精神。"]}, {"s": "要想……就要……", "d": "Muốn… thì phải….", "ok": "要想生活快乐，就要学会根据实际情况调整目标。", "vi": "Muốn sống vui thì phải biết điều chỉnh mục tiêu theo thực tế.", "bad": ["要想生活快乐，才要学会根据实际情况调整目标。", "就要想生活快乐，要学会根据实际情况调整目标。"]}, {"s": "一旦……（后）", "d": "Một khi… (điều kiện).", "ok": "一旦人的基本需要得到满足后，财富的增加就不再有特殊意义。", "vi": "Một khi nhu cầu cơ bản được đáp ứng, thêm tiền không còn ý nghĩa đặc biệt.", "bad": ["一旦人的基本需要得到满足后，但财富的增加不再有特殊意义。", "人的基本需要一旦后得到满足，财富的增加不再有意义。"]}, {"s": "一……就是……", "d": "Hễ làm là… (nhấn mạnh thời gian dài).", "ok": "他一头扎进了研究室，一干就是十年。", "vi": "Ông lao vào phòng nghiên cứu, làm một mạch mười năm.", "bad": ["他一头扎进了研究室，一干才是十年。", "他一头扎进了研究室，干一就是十年。"]}], "disc": [{"q": "你会和别人攀比吗？怎样才能有“不比为贵”的心态？", "py": "Nǐ huì hé biérén pānbǐ ma? Zěnyàngcáinéng yǒu “Bùbǐwèi guì” de xīntài?", "vi": "Bạn có so bì với người khác không? Làm sao có tâm thế “không so bì”?", "keys": ["并不是……而是|不是……而是", "要想……就", "尽管……却|尽管……但"], "sample": "我有时候会和同学比成绩。其实烦恼并不是因为自己不好，而是因为总跟别人比。要想快乐，就要接受自己。尽管有压力，我却想脚踏实地地过好自己的生活。", "spy": "Wǒ yǒushíhou huì hé tóngxué bǐ chéngjì. Qíshí fánnǎo bìng búshì yīnwèi zìjǐ bùhǎo, érshì yīnwèi zǒng gēn biérén bǐ. Yào xiǎng kuàilè, jiùyào jiēshòu zìjǐ. Jǐnguǎn yǒu yālì, wǒ què xiǎng jiǎotàshídì dìguò hǎo zìjǐ de shēnghuó."}], "comp": [{"vi": "Muốn nói tiếng Trung lưu loát thì phải luyện nói mỗi ngày. (要想……就要……)", "keys": ["要想", "就要|就得"], "model": "要想说一口流利的汉语，就要每天练习口语。", "mpy": "Yào xiǎng shuō yìkǒu liúlì de hànyǔ, jiùyào měitiān liànxí kǒuyǔ."}, {"vi": "Dù rất mệt, cô ấy vẫn kiên trì học. (尽管……却……)", "keys": ["尽管", "却|还是|仍然"], "model": "尽管很累，她却坚持学习。", "mpy": "Jǐnguǎn hěnlèi, tā què jiānchí xuéxí."}, {"vi": "Không phải tôi không muốn đi, mà là không có thời gian. (并不是……而是……)", "keys": ["不是", "而是"], "model": "我并不是不想去，而是没有时间。", "mpy": "Wǒ bìng búshì bùxiǎng qù, érshì méiyǒu shíjiān."}], "ex": [{"q": "“不比为贵”是什么意思？", "qvi": "“不比为贵” nghĩa là gì?", "a": "不和别人攀比，满足于自己从生活中得到的。", "avi": "Không so bì với người khác, hài lòng với những gì mình có.", "bad": ["什么东西都不比较便宜。", "一定要比别人强。"], "p": 0}, {"q": "郑逸梅先生长寿的秘诀是什么？", "qvi": "Bí quyết sống lâu của Trịnh Dật Mai là gì?", "a": "不跟人家比财富地位，满足于工作和生活的快乐。", "avi": "Không so tiền tài địa vị, hài lòng với niềm vui công việc và cuộc sống.", "bad": ["每天运动三个小时。", "只吃素菜。"], "p": 1}, {"q": "霍金为什么仍然感到充实而快乐？", "qvi": "Vì sao Hawking vẫn thấy đầy đủ và vui vẻ?", "a": "他看到自己还能思维，有理想，有爱他的亲人朋友。", "avi": "Ông thấy mình còn tư duy được, có lý tưởng, có người thân bạn bè yêu thương.", "bad": ["因为他很有钱。", "因为他的病好了。"], "p": 2}, {"q": "研究发现财富和幸福有什么关系？", "qvi": "Nghiên cứu cho thấy tài sản và hạnh phúc liên quan thế nào?", "a": "基本需要满足以后，财富增加对幸福不再有特殊意义。", "avi": "Khi nhu cầu cơ bản được đáp ứng, thêm tiền không còn ý nghĩa đặc biệt với hạnh phúc.", "bad": ["财富越多越幸福。", "没有钱的人最幸福。"], "p": 3}, {"q": "王章程毕业后选择了什么？", "qvi": "Sau khi tốt nghiệp, Vương Chương Trình chọn gì?", "a": "进研究室做了十年研究，不羡慕同学的财富。", "avi": "Vào phòng nghiên cứu mười năm, không ghen tị tiền của bạn.", "bad": ["去大公司当老板。", "回国开了一个饭馆。"], "p": 4}]}}, {"id": "hk4-l7", "no": 7, "day": "HK4 · Bài 7", "time": "10:00", "scene": "library", "room": "library", "cast": ["prof", "tianfang", "zhangdong", "edward"], "vi": "Thuyết Văn Giải Tự", "zh": "说文解字", "py": "Shuōwénjiězì", "shop": {"label": "文房四宝店", "sub": "Tiệm bút mực", "icon": "🖌️"}, "vocab": [["说文解字", "Shuōwén Jiězì", "Thuyết Văn Giải Tự (tên sách)", ""], ["系统", "xìtǒng", "có hệ thống", ""], ["分析", "fēnxī", "phân tích", ""], ["字形", "zìxíng", "hình dạng chữ", ""], ["考究", "kǎojiū", "khảo cứu, nghiên cứu kỹ lưỡng", ""], ["字源", "zìyuán", "nguồn gốc chữ", ""], ["字书", "zìshū", "sách chữ (từ điển thời xưa)", ""], ["流传", "liúchuán", "lưu truyền", ""], ["工具书", "gōngjùshū", "sách công cụ, từ điển, sách tra cứu", ""], ["文字学", "wénzìxué", "văn tự học", ""], ["权威性", "quánwēi xìng", "tính uy quyền", ""], ["著作", "zhùzuò", "tác phẩm, trước tác", ""], ["作者", "zuòzhě", "tác giả", ""], ["许慎", "Xǔ Shèn", "Hứa Thận (tên tác giả)", ""], ["汉代", "Hàndài", "thời nhà Hán", ""], ["开拓者", "kāituòzhě", "người mở đường, người khai phá", ""], ["杰作", "jiézuò", "kiệt tác", ""], ["后人", "hòurén", "người đời sau", ""], ["古籍", "gǔjí", "sách cổ", ""], ["探讨", "tàntǎo", "thảo luận, tìm hiểu", ""], ["古代", "gǔdài", "thời cổ đại", ""], ["古文", "gǔwén", "văn tự cổ (chữ cổ)", ""], ["必不可少", "bì bùkě shǎo", "không thể thiếu", ""], ["桥梁", "qiáoliáng", "cầu nối", ""], ["钥匙", "yàoshi", "chìa khóa", ""], ["简称", "jiǎnchēng", "gọi tắt", ""], ["按照", "ànzhào", "theo, căn cứ theo", ""], ["部首", "bùshǒu", "bộ thủ", ""], ["编排", "biānpái", "sắp xếp, biên soạn", ""], ["字典", "zìdiǎn", "từ điển (chữ)", ""], ["原书", "yuán shū", "nguyên bản, sách gốc", ""], ["失落", "shīluò", "thất lạc, mất", ""], ["版本", "bǎnběn", "bản in, phiên bản", ""], ["注释", "zhùshì", "chú giải, chú thích", ""], ["异体字", "yìtǐzì", "chữ dị thể (biến thể)", ""], ["总结", "zǒngjié", "tổng kết", ""], ["先秦", "Xiānqín", "Tiên Tần (trước nhà Tần)", ""], ["两汉", "Liǎng Hàn", "Lưỡng Hán (Tây Hán + Đông Hán)", ""], ["成果", "chéngguǒ", "thành quả", ""], ["保存", "bǎocún", "bảo tồn, lưu giữ", ""]], "story": [{"c": "panda", "vi": "HK4 · Thuyết Văn Giải Tự. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "tianfang", "zh": "《说文解字》是中国第一部系统地分析汉字字形和考究字源的字书，也是流传最广的中文工具书。《说文解字》是两千年来中国文字学研究最具权威性的著作。", "py": "“Shuōwén Jiězì” shì Zhōngguó dì-yī bù xìtǒng de fēnxī Hànzì zìxíng hé kǎojiū zìyuán de zìshū, yě shì liúchuán zuì guǎng de Zhōngwén gōngjùshū. “Shuōwén Jiězì” shì liǎng qiān nián lái Zhōngguó wénzìxué yánjiū zuì jù quánwēi xìng de zhùzuò.", "vi": "Thuyết Văn Giải Tự là cuốn sách chữ (từ điển) đầu tiên của Trung Quốc phân tích một cách có hệ thống hình dạng chữ Hán và khảo cứu nguồn gốc chữ, đồng thời cũng là công cụ tra cứu tiếng Trung phổ biến nhất. Thuyết Văn Giải Tự là tác phẩm có tính uy quyền nhất trong nghiên cứu văn tự học Trung Quốc suốt hai nghìn năm qua."}, {"c": "prof", "zh": "《说文解字》是一部什么样的书？", "py": "«Shuōwénjiězì» shì yíbù shénmeyàng de shū?", "vi": "《说文解字》 là sách thế nào?"}, {"me": "Bộ sách đầu tiên phân tích có hệ thống tự hình và nguồn gốc chữ Hán.", "opts": [["中国第一部系统分析汉字字形和字源的字书。", "Zhōngguó dìyībù xìtǒngfēnxī hànzì zìxíng hé zìyuán de zìshū.", "Bộ sách đầu tiên phân tích có hệ thống tự hình và nguồn gốc chữ Hán."], ["一本现代小说。", "Yìběn xiàndài xiǎoshuō.", "(chưa đúng với bài)"], ["一本英语词典。", "Yìběn yīngyǔcídiǎn.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "《说文解字》的作者许慎（约公元58年—约公元147年）是汉代有名的文字学家、语言学家，是中国文字学的开拓者。他的这部杰作成为后人阅读古籍，探讨古代文化，研究古文必不可少的桥梁和钥匙。", "py": "“Shuōwén Jiězì” de zuòzhě Xǔ Shèn (yuē gōngyuán 58 nián — yuē gōngyuán 147 nián) shì Hàndài yǒumíng de wénzìxué jiā, yǔyánxué jiā, shì Zhōngguó wénzìxué de kāituòzhě. Tā de zhè bù jiézuò chéngwéi hòurén yuèdú gǔjí, tàntǎo gǔdài wénhuà, yánjiū gǔwén bì bùkě shǎo de qiáoliáng hé yàoshi.", "vi": "Tác giả của Thuyết Văn Giải Tự là Hứa Thận (khoảng năm 58 – khoảng năm 147 sau Công nguyên), là nhà văn tự học, nhà ngôn ngữ học nổi tiếng thời Hán, là người mở đường cho văn tự học Trung Quốc. Kiệt tác này của ông đã trở thành cầu nối và chìa khóa không thể thiếu cho người đời sau đọc sách cổ, tìm hiểu văn hóa cổ đại và nghiên cứu văn tự cổ."}, {"c": "prof", "zh": "《说文解字》的作者是谁？", "py": "«Shuōwénjiězì» de zuòzhě shì shuí?", "vi": "Tác giả là ai?"}, {"me": "Hứa Thận, nhà văn tự học đời Hán.", "opts": [["汉代的文字学家许慎。", "Hàndài de wénzìxuéjiā xǔshèn.", "Hứa Thận, nhà văn tự học đời Hán."], ["唐代的李白。", "Tángdài de lǐbái.", "(chưa đúng với bài)"], ["清代的段玉裁。", "Qīngdài de duànyùcái.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "《说文解字》，简称《说文》，是历史上第一部按照部首编排的汉语字典。原书作于公元100年到121年，现已失落，传至今日的大多是宋朝的版本，或是清朝的段玉裁注释本。全书共分540部首，收字9353个，另有异体字1163个，共10516字。", "py": "“Shuōwén Jiězì”, jiǎnchēng “Shuōwén”, shì lìshǐ shàng dì-yī bù ànzhào bùshǒu biānpái de Hànyǔ zìdiǎn. Yuán shū zuò yú gōngyuán 100 nián dào 121 nián, xiàn yǐ shīluò, chuán zhì jīnrì de dàduō shì Sòngcháo de bǎnběn, huò shì Qīngcháo de Duàn Yùcái zhùshì běn. Quán shū gòng fēn 540 bùshǒu, shōu zì 9353 gè, lìng yǒu yìtǐzì 1163 gè, gòng 10516 zì.", "vi": "Thuyết Văn Giải Tự, gọi tắt là Thuyết Văn, là cuốn từ điển tiếng Hán đầu tiên trong lịch sử được sắp xếp theo bộ thủ. Nguyên bản được viết vào năm 100 đến 121 sau Công nguyên, nay đã thất truyền, phần lớn những bản truyền đến ngày nay là bản in đời Tống, hoặc bản chú giải của Đoàn Ngọc Tài đời Thanh. Toàn sách chia làm 540 bộ thủ, thu nhận 9353 chữ, ngoài ra có 1163 chữ dị thể, tổng cộng 10516 chữ."}, {"c": "prof", "zh": "《说文解字》按照什么编排？收了多少字？", "py": "«Shuōwénjiězì» ànzhào shénme biānpái? Shōu le duōshao zì?", "vi": "Sắp xếp theo gì? Thu bao nhiêu chữ?"}, {"me": "Theo 540 bộ thủ, tổng 10.516 chữ.", "opts": [["按照540个部首编排，共10516字。", "Ànzhào540 ge bùshǒu biānpái, gòng10516 zì.", "Theo 540 bộ thủ, tổng 10.516 chữ."], ["按照拼音编排，共3000字。", "Ànzhào pīnyīn biānpái, gòng3000 zì.", "(chưa đúng với bài)"], ["按照笔画编排，共100字。", "Ànzhào bǐhuà biānpái, gòng100 zì.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "《说文解字》总结了先秦、两汉的文学成果，给我们保存了汉字的形、音、义，是研究甲骨文、金文和古音等不可缺少的桥梁。特别是《说文》对字义的解释一般保存了最古的含义，对理解古书上的词义更有帮助。书中还有关于秦汉时期全国各地方言的介绍，这本书也成为了解中国古代方言的一本重要参考书籍。", "py": "“Shuōwén Jiězì” zǒngjié le Xiānqín, Liǎng Hàn de wénxué chéngguǒ, gěi wǒmen bǎocún le Hànzì de xíng, yīn, yì, shì yánjiū jiǎgǔwén, jīnwén hé gǔyīn děng bùkě quēshǎo de qiáoliáng. Tèbié shì “Shuōwén” duì zìyì de jiěshì yìbān bǎocún le zuì gǔ de hányì, duì lǐjiě gǔshū shàng de cíyì gèng yǒu bāngzhù. Shū zhōng hái yǒu guānyú Qín-Hàn shíqī quánguó gè dì fāngyán de jièshào, zhè běn shū yě chéngwéi liǎojiě Zhōngguó gǔdài fāngyán de yì běn zhòngyào cānkǎo shūjí.", "vi": "Thuyết Văn Giải Tự đã tổng kết thành quả văn học thời Tiên Tần và Lưỡng Hán, bảo tồn cho chúng ta hình, âm, nghĩa của chữ Hán, là cầu nối không thể thiếu trong nghiên cứu giáp cốt văn, kim văn và cổ âm v.v... Đặc biệt, phần giải thích nghĩa chữ của Thuyết Văn thường bảo tồn được nghĩa cổ xưa nhất, rất hữu ích cho việc hiểu nghĩa từ trong sách cổ. Trong sách còn có giới thiệu về phương ngữ các vùng trên cả nước thời Tần – Hán, cuốn sách này cũng trở thành tài liệu tham khảo quan trọng để tìm hiểu phương ngữ cổ đại Trung Quốc."}, {"c": "zhangdong", "zh": "除了语言学方面的价值，《说文解字》还保存了古代社会历史、文化等各方面的材料，是我们整理中国古代文化遗产的重要依据。《说文》中对字的各种含义的解释，反映了古代的政治、经济、文化、风俗习惯等等。如《说文》中这样解释“车”字：“车，舆轮之总名，夏后时奚仲所造”。根据《说文》的这个解释，可以肯定，在夏代已经有了“车”这种交通工具。又如我们从“姓”字是“女”字旁，以及“姜”、“姚”等“女”字旁的姓中，也可以观察到古代母系社会的一些生活情况。由此可见，《说文》反映了古代的一些社会历史情况，有助于我们了解古代丰富的文化，思考它的变化发展。", "py": "Chúle yǔyánxué fāngmiàn de jiàzhí, “Shuōwén Jiězì” hái bǎocún le gǔdài shèhuì lìshǐ, wénhuà děng gè fāngmiàn de cáiliào, shì wǒmen zhěnglǐ Zhōngguó gǔdài wénhuà yíchǎn de zhòngyào yījù. “Shuōwén” zhōng duì zì de gè zhǒng hányì de jiěshì, fǎnyìng le gǔdài de zhèngzhì, jīngjì, wénhuà, fēngsú xíguàn děng děng. Rú “Shuōwén” zhōng zhèyàng jiěshì “chē” zì: “Chē, yú lún zhī zǒngmíng, Xià Hòu shí Xī Zhòng suǒ zào”. Gēnjù “Shuōwén” de zhège jiěshì, kěyǐ kěndìng, zài Xià dài yǐjīng yǒu le “chē” zhè zhǒng jiāotōng gōngjù. Yòu rú wǒmen cóng “xìng” zì shì “nǚ” zì páng, yǐjí “Jiāng”, “Yáo” děng “nǚ” zì páng de xìng zhōng, yě kěyǐ guānchá dào gǔdài mǔxì shèhuì de yìxiē shēnghuó qíngkuàng. Yóu cǐ kějiàn, “Shuōwén” fǎnyìng le gǔdài de yìxiē shèhuì lìshǐ qíngkuàng, yǒuzhù yú wǒmen liǎojiě gǔdài fēngfù de wénhuà, sīkǎo tā de biànhuà fāzhǎn.", "vi": "Ngoài giá trị về mặt ngôn ngữ học, Thuyết Văn Giải Tự còn bảo tồn các tư liệu về nhiều mặt như lịch sử xã hội, văn hóa thời cổ đại, là căn cứ quan trọng để chúng ta chỉnh lý di sản văn hóa cổ đại Trung Quốc. Phần giải thích các tầng nghĩa khác nhau của chữ trong Thuyết Văn phản ánh chính trị, kinh tế, văn hóa, phong tục tập quán thời cổ đại v.v... Ví dụ trong Thuyết Văn giải thích chữ “车” (xe) như sau: “Xe, là tên gọi chung của cỗ xe và bánh xe, do Hề Trọng thời nhà Hạ chế tạo”. Căn cứ vào giải thích này của Thuyết Văn, có thể khẳng định rằng thời nhà Hạ đã có phương tiện giao thông “xe”. Lại như từ chữ “姓” (họ) có bộ “女” (nữ), cùng với các họ như “姜”, “姚” cũng có bộ “女”, chúng ta cũng có thể quan sát được một số tình huống sinh hoạt của xã hội mẫu hệ cổ đại. Do đó có thể thấy, Thuyết Văn đã phản ánh một số tình hình lịch sử xã hội cổ đại, giúp ích cho chúng ta trong việc tìm hiểu văn hóa phong phú thời cổ đại và suy ngẫm về sự biến hóa phát triển của nó."}, {"c": "prof", "zh": "从《说文》对“车”字的解释可以知道什么？", "py": "Cóng «Shuōwén» duì “Chē” zì de jiěshì kěyǐ zhīdao shénme?", "vi": "Từ cách giải thích chữ 车 có thể biết gì?"}, {"me": "Thời Hạ đã có xe làm phương tiện giao thông.", "opts": [["在夏代已经有了车这种交通工具。", "Zài xiàdài yǐjīng yǒu le chē zhèzhǒng jiāotōnggōngjù.", "Thời Hạ đã có xe làm phương tiện giao thông."], ["汉代才有车。", "Hàndài cái yǒuchē.", "(chưa đúng với bài)"], ["车是外国人发明的。", "Chēshì wàiguórén fāmíng de.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "“是……的” (shì... de) – cấu trúc nhấn mạnh", "d": "Thuyết Văn Giải Tự là cuốn sách chữ đầu tiên của Trung Quốc phân tích có hệ thống hình dạng chữ Hán và khảo cứu nguồn gốc chữ. 是 + [đối tượng] + 的", "ex": [["《说文解字》是中国第一部系统地分析汉字字形和考究字源的字书。", "«Shuōwénjiězì» shì zhōngguó dìyībù xìtǒngdì fēnxī hànzì zìxíng hé kǎojiū zìyuán de zìshū.", ""]]}, {"t": "“最有……” (zuì yǒu...) → Nhất / có... nhất", "d": "Là tác phẩm có tính uy quyền nhất trong nghiên cứu văn tự học Trung Quốc suốt hai nghìn năm.", "ex": [["是两千年来中国文字学研究最具权威性的著作。", "Shì liǎngqiānnián lái zhōngguó wénzìxué yánjiū zuìjù quánwēixìng de zhùzuò.", ""]]}, {"t": "“成为……必不可少的……” (chéngwéi... bì bùkě shǎo de...)", "d": "Trở thành... không thể thiếu... Trở thành cầu nối và chìa khóa không thể thiếu cho người đời sau đọc sách cổ, tìm hiểu văn hóa cổ đại và nghiên cứu văn tự cổ.", "ex": [["成为后人阅读古籍，探讨古代文化，研究古文必不可少的桥梁和钥匙。", "Chéngwéi hòurén yuèdú gǔjí, tàntǎo gǔdài wénhuà, yánjiū gǔwén bìbùkěshǎo de qiáoliáng hé yàoshi.", ""]]}, {"t": "“按照……” (ànzhào...) → Theo / căn cứ theo...", "d": "Là cuốn từ điển tiếng Hán đầu tiên trong lịch sử được sắp xếp theo bộ thủ.", "ex": [["是历史上第一部按照部首编排的汉语字典。", "Shì lìshǐ shàng dìyībù ànzhào bùshǒu biānpái de hànyǔ zìdiǎn.", ""]]}, {"t": "“现已……” (xiàn yǐ...) → Hiện nay đã...", "d": "Nguyên bản được viết từ năm 100 đến 121 sau CN, hiện đã thất truyền.", "ex": [["原书作于公元100年到121年，现已失落。", "Yuánshū zuòyú gōngyuán100 nián dào121 nián, xiànyǐ shīluò.", ""]]}, {"t": "“或是……” (huò shì...) → Hoặc là...", "d": "Phần lớn bản truyền đến nay là bản in đời Tống, hoặc bản chú giải của Đoàn Ngọc Tài đời Thanh.", "ex": [["传至今日的大多是宋朝的版本，或是清朝的段玉裁注释本。", "Chuánzhì jīnrì de dàduō shì sòngcháo de bǎnběn, huòshì qīngcháo de duànyùcái zhùshì běn.", ""]]}, {"t": "“共……” (gòng...) → Tổng cộng...", "d": "Toàn sách chia làm 540 bộ thủ, thu 9353 chữ, ngoài ra 1163 chữ dị thể, tổng cộng 10516 chữ.", "ex": [["全书共分540部首，收字9353个，另有异体字1163个，共10516字。", "Quánshū gòngfēn540 bùshǒu, shōuzì9353 ge, lìngyǒu yìtǐzì1163 ge, gòng10516 zì.", ""]]}, {"t": "“特别是……” (tèbié shì...) → Đặc biệt là...", "d": "Đặc biệt là phần giải thích nghĩa chữ của Thuyết Văn thường bảo tồn được nghĩa cổ xưa nhất.", "ex": [["特别是《说文》对字义的解释一般保存了最古的含义。", "Tèbié shì «Shuōwén» duì zìyì de jiěshì yìbān bǎocún le zuìgǔ de hányì.", ""]]}], "order": [], "u": {"gq": [{"s": "是……的 (nhấn mạnh)", "d": "Nhấn mạnh thời gian, cách thức… của việc đã xảy ra.", "ok": "原书是公元100年到121年写成的。", "vi": "Sách gốc được viết vào năm 100–121.", "bad": ["原书是公元100年到121年写成。", "原书的是公元100年到121年写成。"]}, {"s": "按照……", "d": "Theo, căn cứ theo….", "ok": "这是第一部按照部首编排的汉语字典。", "vi": "Đây là từ điển đầu tiên sắp xếp theo bộ thủ.", "bad": ["这是第一部部首按照编排的汉语字典。", "这是第一部按照编排部首的汉语字典。"]}, {"s": "除了……还……", "d": "Ngoài… ra còn….", "ok": "除了语言学方面的价值，《说文解字》还保存了古代社会历史的材料。", "vi": "Ngoài giá trị ngôn ngữ học, sách còn lưu giữ tư liệu lịch sử xã hội cổ đại.", "bad": ["除了语言学方面的价值，《说文解字》才保存了古代社会历史的材料。", "《说文解字》除了还保存了古代社会历史的材料语言学价值。"]}, {"s": "由此可见", "d": "Do đó có thể thấy….", "ok": "由此可见，《说文》反映了古代的一些社会历史情况。", "vi": "Do đó có thể thấy, 《说文》 phản ánh một số tình hình lịch sử xã hội cổ đại.", "bad": ["由此看可见，《说文》反映了古代的一些社会历史情况。", "可见由此，《说文》反映了古代的一些社会历史情况。"]}, {"s": "有助于……", "d": "Có ích cho, giúp ích cho….", "ok": "《说文》有助于我们了解古代丰富的文化。", "vi": "《说文》 giúp chúng ta hiểu văn hóa cổ đại phong phú.", "bad": ["《说文》有助我们于了解古代丰富的文化。", "《说文》助有于我们了解古代丰富的文化。"]}], "disc": [{"q": "学习汉字的字源对你学汉语有什么帮助？举一个例子。", "py": "Xuéxí hànzì de zìyuán duì nǐ xué hànyǔ yǒu shénme bāngzhù? Jǔ yíge lìzi.", "vi": "Học nguồn gốc chữ Hán giúp bạn học tiếng Trung thế nào? Cho một ví dụ.", "keys": ["有助于", "由此可见|可见", "比如|如"], "sample": "了解字源有助于记汉字。比如“休”字是一个人靠在树旁边，意思是休息。由此可见，知道字源以后，汉字就不难记了。", "spy": "Liǎojiě zìyuán yǒuzhùyú jì hànzì. Bǐrú “Xiū” zì shì yíge rénkào zài shù pángbiān, yìsi shì xiūxi. Yóucǐkějiàn, zhīdao zìyuán yǐhòu, hànzì jiù bùnán jì le."}], "comp": [{"vi": "Đọc sách có ích cho việc mở rộng tầm nhìn. (有助于)", "keys": ["有助于"], "model": "读书有助于开阔眼界。", "mpy": "Dúshū yǒuzhùyú kāikuòyǎnjiè."}, {"vi": "Do đó có thể thấy, anh ấy rất thích chữ Hán. (由此可见)", "keys": ["由此可见"], "model": "由此可见，他非常喜欢汉字。", "mpy": "Yóucǐkějiàn, tā fēicháng xǐhuan hànzì."}, {"vi": "Hãy sắp xếp những từ này theo bộ thủ. (按照)", "keys": ["按照"], "model": "请按照部首排列这些词。", "mpy": "Qǐng ànzhào bùshǒu páiliè zhèxiē cí."}], "ex": [{"q": "《说文解字》是一部什么样的书？", "qvi": "《说文解字》 là sách thế nào?", "a": "中国第一部系统分析汉字字形和字源的字书。", "avi": "Bộ sách đầu tiên phân tích có hệ thống tự hình và nguồn gốc chữ Hán.", "bad": ["一本现代小说。", "一本英语词典。"], "p": 0}, {"q": "《说文解字》的作者是谁？", "qvi": "Tác giả là ai?", "a": "汉代的文字学家许慎。", "avi": "Hứa Thận, nhà văn tự học đời Hán.", "bad": ["唐代的李白。", "清代的段玉裁。"], "p": 1}, {"q": "《说文解字》按照什么编排？收了多少字？", "qvi": "Sắp xếp theo gì? Thu bao nhiêu chữ?", "a": "按照540个部首编排，共10516字。", "avi": "Theo 540 bộ thủ, tổng 10.516 chữ.", "bad": ["按照拼音编排，共3000字。", "按照笔画编排，共100字。"], "p": 2}, {"q": "从《说文》对“车”字的解释可以知道什么？", "qvi": "Từ cách giải thích chữ 车 có thể biết gì?", "a": "在夏代已经有了车这种交通工具。", "avi": "Thời Hạ đã có xe làm phương tiện giao thông.", "bad": ["汉代才有车。", "车是外国人发明的。"], "p": 4}]}}, {"id": "hk4-l8", "no": 8, "day": "HK4 · Bài 8", "time": "19:00", "scene": "hall", "room": "hall", "cast": ["prof", "officer", "edward", "lee"], "vi": "Đường Thái Tông thả tử tù", "zh": "唐太宗纵囚", "py": "Tángtàizōng zòngqiú", "shop": {"label": "京剧院", "sub": "Nhà hát Kinh kịch", "icon": "🎭"}, "vocab": [["贤能", "xiánnéng", "Hiền năng (tài đức vẹn toàn)", ""], ["视察", "shìchá", "Thị sát, đi kiểm tra", ""], ["判处", "pànchǔ", "Kết án, tuyên án", ""], ["慎重", "shènzhòng", "Thận trọng", ""], ["关乎", "guānhu", "Liên quan đến", ""], ["审核", "shěnhé", "Thẩm tra, xét duyệt", ""], ["死罪", "sǐzuì", "Tội chết", ""], ["安慰", "ānwèi", "An ủi", ""], ["渴望", "kěwàng", "Khao khát", ""], ["团聚", "tuánjù", "Đoàn tụ", ""], ["约定", "yuēdìng", "Giao ước, hẹn ước", ""], ["欢呼", "huānhū", "Hoan hô", ""], ["三思而后行", "sānsī'érhòuxíng", "Tam tư nhi hậu hành (suy nghĩ kỹ rồi hãy làm)", ""], ["将信将疑", "jiāngxìnjiāngyí", "Bán tín bán nghi", ""], ["履行", "lǚxíng", "Thực hiện, thi hành", ""], ["有气无力", "yǒuqìwúlì", "Yếu ớt không sức lực", ""], ["欣慰", "xīnwèi", "Mãn nguyện, vui mừng", ""], ["赦免", "shèmiǎn", "Ân xá", ""], ["异议", "yìyì", "Ý kiến phản đối", ""], ["奖赏", "jiǎngshǎng", "Khen thưởng, phần thưởng", ""]], "story": [{"c": "panda", "vi": "HK4 · Đường Thái Tông thả tử tù. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "officer", "zh": "唐太宗李世民是中国历史上一位贤能的皇帝。公元633年的12月，唐太宗视察监狱，那里有390名被判处死刑的罪犯正在等待最后批准，准备执行死刑。唐太宗历来对死刑的判决非常慎重，因为这关乎人命。他规定死刑要审核三次，也就是向皇帝报告三次，后来因为错判过一个官员，他又把三次改成五次。现在这些关在监狱里的死刑犯，都是经过了五次审核，也就是真正犯有死罪的人。即使这样，唐太宗还是对他们进行最后的安慰。", "py": "Táng Tàizōng Lǐ Shìmín shì Zhōngguó lìshǐ shàng yī wèi xiánnéng de huángdì. Gōngyuán 633 nián de 12 yuè, Táng Tàizōng shìchá jiānyù, nàlǐ yǒu 390 míng bèi pànchǔ sǐxíng de zuìfàn zhèngzài děngdài zuìhòu pīzhǔn, zhǔnbèi zhíxíng sǐxíng. Táng Tàizōng lìlái duì sǐxíng de pànjué fēicháng shènzhòng, yīnwèi zhè guānhu rénmìng. Tā guīdìng sǐxíng yào shěnhé sān cì, yě jiùshì xiàng huángdì bàogào sān cì, hòulái yīnwèi cuòpàn guò yī gè guānyuán, tā yòu bǎ sān cì gǎichéng wǔ cì. Xiànzài zhèxiē guān zài jiānyù lǐ de sǐxíngfàn, dōu shì jīngguòle wǔ cì shěnhé, yě jiùshì zhēnzhèng fàn yǒu sǐzuì de rén. Jíshǐ zhèyàng, Táng Tàizōng háishì duì tāmen jìnxíng zuìhòu de ānwèi.", "vi": "Đường Thái Tông Lý Thế Dân là một vị hoàng đế hiền năng trong lịch sử Trung Quốc. Tháng 12 năm 633 Công nguyên, Đường Thái Tông đi thị sát nhà ngục, ở đó có 390 phạm nhân bị kết án tử hình đang chờ phê chuẩn cuối cùng để chuẩn bị thi hành án. Đường Thái Tông xưa nay vốn rất thận trọng với các bản án tử hình, vì điều này liên quan đến tính mạng con người. Ông quy định án tử hình phải được thẩm tra ba lần, tức là báo cáo lên hoàng đế ba lần, sau này vì xử oan một vị quan, ông lại đổi ba lần thành năm lần. Những tử tù hiện đang bị giam trong ngục này đều đã trải qua năm lần thẩm tra, tức là những người thực sự phạm tội chết. Dù vậy, Đường Thái Tông vẫn tiến hành an ủi họ lần cuối."}, {"c": "prof", "zh": "唐太宗为什么对死刑的判决非常慎重？", "py": "Tángtàizōng wèishénme duì sǐxíng de pànjué fēicháng shènzhòng?", "vi": "Vì sao Đường Thái Tông rất thận trọng khi xử tử?"}, {"me": "Vì liên quan mạng người; ông quy định án tử phải thẩm định năm lần.", "opts": [["因为这关乎人命，他规定死刑要审核五次。", "Yīnwèi zhè guānhū rénmìng, tā guīdìng sǐxíng yào shěnhé wǔcì.", "Vì liên quan mạng người; ông quy định án tử phải thẩm định năm lần."], ["因为他不喜欢工作。", "Yīnwèi tā bù xǐhuan gōngzuò.", "(chưa đúng với bài)"], ["因为监狱太小了。", "Yīnwèi jiānyù tàixiǎo le.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "唐太宗亲自问话时，死刑犯对判决都没有反对意见，但他们都表示，非常渴望能够回家最后看望一次亲人。唐太宗低头沉思了一会儿，作出了一个令人大吃一惊的决定：你们可以回家与亲人团聚，在亲情和关爱中度过人生中的最后一段时光，但必须遵守一个约定：第二年的九月初四必须返回监狱，接受死刑。", "py": "Tángtàizōng qīnzì wènhuà shí, sǐxíngfàn duì pànjué dōu méiyǒu fǎnduì yìjiàn, dàn tāmen dōu biǎoshì, fēicháng kěwàng nénggòu huíjiā zuìhòu kànwàng yícì qīnrén. Tángtàizōng dītóu chénsī le yíhuìr, zuòchū le yíge lìngrén dàchīyìjīng de juédìng: Nǐmen kěyǐ huíjiā yǔ qīnrén tuánjù, zài qīnqíng hé guānài zhōng dùguò rénshēng zhōng de zuìhòu yíduàn shíguāng, dàn bìxū zūnshǒu yíge yuēdìng: Dìèrnián de jiǔyuèchū sì bìxū fǎnhuí jiānyù, jiēshòu sǐxíng.", "vi": "Đường Thái Tông đích thân hỏi chuyện, các tử tù đều không phản đối bản án, nhưng họ đều nói rất khao khát được về nhà gặp người thân lần cuối. Đường Thái Tông cúi đầu suy nghĩ một lúc, rồi đưa ra một quyết định khiến mọi người kinh ngạc: các ngươi được về nhà đoàn tụ với người thân, sống những ngày cuối đời trong tình thân và sự quan tâm, nhưng phải giữ một lời hẹn: mùng 4 tháng 9 năm sau phải quay lại nhà ngục chịu án tử."}, {"c": "prof", "zh": "唐太宗作出了什么决定？", "py": "Tángtàizōng zuòchū le shénme juédìng?", "vi": "Đường Thái Tông đã quyết định gì?"}, {"me": "Cho tử tù về đoàn tụ gia đình, mùng 4 tháng 9 năm sau quay lại.", "opts": [["让死刑犯回家与亲人团聚，第二年九月初四再回来。", "Ràng sǐxíngfàn huíjiā yǔ qīnrén tuánjù, dìèrnián jiǔyuèchū sìzài huílái.", "Cho tử tù về đoàn tụ gia đình, mùng 4 tháng 9 năm sau quay lại."], ["马上执行死刑。", "Mǎshàng zhíxíng sǐxíng.", "(chưa đúng với bài)"], ["把他们送到外国。", "Bǎ tāmen sòngdào wàiguó.", "(chưa đúng với bài)"]]}, {"c": "lee", "zh": "罪犯们简直不敢相信自己的耳朵，他们都欢呼起来。官员们上前提醒唐太宗：“皇上，这些人都是死刑犯，到了约定的日子不回来怎么办？您要三思而后行啊！”唐太宗坚定地回答：“用诚心才能换忠心，我相信他们会对得起我的信任。”话虽这么说，可是所有人都将信将疑。", "py": "Zuìfàn men jiǎnzhí bùgǎnxiāngxìn zìjǐ de ěrduǒ, tāmen dōu huānhū qǐlái. Guānyuán men shàngqián tíxǐng tángtàizōng: “Huángshàng, zhèxiē rén dōu shì sǐxíngfàn, dào le yuēdìng de rìzi bù huílái zěnmebàn? Nín yào sān sī ér hòu xíng a!” tángtàizōng jiāndìng dì huídá: “Yòng chéngxīn cáinéng huàn zhōngxīn, wǒ xiāngxìn tāmen huì duìdeqǐ wǒ de xìnrèn.” huà suī zhème shuō, kěshì suǒyǒurén dōu jiāngxìnjiāngyí.", "vi": "Các tội phạm đơn giản là không dám tin vào tai mình, họ đều hoan hô. Các quan viên tiến lên nhắc nhở Đường Thái Tông: \"Hoàng thượng, những người này đều là tử tù, đến ngày hẹn mà không quay lại thì làm thế nào? Người phải suy nghĩ kỹ rồi hãy làm ạ!\" Đường Thái Tông kiên định trả lời: \"Dùng lòng thành mới đổi được lòng trung, ta tin họ sẽ không phụ lòng tin của ta.\" Tuy nói vậy, nhưng mọi người đều bán tín bán nghi."}, {"c": "prof", "zh": "官员们对这个决定有什么看法？", "py": "Guānyuán men duì zhège juédìng yǒu shénme kànfǎ?", "vi": "Các quan nghĩ gì về quyết định này?"}, {"me": "Lo họ không quay về, khuyên vua nghĩ kỹ.", "opts": [["担心他们到时候不回来，劝皇上三思而后行。", "Dānxīn tāmen dàoshíhòu bù huílái, quàn huángshàng sān sī ér hòu xíng.", "Lo họ không quay về, khuyên vua nghĩ kỹ."], ["都非常赞成。", "Dōu fēicháng zànchéng.", "(chưa đúng với bài)"], ["都想跟死刑犯一起回家。", "Dōu xiǎng gēn sǐxíngfàn yìqǐ huíjiā.", "(chưa đúng với bài)"]]}, {"c": "officer", "zh": "到了第二年（公元634年）九月初四这一天，四面八方的人都来到大理寺门口，因为这一天是唐太宗同390名死刑犯的死刑约定到期的日子，大家想看看那些罪犯们是否真的会履行约定，自动来送死。", "py": "Dàole dì'èr nián (Gōngyuán 634 nián) jiǔyuè chūsì zhè yī tiān, sìmiànbāfāng de rén dōu lái dào Dàlǐsì ménkǒu, yīnwèi zhè yī tiān shì Táng Tàizōng tóng 390 míng sǐxíngfàn de sǐxíng yuēdìng dàoqī de rìzi, dàjiā xiǎng kànkan nàxiē zuìfànmen shìfǒu zhēn de huì lǚxíng yuēdìng, zìdòng lái sòngsǐ.", "vi": "Đến ngày mùng 4 tháng 9 năm thứ hai (năm 634 Công nguyên), người từ bốn phương tám hướng đều kéo đến trước cổng Đại Lý Tự, vì ngày này là ngày hết hạn giao ước tử hình giữa Đường Thái Tông và 390 tử tù, mọi người muốn xem những tội phạm đó có thực sự thực hiện giao ước, tự động đến chịu chết hay không."}, {"c": "edward", "zh": "令大家想不到的是，这一天死刑犯们真的一个接一个地回来了。约定的时间到了，数了一下人数，就差一个名叫徐福林的死刑犯还没到。大家的目光又都转向了唐太宗，这位年仅35岁的皇帝镇定地说：“再等等！”", "py": "Lìng dàjiā xiǎngbudào de shì, zhè yī tiān sǐxíngfànmen zhēn de yī gè jiē yī gè de huílái le. Yuēdìng de shíjiān dào le, shǔle yīxià rénshù, jiù chà yī gè míng jiào Xú Fúlín de sǐxíngfàn hái méi dào. Dàjiā de mùguāng yòu dōu zhuǎnxiàngle Táng Tàizōng, zhè wèi nián jǐn 35 suì de huángdì zhèndìng de shuō: “Zài děngděng!”", "vi": "Điều khiến mọi người không ngờ là, ngày hôm đó các tử tù thực sự lần lượt quay trở về. Đến giờ hẹn, đếm số người, chỉ thiếu một tử tù tên là Từ Phúc Lâm chưa đến. Ánh mắt mọi người lại đổ dồn về phía Đường Thái Tông, vị hoàng đế chỉ mới 35 tuổi này bình tĩnh nói: \"Chờ thêm chút nữa!\""}, {"c": "lee", "zh": "这时，远远地传来了车轮的声音，一辆牛车急急地走过来，车上坐着的人正是徐福林。他有气无力，一脸病态。原来，他在返回京城的路上病倒了，只好雇了一辆牛车赶路，结果比约定的时间晚了一个小时。", "py": "Zhèshí, yuǎnyuǎn de chuánláile chēlún de shēngyīn, yī liàng niúchē jíjí de zǒu guòlái, chē shàng zuòzhe de rén zhèngshì Xú Fúlín. Tā yǒuqìwúlì, yī liǎn bìngtài. Yuánlái, tā zài fǎnhuí jīngchéng de lùshang bìngdǎo le, zhǐhǎo gùle yī liàng niúchē gǎnlù, jiéguǒ bǐ yuēdìng de shíjiān wǎnle yī gè xiǎoshí.", "vi": "Lúc này, từ xa vọng lại tiếng bánh xe, một chiếc xe bò vội vã chạy tới, người ngồi trên xe chính là Từ Phúc Lâm. Ông ta yếu ớt không có sức lực, gương mặt đầy vẻ bệnh tật. Thì ra, trên đường trở về kinh thành ông ta bị ốm, đành phải thuê một chiếc xe bò để đi đường, kết quả là đến muộn hơn thời gian hẹn một tiếng đồng hồ."}, {"c": "prof", "zh": "徐福林为什么晚到了？", "py": "Xúfú lín wèishénme wǎndào le?", "vi": "Vì sao Từ Phúc Lâm đến muộn?"}, {"me": "Ông bị ốm dọc đường, đành thuê xe bò.", "opts": [["他在路上病倒了，只好雇牛车赶路。", "Tā zài lùshàng bìngdào le, zhǐhǎo gù niúchē gǎnlù.", "Ông bị ốm dọc đường, đành thuê xe bò."], ["他逃跑了又回来。", "Tā táopǎo le yòu huílái.", "(chưa đúng với bài)"], ["他忘了日子。", "Tā wàng le rìzi.", "(chưa đúng với bài)"]]}, {"c": "officer", "zh": "唐太宗的脸上露出了欣慰的笑容。390名死刑犯能够遵守与唐太宗的死亡约定，他们的信用得到了最高的奖赏，他们全被赦免！没有人对此提出异议，因为用生命来守信诺言的人，应该得到这样的奖赏。", "py": "Táng Tàizōng de liǎnshang lùchūle xīnwèi de xiàoróng. 390 míng sǐxíngfàn nénggòu zūnshǒu yǔ Táng Tàizōng de sǐwáng yuēdìng, tāmen de xìnyòng dédàole zuìgāo de jiǎngshǎng, tāmen quán bèi shèmiǎn! Méiyǒu rén duì cǐ tíchū yìyì, yīnwèi yòng shēngmìng lái shǒu xìn nuòyán de rén, yīnggāi dédào zhèyàng de jiǎngshǎng.", "vi": "Trên mặt Đường Thái Tông lộ ra nụ cười mãn nguyện. 390 tử tù có thể tuân thủ giao ước tử hình với Đường Thái Tông, chữ tín của họ đã nhận được phần thưởng cao nhất, họ đều được ân xá! Không ai phản đối điều này, vì những người dùng mạng sống để giữ lời hứa, nên nhận được phần thưởng như vậy."}, {"c": "prof", "zh": "故事的结局是什么？", "py": "Gùshi de jiéjú shì shénme?", "vi": "Kết cục câu chuyện là gì?"}, {"me": "390 tử tù đều được tha.", "opts": [["390名死刑犯全被赦免了。", "390 míng sǐxíngfàn quán bèi shèmiǎn le.", "390 tử tù đều được tha."], ["只有徐福林被赦免了。", "Zhǐyǒu xúfú lín bèi shèmiǎn le.", "(chưa đúng với bài)"], ["他们都被执行了死刑。", "Tāmen dōu bèi zhíxíng le sǐxíng.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "即使……还是…… (Jíshǐ... háishì...)", "d": "Cho dù... vẫn... Dịch: Cho dù như vậy, Đường Thái Tông vẫn tiến hành an ủi họ lần cuối.", "ex": [["即使这样，唐太宗还是对他们进行最后的安慰。", "Jíshǐ zhèyàng, tángtàizōng háishì duì tāmen jìnxíng zuìhòu de ānwèi.", ""]]}, {"t": "令…… (Lìng...)", "d": "Khiến cho... (thường dùng trong văn viết, mang tính trang trọng) Dịch: Điều khiến mọi người không ngờ là...", "ex": [["令大家想不到的是...", "Lìng dàjiā xiǎngbúdào de shì...", ""]]}, {"t": "一个接一个 (Yī gè jiē yī gè)", "d": "Lần lượt từng người một, nối tiếp nhau. Dịch: Các tử tù thực sự lần lượt từng người một quay trở về.", "ex": [["死刑犯们真的一个接一个地回来了。", "Sǐxíngfàn men zhēnde yíge jiē yíge dì huílái le.", ""]]}, {"t": "是否 (Shìfǒu)", "d": "Có phải... hay không (dùng để hỏi hoặc diễn tả sự nghi vấn trong câu trần thuật). Dịch: Mọi người muốn xem những tội phạm đó có thực sự thực hiện giao ước hay không.", "ex": [["大家想看看那些罪犯们是否真的会履行约定。", "Dàjiā xiǎng kànkan nàxiē zuìfàn men shìfǒu zhēnde huì lǚxíng yuēdìng.", ""]]}, {"t": "差……还没…… (Chà... hái méi...)", "d": "Thiếu... vẫn chưa... Dịch: Chỉ thiếu một tử tù tên là Từ Phúc Lâm vẫn chưa đến.", "ex": [["就差一个名叫徐福林的死刑犯还没到。", "Jiù chà yíge míngjiào xúfú lín de sǐxíngfàn hái méidào.", ""]]}, {"t": "用……来…… (Yòng... lái...)", "d": "Dùng... để... Dịch: Những người dùng mạng sống để giữ lời hứa.", "ex": [["用生命来守信诺言的人。", "Yòng shēngmìng lái shǒuxìn nuòyán de rén.", ""]]}, {"t": "因为…… (Yīnwèi...)", "d": "Bởi vì... Dịch: Bởi vì những người dùng mạng sống để giữ lời hứa, nên nhận được phần thưởng như vậy.", "ex": [["因为用生命来守信诺言的人，应该得到这样的奖赏。", "Yīnwèi yòng shēngmìng lái shǒuxìn nuòyán de rén, yīnggāi dédào zhèyàng de jiǎngshǎng.", ""]]}, {"t": "被 (Bèi) - Câu bị động", "d": "Được/bị (chỉ hành động bị động). Dịch: Họ đều được ân xá!", "ex": [["他们全被赦免！", "Tāmen quán bèi shèmiǎn!", ""]]}], "order": [], "u": {"gq": [{"s": "即使……还是……", "d": "Cho dù… vẫn….", "ok": "即使这样，唐太宗还是对他们进行最后的安慰。", "vi": "Dù vậy, Đường Thái Tông vẫn an ủi họ lần cuối.", "bad": ["即使这样，唐太宗所以对他们进行最后的安慰。", "唐太宗即使这样还是，对他们进行最后的安慰。"]}, {"s": "令……", "d": "Khiến…, làm cho… (văn viết).", "ok": "他作出了一个令人大吃一惊的决定。", "vi": "Ông đưa ra một quyết định khiến người ta kinh ngạc.", "bad": ["他作出了一个人令大吃一惊的决定。", "他作出了一个令大吃一惊人的决定。"]}, {"s": "是否", "d": "Có… hay không (văn viết).", "ok": "大家想看看那些罪犯是否真的会履行约定。", "vi": "Mọi người muốn xem các tội phạm có thật sự giữ lời hẹn không.", "bad": ["大家想看看那些罪犯是否真的会履行约定吗。", "大家想看看那些罪犯真的是否不会履行约定否。"]}, {"s": "用……来……", "d": "Dùng… để….", "ok": "用生命来守信诺言的人，应该得到这样的奖赏。", "vi": "Người dùng sinh mạng để giữ lời hứa đáng được thưởng như vậy.", "bad": ["用生命来的守信诺言人，应该得到这样的奖赏。", "来用生命守信诺言的人，应该得到这样的奖赏。"]}, {"s": "对……进行……", "d": "Tiến hành… đối với….", "ok": "唐太宗对他们进行最后的安慰。", "vi": "Đường Thái Tông an ủi họ lần cuối.", "bad": ["唐太宗进行对他们最后的安慰。", "唐太宗对他们最后的安慰进行了吗。"]}], "disc": [{"q": "你怎么看唐太宗的决定？“用诚心换忠心”在今天还有用吗？", "py": "Nǐ zěnme kàn tángtàizōng de juédìng? “Yòng chéngxīn huàn zhōngxīn” zài jīntiān háiyǒu yòng ma?", "vi": "Bạn nghĩ gì về quyết định của Đường Thái Tông? “Dùng thành tâm đổi lòng trung” ngày nay còn đúng không?", "keys": ["即使……还是|即使……也", "令", "用……来"], "sample": "我觉得唐太宗的决定令人佩服。即使是死刑犯，他还是相信他们。今天用诚心来对待别人，别人也会用诚心来回报你，所以这句话还有用。", "spy": "Wǒ juéde tángtàizōng de juédìng lìngrén pèifú. Jíshǐ shì sǐxíngfàn, tā háishì xiāngxìn tāmen. Jīntiān yòng chéngxīn lái duìdài biérén, biérén yě huì yòng chéngxīn lái huíbào nǐ, suǒyǐ zhèjù huà háiyǒu yòng."}], "comp": [{"vi": "Cho dù trời mưa, chúng tôi vẫn đi. (即使……还是……)", "keys": ["即使", "还是|也"], "model": "即使下雨，我们还是要去。", "mpy": "Jíshǐ xiàyǔ, wǒmen háishì yào qù."}, {"vi": "Kết quả này khiến mọi người rất bất ngờ. (令)", "keys": ["令"], "model": "这个结果令大家很意外。", "mpy": "Zhège jiéguǒ lìng dàjiā hěn yìwài."}, {"vi": "Tôi không biết anh ấy có đến hay không. (是否)", "keys": ["是否"], "model": "我不知道他是否会来。", "mpy": "Wǒ bù zhīdao tā shìfǒu huì lái."}], "ex": [{"q": "唐太宗为什么对死刑的判决非常慎重？", "qvi": "Vì sao Đường Thái Tông rất thận trọng khi xử tử?", "a": "因为这关乎人命，他规定死刑要审核五次。", "avi": "Vì liên quan mạng người; ông quy định án tử phải thẩm định năm lần.", "bad": ["因为他不喜欢工作。", "因为监狱太小了。"], "p": 0}, {"q": "唐太宗作出了什么决定？", "qvi": "Đường Thái Tông đã quyết định gì?", "a": "让死刑犯回家与亲人团聚，第二年九月初四再回来。", "avi": "Cho tử tù về đoàn tụ gia đình, mùng 4 tháng 9 năm sau quay lại.", "bad": ["马上执行死刑。", "把他们送到外国。"], "p": 1}, {"q": "官员们对这个决定有什么看法？", "qvi": "Các quan nghĩ gì về quyết định này?", "a": "担心他们到时候不回来，劝皇上三思而后行。", "avi": "Lo họ không quay về, khuyên vua nghĩ kỹ.", "bad": ["都非常赞成。", "都想跟死刑犯一起回家。"], "p": 2}, {"q": "徐福林为什么晚到了？", "qvi": "Vì sao Từ Phúc Lâm đến muộn?", "a": "他在路上病倒了，只好雇牛车赶路。", "avi": "Ông bị ốm dọc đường, đành thuê xe bò.", "bad": ["他逃跑了又回来。", "他忘了日子。"], "p": 5}, {"q": "故事的结局是什么？", "qvi": "Kết cục câu chuyện là gì?", "a": "390名死刑犯全被赦免了。", "avi": "390 tử tù đều được tha.", "bad": ["只有徐福林被赦免了。", "他们都被执行了死刑。"], "p": 6}]}}, {"id": "hk4-l9", "no": 9, "day": "HK4 · Bài 9", "time": "21:00", "scene": "bedroom", "room": "bedroom", "cast": ["prof", "meimei", "lee", "roland"], "vi": "Từ mạng “囧”", "zh": "网络词语“囧”", "py": "Wǎngluò cíyǔ “Jiǒng”", "shop": {"label": "网吧", "sub": "Quán net", "icon": "🌐"}, "vocab": [["网友", "wǎngyǒu", "Cư dân mạng, bạn trên mạng", ""], ["传播", "chuánbō", "Lan truyền", ""], ["究竟", "jiūjìng", "Rốt cuộc, cuối cùng", ""], ["源于", "yuányú", "Bắt nguồn từ", ""], ["甲骨文", "jiǎgǔwén", "Giáp cốt văn (chữ viết trên mai rùa/xương thú)", ""], ["象形字", "xiàngxíngzì", "Chữ tượng hình", ""], ["本义", "běnyì", "Nghĩa gốc", ""], ["引申", "yǐnshēn", "Mở rộng (nghĩa)", ""], ["郁闷", "yùmèn", "U uất, bực bội", ""], ["窘迫", "jiǒngpò", "Khốn quẫn, bối rối", ""], ["审美", "shěnměi", "Thẩm mỹ", ""], ["谐音", "xiéyīn", "Hài âm (âm đọc giống nhau)", ""], ["简洁", "jiǎnjié", "Đơn giản, ngắn gọn", ""], ["交际", "jiāojì", "Giao tiếp, giao lưu", ""], ["哭笑不得", "kūxiàobùdé", "Khóc cười không được (dở khóc dở cười)", ""], ["时尚", "shíshàng", "Thời thượng", ""], ["风趣", "fēngqù", "Thú vị, hóm hỉnh", ""], ["发泄", "fāxiè", "Giải tỏa, phát tiết", ""], ["时髦前卫", "shímáo qiánwèi", "Thời thượng tiên phong", ""], ["直观", "zhíguān", "Trực quan", ""], ["愁眉苦脸", "chóuméikǔliǎn", "Mặt mày ủ dột, chau mày khổ mặt", ""], ["适可而止", "shìkě'érzhǐ", "Dừng lại đúng lúc, thích hợp thì dừng", ""]], "story": [{"c": "panda", "vi": "HK4 · Từ mạng “囧”. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "meimei", "zh": "“囧（jiǒng）”被众多网友称为“21世纪最牛的一个字”，在网络上的使用和传播速度极快、范围极大。究竟“囧”是什么意思，又源于何处？它在网上是如何迅速传播的？", "py": "“Jiǒng” bèi zhòngduō wǎngyǒu chēng wéi “21 shìjì zuì niú de yī gè zì”, zài wǎngluò shàng de shǐyòng hé chuánbō sùdù jí kuài, fànwéi jí dà. Jiūjìng “jiǒng” shì shénme yìsi, yòu yuányú héchù? Tā zài wǎng shàng shì rúhé xùnsù chuánbō de?", "vi": "\"Quẫn\" (jiǒng) được đông đảo cư dân mạng gọi là \"chữ ngầu nhất thế kỷ 21\", tốc độ sử dụng và lan truyền trên mạng cực nhanh, phạm vi cực lớn. Rốt cuộc \"Quẫn\" có nghĩa là gì, và bắt nguồn từ đâu? Nó đã lan truyền nhanh chóng trên mạng như thế nào?"}, {"c": "lee", "zh": "“囧”在甲骨文中本有其字。据《古代汉语词典》解释，“囧”为象形字，外面的大方块表示房子，里面的小方块表示窗户，窗户可以照进阳光，所以本义为窗口光亮，引申为明亮、光明之义。在网络语言中，“囧”同样成了一个象形字，然而人们根据“囧”像一张表情沉重郁闷的人脸，而“囧”又与汉字“窘”发音相同，因此，用来表达一个人郁闷、窘迫的心理状态。", "py": "“Jiǒng” zài jiǎgǔwén zhōng běn yǒu qí zì. Jù 《Gǔdài Hànyǔ Cídiǎn》 jiěshì, “jiǒng” wéi xiàngxíngzì, wàimiàn de dà fāngkuài biǎoshì fángzi, lǐmiàn de xiǎo fāngkuài biǎoshì chuānghu, chuānghu kěyǐ zhàojìn yángguāng, suǒyǐ běnyì wéi chuāngkǒu guāngliàng, yǐnshēn wéi míngliàng, guāngmíng zhī yì. Zài wǎngluò yǔyán zhōng, “jiǒng” tóngyàng chéngle yī gè xiàngxíngzì, rán'ér rénmen gēnjù “jiǒng” xiàng yī zhāng biǎoqíng chénzhòng yùmèn de rénliǎn, ér “jiǒng” yòu yǔ Hànzì “jiǒng” fāyīn xiāngtóng, yīncǐ, yòng lái biǎodá yī gè rén yùmèn, jiǒngpò de xīnlǐ zhuàngtài.", "vi": "\"Quẫn\" vốn có chữ này trong giáp cốt văn. Theo giải thích trong \"Từ điển Hán ngữ cổ đại\", \"Quẫn\" là chữ tượng hình, ô vuông lớn bên ngoài biểu thị ngôi nhà, ô vuông nhỏ bên trong biểu thị cửa sổ, cửa sổ có thể đón ánh sáng mặt trời chiếu vào, nên nghĩa gốc là cửa sổ sáng sủa, mở rộng ra thành nghĩa sáng sủa, quang minh. Trong ngôn ngữ mạng, \"Quẫn\" cũng trở thành một chữ tượng hình, tuy nhiên mọi người dựa vào việc \"Quẫn\" giống như một khuôn mặt người có biểu cảm nặng nề u uất, mà \"Quẫn\" lại có phát âm giống với chữ Hán \"Quẫn\" (窘 - khốn quẫn), vì thế, được dùng để biểu đạt trạng thái tâm lý u uất, khốn quẫn của một người."}, {"c": "prof", "zh": "“囧”的本义是什么？", "py": "“Jiǒng” de běnyì shì shénme?", "vi": "Nghĩa gốc của 囧 là gì?"}, {"me": "Cửa sổ sáng, nghĩa rộng là sáng sủa.", "opts": [["窗口光亮，引申为明亮、光明。", "Chuāngkǒu guāngliàng, yǐnshēnwèi míngliàng, guāngmíng.", "Cửa sổ sáng, nghĩa rộng là sáng sủa."], ["一个人在哭。", "Yíge rén zài kū.", "(chưa đúng với bài)"], ["一张桌子。", "Yìzhāng zhuōzi.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "在网络语言中，“囧”表示什么？", "py": "Zài wǎngluò yǔyán zhōng, “Jiǒng” biǎoshì shénme?", "vi": "Trên mạng 囧 biểu thị gì?"}, {"me": "Trạng thái buồn bực, khốn quẫn.", "opts": [["一个人郁闷、窘迫的心理状态。", "Yíge rén yùmèn, jiǒngpò de xīnlǐ zhuàngtài.", "Trạng thái buồn bực, khốn quẫn."], ["非常高兴。", "Fēichánggāoxìng.", "(chưa đúng với bài)"], ["很有钱。", "Hěn yǒuqián.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "网络语言之所以能很快为众多人所接受并迅速传播，正是由于其特征符合大众，特别是众多网民的需要和审美需求。“囧”也是如此。一个“囧”字，既有象形的图案，又有谐音的“窘”义，因此被网民迅速接受并使用。", "py": "Wǎngluò yǔyán zhī suǒyǐ néng hěn kuài wéi zhòngduō rén suǒ jiēshòu bìng xùnsù chuánbō, zhèng shì yóuyú qí tèzhēng fúhé dàzhòng, tèbié shì zhòngduō wǎngmín de xūyào hé shěnměi xūqiú. “Jiǒng” yě shì rúcǐ. Yī gè “jiǒng” zì, jì yǒu xiàngxíng de tú'àn, yòu yǒu xiéyīn de “jiǒng” yì, yīncǐ bèi wǎngmín xùnsù jiēshòu bìng shǐyòng.", "vi": "Ngôn ngữ mạng có thể nhanh chóng được đông đảo mọi người tiếp nhận và lan truyền nhanh chóng, chính là do đặc trưng của nó phù hợp với nhu cầu và thẩm mỹ của đại chúng, đặc biệt là của đông đảo cư dân mạng. \"Quẫn\" cũng như vậy. Một chữ \"Quẫn\", vừa có hình vẽ tượng hình, lại vừa có nghĩa hài âm là \"quẫn\" (khốn quẫn), vì thế được cư dân mạng nhanh chóng tiếp nhận và sử dụng."}, {"c": "prof", "zh": "“囧”为什么能很快被网民接受？", "py": "“Jiǒng” wèishénme néng hěnkuài bèi wǎngmín jiēshòu?", "vi": "Vì sao 囧 nhanh chóng được cư dân mạng chấp nhận?"}, {"me": "Vừa có hình tượng, vừa đồng âm với 窘.", "opts": [["既有象形的图案，又有谐音“窘”的意思。", "Jìyǒu xiàngxíng de túàn, yòu yǒu xiéyīn “Jiǒng” de yìsi.", "Vừa có hình tượng, vừa đồng âm với 窘."], ["因为政府要求使用。", "Yīnwèi zhèngfǔ yāoqiú shǐyòng.", "(chưa đúng với bài)"], ["因为它笔画很多。", "Yīnwèi tā bǐhuà hěnduō.", "(chưa đúng với bài)"]]}, {"c": "meimei", "zh": "“囧”具有简洁实用的特点。在网络交际中，人们为了以快捷的方式交流，往往利用数字、汉字的谐音以及用单字来表达较复杂的意义。“囧”与“窘”谐音，仅一个字就可以表达哭笑不得、不得已、郁闷等多种意义，具有很强的实用性。", "py": "“Jiǒng” jùyǒu jiǎnjié shíyòng de tèdiǎn. Zài wǎngluò jiāojì zhōng, rénmen wèile yǐ kuàijié de fāngshì jiāoliú, wǎngwǎng lìyòng shùzì, Hànzì de xiéyīn yǐjí yòng dānzì lái biǎodá jiào fùzá de yìyì. “Jiǒng” yǔ “jiǒng” xiéyīn, jǐn yī gè zì jiù kěyǐ biǎodá kūxiàobùdé, bùdéyǐ, yùmèn děng duō zhǒng yìyì, jùyǒu hěn qiáng de shíyòngxìng.", "vi": "\"Quẫn\" có đặc điểm đơn giản và thực dụng. Trong giao tiếp trên mạng, để giao lưu theo cách nhanh chóng, mọi người thường sử dụng chữ số, hài âm của chữ Hán và dùng một chữ đơn để biểu đạt ý nghĩa phức tạp hơn. \"Quẫn\" hài âm với \"quẫn\" (窘), chỉ một chữ đã có thể biểu đạt nhiều ý nghĩa như khóc cười không được, bất đắc dĩ, u uất, có tính thực dụng rất mạnh."}, {"c": "lee", "zh": "“囧”具有时尚风趣的特点。网民上网聊天，大多是为了减轻压力，发泄心中的烦恼，放松心情，而且他们大多是年轻人，因而时髦前卫的语言符合他们的审美需求。表示郁闷、哭笑不得的“囧”，在他们看来十分风趣。", "py": "“Jiǒng” jùyǒu shíshàng fēngqù de tèdiǎn. Wǎngmín shàngwǎng liáotiān, dàduō shì wèile jiǎnqīng yālì, fāxiè xīnzhōng de fánnǎo, fàngsōng xīnqíng, érqiě tāmen dàduō shì niánqīngrén, yīn'ér shímáo qiánwèi de yǔyán fúhé tāmen de shěnměi xūqiú. Biǎoshì yùmèn, kūxiàobùdé de “jiǒng”, zài tāmen kànlái shífēn fēngqù.", "vi": "\"Quẫn\" có đặc điểm thời thượng và thú vị. Cư dân mạng lên mạng trò chuyện, phần lớn là để giảm bớt áp lực, giải tỏa nỗi phiền não trong lòng, thư giãn tâm trạng, hơn nữa họ phần lớn là người trẻ tuổi, do đó ngôn ngữ thời thượng tiên phong phù hợp với nhu cầu thẩm mỹ của họ. \"Quẫn\" biểu thị sự u uất, khóc cười không được, trong mắt họ vô cùng thú vị."}, {"c": "prof", "zh": "网民上网聊天大多是为了什么？", "py": "Wǎngmín shàngwǎng liáotiān dàduō shì wèile shénme?", "vi": "Cư dân mạng chat chủ yếu để làm gì?"}, {"me": "Giảm áp lực, xả phiền muộn, thư giãn.", "opts": [["减轻压力，发泄烦恼，放松心情。", "Jiǎnqīng yālì, fāxiè fánnǎo, fàngsōng xīnqíng.", "Giảm áp lực, xả phiền muộn, thư giãn."], ["学习古代汉语。", "Xuéxí gǔdàihànyǔ.", "(chưa đúng với bài)"], ["找工作。", "Zhǎo gōngzuò.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "“囧”具有形象直观的特点，有利于更为直接地表达网民的意图。“囧”的“愁眉苦脸”的形象生动地展示了网友们的郁闷心情。", "py": "“Jiǒng” jùyǒu xíngxiàng zhíguān de tèdiǎn, yǒulì yú gèng wéi zhíjiē de biǎodá wǎngmín de yìtú. “Jiǒng” de “chóuméikǔliǎn” de xíngxiàng shēngdòng de zhǎnshìle wǎngyǒumen de yùmèn xīnqíng.", "vi": "\"Quẫn\" có đặc điểm hình tượng trực quan, có lợi cho việc biểu đạt ý đồ của cư dân mạng một cách trực tiếp hơn. Hình tượng \"mặt mày ủ dột\" của \"Quẫn\" đã sinh động thể hiện tâm trạng u uất của các bạn cư dân mạng."}, {"c": "meimei", "zh": "但是，我认为“囧”这类网络语言中的古代汉字还是越少越好，而且应限于在网络中使用，不要扩大到其他媒体。如果随便改变古代汉字的意义，那么可能有一天会影响到对古代的语言、古代的文化理解。以古求新的网络语言应当适可而止。", "py": "Dànshì, wǒ rènwéi “jiǒng” zhè lèi wǎngluò yǔyán zhōng de gǔdài Hànzì háishì yuè shǎo yuè hǎo, érqiě yīng xiànyú zài wǎngluò zhōng shǐyòng, bùyào kuòdà dào qítā méitǐ. Rúguǒ suíbiàn gǎibiàn gǔdài Hànzì de yìyì, nàme kěnéng yǒu yī tiān huì yǐngxiǎng dào duì gǔdài de yǔyán, gǔdài de wénhuà lǐjiě. Yǐ gǔ qiú xīn de wǎngluò yǔyán yīngdāng shìkě'érzhǐ.", "vi": "Nhưng, tôi cho rằng những chữ Hán cổ trong ngôn ngữ mạng như \"Quẫn\" càng ít càng tốt, hơn nữa nên hạn chế sử dụng trong mạng, không nên mở rộng sang các phương tiện truyền thông khác. Nếu tùy tiện thay đổi ý nghĩa của chữ Hán cổ, thì có thể một ngày nào đó sẽ ảnh hưởng đến việc hiểu biết về ngôn ngữ cổ, văn hóa cổ. Ngôn ngữ mạng \"dùng cái cũ để tìm cái mới\" nên dừng lại đúng lúc."}, {"c": "prof", "zh": "作者对“囧”这类网络语言有什么看法？", "py": "Zuòzhě duì “Jiǒng” zhè lèiwǎngluò yǔyán yǒu shénme kànfǎ?", "vi": "Tác giả nghĩ gì về loại từ mạng như 囧?"}, {"me": "Càng ít càng tốt, chỉ dùng trên mạng, nên vừa phải.", "opts": [["越少越好，应限于网络中使用，适可而止。", "Yuèshǎo yuè hǎo, yīng xiànyú wǎngluò zhōng shǐyòng, shìkěérzhǐ.", "Càng ít càng tốt, chỉ dùng trên mạng, nên vừa phải."], ["应该写进所有的课本。", "Yīnggāi xiě jìn suǒyǒu de kèběn.", "(chưa đúng với bài)"], ["越多越好。", "Yuèduōyuèhǎo.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "被……称为…… (Bèi... chēng wéi...)", "d": "Được... gọi là... Dịch: \"Quẫn\" được đông đảo cư dân mạng gọi là \"chữ ngầu nhất thế kỷ 21\".", "ex": [["“囧（jiǒng）”被众多网友称为“21世纪最牛的一个字”。", "“Jiǒng (Jiǒng)” bèi zhòngduō wǎngyǒu chēngwéi “21 shìjì zuìniú de yíge zì”.", ""]]}, {"t": "究竟…… (Jiūjìng...)", "d": "Rốt cuộc... (dùng để nhấn mạnh câu hỏi hoặc sự tò mò). Dịch: Rốt cuộc \"Quẫn\" có nghĩa là gì, và bắt nguồn từ đâu?", "ex": [["究竟“囧”是什么意思，又源于何处？", "Jiūjìng “Jiǒng” shì shénme yìsi, yòu yuányú héchù?", ""]]}, {"t": "据……解释 (Jù... jiěshì)", "d": "Theo... giải thích. Dịch: Theo giải thích trong \"Từ điển Hán ngữ cổ đại\"...", "ex": [["据《古代汉语词典》解释...", "Jù «Gǔdàihànyǔ cídiǎn» jiěshì...", ""]]}, {"t": "之所以……正是由于…… (Zhī suǒyǐ... zhèng shì yóuyú...)", "d": "Sở dĩ... chính là do... Dịch: Ngôn ngữ mạng sở dĩ có thể nhanh chóng được đông đảo mọi người tiếp nhận và lan truyền nhanh chóng, chính là do đặc trưng của nó phù hợp với đại chúng...", "ex": [["网络语言之所以能很快为众多人所接受并迅速传播，正是由于其特征符合大众...", "Wǎngluò yǔyán zhīsuǒyǐ néng hěnkuài wèi zhòngduō rén suǒ jiēshòu bìng xùnsù chuánbō, zhèngshì yóuyú qí tèzhēng fúhé dàzhòng...", ""]]}, {"t": "为……所…… (Wéi... suǒ...)", "d": "Được/bị... (cấu trúc bị động trong văn viết). Dịch: Được đông đảo mọi người tiếp nhận.", "ex": [["为众多人所接受。", "Wèi zhòngduō rén suǒ jiēshòu.", ""]]}, {"t": "为了…… (Wèile...)", "d": "Để... (chỉ mục đích). Dịch: Mọi người để giao lưu theo cách nhanh chóng...", "ex": [["人们为了以快捷的方式交流...", "Rénmen wèile yǐ kuàijié de fāngshì jiāoliú...", ""]]}, {"t": "往往…… (Wǎngwǎng...)", "d": "Thường thường... (chỉ quy luật hoặc thói quen). Dịch: Thường thường sử dụng chữ số, hài âm của chữ Hán...", "ex": [["往往利用数字、汉字的谐音...", "Wǎngwǎng lìyòng shùzì, hànzì de xiéyīn...", ""]]}, {"t": "仅……就…… (Jǐn... jiù...)", "d": "Chỉ cần... là đã... Dịch: Chỉ một chữ đã có thể biểu đạt nhiều ý nghĩa như dở khóc dở cười, bất đắc dĩ, u uất.", "ex": [["仅一个字就可以表达哭笑不得、不得已、郁闷等多种意义。", "Jǐn yíge zì jiù kěyǐ biǎodá kūxiàobùdé, bùdéyǐ, yùmèn děng duōzhǒng yìyì.", ""]]}], "order": [], "u": {"gq": [{"s": "被……称为……", "d": "Được… gọi là….", "ok": "“囧”被众多网友称为“21世纪最牛的一个字”。", "vi": "囧 được nhiều cư dân mạng gọi là “chữ ngầu nhất thế kỷ 21”.", "bad": ["“囧”被称为众多网友“21世纪最牛的一个字”。", "“囧”称为被众多网友“21世纪最牛的一个字”。"]}, {"s": "之所以……正是由于……", "d": "Sở dĩ… chính là do….", "ok": "网络语言之所以能很快传播，正是由于其特征符合大众的需要。", "vi": "Ngôn ngữ mạng sở dĩ lan nhanh chính là vì đặc điểm hợp nhu cầu số đông.", "bad": ["网络语言之所以能很快传播，所以由于其特征符合大众的需要。", "之所以网络语言能很快传播，正是其特征由于符合大众的需要。"]}, {"s": "为……所……", "d": "Được/bị… (bị động văn viết).", "ok": "网络语言能很快为众多人所接受。", "vi": "Ngôn ngữ mạng nhanh chóng được nhiều người chấp nhận.", "bad": ["网络语言能很快为众多人接受所。", "网络语言能很快所众多人为接受。"]}, {"s": "仅……就……", "d": "Chỉ… đã….", "ok": "仅一个字就可以表达多种意义。", "vi": "Chỉ một chữ đã diễn đạt được nhiều nghĩa.", "bad": ["仅一个字才可以表达多种意义。", "就一个字仅可以表达多种意义。"]}, {"s": "如果……那么……", "d": "Nếu… thì….", "ok": "如果随便改变古代汉字的意义，那么可能会影响对古代文化的理解。", "vi": "Nếu tùy tiện đổi nghĩa chữ cổ thì có thể ảnh hưởng việc hiểu văn hóa cổ.", "bad": ["如果随便改变古代汉字的意义，但是可能会影响对古代文化的理解。", "那么随便改变古代汉字的意义，如果可能会影响理解。"]}], "disc": [{"q": "你常用哪些网络词语？你觉得网络语言对语言发展好不好？", "py": "Nǐ chángyòng nǎxiē wǎngluò cíyǔ? Nǐ juéde wǎngluò yǔyán duì yǔyán fāzhǎn hǎobùhǎo?", "vi": "Bạn hay dùng từ mạng nào? Ngôn ngữ mạng tốt hay xấu cho phát triển ngôn ngữ?", "keys": ["之所以……是因为|之所以……正是由于", "如果……那么|如果……就", "越……越"], "sample": "我常用“囧”和“点赞”。网络语言之所以流行，是因为简单又有意思。但是如果大家什么地方都用，那么正式的语言会受到影响。我觉得在正式场合，网络词语越少越好。", "spy": "Wǒ chángyòng “Jiǒng” hé “Diǎnzàn”. Wǎngluò yǔyán zhīsuǒyǐ liúxíng, shìyīnwèi jiǎndān yòu yǒu yìsi. Dànshì rúguǒ dàjiā shénme dìfāng dōu yòng, nàme zhèngshì de yǔyán huì shòudào yǐngxiǎng. Wǒ juéde zài zhèngshì chǎnghé, wǎngluò cíyǔ yuèshǎo yuè hǎo."}], "comp": [{"vi": "Sở dĩ tôi học tiếng Trung là vì tôi thích văn hóa Trung Quốc. (之所以……是因为……)", "keys": ["之所以", "是因为|是由于"], "model": "我之所以学汉语，是因为我喜欢中国文化。", "mpy": "Wǒ zhīsuǒyǐ xué hànyǔ, shìyīnwèi wǒ xǐhuan zhōngguó wénhuà."}, {"vi": "Bài hát này được nhiều người trẻ yêu thích. (为……所……)", "keys": ["为", "所"], "model": "这首歌为很多年轻人所喜爱。", "mpy": "Zhè shǒugē wèi hěnduō niánqīngrén suǒ xǐài."}, {"vi": "Chỉ một ngày đã bán được một nghìn cuốn. (仅……就……)", "keys": ["仅", "就"], "model": "仅一天就卖出了一千本。", "mpy": "Jǐn yìtiān jiù màichū le yìqiānběn."}], "ex": [{"q": "“囧”的本义是什么？", "qvi": "Nghĩa gốc của 囧 là gì?", "a": "窗口光亮，引申为明亮、光明。", "avi": "Cửa sổ sáng, nghĩa rộng là sáng sủa.", "bad": ["一个人在哭。", "一张桌子。"], "p": 1}, {"q": "在网络语言中，“囧”表示什么？", "qvi": "Trên mạng 囧 biểu thị gì?", "a": "一个人郁闷、窘迫的心理状态。", "avi": "Trạng thái buồn bực, khốn quẫn.", "bad": ["非常高兴。", "很有钱。"], "p": 1}, {"q": "“囧”为什么能很快被网民接受？", "qvi": "Vì sao 囧 nhanh chóng được cư dân mạng chấp nhận?", "a": "既有象形的图案，又有谐音“窘”的意思。", "avi": "Vừa có hình tượng, vừa đồng âm với 窘.", "bad": ["因为政府要求使用。", "因为它笔画很多。"], "p": 2}, {"q": "网民上网聊天大多是为了什么？", "qvi": "Cư dân mạng chat chủ yếu để làm gì?", "a": "减轻压力，发泄烦恼，放松心情。", "avi": "Giảm áp lực, xả phiền muộn, thư giãn.", "bad": ["学习古代汉语。", "找工作。"], "p": 4}, {"q": "作者对“囧”这类网络语言有什么看法？", "qvi": "Tác giả nghĩ gì về loại từ mạng như 囧?", "a": "越少越好，应限于网络中使用，适可而止。", "avi": "Càng ít càng tốt, chỉ dùng trên mạng, nên vừa phải.", "bad": ["应该写进所有的课本。", "越多越好。"], "p": 6}]}}, {"id": "hk4-l10", "no": 10, "day": "HK4 · Bài 10", "time": "08:30", "scene": "classroom", "room": "classroom", "cast": ["prof", "zhangdong", "tianfang", "roland"], "vi": "Bàn về khiêm tốn", "zh": "谈谦虚", "py": "Tán qiānxū", "shop": {"label": "读书会", "sub": "Câu lạc bộ đọc sách", "icon": "📖"}, "vocab": [["满招损，谦受益", "mǎn zhāo sǔn, qiān shòu yì", "Khiêm tốn thì được lợi, kiêu ngạo thì chịu tổn hại", ""], ["检验", "jiǎnyàn", "Kiểm nghiệm, kiểm tra", ""], ["俯拾即是", "fǔshíjíshì", "Nhan nhản khắp nơi, cúi xuống là nhặt được", ""], ["拙作", "zhuōzuò", "Tác phẩm vụng về (cách nói khiêm tốn về tác phẩm của mình)", ""], ["愚见", "yújiàn", "Ý kiến ngu dốt (cách nói khiêm tốn về quan điểm của mình)", ""], ["受益", "shòuyì", "Được lợi, nhận lợi ích", ""], ["学者", "xuézhě", "Học giả", ""], ["实事求是", "shìqiúshìshì", "Thực sự cầu thị, tìm cầu chân lý từ sự thật", ""], ["康有为", "Kāng Yǒuwéi", "Khang Hữu Vi (nhà cải cách cuối thời Thanh)", ""], ["年届", "niánjiè", "Tuổi đời đến, tuổi đã đến mức", ""], ["革新家", "géxīnjiā", "Nhà cách tân, nhà đổi mới", ""], ["虚怀若谷", "xūhuáiruògǔ", "Khiêm tốn như thung lũng rỗng, lòng rộng lượng", ""], ["傲气", "àoqì", "Kiêu ngạo, vẻ kiêu căng", ""], ["样样通，样样松", "yàngyàng tōng, yàngyàng sōng", "Môn nào cũng biết, môn nào cũng lỏng (biết nhiều nhưng không chuyên sâu)", ""], ["自知之明", "zìzhīzhīmíng", "Sự tự biết mình, sự tự hiểu rõ bản thân", ""], ["虚度光阴", "xūdù guāngyīn", "Sống vô ích, lãng phí thời gian", ""], ["赞誉", "zànyù", "Khen ngợi, tán dương", ""], ["受之有愧", "shòuzhīyǒukuì", "Nhận được mà cảm thấy hổ thẹn, không xứng đáng nhận", ""], ["头衔", "tóuxián", "Danh hiệu, chức danh", ""], ["矛盾", "máodùn", "Mâu thuẫn", ""]], "story": [{"c": "panda", "vi": "HK4 · Bàn về khiêm tốn. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "zhangdong", "zh": "“满招损，谦受益”，这本来是中国一句老话，一直到了今天，还经常挂在人们嘴上。可见此话道出了一个真理，经过近三千年的检验，也说明它是可靠的。这句话适用于干一切工作的人，特别是做学问的人。", "py": "“Mǎn zhāo sǔn, qiān shòu yì”, zhè běnlái shì Zhōngguó yī jù lǎohuà, yīzhí dào le jīntiān, hái jīngcháng guà zài rénmen zuǐ shàng. Kějiàn cǐ huà dào chū le yī gè zhēnlǐ, jīngguò jìn sānqiān nián de jiǎnyàn, yě shuōmíng tā shì kěkào de. Zhè jù huà shìyòng yú gàn yīqiè gōngzuò de rén, tèbié shì zuò xuéwèn de rén.", "vi": "“Khiêm tốn thì được lợi, kiêu ngạo thì chịu tổn hại”, đây vốn là một câu nói cổ của Trung Quốc, cho đến tận ngày nay vẫn thường được mọi người nhắc đến. Có thể thấy câu nói này đã nói lên một chân lý, trải qua gần ba ngàn năm kiểm nghiệm, cũng chứng minh nó là đáng tin cậy. Câu nói này áp dụng cho tất cả những người làm bất kỳ công việc gì, đặc biệt là những người làm học vấn."}, {"c": "prof", "zh": "“满招损，谦受益”经过多长时间的检验？", "py": "“Mǎnzhāosǔn, qiānshòuyì” jīngguò duōzhǎngshíjiān de jiǎnyàn?", "vi": "“满招损，谦受益” đã được kiểm nghiệm bao lâu?"}, {"me": "Gần ba nghìn năm.", "opts": [["近三千年。", "Jìn sānqiānnián.", "Gần ba nghìn năm."], ["三十年。", "Sānshínián.", "(chưa đúng với bài)"], ["三百年。", "Sānbǎinián.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "根据我自己的思考与分析，谦虚有两种，一真一假。假谦虚的例子，真可以说是俯拾即是。中国人称自己的著作为拙作，自己的观点为愚见，这类谦虚的词，谁都知道是客气话，然而这种客气话不是真正的谦虚，也不会使任何人受益。", "py": "Gēnjù wǒ zìjǐ de sīkǎo yǔ fēnxī, qiānxū yǒu liǎng zhǒng, yī zhēn yī jiǎ. Jiǎ qiānxū de lìzi, zhēn kěyǐ shuō shì fǔshíjíshì. Zhōngguó rén chēng zìjǐ de zhùzuò wéi zhuōzuò (zhuōzuò), zìjǐ de guāndiǎn wéi yújiàn (yújiàn), zhè lèi qiānxū de cí, shuí dōu zhīdào shì kèqì huà, rán'ér zhè zhǒng kèqì huà bùshì zhēnzhèng de qiānxū, yě bù huì shǐ rènhé rén shòuyì.", "vi": "Theo suy nghĩ và phân tích của bản thân tôi, khiêm tốn có hai loại, một thật một giả. Những ví dụ về khiêm tốn giả, thật có thể nói là “cúi xuống là nhặt được” (nhan nhản khắp nơi). Người Trung Quốc gọi tác phẩm của mình là “chuyết tác” (tác phẩm vụng về), quan điểm của mình là “ngu kiến” (ý kiến ngu dốt), những từ khiêm tốn như thế này, ai cũng biết là lời khách sáo, nhưng loại lời khách sáo này không phải là sự khiêm tốn thực sự, cũng sẽ không khiến bất kỳ ai được lợi."}, {"c": "prof", "zh": "作者认为什么是假谦虚？", "py": "Zuòzhě rènwéi shénme shì jiǎ qiānxū?", "vi": "Tác giả cho rằng thế nào là khiêm tốn giả?"}, {"me": "Những lời khách sáo như gọi tác phẩm của mình là “拙作”.", "opts": [["把自己的著作叫“拙作”这类客气话。", "Bǎ zìjǐ de zhùzuò jiào “Zhuōzuò” zhè lèi kèqìhuà.", "Những lời khách sáo như gọi tác phẩm của mình là “拙作”."], ["认真向别人学习。", "Rènzhēn xiàng biérén xuéxí.", "(chưa đúng với bài)"], ["承认自己知识不够。", "Chéngrèn zìjǐ zhīshí búgòu.", "(chưa đúng với bài)"]]}, {"c": "roland", "zh": "我们要的是真正的谦虚，做学问更是如此。如果一个学者，不管是年轻的，还是中年的、老年的，觉得自己的学问已经够大了，没有必要再进行学习了，他就不会再进步。事实上，不管你搞哪一门学问，绝不会有搞得完全彻底一点问题也不留的。人即使能活上1000年，也是办不到的。因此，在做学问上谦虚，不但表示这个人有道德，也表示这个人是实事求是的。", "py": "Wǒmen yào de shì zhēnzhèng de qiānxū, zuò xuéwèn gèng shì rúcǐ. Rúguǒ yī gè xuézhě, bùguǎn shì niánqīng de, háishì zhōngnián de, lǎonián de, juéde zìjǐ de xuéwèn yǐjīng gòu dà le, méiyǒu bìyào zài jìnxíng xuéxí le, tā jiù bù huì zài jìnbù. Shìshí shàng, bùguǎn nǐ gǎo nǎ yī mén xuéwèn, jué bù huì yǒu gǎo de wánquán chèdǐ yīdiǎn wèntí yě bù liú de. Rén jíshǐ néng huó shàng 1000 nián, yě shì bàn bù dào de. Yīncǐ, zài zuò xuéwèn shàng qiānxū, bùdàn biǎoshì zhège rén yǒu dàodé, yě biǎoshì zhège rén shì shìqiúshìshì de.", "vi": "Chúng ta cần là sự khiêm tốn thực sự, làm học vấn lại càng như vậy. Nếu một học giả, bất kể là trẻ tuổi, hay trung niên, hay già, cảm thấy học vấn của mình đã đủ lớn rồi, không cần thiết phải tiếp tục học nữa, thì anh ta sẽ không tiến bộ được nữa. Trên thực tế, bất kể bạn nghiên cứu môn học nào, tuyệt đối không thể có chuyện nghiên cứu triệt để hoàn toàn mà không để lại một vấn đề nào. Con người cho dù có thể sống đến 1000 năm, cũng không làm được điều đó. Vì vậy, khiêm tốn trong việc làm học vấn, không chỉ biểu thị người này có đạo đức, mà còn biểu thị người này là người thực sự cầu thị."}, {"c": "prof", "zh": "为什么做学问要谦虚？", "py": "Wèishénme zuòxuéwèn yào qiānxū?", "vi": "Vì sao làm học vấn phải khiêm tốn?"}, {"me": "Học vấn không bao giờ học hết, thấy đủ rồi thì sẽ không tiến bộ.", "opts": [["学问永远学不完，觉得自己够了就不会进步。", "Xuéwen yǒngyuǎn xuébùwán, juéde zìjǐ gòu le jiù búhuì jìnbù.", "Học vấn không bao giờ học hết, thấy đủ rồi thì sẽ không tiến bộ."], ["因为谦虚可以得到奖金。", "Yīnwèi qiānxū kěyǐ dédào jiǎngjīn.", "(chưa đúng với bài)"], ["因为老师要求。", "Yīnwèi lǎoshī yāoqiú.", "(chưa đúng với bài)"]]}, {"c": "zhangdong", "zh": "听说康有为说过，他年届三十，就把天下学问学完了。仅仅从这件事情上，就可以证明，康有为并不懂得什么叫做学问。现在有人称他为“国学大师”，我认为是可笑的。他至多只能算是一个革新家。在当今中国学术界，自认为了不起的人，到处都能看到；而真正虚怀若谷的人，却非常少见。有不少年轻的学者，写过几篇论文，出过几册专著，就傲气十足。这种态度不利于他们自己的进步，也不利于中国学术的发展。", "py": "Tīngshuō Kāng Yǒuwéi shuōguò, tā niánjiè (jiè) sānshí, jiù bǎ tiānxià xuéwèn xué wán le. Jǐnjǐn cóng zhè jiàn shìqíng shàng, jiù kěyǐ zhèngmíng, Kāng Yǒuwéi bìng bù dǒngdé shénme jiào zuò xuéwèn. Xiànzài yǒu rén chēng tā wéi “guóxué dàshī”, wǒ rènwéi shì kěxiào de. Tā zhìduō zhǐnéng suàn shì yī gè géxīnjiā. Zài dāngjīn Zhōngguó xuéshùjiè, zì rènwéi liǎobùqǐ de rén, dàochù dōu néng kàndào; ér zhēnzhèng xūhuáiruògǔ de rén, què fēicháng shǎojiàn. Yǒu bùshǎo niánqīng de xuézhě, xiěguò jǐ piān lùnwén, chūguò jǐ cè zhuānzhù, jiù àoqì (àoqì) shízú. Zhè zhǒng tàidù bù lìyú tāmen zìjǐ de jìnbù, yě bù lìyú Zhōngguó xuéshù de fāzhǎn.", "vi": "Nghe nói Khang Hữu Vi đã từng nói, ông ta khi tuổi đời mới ba mươi, đã học hết học vấn thiên hạ rồi. Chỉ riêng từ sự việc này, đã có thể chứng minh, Khang Hữu Vi hoàn toàn không hiểu thế nào gọi là học vấn. Hiện nay có người gọi ông ta là “Quốc học đại sư”, tôi cho rằng thật là nực cười. Ông ta cùng lắm chỉ có thể được coi là một nhà cách tân. Trong giới học thuật Trung Quốc ngày nay, những người tự cho mình là ghê gớm, đâu đâu cũng có thể thấy; nhưng những người thực sự khiêm tốn (lòng rỗng như thung lũng) thì lại vô cùng hiếm thấy. Có không ít học giả trẻ tuổi, viết được vài bài luận văn, xuất bản được vài cuốn chuyên khảo, là đã kiêu ngạo đầy mình. Thái độ này không có lợi cho sự tiến bộ của bản thân họ, cũng không có lợi cho sự phát triển của học thuật Trung Quốc."}, {"c": "prof", "zh": "作者怎么看康有为？", "py": "Zuòzhě zěnme kàn kāngyǒuwéi?", "vi": "Tác giả nhìn Khang Hữu Vi thế nào?"}, {"me": "Ông không hiểu thế nào là học vấn, nhiều nhất là nhà cải cách.", "opts": [["他不懂什么叫做学问，至多是一个革新家。", "Tā bù dǒng shénme jiàozuò xuéwen, zhìduōshì yíge géxīnjiā.", "Ông không hiểu thế nào là học vấn, nhiều nhất là nhà cải cách."], ["他是真正的国学大师。", "Tā shì zhēnzhèng de guóxué dàshī.", "(chưa đúng với bài)"], ["他是最谦虚的学者。", "Tā shì zuì qiānxū de xuézhě.", "(chưa đúng với bài)"]]}, {"c": "tianfang", "zh": "我自己怎样呢？我总觉得自己不行。我常常讲，我是样样通，样样松。我一生勤奋学习，天天都在读书写文章，但一遇到一个必须深入钻研的问题，就会觉得自己知识不够。一个人要有自知之明很难，我却觉得，自己有时谦虚得过了头，简直不是谦虚，而是心虚了。自己谦虚可以说是一个好现象，但是我心里又有极大的矛盾：我看待别人也有很高的标准，我觉得真正行的人非常少。我觉得好多人学不够勤奋，有的人天天虚度光阴。我经常处在这种心理矛盾中。别人对我的赞誉，我非常感激；但是我要劝大家，不要全信那些赞誉。有人要给我安上“国学大师”等头衔，那些高得惊人的帽子，我更是受之有愧。", "py": "Wǒ zìjǐ zěnyàng ne? Wǒ zǒng juéde zìjǐ bùxíng. Wǒ chángcháng jiǎng, wǒ shì yàngyàng tōng, yàngyàng sōng. Wǒ yīshēng qínfèn xuéxí, tiāntiān dōu zài dúshū xiě wénzhāng, dàn yī yùdào yī gè bìxū shēnrù zuānyán de wèntí, jiù huì juéde zìjǐ zhīshì bùgòu. Yī gè rén yào yǒu zìzhīzhīmíng hěn nán, wǒ què juéde, zìjǐ yǒushí qiānxū de guò le tóu, jiǎnzhí bùshì qiānxū, ér shì xīnxū le. Zìjǐ qiānxū kěyǐ shuō shì yī gè hǎo xiànxiàng, dànshì wǒ xīnlǐ yòu yǒu jídà de máodùn: wǒ kàndài biérén yě yǒu hěn gāo de biāozhǔn, wǒ juéde zhēnzhèng xíng de rén fēicháng shǎo. Wǒ juéde hǎo duō rén xué bù gòu qínfèn, yǒu de rén tiāntiān xūdù guāngyīn. Wǒ jīngcháng chǔ zài zhè zhǒng xīnlǐ máodùn zhōng. Biérén duì wǒ de zànyù, wǒ fēicháng gǎnjī; dànshì wǒ yào quàn dàjiā, bùyào quán xìn nàxiē zànyù. Yǒu rén yào gěi wǒ ān shàng “guóxué dàshī” děng tóuxián, nàxiē gāo de jīngrén de màozi, wǒ gèng shì shòuzhīyǒukuì.", "vi": "Bản thân tôi thì thế nào? Tôi luôn cảm thấy mình không giỏi. Tôi thường nói, tôi là “môn nào cũng biết, môn nào cũng lỏng”. Cả đời tôi chăm chỉ học tập, ngày ngày đều đọc sách viết văn, nhưng hễ gặp phải một vấn đề cần phải nghiên cứu sâu, là lại cảm thấy kiến thức của mình không đủ. Một người có được sự tự biết mình là rất khó, nhưng tôi lại cảm thấy, đôi khi mình khiêm tốn quá mức, đơn giản không phải là khiêm tốn, mà là tự ti (chột dạ). Bản thân khiêm tốn có thể nói là một hiện tượng tốt, nhưng trong lòng tôi lại có mâu thuẫn cực lớn: Tôi nhìn nhận người khác cũng có tiêu chuẩn rất cao, tôi cảm thấy người thực sự giỏi rất ít. Tôi cảm thấy nhiều người học không đủ chăm chỉ, có người ngày ngày sống vô ích. Tôi thường xuyên ở trong trạng thái mâu thuẫn tâm lý này. Người khác khen ngợi tôi, tôi vô cùng biết ơn; nhưng tôi muốn khuyên mọi người, đừng tin hoàn toàn những lời khen ngợi đó. Có người muốn gán cho tôi danh hiệu “Quốc học đại sư” v.v., những chiếc mũ cao đến kinh người đó, tôi lại càng cảm thấy hổ thẹn khi nhận được."}, {"c": "prof", "zh": "作者心里有什么矛盾？", "py": "Zuòzhě xīnlǐ yǒu shénme máodùn?", "vi": "Trong lòng tác giả có mâu thuẫn gì?"}, {"me": "Mình rất khiêm tốn nhưng tiêu chuẩn với người khác cũng rất cao.", "opts": [["自己很谦虚，但看待别人的标准也很高。", "Zìjǐ hěn qiānxū, dàn kàndài biérén de biāozhǔn yě hěn gāo.", "Mình rất khiêm tốn nhưng tiêu chuẩn với người khác cũng rất cao."], ["他想当国学大师，又不想学习。", "Tā xiǎng dāng guóxué dàshī, yòu bùxiǎng xuéxí.", "(chưa đúng với bài)"], ["他不喜欢读书。", "Tā bù xǐhuan dúshū.", "(chưa đúng với bài)"]]}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "一真一假 (yī zhēn yī jiǎ)", "d": "一 + A + 一 + B Biểu thị hai sự vật/tính chất đối lập nhau, tương ứng với “một... một...”, “vừa... vừa...”.", "ex": [["谦虚有两种，一真一假。", "Qiānxū yǒu liǎngzhǒng, yìzhēn yìjiǎ.", "Khiêm tốn có hai loại, một thật một giả."]]}, {"t": "不管...还是... (bùguǎn... háishì...)", "d": "不管 + [các lựa chọn] + 都/也... “Bất kể là... hay là...”, dùng để chỉ sự lựa chọn không ảnh hưởng đến kết quả.", "ex": [["如果一个学者，不管是年轻的，还是中年的、老年的...", "Rúguǒ yíge xuézhě, bùguǎn shì niánqīng de, háishì zhōngnián de, lǎonián de...", "Nếu một học giả, bất kể là trẻ tuổi, hay trung niên, hay già..."]]}, {"t": "即使...也... (jíshǐ... yě...)", "d": "即使 + [giả thiết] + 也 + [kết quả] “Cho dù... cũng...”, biểu thị sự nhượng bộ.", "ex": [["人即使能活上1000年，也是办不到的。", "Rén jíshǐ nénghuó shàng1000 nián, yě shì bànbúdào de.", "Con người cho dù có thể sống đến 1000 năm, cũng không làm được."]]}, {"t": "不但...也... (bùdàn... yě...)", "d": "不但 + A + 也 + B “Không những... mà còn...”, biểu thị quan hệ tiến thêm một bước.", "ex": [["不但表示这个人有道德，也表示这个人是实事求是的。", "Búdàn biǎoshì zhège rényǒu dàodé, yě biǎoshì zhège rén shì shíshìqiúshì de.", "Không chỉ biểu thị người này có đạo đức, mà còn biểu thị người này là người thực sự cầu thị."]]}, {"t": "一...就... (yī... jiù...)", "d": "一 + [hành động/điều kiện] + 就 + [kết quả] “Hễ... là...”, “vừa... là...”, biểu thị kết quả xảy ra ngay sau điều kiện.", "ex": [["一遇到一个必须深入钻研的问题，就会觉得自己知识不够。", "Yí yùdào yíge bìxū shēnrù zuānyán de wèntí, jiù huì juéde zìjǐ zhīshí búgòu.", "Hễ gặp phải một vấn đề cần phải nghiên cứu sâu, là lại cảm thấy kiến thức của mình không đủ."]]}, {"t": "简直 (jiǎnzhí)", "d": "“Đơn giản là”, “quả thực là”, dùng để nhấn mạnh mức độ, thường mang ý nghĩa hơi cường điệu.", "ex": [["简直不是谦虚，而是心虚了。", "Jiǎnzhí búshì qiānxū, érshì xīnxū le.", "Đơn giản không phải là khiêm tốn, mà là tự ti/chột dạ."]]}, {"t": "受之有愧 (shòuzhīyǒukuì)", "d": "Đây là một thành ngữ, có nghĩa là “nhận được mà cảm thấy hổ thẹn”, thường dùng để nói khiêm tốn khi nhận được lời khen hoặc danh hiệu.", "ex": [["那些高得惊人的帽子，我更是受之有愧。", "Nàxiē gāodé jīngrén de màozi, wǒ gèngshì shòuzhīyǒukuì.", "Những chiếc mũ cao đến kinh người đó, tôi lại càng cảm thấy hổ thẹn khi nhận được."]]}], "order": [], "u": {"gq": [{"s": "不管……还是……", "d": "Bất kể… hay… (đều).", "ok": "不管是年轻的，还是老年的学者，都不应该停止学习。", "vi": "Bất kể học giả trẻ hay già đều không nên ngừng học.", "bad": ["不管是年轻的，或者老年的学者，就不应该停止学习。", "虽然是年轻的，还是老年的学者，都不应该停止学习。"]}, {"s": "即使……也……", "d": "Cho dù… cũng….", "ok": "人即使能活上1000年，也是办不到的。", "vi": "Con người cho dù sống được 1000 năm cũng không làm nổi.", "bad": ["人即使能活上1000年，所以是办不到的。", "人即使能活上1000年，就是办不到的。"]}, {"s": "不但……也……", "d": "Không những… mà còn….", "ok": "谦虚不但表示这个人有道德，也表示这个人实事求是。", "vi": "Khiêm tốn không những cho thấy có đạo đức mà còn thực sự cầu thị.", "bad": ["谦虚不但表示这个人有道德，但表示这个人实事求是。", "不但谦虚表示这个人有道德，也而且表示实事求是。"]}, {"s": "一……就……", "d": "Hễ… là….", "ok": "一遇到必须深入钻研的问题，就会觉得自己知识不够。", "vi": "Hễ gặp vấn đề phải nghiên cứu sâu là thấy kiến thức mình chưa đủ.", "bad": ["一遇到必须深入钻研的问题，才会觉得自己知识不够。", "就遇到必须深入钻研的问题，一会觉得自己知识不够。"]}, {"s": "不是……而是……", "d": "Không phải… mà là….", "ok": "简直不是谦虚，而是心虚了。", "vi": "Quả thực không phải khiêm tốn mà là chột dạ.", "bad": ["简直不是谦虚，但是心虚了。", "简直而是谦虚，不是心虚了。"]}], "disc": [{"q": "你觉得谦虚和自信矛盾吗？为什么？", "py": "Nǐ juéde qiānxū hé zìxìn máodùn ma? Wèishénme?", "vi": "Bạn thấy khiêm tốn và tự tin có mâu thuẫn không? Vì sao?", "keys": ["不但……也|不但……而且", "不是……而是", "即使……也"], "sample": "我觉得谦虚和自信不矛盾。真正的谦虚不是说客气话，而是知道自己还要学习。一个人不但要有自信，也要谦虚。即使学得很好，也不应该觉得自己了不起。", "spy": "Wǒ juéde qiānxū hé zìxìn bù máodùn. Zhēnzhèng de qiānxū búshì shuō kèqìhuà, érshì zhīdao zìjǐ háiyào xuéxí. Yíge rén búdàn yào yǒu zìxìn, yě yào qiānxū. Jíshǐ xuédé hěn hǎo, yě bù yīnggāi juéde zìjǐ liǎobùqǐ."}], "comp": [{"vi": "Bất kể là ai cũng phải tuân thủ quy định. (不管……都……)", "keys": ["不管", "都"], "model": "不管是谁，都要遵守规定。", "mpy": "Bùguǎnshìshuí, dōu yào zūnshǒu guīdìng."}, {"vi": "Hễ có thời gian là tôi đến thư viện. (一……就……)", "keys": ["一", "就"], "model": "我一有时间就去图书馆。", "mpy": "Wǒ yìyǒu shíjiān jiù qù túshūguǎn."}, {"vi": "Đây không phải khiêm tốn mà là thiếu tự tin. (不是……而是……)", "keys": ["不是", "而是"], "model": "这不是谦虚，而是没有自信。", "mpy": "Zhè búshì qiānxū, érshì méiyǒu zìxìn."}], "ex": [{"q": "“满招损，谦受益”经过多长时间的检验？", "qvi": "“满招损，谦受益” đã được kiểm nghiệm bao lâu?", "a": "近三千年。", "avi": "Gần ba nghìn năm.", "bad": ["三十年。", "三百年。"], "p": 0}, {"q": "作者认为什么是假谦虚？", "qvi": "Tác giả cho rằng thế nào là khiêm tốn giả?", "a": "把自己的著作叫“拙作”这类客气话。", "avi": "Những lời khách sáo như gọi tác phẩm của mình là “拙作”.", "bad": ["认真向别人学习。", "承认自己知识不够。"], "p": 1}, {"q": "为什么做学问要谦虚？", "qvi": "Vì sao làm học vấn phải khiêm tốn?", "a": "学问永远学不完，觉得自己够了就不会进步。", "avi": "Học vấn không bao giờ học hết, thấy đủ rồi thì sẽ không tiến bộ.", "bad": ["因为谦虚可以得到奖金。", "因为老师要求。"], "p": 2}, {"q": "作者怎么看康有为？", "qvi": "Tác giả nhìn Khang Hữu Vi thế nào?", "a": "他不懂什么叫做学问，至多是一个革新家。", "avi": "Ông không hiểu thế nào là học vấn, nhiều nhất là nhà cải cách.", "bad": ["他是真正的国学大师。", "他是最谦虚的学者。"], "p": 3}, {"q": "作者心里有什么矛盾？", "qvi": "Trong lòng tác giả có mâu thuẫn gì?", "a": "自己很谦虚，但看待别人的标准也很高。", "avi": "Mình rất khiêm tốn nhưng tiêu chuẩn với người khác cũng rất cao.", "bad": ["他想当国学大师，又不想学习。", "他不喜欢读书。"], "p": 4}]}}, {"id": "hk4-l11", "no": 11, "day": "HK4 · Bài 11", "time": "20:00", "scene": "living", "room": "living", "cast": ["prof", "mom", "meimei", "edward"], "vi": "Thưởng thức phim “Người thương tôi nhất đã ra đi”", "zh": "《世界上最疼我的那个人去了》赏析", "py": "«Shìjiè shàng zuì téng wǒ de nàge rénqù le» shǎngxī", "shop": {"label": "电影院", "sub": "Rạp chiếu phim", "icon": "🎬"}, "vocab": [["赏析", "shǎngxī", "Thưởng thức và phân tích", ""], ["改编", "gǎibiān", "Chuyển thể, cải biên", ""], ["剧情", "jùqíng", "Cốt truyện, tình tiết phim", ""], ["内心活动", "nèixīn huódòng", "Hoạt động nội tâm", ""], ["回味", "huíwèi", "Suy ngẫm, hồi tưởng lại (thấy thú vị)", ""], ["领悟", "lǐngwù", "Lĩnh hội, hiểu ra", ""], ["共鸣", "gòngmíng", "Đồng cảm, cộng hưởng", ""], ["分寸", "fēncùn", "Mức độ, chừng mực", ""], ["适得其反", "shìdéqífǎn", "Đi ngược lại mong muốn, phản tác dụng", ""], ["一相情愿", "yīxiāngqíngyuàn", "Tự cho mình là đúng, một phía mong muốn (thường viết là 一厢情愿)", ""], ["来日方长", "láirìfāngcháng", "Ngày tháng còn dài, tương lai còn dài", ""], ["掩盖", "yǎngài", "Che giấu, che đậy", ""], ["饱满", "bǎomǎn", "Đầy đặn, tràn đầy", ""], ["恰到好处", "qiàdàohǎochù", "Vừa vặn, đúng mức", ""], ["处女作", "chùnǚzuò", "Tác phẩm đầu tay", ""], ["感同身受", "gǎntóngshēnshòu", "Đồng cảm sâu sắc, như chính mình trải qua", ""], ["朴素", "pǔsù", "Mộc mạc, giản dị", ""], ["诚意", "chéngyì", "Thành ý, sự chân thành", ""], ["核心", "héxīn", "Cốt lõi, trọng tâm", ""], ["风风雨雨", "fēngfēngyǔyǔ", "Sóng gió, gian nan thử thách", ""]], "story": [{"c": "panda", "vi": "HK4 · Thưởng thức phim “Người thương tôi nhất đã ra đi”. Buổi seminar: mọi người đọc bài khóa gốc, giáo sư hỏi, em trả lời bằng 🎤 (hoặc chạm “Gợi ý câu”)."}, {"c": "mom", "zh": "电影《世界上最疼我的那个人去了》根据同名小说改编，电影的剧情很简单，讲述的是一位女作家在老母亲生重病后，与母亲相处的最后一段日子中所发生的事情。这个简单的故事所展现出来的人物的内心活动，则令人回味，也是需要观众慢慢去领悟的。", "py": "Diànyǐng 《Shìjiè shàng zuì téng wǒ de nàge rén qù le》 gēnjù tóngmíng xiǎoshuō gǎibiān, diànyǐng de jùqíng hěn jiǎndān, jiǎngshù de shì yī wèi nǚ zuòjiā zài lǎo mǔqīn shēng zhòngbìng hòu, yǔ mǔqīn xiāngchǔ de zuìhòu yī duàn rìzi zhōng suǒ fāshēng de shìqíng. Zhège jiǎndān de gùshì suǒ zhǎnxiàn chūlái de rénwù de nèixīn huódòng, zé lìng rén huíwèi, yě shì xūyào guānzhòng mànmàn qù lǐngwù de.", "vi": "Bộ phim \"Người thương tôi nhất trên thế gian đã ra đi\" được chuyển thể từ tiểu thuyết cùng tên, cốt truyện của phim rất đơn giản, kể về những sự việc xảy ra trong khoảng thời gian cuối cùng mà một nữ nhà văn sống cùng mẹ sau khi mẹ già bị bệnh nặng. Những hoạt động nội tâm của nhân vật được thể hiện qua câu chuyện đơn giản này khiến người ta phải suy ngẫm, và cũng cần khán giả từ từ lĩnh hội."}, {"c": "prof", "zh": "这部电影讲的是什么故事？", "py": "Zhèbù diànyǐng jiǎng de shì shénme gùshi?", "vi": "Phim kể câu chuyện gì?"}, {"me": "Những ngày cuối cùng một nữ nhà văn ở bên mẹ sau khi mẹ bệnh nặng.", "opts": [["一位女作家在母亲生重病后与母亲相处的最后一段日子。", "Yíwèi nǚzuòjiā zài mǔqīn shēng zhòngbìng hòu yǔ mǔqīn xiāngchǔ de zuìhòu yíduàn rìzi.", "Những ngày cuối cùng một nữ nhà văn ở bên mẹ sau khi mẹ bệnh nặng."], ["一位母亲去国外旅行。", "Yíwèi mǔqīn qù guówài lǚxíng.", "(chưa đúng với bài)"], ["两个朋友一起创业。", "Liǎngge péngyou yìqǐ chuàngyè.", "(chưa đúng với bài)"]]}, {"c": "meimei", "zh": "在作品中表现这样一段由母女二人构成的情感故事既容易，又困难。容易的是每个人都有母亲，演员的表演很容易引起观众的共鸣，然而，也正因为母女、母子之情是每个人都有切身体会的情感，如果表演分寸把握不好，效果会适得其反。", "py": "Zài zuòpǐn zhōng biǎoxiàn zhèyàng yī duàn yóu mǔ nǚ èr rén gòuchéng de qínggǎn gùshì jì róngyì, yòu kùnnán. Róngyì de shì měi gè rén dōu yǒu mǔqīn, yǎnyuán de biǎoyǎn hěn róngyì yǐnqǐ guānzhòng de gòngmíng, rán'ér, yě zhèng yīnwèi mǔ nǚ, mǔ zǐ zhī qíng shì měi gè rén dōu yǒu qiètǐ huì de qínggǎn, rúguǒ biǎoyǎn fēncùn bǎwò bù hǎo, xiàoguǒ huì shìdéqífǎn.", "vi": "Việc thể hiện một câu chuyện tình cảm được tạo nên bởi hai mẹ con như thế này trong tác phẩm vừa dễ lại vừa khó. Cái dễ là vì mỗi người đều có mẹ, diễn xuất của diễn viên rất dễ gây được sự đồng cảm nơi khán giả, tuy nhiên, cũng chính vì tình mẫu tử, tình mẹ con là thứ tình cảm mà mỗi người đều có sự thấu hiểu sâu sắc, nếu không nắm bắt tốt mức độ diễn xuất, hiệu quả sẽ đi ngược lại mong muốn."}, {"c": "prof", "zh": "为什么说表现母女的故事“既容易又困难”？", "py": "Wèishénme shuō biǎoxiàn mǔnǚ de gùshi “Jì róngyì yòu kùnnán”?", "vi": "Vì sao nói kể chuyện mẹ con “vừa dễ vừa khó”?"}, {"me": "Dễ gây đồng cảm, nhưng không giữ chừng mực sẽ phản tác dụng.", "opts": [["容易引起共鸣，但分寸把握不好会适得其反。", "Róngyì yǐnqǐgòngmíng, dàn fēncùn bǎwò bùhǎo huì shìdéqífǎn.", "Dễ gây đồng cảm, nhưng không giữ chừng mực sẽ phản tác dụng."], ["因为演员太少。", "Yīnwèi yǎnyuán tài shǎo.", "(chưa đúng với bài)"], ["因为电影太长。", "Yīnwèi diànyǐng tài zhǎng.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "剧中的作家就像一面镜子。从她身上我们既看到自己对父母的爱，又清晰地照见自己的自私。在母亲生病的时候，许多人会像那位作家那样尽全力照顾母亲，希望母亲快点儿恢复健康，但内心更真实的愿望是尽快回到正常生活秩序中去。没有多少人会意识到最辛苦的是生病的母亲，每个人都一相情愿地认为来日方长，而手头的工作和自己读书的孩子似乎都比养育了自己的母亲更重要。", "py": "Jù zhōng de zuòjiā jiù xiàng yī miàn jìngzi. Cóng tā shēnshang wǒmen jì kàndào zìjǐ duì fùmǔ de ài, yòu qīngxī de zhào jiàn zìjǐ de zìsī. Zài mǔqīn shēngbìng de shíhòu, xǔduō rén huì xiàng nà wèi zuòjiā nàyàng jìn quánlì zhàogù mǔqīn, xīwàng mǔqīn kuài diǎnr huīfù jiànkāng, dàn nèixīn gèng zhēnshí de yuànwàng shì jǐnkuài huídào zhèngcháng shēnghuó zhìxù zhōng qù. Méiyǒu duōshǎo rén huì yìshí dào zuì xīnkǔ de shì shēngbìng de mǔqīn, měi gè rén dōu yīxiāngqíngyuàn de rènwéi láirìfāngcháng, ér shǒutóu de gōngzuò hé zìjǐ dúshū de háizi sìhū dōu bǐ yǎngyù le zìjǐ de mǔqīn gèng zhòngyào.", "vi": "Nhà văn trong phim giống như một tấm gương. Từ cô ấy, chúng ta vừa nhìn thấy tình yêu của mình dành cho cha mẹ, lại vừa soi rõ được sự ích kỷ của bản thân. Khi mẹ bị bệnh, nhiều người sẽ giống như nhà văn đó, dốc hết sức chăm sóc mẹ, mong mẹ nhanh chóng hồi phục sức khỏe, nhưng mong muốn thực sự hơn trong lòng là sớm quay trở lại trật tự cuộc sống bình thường. Không có nhiều người ý thức được rằng người vất vả nhất chính là người mẹ bị bệnh, mỗi người đều tự cho mình là đúng mà nghĩ rằng ngày tháng còn dài, còn công việc trước mắt và đứa con đang đi học của mình dường như đều quan trọng hơn người mẹ đã nuôi nấng mình."}, {"c": "prof", "zh": "剧中的作家像一面镜子，让我们看到了什么？", "py": "Jùzhōng de zuòjiā xiàng yímiànjìngzi, ràng wǒmen kàndào le shénme?", "vi": "Nhà văn trong phim như tấm gương, cho ta thấy gì?"}, {"me": "Tình yêu với cha mẹ và cả sự ích kỷ của mình.", "opts": [["自己对父母的爱，也照见自己的自私。", "Zìjǐ duì fùmǔ de ài, yě zhàojiàn zìjǐ de zìsī.", "Tình yêu với cha mẹ và cả sự ích kỷ của mình."], ["自己的长相。", "Zìjǐ de zhǎngxiàng.", "(chưa đúng với bài)"], ["别人的缺点。", "Biérén de quēdiǎn.", "(chưa đúng với bài)"]]}, {"c": "mom", "zh": "演员的出色表演令人感动，尤其是母亲的扮演者黄素影，她将一位经历了人生的风风雨雨、但仍坚强地面对生活的母亲表现得亲切感人。剧中的母亲始终担心给女儿添麻烦，自然而然地将自己的需求放在第二位。母亲一生中曾经受过苦难，有过感伤，而这一切都被她的平和、幽默所悄悄掩盖。", "py": "Yǎnyuán de chūsè biǎoyǎn lìng rén gǎndòng, yóuqí shì mǔqīn de bànyǎnzhě Huáng Sùyǐng, tā jiāng yī wèi jīnglì le rénshēng de fēngfēngyǔyǔ, dàn réng jiānqiáng de miànduì shēnghuó de mǔqīn biǎoxiàn de qīnqiè gǎnrén. Jù zhōng de mǔqīn shǐzhōng dānxīn gěi nǚ'ér tiān máfan, zìrán'érrán de jiāng zìjǐ de xūqiú fàng zài dì èr wèi. Mǔqīn yīshēng zhōng céngjīng shòuguò kǔnàn, yǒuguò gǎnshāng, ér zhè yīqiè dōu bèi tā de pínghé, yōumò suǒ qiāoqiāo yǎngài.", "vi": "Diễn xuất xuất sắc của diễn viên khiến người ta cảm động, đặc biệt là người đóng vai mẹ - Hoàng Tố Ảnh, bà đã thể hiện một người mẹ đã trải qua những sóng gió của cuộc đời, nhưng vẫn kiên cường đối mặt với cuộc sống một cách vô cùng thân thiết và cảm động. Người mẹ trong phim luôn lo lắng làm phiền con gái, một cách tự nhiên đặt nhu cầu của bản thân xuống vị trí thứ hai. Cả đời người mẹ từng chịu đựng gian khổ, từng có những nỗi buồn, nhưng tất cả những điều đó đều được sự bình thản và hài hước của bà lặng lẽ che giấu đi."}, {"c": "prof", "zh": "剧中的母亲是一个什么样的人？", "py": "Jùzhōng de mǔqīn shì yíge shénmeyàng de rén?", "vi": "Người mẹ trong phim là người thế nào?"}, {"me": "Kiên cường, luôn sợ làm phiền con, đặt nhu cầu mình xuống thứ hai.", "opts": [["坚强，总担心给女儿添麻烦，把自己的需求放在第二位。", "Jiānqiáng, zǒng dānxīn gěi nǚér tiānmáfán, bǎ zìjǐ de xūqiú fàngzài dìèrwèi.", "Kiên cường, luôn sợ làm phiền con, đặt nhu cầu mình xuống thứ hai."], ["非常自私。", "Fēicháng zìsī.", "(chưa đúng với bài)"], ["总是抱怨女儿。", "Zǒngshì bàoyuàn nǚér.", "(chưa đúng với bài)"]]}, {"c": "meimei", "zh": "整部影片的感情饱满，但很自然，许多地方导演加以控制，将情感表现得恰到好处。观众在被人物深深打动之后，会很自然地反思自己和亲人的关系，考虑生活中最重要的是什么。这也许正是导演真正的意图，她希望传达给观众一个简单而又重要的道理：亲情、友情是最珍贵的。", "py": "Zhěng bù yǐngpiàn de gǎnqíng bǎomǎn, dàn hěn zìrán, xǔduō dìfāng dǎoyǎn jiāyǐ kòngzhì, jiāng qínggǎn biǎoxiàn de qiàdàohǎochù. Guānzhòng zài bèi rénwù shēnshēn dǎdòng zhīhòu, huì hěn zìrán de fǎnsī zìjǐ hé qīnrén de guānxì, kǎolǜ shēnghuó zhōng zuì zhòngyào de shì shénme. Zhè yěxǔ zhèng shì dǎoyǎn zhēnzhèng de yìtú, tā xīwàng chuándá gěi guānzhòng yī gè jiǎndān ér yòu zhòngyào de dàolǐ: qīnqíng, yǒuqíng shì zuì zhēnguì de.", "vi": "Tình cảm trong toàn bộ bộ phim rất đầy đặn, nhưng rất tự nhiên, nhiều chỗ đạo diễn đã kiểm soát, thể hiện tình cảm một cách vừa vặn. Sau khi bị nhân vật lay động sâu sắc, khán giả sẽ rất tự nhiên suy ngẫm về mối quan hệ giữa bản thân và người thân, cân nhắc xem điều quan trọng nhất trong cuộc sống là gì. Đây có lẽ chính là ý đồ thực sự của đạo diễn, cô ấy hy vọng truyền đạt đến khán giả một đạo lý đơn giản mà quan trọng: Tình thân, tình bạn là quý giá nhất."}, {"c": "prof", "zh": "导演想传达什么道理？", "py": "Dǎoyǎn xiǎng chuándá shénme dàolǐ?", "vi": "Đạo diễn muốn truyền tải điều gì?"}, {"me": "Tình thân, tình bạn là quý giá nhất.", "opts": [["亲情、友情是最珍贵的。", "Qīnqíng, yǒuqíng shì zuì zhēnguì de.", "Tình thân, tình bạn là quý giá nhất."], ["工作比家人更重要。", "Gōngzuò bǐ jiārén gèng zhòngyào.", "(chưa đúng với bài)"], ["钱是最重要的。", "Qián shì zuì zhòngyào de.", "(chưa đúng với bài)"]]}, {"c": "edward", "zh": "本片虽然是导演的处女作，从导演的表达方式来看，她没有许多年轻导演所常有的自我中心意识，她只是以朴素的手法展开故事，展示人物命运。观众能够对剧中人物内心的痛苦感同身受，这样的感受来自于这部电影的创作者的诚意，而这种诚意正是艺术作品的核心。", "py": "Běn piàn suīrán shì dǎoyǎn de chùnǚzuò, cóng dǎoyǎn de biǎodá fāngshì lái kàn, tā méiyǒu xǔduō niánqīng dǎoyǎn suǒ cháng yǒu de zìwǒ zhōngxīn yìshí, tā zhǐshì yǐ pǔsù de shǒufǎ zhǎnkāi gùshì, zhǎnshì rénwù mìngyùn. Guānzhòng nénggòu duì jù zhōng rénwù nèixīn de tòngkǔ gǎntóngshēnshòu, zhèyàng de gǎnshòu láizì yú zhè bù diànyǐng de chuàngzuòzhě de chéngyì, ér zhè zhǒng chéngyì zhèng shì yìshù zuòpǐn de héxīn.", "vi": "Bộ phim này tuy là tác phẩm đầu tay của đạo diễn, nhưng từ cách thể hiện của đạo diễn mà nói, cô ấy không có ý thức lấy bản thân làm trung tâm thường thấy ở nhiều đạo diễn trẻ, cô ấy chỉ dùng thủ pháp mộc mạc để triển khai câu chuyện,展示 số phận nhân vật. Khán giả có thể đồng cảm sâu sắc với nỗi đau trong lòng nhân vật trong phim, cảm giác như vậy đến từ sự chân thành của những người sáng tạo ra bộ phim này, và sự chân thành này chính là cốt lõi của tác phẩm nghệ thuật."}, {"c": "prof", "zh": "今天的讨论很精彩。下课以后，请大家去大学的各个学院继续练习。", "py": "Jīntiān de tǎolùn hěn jīngcǎi. Xiàkè yǐhòu, qǐng dàjiā qù dàxué de gège xuéyuàn jìxù liànxí.", "vi": "Buổi thảo luận hôm nay rất hay. Sau giờ học, mời các em sang các khoa luyện tiếp."}], "grammar": [{"t": "既...又... (jì... yòu...)", "d": "既 + A + 又 + B “Vừa... lại vừa...”, biểu thị hai tính chất cùng tồn tại.", "ex": [["表现这样一段由母女二人构成的情感故事既容易，又困难。", "Biǎoxiàn zhèyàng yíduàn yóu mǔnǚ èrrén gòuchéng de qínggǎngùshì jì róngyì, yòu kùnnán.", "Thể hiện một câu chuyện tình cảm được tạo nên bởi hai mẹ con như thế này vừa dễ lại vừa khó."]]}, {"t": "如果...会... (rúguǒ... huì...)", "d": "如果 + [điều kiện] + 会 + [kết quả] “Nếu... thì sẽ...”, biểu thị điều kiện giả định.", "ex": [["如果表演分寸把握不好，效果会适得其反。", "Rúguǒ biǎoyǎn fēncùn bǎwò bùhǎo, xiàoguǒ huì shìdéqífǎn.", "Nếu không nắm bắt tốt mức độ diễn xuất, hiệu quả sẽ đi ngược lại mong muốn."]]}, {"t": "从...身上 (cóng... shēnshang)", "d": "从 + [người/vật] + 身上 “Từ (nơi) ai đó”, “ở nơi ai đó”.", "ex": [["从她身上我们既看到自己对父母的爱...", "Cóng tā shēnshàng wǒmen jì kàndào zìjǐ duì fùmǔ de ài...", "Từ cô ấy, chúng ta vừa nhìn thấy tình yêu của mình dành cho cha mẹ..."]]}, {"t": "被...所... (bèi... suǒ...)", "d": "被 + [tác nhân] + 所 + [động từ] “Bị/được... bởi...”, cấu trúc bị động mang tính văn viết, nhấn mạnh hành động.", "ex": [["而这一切都被她的平和、幽默所悄悄掩盖。", "Ér zhè yíqiè dōu bèi tā de pínghé, yōumò suǒ qiāoqiāo yǎngài.", "Và tất cả những điều đó đều được sự bình thản và hài hước của bà lặng lẽ che giấu đi."]]}, {"t": "在...之后 (zài... zhīhòu)", "d": "在 + [sự việc] + 之后 “Sau khi...”, “sau...”.", "ex": [["观众在被人物深深打动之后，会很自然地反思自己和亲人的关系...", "Guānzhòng zài bèi rénwù shēnshēn dǎdòng zhīhòu, huì hěn zìrán dì fǎnsī zìjǐ hé qīnrén de guānxi...", "Sau khi bị nhân vật lay động sâu sắc, khán giả sẽ rất tự nhiên suy ngẫm về mối quan hệ giữa bản thân và người thân..."]]}, {"t": "虽然...但/但是... (suīrán... dàn/dànshì...)", "d": "虽然 + A + 但/但是 + B “Tuy... nhưng...”, biểu thị sự nhượng bộ.", "ex": [["本片虽然是导演的处女作，从导演的表达方式来看，她没有许多年轻导演所常有的自我中心意识...", "Běnpiàn suīrán shì dǎoyǎn de chǔnǚzuò, cóng dǎoyǎn de biǎodáfāngshì láikàn, tā méiyǒu xǔduō niánqīng dǎoyǎn suǒ chángyǒu de zìwǒzhōngxīn yìshí...", "Bộ phim này tuy là tác phẩm đầu tay của đạo diễn, nhưng từ cách thể hiện của đạo diễn mà nói, cô ấy không có ý thức lấy bản thân làm trung tâm thường thấy ở nhiều đạo diễn trẻ..."]]}], "order": [], "u": {"gq": [{"s": "既……又……", "d": "Vừa… vừa….", "ok": "表现这样的情感故事既容易，又困难。", "vi": "Thể hiện câu chuyện tình cảm như vậy vừa dễ vừa khó.", "bad": ["表现这样的情感故事既容易，也又困难。", "表现这样的情感故事又容易，既困难。"]}, {"s": "如果……会……", "d": "Nếu… sẽ….", "ok": "如果表演分寸把握不好，效果会适得其反。", "vi": "Nếu không nắm chừng mực diễn xuất, hiệu quả sẽ phản tác dụng.", "bad": ["如果表演分寸把握不好，但效果会适得其反。", "表演分寸如果会把握不好，效果适得其反。"]}, {"s": "被……所……", "d": "Bị/được… (bị động văn viết).", "ok": "这一切都被她的平和、幽默所悄悄掩盖。", "vi": "Tất cả đều được sự bình thản, hài hước của bà lặng lẽ che đi.", "bad": ["这一切都被她的平和、幽默悄悄所掩盖了所。", "这一切都所她的平和、幽默被悄悄掩盖。"]}, {"s": "从……来看", "d": "Xét từ….", "ok": "从导演的表达方式来看，她没有自我中心意识。", "vi": "Xét từ cách thể hiện, đạo diễn không có ý thức tự cho mình là trung tâm.", "bad": ["从导演的表达方式来，看她没有自我中心意识。", "从来看导演的表达方式，她没有自我中心意识。"]}, {"s": "虽然……但……", "d": "Tuy… nhưng….", "ok": "本片虽然是导演的处女作，但表现得很成熟。", "vi": "Phim tuy là tác phẩm đầu tay nhưng thể hiện rất chín chắn.", "bad": ["本片虽然是导演的处女作，所以表现得很成熟。", "虽然本片是导演的处女作，表现但得很成熟。"]}], "disc": [{"q": "介绍一部让你感动的电影，说说它为什么打动你。", "py": "Jièshào yíbù ràng nǐ gǎndòng de diànyǐng, shuō shuō tā wèishénme dǎdòng nǐ.", "vi": "Giới thiệu một bộ phim khiến bạn cảm động, vì sao nó lay động bạn.", "keys": ["既……又", "从……来看|从……看", "虽然……但|虽然……但是"], "sample": "我很喜欢电影《寻梦环游记》。这部电影既有趣，又让人感动。从故事来看，它讲的是家人之间的爱。虽然是动画片，但是我看完以后哭了。", "spy": "Wǒ hěn xǐhuan diànyǐng «Xúnmèng huán yóujì». Zhèbù diànyǐng jì yǒuqù, yòu ràng rén gǎndòng. Cóng gùshi láikàn, tā jiǎng de shì jiārén zhījiān de ài. Suīrán shì dònghuàpiàn, dànshì wǒ kàn wán yǐhòu kū le."}], "comp": [{"vi": "Bộ phim này vừa hài hước vừa cảm động. (既……又……)", "keys": ["既", "又"], "model": "这部电影既幽默又感人。", "mpy": "Zhèbù diànyǐng jì yōumò yòu gǎnrén."}, {"vi": "Xét từ kết quả thi, cậu ấy tiến bộ rất nhiều. (从……来看)", "keys": ["从", "来看"], "model": "从考试成绩来看，他进步很大。", "mpy": "Cóng kǎoshìchéngjì láikàn, tā jìnbù hěndà."}, {"vi": "Nếu không nghỉ ngơi đầy đủ, bạn sẽ bị ốm. (如果……会……)", "keys": ["如果", "会"], "model": "如果不好好休息，你会生病的。", "mpy": "Rúguǒ bù hǎohǎo xiūxi, nǐ huì shēngbìng de."}], "ex": [{"q": "这部电影讲的是什么故事？", "qvi": "Phim kể câu chuyện gì?", "a": "一位女作家在母亲生重病后与母亲相处的最后一段日子。", "avi": "Những ngày cuối cùng một nữ nhà văn ở bên mẹ sau khi mẹ bệnh nặng.", "bad": ["一位母亲去国外旅行。", "两个朋友一起创业。"], "p": 0}, {"q": "为什么说表现母女的故事“既容易又困难”？", "qvi": "Vì sao nói kể chuyện mẹ con “vừa dễ vừa khó”?", "a": "容易引起共鸣，但分寸把握不好会适得其反。", "avi": "Dễ gây đồng cảm, nhưng không giữ chừng mực sẽ phản tác dụng.", "bad": ["因为演员太少。", "因为电影太长。"], "p": 1}, {"q": "剧中的作家像一面镜子，让我们看到了什么？", "qvi": "Nhà văn trong phim như tấm gương, cho ta thấy gì?", "a": "自己对父母的爱，也照见自己的自私。", "avi": "Tình yêu với cha mẹ và cả sự ích kỷ của mình.", "bad": ["自己的长相。", "别人的缺点。"], "p": 2}, {"q": "剧中的母亲是一个什么样的人？", "qvi": "Người mẹ trong phim là người thế nào?", "a": "坚强，总担心给女儿添麻烦，把自己的需求放在第二位。", "avi": "Kiên cường, luôn sợ làm phiền con, đặt nhu cầu mình xuống thứ hai.", "bad": ["非常自私。", "总是抱怨女儿。"], "p": 3}, {"q": "导演想传达什么道理？", "qvi": "Đạo diễn muốn truyền tải điều gì?", "a": "亲情、友情是最珍贵的。", "avi": "Tình thân, tình bạn là quý giá nhất.", "bad": ["工作比家人更重要。", "钱是最重要的。"], "p": 4}]}}];
  Object.assign(C.book.lessons, {"hk4-l1": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 1", "kw": [{"h": "课文 几何学家陈省身", "lines": [["", "1911年，陈省身出生于浙江的一个书香世家。中学时代，陈省身的数学天才已经崭露头角。他说：“我学习数学感到特别容易。我不是一个规规矩矩、老老实实念书的学生。我的数学分数总很好，其他功课平常非常。我喜欢去图书馆看书，什么书都是拿来就着。除了数学方面的书，我也喜欢看历史、文学等方面的书，时常一待就几个钟头。”他习惯自己主动地去看书学习，而不只是看老师指定的参考书。由于成绩特别好，他15岁时就被南开大学理学院录取。1930年，陈省身从南开大学毕业，被清华大学录取攻读硕士学位，清华大学校方每年都资助学习成绩好的学生出国留学，陈省身成为了选派对象。", "1911 nián, Chén Xǐngshēn chūshēng yú Zhèjiāng de yīgè shūxiāng shìjiā. Zhōngxué shídài, Chén Xǐngshēn de shùxué tiāncái yǐjīng zhǎnlù tóujiǎo. Tā shuō: “Wǒ xuéxí shùxué gǎndào tèbié róngyì. Wǒ bùshì yīgè guīguījǔjǔ, lǎolǎoshishí niànshū de xuéshēng. Wǒ de shùxué fēnshù zǒng hěn hǎo, qítā gōngkè píngcháng fēicháng. Wǒ xǐhuān qù túshūguǎn kàn shū, shénme shū dōu shì nálái jiù zhe. Chúle shùxué fāngmiàn de shū, wǒ yě xǐhuān kàn lìshǐ, wénxué děng fāngmiàn de shū, shícháng yī dài jiù jǐ gè zhōngtóu.” Tā xíguàn zìjǐ zhǔdòng de qù kàn shū xuéxí, ér bù zhǐshì kàn lǎoshī zhǐdìng de cānkǎo shū. Yóuyú chéngjī tèbié hǎo, tā 15 suì shí jiù bèi Nánkāi Dàxué Lǐxuéyuàn lùqǔ. 1930 nián, Chén Xǐngshēn cóng Nánkāi Dàxué bìyè, bèi Qīnghuá Dàxué lùqǔ gōngdú shuòshì xuéwèi, Qīnghuá Dàxué xiàofāng měi nián dōu zīzhù xuéxí chéngjī hǎo de xuéshēng chūguó liúxué, Chén Xǐngshēn chéngwéi le xuǎnpài duìxiàng.", "Năm 1911, Trần Tỉnh Thân sinh ra tại Chiết Giang trong một gia đình gia thế hiếu học. Thời trung học, thiên tài toán học của ông đã bắt đầu bộc lộ. Ông nói: “Tôi học toán cảm thấy rất dễ dàng. Tôi không phải là một học sinh học hành câu nệ, khuôn phép. Điểm toán của tôi luôn rất tốt, các môn khác thì bình thường. Tôi thích đến thư viện đọc sách, sách gì tôi cũng cầm lên đọc. Ngoài sách toán, tôi cũng thích đọc sách lịch sử, văn học..., thường ngồi đó cả mấy giờ.” Ông có thói quen chủ động tự học, chứ không chỉ đọc sách tham khảo do giáo viên chỉ định. Vì thành tích đặc biệt tốt, ông được nhận vào Học viện Khoa học Tự nhiên của Đại học Nam Khai năm 15 tuổi. Năm 1930, ông tốt nghiệp Đại học Nam Khai, được nhận vào Đại học Thanh Hoa học thạc sĩ. Hàng năm, trường Thanh Hoa đều tài trợ cho sinh viên có thành tích tốt đi du học, và Trần Tỉnh Thân đã trở thành ứng viên được chọn."], ["", "1934年9月，陈省身到达汉堡。在那里，陈省身师从德国几何学家布拉施克。布拉施克第一次见到自己的中国弟子，就给了他一大叠自己最新的论文。但这位德国老师怎么也没想到，一个来自中国的青年学生，一下子就发现了其中一篇论文中的漏洞。布拉施克感到又惊又喜，对陈省身大为欣赏。在德国不到一年半，陈省身就拿到了博士学位。1936年，陈省身前往法国巴黎大学，追随几何学家嘉当进行研究。在10个月的研究过程中，陈省身学到的东西使他终身受用，他与嘉当也结下了终生的友谊。", "1934 nián 9 yuè, Chén Xǐngshēn dàodá Hànbǎo. Zài nàli, Chén Xǐngshēn shīcóng Déguó jǐhéxuéjiā Bùlāshīkè. Bùlāshīkè dì yī cì jiàndào zìjǐ de Zhōngguó dìzǐ, jiù gěile tā yī dàdié zìjǐ zuìxīn de lùnwén. Dàn zhè wèi Déguó lǎoshī zěnme yě méi xiǎngdào, yīgè láizì Zhōngguó de qīngnián xuéshēng, yīxiàzi jiù fāxiànle qízhōng yī piān lùnwén zhōng de lòudòng. Bùlāshīkè gǎndào yòu jīng yòu xǐ, duì Chén Xǐngshēn dàwéi xīnshǎng. Zài Déguó bù dào yī nián bàn, Chén Xǐngshēn jiù nádàole bóshì xuéwèi. 1936 nián, Chén Xǐngshēn qiánwǎng Fǎguó Bālí Dàxué, zhuīsuí jǐhéxuéjiā Jiādāng jìnxíng yánjiū. Zài 10 gè yuè de yánjiū guòchéng zhōng, Chén Xǐngshēn xué dào de dōngxi shǐ tā zhōngshēn shòuyòng, tā yǔ Jiādāng yě jiéxiàle zhōngshēng de yǒuyì.", "Tháng 9 năm 1934, Trần Tỉnh Thân đến Hamburg. Tại đó, ông theo học nhà hình học người Đức Blaschke. Lần đầu gặp người học trò Trung Quốc của mình, Blaschke đã đưa cho ông một tập dày các bài báo mới nhất của mình. Nhưng vị giáo sư Đức này không ngờ rằng, một sinh viên trẻ đến từ Trung Quốc lại ngay lập tức phát hiện ra một lỗ hổng trong một bài báo. Blaschke vừa ngạc nhiên vừa mừng rỡ, rất quý trọng Trần Tỉnh Thân. Chưa đầy một năm rưỡi ở Đức, ông đã lấy được bằng tiến sĩ. Năm 1936, ông sang Đại học Paris, theo học nhà hình học Cartan nghiên cứu. Trong 10 tháng nghiên cứu, những gì ông học được đã giúp ích cho ông suốt đời, và ông cũng kết thân với Cartan."], ["", "1943年，陈省身受美国普林斯顿大学数学研究所的邀请，到那里作学术访问。在那里，他完成了一生中最出色的工作，发表了数篇在数学界有重大影响的论文，其中包括现在被称为“陈类”的理论。1960年，陈省身前住美国加州大学伯克利分校从事教学研究，一直到退休。当陈省身68岁功成身退的时候，加州大学为他举行了为期5天的国际几何学会议。300多位数学家在伯克利校园聚会，共同研讨数学问题，也表示对陈先生的敬意。", "1943 nián, Chén Xǐngshēn shòu Měiguó Pǔlǐnsītùn Dàxué Shùxué Yánjiūsuǒ de yāoqǐng, dào nàli zuò xuéshù fǎngwèn. Zài nàli, tā wánchéngle yīshēng zhōng zuì chūsè de gōngzuò, fābiǎole shù piān zài shùxuéjiè yǒu zhòngdà yǐngxiǎng de lùnwén, qízhōng bāokuò xiànzài bèi chēng wéi “Chén lèi” de lǐlùn. 1960 nián, Chén Xǐngshēn qiánwǎng Měiguó Jiāzhōu Dàxué Bókèlì fēnxiào cóngshì jiàoxué yánjiū, yīzhí dào tuìxiū. Dāng Chén Xǐngshēn 68 suì gōngchéng shēn tuì de shíhòu, Jiāzhōu Dàxué wèi tā jǔxíngle wéiqī 5 tiān de guójì jǐhéxué huìyì. 300 duō wèi shùxuéjiā zài Bókèlì xiàoyuán jùhuì, gòngtóng yántǎo shùxué wèntí, yě biǎoshì duì Chén xiānshēng de jìngyì.", "Năm 1943, Trần Tỉnh Thân được Viện Nghiên cứu Toán học Đại học Princeton mời đến thăm và nghiên cứu. Tại đó, ông hoàn thành công trình xuất sắc nhất đời mình, công bố nhiều bài báo có ảnh hưởng lớn trong giới toán học, trong đó có lý thuyết ngày nay được gọi là “lớp Trần” (Chen class). Năm 1960, ông đến Đại học California tại Berkeley giảng dạy và nghiên cứu cho đến khi nghỉ hưu. Năm 68 tuổi, khi ông rời vị trí, Đại học California đã tổ chức một hội nghị hình học quốc tế kéo dài 5 ngày. Hơn 300 nhà toán học tụ họp tại khuôn viên Berkeley, cùng thảo luận các vấn đề toán học và bày tỏ lòng kính trọng với ông."], ["", "陈省身在国际上的学术声誉如日中天，但他十分怀念祖国。1972年，陈省身带着夫人与孩子回到离别24年的祖国。此后的30多年，他数十次回到中国，并利用自己在国际数学界的广泛影响，不断加强中国和国际数学界的交流。当今世界数学界，由以色列沃尔夫基金会颁发的沃尔夫奖举世瞩目。1983年，陈省身先生荣获沃尔夫奖，成为唯一获得世界数学界最高荣誉“沃尔夫奖”的华人。", "Chén Xǐngshēn zài guójì shàng de xuéshù shēngyù rú rì zhōng tiān, dàn tā shífēn huáiniàn zǔguó. 1972 nián, Chén Xǐngshēn dàizhe fūren yǔ háizi huí dào líbié 24 nián de zǔguó. Cǐhòu de 30 duō nián, tā shùshí cì huí dào Zhōngguó, bìng lìyòng zìjǐ zài guójì shùxuéjiè de guǎngfàn yǐngxiǎng, bùduàn jiāqiáng Zhōngguó hé guójì shùxuéjiè de jiāoliú. Dāngjīn shìjiè shùxuéjiè, yóu Yǐsèliè Wò'ěrfú Jījīnhuì bānfā de Wò'ěrfú jiǎng jǔshì zhǔmù. 1983 nián, Chén Xǐngshēn xiānshēng róng huò Wò'ěrfú jiǎng, chéngwéi wéiyī huòdé shìjiè shùxuéjiè zuìgāo róngyù “Wò'ěrfú jiǎng” de Huárén.", "Danh tiếng học thuật của Trần Tỉnh Thân trên trường quốc tế đang lên như mặt trời giữa trưa, nhưng ông rất nhớ quê hương. Năm 1972, ông cùng vợ và con trở về tổ quốc sau 24 năm xa cách. Trong hơn 30 năm sau đó, ông đã về Trung Quốc hàng chục lần, và tận dụng ảnh hưởng rộng lớn của mình trong giới toán học quốc tế để không ngừng tăng cường giao lưu giữa Trung Quốc và thế giới. Trong giới toán học thế giới hiện nay, giải Wolf do Quỹ Wolf của Israel trao tặng rất được chú ý. Năm 1983, ông được trao giải Wolf, trở thành người Hoa duy nhất đạt được vinh dự cao nhất của giới toán học thế giới."], ["", "2004年10月28日，陈省身度过了他的93岁寿辰。第二天，他来到南开数学研究所，作了一场学术报告，没想到仅一个月之后，这位国际数学大师就悄然离开了这个世界。人的生命是有限的，但陈省身对数学领域的深远影响却是永存的。", "2004 nián 10 yuè 28 rì, Chén Xǐngshēn dùguòle tā de 93 suì shòuchén. Dì èr tiān, tā lái dào Nánkāi Shùxué Yánjiūsuǒ, zuòle yī chǎng xuéshù bàogào, méi xiǎngdào jǐn yīgè yuè zhīhòu, zhè wèi guójì shùxué dàshī jiù qiǎorán líkāile zhège shìjiè. Rén de shēngmìng shì yǒuxiàn de, dàn Chén Xǐngshēn duì shùxué lǐngyù de shēnyuǎn yǐngxiǎng què shì yǒngcún de.", "Ngày 28 tháng 10 năm 2004, ông tròn 93 tuổi. Hôm sau, ông đến Viện Nghiên cứu Toán học Nam Khai và trình bày một báo cáo học thuật. Không ngờ chỉ một tháng sau, vị đại sư toán học quốc tế này đã lặng lẽ rời xa thế giới. Sự sống của con người là hữu hạn, nhưng ảnh hưởng sâu xa của Trần Tỉnh Thân đối với lĩnh vực toán học thì còn mãi."]]}], "fn": [["“被” (bị/được)", "", "Chủ ngữ + 被 + tác nhân + động từ", "他被南开大学录取。"], ["“把” (đưa/lấy)", "", "Chủ ngữ + 把 + tân ngữ + động từ", "他把书放在桌子上。"], ["“除了...还/也...” (ngoài... còn...)", "", "除了 A，还/也 B = Ngoài A ra, còn B", "除了数学，我也喜欢历史。"], ["“对... (感到/表示)...” (đối với...)", "", "对 + danh từ/đại từ + biểu thị cảm xúc/hành động", "我对这件事很感兴趣。"], ["“不仅...也/还...” (không những... mà còn...)", "", "", "他不仅聪明，也很努力。"], ["“...之一” (một trong những...)", "", "", "他是中国最著名的数学家之一。"], ["“当...的时候” (khi...)", "", "当 + mệnh đề + 的时候 = Khi...", "当陈省身68岁的时候，他退休了。"], ["“由...颁发” (do... trao tặng)", "", "由 + tổ chức/cá nhân + 颁发 = do... trao tặng", "该奖项由政府颁发。"]], "adv": [["祖国", "zǔguó", "tổ quốc"], ["离别", "líbié", "xa cách, chia tay"], ["广泛", "guǎngfàn", "rộng rãi"], ["加强", "jiāqiáng", "tăng cường"], ["交流", "jiāoliú", "giao lưu"], ["基金", "jījīn", "quỹ (tài chính)"], ["颁发", "bānfā", "trao tặng"], ["举世瞩目", "jǔshì zhǔmù", "cả thế giới chú ý"], ["荣获", "róng huò", "vinh dự nhận được"], ["最高荣誉", "zuìgāo róngyù", "vinh dự cao nhất"], ["华人", "Huárén", "người Hoa (gốc Trung Quốc)"], ["寿辰", "shòuchén", "sinh nhật (người lớn tuổi)"], ["学术报告", "xuéshù bàogào", "báo cáo học thuật"], ["仅", "jǐn", "chỉ vẻn vẹn"], ["悄然", "qiǎorán", "lặng lẽ"], ["有限", "yǒuxiàn", "có hạn"], ["深远", "shēnyuǎn", "sâu xa, lâu dài"], ["永存", "yǒngcún", "mãi mãi tồn tại"]], "ex2": [["中学时代陈省身是一个什么样的学生？", "数学特别好，喜欢自己主动看书，不只看老师指定的参考书。", ["每门功课都非常好，从不去图书馆。", "只看老师指定的参考书。"]], ["陈省身第一次见德国老师时发生了什么？", "他一下子就发现了老师一篇论文中的漏洞。", ["老师让他回国学习。", "他把老师的论文都弄丢了。"]], ["陈省身退休时，加州大学怎样表达敬意？", "举行了为期5天的国际几何学会议。", ["送给他一辆汽车。", "请他再工作十年。"]], ["1983年陈省身获得了什么荣誉？", "沃尔夫奖，他是唯一获得这个奖的华人。", ["诺贝尔奖。", "美国数学界的一个小奖。"]], ["陈省身去世前一个月做了什么？", "在南开数学研究所作了一场学术报告。", ["去法国旅游。", "停止了所有研究。"]]]}, "hk4-l2": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 1", "kw": [{"h": "课文 中国人的姓", "lines": [["", "中国人在三皇五帝以前（距今约五千年）就有了姓。那时是母系社会，人们只知有母，不知有父，所以“姓”是“女”和“生”组成，这说明最早的姓，是跟母亲的姓。夏、商、周的时候，人们有姓也有氏。“姓”是从居住的村子或者所属的部族名称而来。“氏”是从君主所封的地、所赐的爵位、所任的官职而来。所以贵族有姓、有名也有氏；平民有姓，有名，没有氏。同氏的男女可以通婚，同姓的男女却不可以通婚。", "Zhōngguó rén zài Sān Huáng Wǔ Dì yǐqián (jù jīn yuē wǔqiān nián) jiù yǒule xìng. Nà shí shì mǔxì shèhuì, rénmen zhǐ zhī yǒu mǔ, bù zhī yǒu fù, suǒyǐ “xìng” shì “nǚ” hé “shēng” zǔchéng, zhè shuōmíng zuìzǎo de xìng, shì gēn mǔqīn de xìng. Xià, Shāng, Zhōu de shíhou, rénmen yǒu xìng yě yǒu shì. “Xìng” shì cóng jūzhù de cūnzi huòzhě suǒshǔ de bùzú míngchēng ér lái. “Shì” shì cóng jūnzhǔ suǒ fēng de dì, suǒ cì de juéwèi, suǒ rèn de guānzhí ér lái. Suǒyǐ guìzú yǒu xìng, yǒu míng yě yǒu shì; píngmín yǒu xìng, yǒu míng, méiyǒu shì. Tóng shì de nánnǚ kěyǐ tōnghūn, tóng xìng de nánnǚ què bù kěyǐ tōnghūn.", "Người Trung Quốc đã có họ từ thời Tam Hoàng Ngũ Đế (cách nay khoảng 5.000 năm). Lúc đó là xã hội mẫu hệ, người ta chỉ biết có mẹ, không biết có cha, vì vậy chữ “họ” (姓) được cấu tạo từ chữ “nữ” (女) và “sinh” (生), điều này cho thấy họ sớm nhất là theo họ mẹ. Vào thời Hạ, Thương, Chu, người ta có cả họ (xìng) và thị (shì). “Họ” (xìng) bắt nguồn từ tên làng nơi cư trú hoặc bộ lạc thuộc về. “Thị” (氏) bắt nguồn từ đất được vua phong, tước vị được ban, hoặc chức quan được giao. Vì thế quý tộc có họ, có tên và có thị; bình dân có họ, có tên nhưng không có thị. Nam nữ cùng thị có thể kết hôn, nhưng nam nữ cùng họ thì không được kết hôn."], ["", "唐太宗的时候——公元627年，有个叫高士廉的官员，把民间的“姓”记录下来，写成一本书叫《氏族志》。中国旧时流行的《百家姓》是北宋（公元960年）的时候写的，里面一共收集了单姓408个，复姓30个，一共438个。姓发展到后来，据说有4000到6000个，但是实际应用的，只有1000个左右。", "Táng Tàizōng de shíhou — gōngyuán 627 nián, yǒu gè jiào Gāo Shìlián de guānyuán, bǎ mínjiān de “xìng” jìlù xiàlái, xiě chéng yī běn shū jiào 《Shìzú Zhì》. Zhōngguó jiùshí liúxíng de 《Bǎijiā Xìng》 shì Běi Sòng (gōngyuán 960 nián) de shíhou xiě de, lǐmiàn yīgòng shōujíle dānxìng 408 gè, fùxìng 30 gè, yīgòng 438 gè. Xìng fāzhǎn dào hòulái, jùshuō yǒu 4000 dào 6000 gè, dànshì shíjì yìngyòng de, zhǐyǒu 1000 gè zuǒyòu.", "Dưới thời Đường Thái Tông – năm 627, có một viên quan tên là Cao Sĩ Liêm đã ghi chép lại các “họ” trong dân gian và viết thành một cuốn sách gọi là 《Thị tộc chí》. Cuốn 《Bách gia tính》 (Trăm họ) thịnh hành ở Trung Quốc xưa được viết vào thời Bắc Tống (năm 960), trong đó thu thập tổng cộng 408 họ đơn, 30 họ kép, tổng cộng 438 họ. Về sau, theo truyền thuyết có khoảng 4000 đến 6000 họ, nhưng trên thực tế được sử dụng chỉ khoảng 1000 họ."], ["", "世界各国都有“三大姓”的说法，如，美国是：Smith，Johnson，Carson；法国是：Martin，Bernard，Dupont；中国呢？有张、王、李、赵，四个大姓。这四个大姓历史悠久，分布广泛，而且古代都是皇帝赐姓。根据最新统计，单是姓张的，就有一亿人，这恐怕是世界上最大的姓了吧。1977年，史学家李栋明在《东方杂志》上发表过一篇有关“姓”的论文，文中指出：", "Shìjiè gèguó dōu yǒu “sān dà xìng” de shuōfǎ, rú, Měiguó shì: Smith, Johnson, Carson; Fǎguó shì: Martin, Bernard, Dupont; Zhōngguó ne? Yǒu Zhāng, Wáng, Lǐ, Zhào, sì gè dà xìng. Zhè sì gè dà xìng lìshǐ yōujiǔ, fēnbù guǎngfàn, érqiě gǔdài dōu shì huángdì cì xìng. Gēnjù zuìxīn tǒngjì, dān shì xìng Zhāng de, jiù yǒu yī yì rén, zhè kǒngpà shì shìjiè shàng zuì dà de xìng le ba. 1977 nián, shǐxuéjiā Lǐ Dōngmíng zài 《Dōngfāng Zázhì》 shàng fābiǎoguo yī piān yǒuguān “xìng” de lùnwén, wén zhōng zhǐchū:", "Các nước trên thế giới đều có thuyết “ba họ lớn”, ví dụ: Mỹ là Smith, Johnson, Carson; Pháp là Martin, Bernard, Dupont; còn Trung Quốc thì có bốn họ lớn là Trương, Vương, Lý, Triệu. Bốn họ lớn này có lịch sử lâu đời, phân bố rộng rãi, và thời xưa đều do hoàng đế ban họ. Theo thống kê mới nhất, riêng họ Trương đã có một trăm triệu người, e rằng đây là họ lớn nhất thế giới. Năm 1977, nhà sử học Lý Đống Minh đã đăng trên tạp chí Phương Đông một bài luận về “họ”, trong đó chỉ ra:"], ["", "华人最大的十个姓是：张、王、李、赵、陈、杨、吴、刘、黄、周，这十个姓占华人人口的40%，约四亿人。第二大的十个姓是：徐、朱、林、孙、马、高、胡、郑、郭、萧，占华人人口的10%以上。第三大的十个姓是：谢、何、许、宋、沈、罗、韩、邓、梁、叶，占华人人口的10%。接下来的15个大姓是：方、崔、程、潘、曹、冯、汪、蔡、袁、卢、唐、钱、杜、彭、陆，加起来也占华人人口的10%。换句话说，在中国十多亿人口中，有七亿人的姓是这45个大姓。", "Huárén zuì dà de shí gè xìng shì: Zhāng, Wáng, Lǐ, Zhào, Chén, Yáng, Wú, Liú, Huáng, Zhōu, zhè shí gè xìng zhàn Huárén rénkǒu de 40%, yuē sì yì rén. Dì èr dà de shí gè xìng shì: Xú, Zhū, Lín, Sūn, Mǎ, Gāo, Hú, Zhèng, Guō, Xiāo, zhàn Huárén rénkǒu de 10% yǐshàng. Dì sān dà de shí gè xìng shì: Xiè, Hé, Xǔ, Sòng, Shěn, Luó, Hán, Dèng, Liáng, Yè, zhàn Huárén rénkǒu de 10%. Jiē xiàlái de 15 gè dà xìng shì: Fāng, Cuī, Chéng, Pān, Cáo, Féng, Wāng, Cài, Yuán, Lú, Táng, Qián, Dù, Péng, Lù, jiā qǐlái yě zhàn Huárén rénkǒu de 10%. Huàn jù huà shuō, zài Zhōngguó shí duō yì rénkǒu zhōng, yǒu qī yì rén de xìng shì zhè 45 gè dà xìng.", "Mười họ lớn nhất của người Hoa là: Trương, Vương, Lý, Triệu, Trần, Dương, Ngô, Lưu, Hoàng, Châu, mười họ này chiếm 40% dân số người Hoa, khoảng 400 triệu người. Mười họ lớn thứ hai là: Từ, Chu, Lâm, Tôn, Mã, Cao, Hồ, Trịnh, Quách, Tiêu, chiếm hơn 10% dân số người Hoa. Mười họ lớn thứ ba là: Tạ, Hà, Hứa, Tống, Thẩm, La, Hàn, Đặng, Lương, Diệp, chiếm 10% dân số người Hoa. 15 họ lớn tiếp theo là: Phương, Thôi, Trình, Phan, Tào, Phùng, Uông, Thái, Viên, Lư, Đường, Tiền, Đỗ, Bành, Lục, cộng lại cũng chiếm 10% dân số người Hoa. Nói cách khác, trong hơn một tỷ dân Trung Quốc, có 700 triệu người mang 45 họ lớn này."]]}], "fn": [["“从...而来” (từ... mà đến/bắt nguồn từ)", "", "从 + danh từ + 而来 = bắt nguồn từ", "“姓”是从居住的村子而来。"], ["“所 + động từ” (làm cho động từ trở thành bị động/mệnh đề danh từ hóa)", "", "所 + V = điều được V / cái mà...", "君主所封的地"], ["“有...也有...” và “有...没有...” (có... cũng có... / có... không có...)", "", "Quý tộc có họ, có tên và cũng có thị; bình dân có họ, có tên nhưng không có thị.", "贵族有姓、有名也有氏；平民有姓，有名，没有氏。"], ["“却” (nhưng, lại – biểu thị sự ngược lại)", "", "Mệnh đề A，却 + mệnh đề B (ý trái ngược) Cùng thị thì có thể, nhưng cùng họ thì lại không thể.", "同氏的男女可以通婚，同姓的男女却不可以通婚。"], ["“把 + tân ngữ + động từ” (đưa/lấy cái gì đó làm gì)", "", "Chủ ngữ + 把 + vật + động từ", "高士廉把民间的“姓”记录下来。"], ["“据说” (nghe nói, theo lời kể)", "", "", "据说有4000到6000个姓。"], ["“单是...就...” (riêng... đã...)", "", "单是 + A + 就 + B = Riêng A thôi đã B", "单是姓张的，就有一亿人。"], ["“在...上” (trong/trên lĩnh vực/phương diện)", "", "", "在《东方杂志》上发表"]], "adv": [["接下来", "jiē xiàlái", "tiếp theo"], ["加起来", "jiā qǐlái", "cộng lại"], ["换句话说", "huàn jù huà shuō", "nói cách khác"], ["亿", "yì", "trăm triệu"]], "ex2": [["为什么“姓”字由“女”和“生”组成？", "因为那时是母系社会，最早的姓跟母亲的姓。", ["因为女人比男人多。", "因为皇帝喜欢这个字。"]], ["古代贵族和平民有什么不同？", "贵族有姓、有名也有氏，平民没有氏。", ["平民没有姓。", "贵族没有名。"]], ["《百家姓》一共收集了多少个姓？", "438个：单姓408个，复姓30个。", ["100个。", "6000个。"]], ["中国的四大姓是哪几个？", "张、王、李、赵。", ["陈、杨、吴、刘。", "徐、朱、林、孙。"]], ["45个大姓占中国人口的多少？", "十多亿人口中，有七亿人。", ["一亿人。", "四亿人。"]]]}, "hk4-l3": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 1", "kw": [{"h": "课文 中国的自然资源", "lines": [["", "中国土地资源的特点是“一多三少”，即总量多，人均耕地少，高质量的耕地少，可开发的备用资源少。虽然中国现有土地面积居世界第三位，但是人均仅及世界人均的1/3；耕地面积列世界第二位，而人均排在世界第67位。在这有限的耕地上，缺乏水源保证、水土流失、污染严重的耕地占了相当大的比例。后备资源2亿亩，其中可开垦成耕地的仅1.2亿亩。考虑到生态保护的要求，耕地后备资源开发受到严格限制，今后通过后备资源开发补充的耕地十分有限。", "Zhōngguó tǔdì zīyuán de tèdiǎn shì “yī duō sān shǎo”, jí zǒngliàng duō, rénjūn gēngdì shǎo, gāo zhìliàng de gēngdì shǎo, kě kāifā de bèiyòng zīyuán shǎo. Suīrán Zhōngguó xiànyǒu tǔdì miànjī jū shìjiè dì sān wèi, dànshì rénjūn jǐn jí shìjiè rénjūn de 1/3; gēngdì miànjī liè shìjiè dì èr wèi, ér rénjūn pái zài shìjiè dì 67 wèi. Zài zhè yǒuxiàn de gēngdì shàng, quēfá shuǐyuán bǎozhèng, shuǐtǔ liúshī, wūrǎn yánzhòng de gēngdì zhànle xiāngdāng dà de bǐlì. Hòubèi zīyuán 2 yì mǔ, qízhōng kě kāikěn chéng gēngdì de jǐn 1.2 yì mǔ. Kǎolǜ dào shēngtài bǎohù de yāoqiú, gēngdì hòubèi zīyuán kāifā shòudào yángé xiànzhì, jīnhòu tōngguò hòubèi zīyuán kāifā bǔchōng de gēngdì shífēn yǒuxiàn.", "Đặc điểm tài nguyên đất đai Trung Quốc là “một nhiều, ba ít”, tức là tổng lượng nhiều, nhưng đất canh tác bình quân đầu người ít, đất canh tác chất lượng cao ít, và tài nguyên dự trữ có thể khai thác ít. Mặc dù diện tích đất hiện có của Trung Quốc đứng thứ ba thế giới, nhưng bình quân đầu người chỉ bằng 1/3 mức trung bình thế giới; diện tích đất canh tác đứng thứ hai thế giới, nhưng bình quân đầu người xếp thứ 67. Trên diện tích đất canh tác có hạn này, đất thiếu nguồn nước đảm bảo, bị xói mòn, ô nhiễm nghiêm trọng chiếm một tỷ lệ khá lớn. Tài nguyên dự trữ là 200 triệu mẫu Anh, trong đó chỉ có 120 triệu mẫu có thể khai hoang thành đất canh tác. Cân nhắc đến yêu cầu bảo vệ sinh thái, việc khai thác tài nguyên đất dự trữ bị hạn chế nghiêm ngặt, trong tương lai, diện tích đất canh tác được bổ sung qua khai thác tài nguyên dự trữ sẽ rất hạn chế."], ["", "中国的矿产资源总量丰富，但人均占有量不足，仅为世界人均水平的58%。同时存在三个突出问题：一是支柱性的矿产（如石油、天然气等）后备储量不足，而储量较多的则是部分用量不大的矿产；二是小矿床多，大型特大型矿床少；支柱性矿产贫矿和难选冶矿多，富矿少，开采利用难度很大；三是资源分布与生产力布局不匹配。未来20-30年内，中国矿产品的需求量将大大增加，而矿产储量的增长速度远远低于矿产消耗的增长速度。据预测，2010年中国45种主要矿产品中，关系国计民生的矿产将难以保证需求。", "Zhōngguó de kuàngchǎn zīyuán zǒngliàng fēngfù, dàn rénjūn zhànyǒu liàng bùzú, jǐn wéi shìjiè rénjūn shuǐpíng de 58%. Tóngshí cúnzài sān gè tūchū wèntí: yī shì zhīzhù xìng de kuàngchǎn (rú shíyóu, tiānránqì děng) hòubèi chǔliàng bùzú, ér chǔliàng jiào duō de zé shì bùfen yòngliàng bù dà de kuàngchǎn; èr shì xiǎo kuàngchuáng duō, dàxíng tè dàxíng kuàngchuáng shǎo; zhīzhù xìng kuàngchǎn pínkuàng hé nán xuǎnyě kuàng duō, fùkuàng shǎo, kāicǎi lìyòng nándù hěn dà; sān shì zīyuán fēnbù yǔ shēngchǎnlì bùjú bù pǐpèi. Wèilái 20-30 nián nèi, Zhōngguó kuàngchǎnpǐn de xūqiú liàng jiāng dàdà zēngjiā, ér kuàngchǎn chǔliàng de zēngzhǎng sùdù yuǎnyuǎn dīyú kuàngchǎn xiāohào de zēngzhǎng sùdù. Jù yùcè, 2010 nián Zhōngguó 45 zhǒng zhǔyào kuàngchǎnpǐn zhōng, guānxì guójì mínshēng de kuàngchǎn jiāng nányǐ bǎozhèng xūqiú.", "Tài nguyên khoáng sản Trung Quốc tổng lượng phong phú, nhưng sở hữu bình quân đầu người không đủ, chỉ bằng 58% mức trung bình thế giới. Đồng thời tồn tại ba vấn đề nổi cộm: Thứ nhất, trữ lượng dự trữ của các khoáng sản trụ cột (như dầu mỏ, khí tự nhiên...) không đủ, trong khi những loại có trữ lượng nhiều lại là các khoáng sản không được sử dụng nhiều; Thứ hai, mỏ nhỏ nhiều, mỏ lớn và đặc lớn ít; khoáng sản trụ cột có nhiều quặng nghèo và quặng khó tuyển luyện, quặng giàu ít, khó khai thác và sử dụng; Thứ ba, phân bố tài nguyên không phù hợp với bố cục năng lực sản xuất. Trong 20-30 năm tới, nhu cầu về sản phẩm khoáng sản của Trung Quốc sẽ tăng mạnh, nhưng tốc độ tăng trưởng trữ lượng khoáng sản thấp hơn nhiều so với tốc độ tăng tiêu thụ. Theo dự báo, vào năm 2010, trong số 45 loại sản phẩm khoáng sản chính của Trung Quốc, các khoáng sản liên quan đến quốc kế dân sinh sẽ khó đáp ứng nhu cầu."], ["", "中国是海洋大国，漫长的海岸线长达18,000多公里，加上岛屿岸线则达32,000多公里。大陆沿岸的海域面积广阔，海区面积470多万平方公里，海洋渔场面积42亿亩，海水可养殖面积73万亩。自然条件优越，海洋资源十分丰富，鱼类5000多种，虾、蟹等有千余种，中国海域有记载的生物可达万余种。", "Zhōngguó shì hǎiyáng dàguó, mànmàn de hǎi'ànxiàn cháng dá 18,000 duō gōnglǐ, jiāshàng dǎoyǔ ànxiàn zé dá 32,000 duō gōnglǐ. Dàlù yán'àn de hǎiyù miànjī guǎngkuò, hǎiqū miànjī 470 duō wàn píngfāng gōnglǐ, hǎiyáng yúchǎng miànjī 42 yì mǔ, hǎishuǐ kě yǎngzhí miànjī 73 wàn mǔ. Zìrán tiáojiàn yōuyuè, hǎiyáng zīyuán shífēn fēngfù, yúlèi 5000 duō zhǒng, xiā, xiè děng yǒu qiān yú zhǒng, Zhōngguó hǎiyù yǒu jìzǎi de shēngwù kě dá wàn yú zhǒng.", "Trung Quốc là một nước biển lớn, đường bờ biển dài hơn 18.000 km, cộng với đường bờ biển của các đảo thì lên tới hơn 32.000 km. Vùng biển ven đất liền rất rộng lớn, diện tích vùng biển hơn 4,7 triệu km², diện tích ngư trường biển là 420 triệu mẫu, diện tích nuôi trồng thủy sản là 730.000 mẫu. Điều kiện tự nhiên thuận lợi, tài nguyên biển rất phong phú, có hơn 5.000 loài cá, hơn 1.000 loài tôm, cua... Các sinh vật được ghi nhận trong vùng biển Trung Quốc có thể lên tới hơn 10.000 loài."], ["", "中国海洋资源中不仅生物资源繁多，还有大量的矿产资源、动力资源和海水资源。近海石油储量估计可达50-150亿吨，其他海洋资源的总蕴藏量约有9亿千瓦，沿岸含有多种价值极高的原料。海水中还含有盐、钾、钠等多种化学资源。", "Zhōngguó hǎiyáng zīyuán zhōng bùjǐn shēngwù zīyuán fánduō, hái yǒu dàliàng de kuàngchǎn zīyuán, dònglì zīyuán hé hǎishuǐ zīyuán. Jìnhǎi shíyóu chǔliàng gūjì kě dá 50-150 yì dūn, qítā hǎiyáng zīyuán de zǒng yùncáng liàng yuē yǒu 9 yì qiānwǎ, yán'àn hányǒu duō zhǒng jiàzhí jí gāo de yuánliào. Hǎishuǐ zhōng hái hányǒu yán, jiǎ, nà děng duō zhǒng huàxué zīyuán.", "Trong tài nguyên biển của Trung Quốc, không chỉ có tài nguyên sinh vật đa dạng, mà còn có nhiều tài nguyên khoáng sản, tài nguyên năng lượng và tài nguyên nước biển. Trữ lượng dầu mỏ ven biển ước tính có thể đạt 5-15 tỷ tấn, tổng trữ lượng tiềm năng của các tài nguyên biển khác khoảng 900 triệu kilowatt, ven biển chứa nhiều loại nguyên liệu có giá trị rất cao. Nước biển còn chứa nhiều tài nguyên hóa học như muối, kali, natri,..."]]}], "fn": [["“即” (tức là)", "", "A，即 B = A, tức là B (dùng để giải thích) Dùng 即 để liệt kê, giải thích cụ thể cho nhận định trước đó.", "“一多三少”，即总量多，人均耕地少..."], ["“虽然...但是...” (mặc dù... nhưng...)", "", "虽然 + A，但是 + B Biểu thị quan hệ nhượng bộ – đối lập.", "虽然中国土地面积居世界第三位，但是人均仅及世界人均的1/3。"], ["“仅及 / 仅为” (chỉ bằng / chỉ là)", "", "Dùng để so sánh mức độ, tỷ lệ.", "人均仅及世界人均的1/3；仅为世界人均水平的58%。"], ["“占...比例” (chiếm tỷ lệ...)", "", "A + 占 + B + 的 + 比例 Để chỉ phần trăm, tỷ lệ chiếm.", "污染严重的耕地占了相当大的比例。"], ["bị động với “受到” (bị/được)", "", "Chủ thể + 受到 + tác động", "耕地后备资源开发受到严格限制。"], ["“一是...二是...三是...” (thứ nhất là... thứ hai là... thứ ba là...)", "", "Cách dùng: Liệt kê các ý một cách có thứ tự.", "一是支柱性的矿产后备储量不足；二是小矿床多；三是资源分布与生产力布局不匹配。"], ["“如...等” (như... v.v.)", "", "Dùng để đưa ra ví dụ điển hình trong một danh sách.", "支柱性的矿产（如石油、天然气等）"], ["“远远低于” (thấp hơn xa, thấp hơn nhiều)", "", "A + 远远低于 + B So sánh mức độ chênh lệch lớn.", "矿产储量的增长速度远远低于矿产消耗的增长速度。"]], "adv": [["大型", "dàxíng", "loại lớn"], ["特大型", "tè dàxíng", "loại đặc lớn"], ["贫矿", "pínkuàng", "quặng nghèo"], ["富矿", "fùkuàng", "quặng giàu"], ["选冶", "xuǎnyě", "tuyển và luyện (quặng)"], ["开采", "kāicǎi", "khai thác (mỏ)"], ["分布", "fēnbù", "phân bố"], ["生产力", "shēngchǎnlì", "năng lực sản xuất"], ["布局", "bùjú", "bố cục, sắp xếp"], ["匹配", "pǐpèi", "phù hợp, khớp"], ["需求量", "xūqiú liàng", "nhu cầu"], ["大大", "dàdà", "rất nhiều, đáng kể"], ["增长速度", "zēngzhǎng sùdù", "tốc độ tăng trưởng"], ["远远", "yuǎnyuǎn", "xa, vượt xa"], ["低于", "dīyú", "thấp hơn"], ["消耗", "xiāohào", "tiêu thụ"], ["据预测", "jù yùcè", "theo dự báo"], ["主要", "zhǔyào", "chủ yếu"], ["关系", "guānxì", "liên quan đến"], ["国计民生", "guójì mínshēng", "quốc kế dân sinh"], ["难以", "nányǐ", "khó có thể"], ["海洋", "hǎiyáng", "đại dương, biển"], ["大国", "dàguó", "nước lớn"], ["漫长", "màncháng", "dài dằng dặc"], ["海岸线", "hǎi'ànxiàn", "đường bờ biển"], ["岛屿", "dǎoyǔ", "đảo"], ["岸线", "ànxiàn", "đường bờ"], ["大陆", "dàlù", "đất liền, lục địa"], ["沿岸", "yán'àn", "ven bờ"], ["海域", "hǎiyù", "vùng biển"], ["广阔", "guǎngkuò", "rộng lớn"], ["海区", "hǎiqū", "khu vực biển"], ["渔场", "yúchǎng", "ngư trường"], ["养殖", "yǎngzhí", "nuôi trồng"], ["自然条件", "zìrán tiáojiàn", "điều kiện tự nhiên"], ["优越", "yōuyuè", "ưu việt, thuận lợi"], ["丰富", "fēngfù", "phong phú"], ["鱼类", "yúlèi", "các loài cá"], ["虾", "xiā", "tôm"], ["蟹", "xiè", "cua"], ["千余种", "qiān yú zhǒng", "hơn 1.000 loài"], ["记载", "jìzǎi", "ghi nhận, ghi chép"], ["生物", "shēngwù", "sinh vật"], ["万余种", "wàn yú zhǒng", "hơn 10.000 loài"], ["不仅...还...", "bùjǐn... hái...", "không chỉ... mà còn..."], ["繁多", "fánduō", "đa dạng, nhiều"], ["大量", "dàliàng", "số lượng lớn"], ["动力资源", "dònglì zīyuán", "tài nguyên năng lượng"], ["估计", "gūjì", "ước tính"], ["吨", "dūn", "tấn"], ["蕴藏量", "yùncáng liàng", "trữ lượng tiềm năng"], ["千瓦", "qiānwǎ", "kilowatt"], ["原料", "yuánliào", "nguyên liệu"], ["化学资源", "huàxué zīyuán", "tài nguyên hóa học"], ["盐", "yán", "muối"], ["钾", "jiǎ", "kali"], ["钠", "nà", "natri"]], "ex2": [["中国土地资源的“一多三少”是什么意思？", "总量多，人均耕地、高质量耕地和备用资源少。", ["人口多，土地少，水少，山少。", "耕地多，城市少。"]], ["中国矿产资源人均占有量是世界人均的多少？", "只有58%。", ["是世界人均的两倍。", "是世界第一。"]], ["中国矿产资源有哪些突出问题？", "支柱性矿产储量不足、大矿少、分布与生产力布局不匹配。", ["矿产太多，用不完。", "只有石油，没有别的矿产。"]], ["中国海岸线加上岛屿岸线有多长？", "32,000多公里。", ["18,000公里。", "5,000公里。"]], ["海洋资源除了生物资源还有什么？", "矿产资源、动力资源和海水资源。", ["只有鱼和虾。", "只有盐。"]]]}, "hk4-l4": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 1", "kw": [{"h": "课文 安全U盘", "lines": [["", "现在，电脑几乎是人们生活中不可缺少的工具。而U盘等移动存储设备也早已普及。很多人在工作和生活中都会用到U盘。U盘体积小巧、携带方便，然而带来这些便利的同时，使用U盘也增加了丢失数据的概率。U盘本身虽然不值钱，但是存储在U盘内的数据却是无价的。存储其中的个人资料、客户信息或是商业机密，其价值难以衡量。就在今年3月，某医院就发生了由于U盘遗失致使47名病人信息泄露的事件。", "Xiànzài, diànnǎo jīhū shì rénmen shēnghuó zhōng bùkě quēshǎo de gōngjù. Ér U pán děng yídòng cúnchú shèbèi yě zǎoyǐ pǔjí. Hěnduō rén zài gōngzuò hé shēnghuó zhōng dōu huì yòng dào U pán. U pán tǐjī xiǎoqiǎo, xiédài fāngbiàn, rán'ér dàilái zhèxiē biànlì de tóngshí, shǐyòng U pán yě zēngjiāle diūshī shùjù de gàilǜ. U pán běnshēn suīrán bù zhíqián, dànshì cúnchú zài U pán nèi de shùjù què shì wújià de. Cúnchú qízhōng de gèrén zīliào, kèhù xìnxī huòshì shāngyè jīmì, qí jiàzhí nányǐ héngliáng. Jiù zài jīnnián 3 yuè, mǒu yīyuàn jiù fāshēngle yóuyú U pán yíshī zhìshǐ 47 míng bìngrén xìnxī xièlòu de shìjiàn.", "Ngày nay, máy tính gần như là công cụ không thể thiếu trong cuộc sống của con người. Và các thiết bị lưu trữ di động như USB cũng đã trở nên phổ biến từ lâu. Rất nhiều người dùng USB trong công việc và cuộc sống. USB có kích thước nhỏ nhắn, tiện lợi khi mang theo. Tuy nhiên, bên cạnh những tiện lợi này, việc sử dụng USB cũng làm tăng khả năng mất dữ liệu. Bản thân chiếc USB tuy không đáng giá bao nhiêu, nhưng dữ liệu được lưu trữ bên trong thì vô giá. Những thông tin cá nhân, dữ liệu khách hàng hay bí mật thương mại được lưu trong đó, giá trị của chúng khó có thể đo đếm được. Ngay trong tháng 3 năm nay, một bệnh viện đã xảy ra sự việc khiến thông tin của 47 bệnh nhân bị rò rỉ do làm mất USB."], ["", "最近，“成功者”电子公司发布了一种新U盘，能解决机密数据随U盘遗失的问题。其实，在中国，乃至世界，信息加密的问题早就受到关注，市场上已经有很多U盘提供了数据加密功能。然而，其中很多U盘的加密是通过软件或外加芯片来完成的，写入芯片的数据并未进行加密，只是限制了数据的读取，如果通过一些技术手段很容易破解。", "Zuìjìn, “Chénggōngzhě” diànzǐ gōngsī fābùle yī zhǒng xīn U pán, néng jiějué jīmì shùjù suí U pán yíshī de wèntí. Qíshí, zài Zhōngguó, nǎizhì shìjiè, xìnxī jiāmì de wèntí zǎo jiù shòudào guānzhù, shìchǎng shàng yǐjīng yǒu hěnduō U pán tígōngle shùjù jiāmì gōngnéng. Rán'ér, qízhōng hěnduō U pán de jiāmì shì tōngguò ruǎnjiàn huò wàijiā xīnpiàn lái wánchéng de, xiěrù xīnpiàn de shùjù bìng wèi jìnxíng jiāmì, zhǐshì xiànzhìle shùjù de dúqǔ, rúguǒ tōngguò yīxiē jìshù shǒuduàn hěn róngyì pòjiě.", "Gần đây, công ty điện tử \"Người Thành Công\" đã ra mắt một loại USB mới, có thể giải quyết vấn đề dữ liệu mật bị rò rỉ theo USB bị thất lạc. Thực tế, ở Trung Quốc, thậm chí trên thế giới, vấn đề mã hóa thông tin từ lâu đã được quan tâm. Trên thị trường đã có rất nhiều USB cung cấp chức năng mã hóa dữ liệu. Tuy nhiên, trong số đó, nhiều USB thực hiện mã hóa thông qua phần mềm hoặc chip bổ sung. Dữ liệu ghi vào chip chưa được mã hóa, mà chỉ hạn chế quyền đọc dữ liệu. Nếu sử dụng một số thủ thuật kỹ thuật, rất dễ dàng để giải mã."], ["", "与普通具有加密功能的U盘相比，“成功者”安全U盘具有与众不同的特点：它的认证主体是主控芯片本身，口令判断在主控芯片内完成；“成功者”安全U盘的使用非常简单，插入电脑后输入正确的密码，即可像正常U盘一样存储数据了。为了方便用户与他人共享数据，“成功者”安全U盘设有公共区和加密区。公共区是不需要密码即可读写的，用户可以将其备份到他人共享的资料放在该区内，而将重要的机密资料保存在加密区内。如果U盘丢失，不知道密码的人在输错10次密码之后，U盘将被自动锁定，无法再对其进行任何操作。即便是专业人员，也无法通过各种技术手段来破解存储的保密数据。", "Yǔ pǔtōng jùyǒu jiāmì gōngnéng de U pán xiāngbǐ, “Chénggōngzhě” ānquán U pán jùyǒu yǔzhòng bùtóng de tèdiǎn: tā de rènzhèng zhǔtǐ shì zhǔkòng xīnpiàn běnshēn, kǒulìng pànduàn zài zhǔkòng xīnpiàn nèi wánchéng; “Chénggōngzhě” ānquán U pán de shǐyòng fēicháng jiǎndān, chārù diànnǎo hòu shūrù zhèngquè de mìmǎ, jí kě xiàng zhèngcháng U pán yīyàng cúnchú shùjùle. Wèile fāngbiàn yònghù yǔ tārén gòngxiǎng shùjù, “Chénggōngzhě” ānquán U pán shèyǒu gōnggòng qū hé jiāmì qū. Gōnggòng qū shì bù xūyào mìmǎ jí kě dúxiě de, yònghù kěyǐ jiāng qí bèifèn dào tārén gòngxiǎng de zīliào fàng zài gāi qū nèi, ér jiāng zhòngyào de jīmì zīliào bǎocún zài jiāmì qū nèi. Rúguǒ U pán diūshī, bù zhīdào mìmǎ de rén zài shūcuò 10 cì mìmǎ zhīhòu, U pán jiāng bèi zìdòng suǒdìng, wúfǎ zài duì qí jìnxíng rènhé cāozuò. Jíbiàn shì zhuānyè rényuán, yě wúfǎ tōngguò gè zhǒng jìshù shǒuduàn lái pòjiě cúnchú de bǎomì shùjù.", "So với USB mã hóa thông thường, USB an toàn \"Người Thành Công\" có những đặc điểm khác biệt: chủ thể xác thực là chính con chip điều khiển chính, việc kiểm tra mật khẩu được hoàn thành ngay bên trong chip điều khiển chính; USB an toàn \"Người Thành Công\" sử dụng rất đơn giản, sau khi cắm vào máy tính và nhập đúng mật khẩu, bạn có thể lưu trữ dữ liệu như USB bình thường. Để tiện cho người dùng chia sẻ dữ liệu với người khác, USB an toàn \"Người Thành Công\" được thiết kế với khu vực công cộng và khu vực mã hóa. Khu vực công cộng có thể đọc và ghi mà không cần mật khẩu. Người dùng có thể đặt các tài liệu cần sao lưu và chia sẻ với người khác vào khu vực này, đồng thời lưu trữ các tài liệu mật quan trọng trong khu vực mã hóa. Nếu USB bị mất, những người không biết mật khẩu sau khi nhập sai 10 lần, USB sẽ tự động bị khóa, không thể thực hiện bất kỳ thao tác nào trên đó nữa. Ngay cả các chuyên gia kỹ thuật cũng không thể thông qua bất kỳ phương tiện kỹ thuật nào để giải mã dữ liệu bảo mật đã lưu."]]}], "fn": [["“几乎” (gần như)", "", "", "电脑几乎是人们生活中不可缺少的工具。"], ["“而...也...” (còn... cũng...)", "", "而 dùng để nối tiếp ý, thêm thông tin mới; 等 nghĩa là \"v.v.\"", "U盘等移动存储设备也早已普及。"], ["“虽然...但是...” (mặc dù... nhưng...)", "", "Cách dùng: Biểu thị quan hệ nhượng bộ – đối lập.", "U盘本身虽然不值钱，但是存储在U盘内的数据却是无价的。"], ["“然而...同时...” (tuy nhiên... đồng thời...)", "", "然而 = tuy nhiên; 同时 = đồng thời, nối hai ý bổ sung cho nhau.", "然而带来这些便利的同时，使用U盘也增加了丢失数据的概率。"], ["“由于” (do, bởi vì)", "", "由于 + nguyên nhân + 致使 + kết quả", "由于U盘遗失致使47名病人信息泄露。"], ["“通过...来...” (thông qua... để...)", "", "Cách dùng: Chỉ phương thức, cách thức thực hiện hành động.", "通过软件或外加芯片来完成的；通过一些技术手段很容易破解。"], ["“并未” (vẫn chưa, không hề)", "", "", "写入芯片的数据并未进行加密。"], ["“与...相比” (so với...)", "", "与 + A + 相比，B + ... Cách dùng: Cấu trúc so sánh đối chiếu.", "与普通具有加密功能的U盘相比，“成功者”安全U盘具有与众不同的特点。"]], "adv": [["限制", "xiànzhì", "hạn chế"], ["读取", "dúqǔ", "đọc (dữ liệu)"], ["技术手段", "jìshù shǒuduàn", "phương tiện kỹ thuật, thủ thuật"], ["破解", "pòjiě", "giải mã, phá giải"], ["普通", "pǔtōng", "thông thường"], ["具有", "jùyǒu", "có, sở hữu"], ["与众不同", "yǔzhòng bùtóng", "khác biệt, khác thường"], ["特点", "tèdiǎn", "đặc điểm"], ["认证", "rènzhèng", "xác thực, chứng nhận"], ["主体", "zhǔtǐ", "chủ thể"], ["主控", "zhǔkòng", "điều khiển chính"], ["口令", "kǒulìng", "mật khẩu, khẩu lệnh"], ["判断", "pànduàn", "phán đoán, kiểm tra"], ["输入", "shūrù", "nhập vào"], ["正确", "zhèngquè", "chính xác"], ["密码", "mìmǎ", "mật khẩu"], ["像...一样", "xiàng... yīyàng", "giống như..."], ["正常", "zhèngcháng", "bình thường"], ["用户", "yònghù", "người dùng"], ["共享", "gòngxiǎng", "chia sẻ"], ["设有", "shè yǒu", "được trang bị, có thiết lập"], ["公共区", "gōnggòng qū", "khu vực công cộng"], ["加密区", "jiāmì qū", "khu vực mã hóa"], ["读写", "dúxiě", "đọc và ghi"], ["备份", "bèifèn", "sao lưu"], ["保存", "bǎocún", "lưu giữ, bảo tồn"], ["输错", "shūcuò", "nhập sai"], ["自动", "zìdòng", "tự động"], ["锁定", "suǒdìng", "khóa lại"], ["任何", "rènhé", "bất kỳ"], ["操作", "cāozuò", "thao tác"], ["即便", "jíbiàn", "ngay cả, cho dù"], ["专业", "zhuānyè", "chuyên nghiệp"], ["人员", "rényuán", "nhân viên"], ["保密", "bǎomì", "bảo mật"]], "ex2": [["U盘有什么优点和缺点？", "体积小、携带方便，但容易丢失数据。", ["价格很贵，但存储很快。", "很重，不方便携带。"]], ["某医院发生了什么事？", "因为U盘遗失，47名病人的信息泄露了。", ["医院买了47个新U盘。", "医生把电脑弄坏了。"]], ["市场上很多加密U盘有什么问题？", "写入芯片的数据并未加密，用技术手段很容易破解。", ["它们太贵了。", "它们不能存数据。"]], ["“成功者”安全U盘的公共区和加密区有什么不同？", "公共区不需要密码，加密区用来保存重要的机密资料。", ["公共区要输两次密码。", "两个区完全一样。"]], ["输错10次密码以后会怎么样？", "U盘将被自动锁定，无法再进行任何操作。", ["U盘会自动打开。", "U盘会给主人打电话。"]]]}, "hk4-l5": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 2", "kw": [{"h": "课文 孔子的忠告", "lines": [["", "孔子的一位朋友要去出任地方官了，就跑来问孔子：“先生，您是一位智者，您说我这个地方官该怎么当啊？”孔子说：“搞管理既可以很容易，也可以很不容易，我只能告诉你九个字：先有司，赦小过，举贤才。”", "Kǒngzǐ de yí wèi péngyou yào qù chūrèn dìfāngguān le, jiù pǎo lái wèn Kǒngzǐ: “Xiānsheng, nín shì yí wèi zhìzhě, nín shuō wǒ zhège dìfāngguān gāi zěnme dāng a?” Kǒngzǐ shuō: “Gǎo guǎnlǐ jì kěyǐ hěn róngyì, yě kěyǐ hěn bù róngyì, wǒ zhǐ néng gàosu nǐ jiǔ gè zì: Xiān yǒu sī, shè xiǎo guò, jǔ xián cái.”", "Một người bạn của Khổng Tử sắp đi nhậm chức quan địa phương, liền chạy đến hỏi Khổng Tử: “Thưa tiên sinh, ngài là bậc trí giả, xin ngài cho biết tôi nên làm quan địa phương thế nào ạ?” Khổng Tử nói: “Làm quản lý thì có thể rất dễ, cũng có thể rất không dễ, tôi chỉ có thể nói với anh chín chữ: Tiên hữu ti, xá tiểu quá, cử hiền tài (Trước hết phải làm gương, tha thứ lỗi nhỏ, tiến cử người hiền tài).”"], ["", "什么叫“先有司”呢？先有司，用今天的话来说，就是首先自己要做好表率。这里至少有两个意思：第一是自己要出色地、专业地完成自己的工作；第二是要在工作状态和职业精神上给下属带好头。这是做管理工作的基本要求。", "Shénme jiào “xiān yǒu sī” ne? Xiān yǒu sī, yòng jīntiān de huà lái shuō, jiùshì shǒuxiān zìjǐ yào zuò hǎo biǎoshuài. Zhèlǐ zhìshǎo yǒu liǎng ge yìsi: Dì-yī shì zìjǐ yào chūsè de, zhuānyè de wánchéng zìjǐ de gōngzuò; dì-èr shì yào zài gōngzuò zhuàngtài hé zhíyè jīngshén shàng gěi xiàshǔ dài hǎo tóu. Zhè shì zuò guǎnlǐ gōngzuò de jīběn yāoqiú.", "“Tiên hữu ti” nghĩa là gì? Nói theo ngày nay, trước hết bản thân phải làm gương tốt. Ở đây ít nhất có hai ý: Thứ nhất, bản thân phải hoàn thành công việc một cách xuất sắc và chuyên nghiệp; thứ hai, phải làm gương cho cấp dưới về tác phong làm việc và tinh thần nghề nghiệp. Đó là yêu cầu cơ bản của công tác quản lý."], ["", "哪个下属会忠诚地追随一个不能胜任自己工作的领导呢？哪个下属会为一个缺乏职业精神的领导效力呢？所以，孔子说的“先有司”，是做好管理工作的第一要义。从一定意义上讲，有什么样的领导就有什么样的下属，有什么样的老板就有什么样的员工。", "Nǎ ge xiàshǔ huì zhōngchéng de zhuīsuí yí ge bùnéng shèngrèn zìjǐ gōngzuò de lǐngdǎo ne? Nǎ ge xiàshǔ huì wèi yí ge quēfá zhíyè jīngshén de lǐngdǎo xiàolì ne? Suǒyǐ, Kǒngzǐ shuō de “xiān yǒu sī”, shì zuò hǎo guǎnlǐ gōngzuò de dì-yī yàoyì. Cóng yídìng yìyì shàng jiǎng, yǒu shénme yàng de lǐngdǎo jiù yǒu shénme yàng de xiàshǔ, yǒu shénme yàng de lǎobǎn jiù yǒu shénme yàng de yuángōng.", "Cấp dưới nào lại trung thành theo đuổi một người lãnh đạo không đủ năng lực làm việc của mình? Cấp dưới nào lại phục vụ cho một người lãnh đạo thiếu tinh thần nghề nghiệp? Vì vậy, điều Khổng Tử nói “tiên hữu ti” là nghĩa quan trọng đầu tiên để làm tốt công tác quản lý. Nói theo một nghĩa nhất định, có kiểu lãnh đạo nào thì có kiểu cấp dưới đó, có ông chủ nào thì có nhân viên đó."], ["", "什么叫“赦小过”呢？孔子的意思是说：金无足赤，人无完人，选用人才要看大局。如果一个人总体上能够胜任你安排的工作职位，那么在一些细节问题上，就应该宽容一些。没有哪个人没有缺点。所以，管理人要做到该严格的地方要严格，该宽松的地方要宽松。管理是一门平衡的艺术，谁不能宽容别人，也就不能很好地领导别人。", "Shénme jiào “shè xiǎo guò” ne? Kǒngzǐ de yìsi shì shuō: Jīn wú zú chì, rén wú wán rén, xuǎnyòng réncái yào kàn dàjú. Rúguǒ yí ge rén zǒngtǐ shàng nénggòu shèngrèn nǐ ānpái de gōngzuò zhíwèi, nàme zài yìxiē xìjié wèntí shàng, jiù yīnggāi kuānróng yìxiē. Méiyǒu nǎ ge rén méiyǒu quēdiǎn. Suǒyǐ, guǎnlǐ rén yào zuò dào gāi yángé de dìfang yào yángé, gāi kuān sōng de dìfang yào kuān sōng. Guǎnlǐ shì yì mén pínghéng de yìshù, shuí bùnéng kuānróng biérén, yě jiù bùnéng hěn hǎo de lǐngdǎo biérén.", "“Xá tiểu quá” nghĩa là gì? Ý Khổng Tử là: Vàng không có đủ, người không ai hoàn hảo, chọn dùng nhân tài phải nhìn vào đại cục. Nếu một người về tổng thể có thể đảm nhiệm được vị trí công việc bạn sắp xếp, thì trong một số vấn đề chi tiết, nên khoan dung một chút. Không ai không có khuyết điểm. Vì vậy, người quản lý phải làm được chỗ nào cần nghiêm khắc thì nghiêm khắc, chỗ nào cần nới lỏng thì nới lỏng. Quản lý là một nghệ thuật cân bằng, ai không thể khoan dung với người khác thì cũng không thể lãnh đạo người khác tốt được."], ["", "什么是“举贤才”呢？就是要重用人才。贤才至少应该符合两个标准，第一是有才能，第二是有品德。真正的人才应该做到德才兼备，一方面具有胜任一个职位的知识、技能和经验，另一方面具有良好的职业道德，有团队精神。汉代第一位皇帝刘邦曾经说，搞战略，我不如张良；搞销售，开拓市场，我不如韩信；管行政，我不如萧何。这三个人都是杰出人才，而我能够用他们。国家兴起就是靠着这样的人才啊！", "Shénme shì “jǔ xián cái” ne? Jiùshì yào zhòngyòng réncái. Xián cái zhìshào yīnggāi fúhé liǎng ge biāozhǔn, dì-yī shì yǒu cáinéng, dì-èr shì yǒu pǐndé. Zhēnzhèng de réncái yīnggāi zuò dào dé cái jiān bèi, yì fāngmiàn jùyǒu shèngrèn yí ge zhíwèi de zhīshi, jìnéng hé jīngyàn, lìng yì fāngmiàn jùyǒu liánghǎo de zhíyè dàodé, yǒu tuánduì jīngshén. Hàn dài dì-yī wèi huángdì Liú Bāng céngjīng shuō, gǎo zhànlüè, wǒ bùrú Zhāng Liáng; gǎo xiāoshòu, kāituò shìchǎng, wǒ bùrú Hán Xìn; guǎn xíngzhèng, wǒ bùrú Xiāo Hé. Zhè sān ge rén dōu shì jiéchū réncái, ér wǒ nénggòu yòng tāmen. Guójiā xīngqǐ jiùshì kàozhe zhèyàng de réncái a!", "“Cử hiền tài” là gì? Là trọng dụng nhân tài. Người hiền tài ít nhất phải đáp ứng hai tiêu chuẩn: thứ nhất là có tài năng, thứ hai là có phẩm đức. Nhân tài thực sự phải đạt được cả đức lẫn tài, một mặt có kiến thức, kỹ năng và kinh nghiệm để đảm nhiệm một vị trí, mặt khác có đạo đức nghề nghiệp tốt và tinh thần đồng đội. Vị hoàng đế đầu tiên của nhà Hán là Lưu Bang từng nói: Về chiến lược, tôi không bằng Trương Lương; về tiêu thụ, mở rộng thị trường, tôi không bằng Hàn Tín; về quản lý hành chính, tôi không bằng Tiêu Hà. Ba người này đều là nhân tài xuất chúng, mà tôi có thể sử dụng họ. Đất nước hưng thịnh chính là nhờ những nhân tài như vậy đó!"], ["", "一流的人才造就一流的公司，二流的人才造就二流的公司。管理者遇到公司管理问题时，不妨先看看自己的左右：我们到底拥有什么样的人才？“先有司，赦小过，举贤才”，这三条忠告是两千多年前孔子说的，直到今日仍然对管理者有警示作用。", "Yīliú de réncái zàojiù yīliú de gōngsī, èrliú de réncái zàojiù èrliú de gōngsī. Guǎnlǐzhě yù dào gōngsī guǎnlǐ wèntí shí, bùfáng xiān kànkan zìjǐ de zuǒyòu: wǒmen dàodǐ yōngyǒu shénme yàng de réncái? “Xiān yǒu sī, shè xiǎo guò, jǔ xián cái”, zhè sān tiáo zhōnggào shì liǎng qiān duō nián qián Kǒngzǐ shuō de, zhí dào jīnrì réngrán duì guǎnlǐzhě yǒu jǐngshì zuòyòng.", "Nhân tài hạng nhất tạo nên công ty hạng nhất, nhân tài hạng nhì tạo nên công ty hạng nhì. Khi người quản lý gặp vấn đề trong quản lý công ty, chẳng hãy nhìn xung quanh mình trước: chúng ta rốt cuộc có loại nhân tài nào? “Tiên hữu ti, xá tiểu quá, cử hiền tài” – ba lời khuyên này là của Khổng Tử cách đây hơn hai nghìn năm, đến nay vẫn có tác dụng cảnh tỉnh đối với người quản lý."]]}], "fn": [["“既……也……” (jì... yě...)", "", "Vừa... cũng... (diễn tả hai trạng thái cùng tồn tại) Phân tích: Gǎo guǎnlǐ jì kěyǐ hěn róngyì, yě kěyǐ hěn bù róngyì.", "搞管理既可以很容易，也可以很不容易。"], ["“用今天的话来说” (yòng jīntiān de huà lái shuō)", "", "Nói theo cách nói ngày hôm nay / nói một cách hiện đại 用 + [cách nói] + 来说 = dùng cách nói... để mà nói", "先有司，用今天的话来说，就是首先自己要做好表率。"], ["“哪个……呢？” (nǎ ge... ne?)", "", "Câu hỏi tu từ (rhetorical question): \"Có ... nào ... đâu?\"", "哪个下属会忠诚地追随一个不能胜任自己工作的领导呢？"], ["“有什么样的……就有什么样的……” (yǒu shénme yàng de... jiù yǒu shénme yàng de...)", "", "Có kiểu ... nào thì có kiểu ... ấy (quan hệ nhân quả / tương ứng)", "有什么样的领导就有什么样的下属，有什么样的老板就有什么样的员工。"], ["“没有……没有……” (méiyǒu... méiyǒu...) – dạng nhấn mạnh", "", "Không có ... nào mà không ...", "没有哪个人没有缺点。"], ["“谁不……，也就不能……” (shuí bù..., yě jiù bùnéng...)", "", "Ai không ... thì cũng không thể ...", "谁不能宽容别人，也就不能很好地领导别人。"], ["“一方面……另一方面……” (yì fāngmiàn... lìng yì fāngmiàn...)", "", "Một mặt..., mặt khác...", "一方面具有胜任一个职位的知识、技能和经验，另一方面具有良好的职业道德，有团队精神。"], ["“不如” (bùrú)", "", "Không bằng / thua kém", "搞战略，我不如张良。"]], "adv": [["战略", "zhànlüè", "chiến lược"], ["销售", "xiāoshòu", "tiêu thụ, bán hàng"], ["开拓", "kāituò", "khai thác, mở rộng"], ["市场", "shìchǎng", "thị trường"], ["行政", "xíngzhèng", "hành chính"], ["杰出", "jiéchū", "xuất chúng, kiệt xuất"], ["兴起", "xīngqǐ", "hưng thịnh, nổi lên"], ["一流", "yīliú", "hạng nhất, đẳng cấp một"], ["二流", "èrliú", "hạng nhì"], ["管理者", "guǎnlǐzhě", "người quản lý"], ["左右", "zuǒyòu", "xung quanh, bên cạnh (cũng nghĩa là trợ thủ)"], ["警示", "jǐngshì", "cảnh tỉnh, răn đe"]], "ex2": [["孔子告诉朋友的九个字是什么？", "先有司，赦小过，举贤才。", ["学而时习之，不亦说乎。", "己所不欲，勿施于人。"]], ["“先有司”用今天的话说是什么意思？", "首先自己要做好表率。", ["先找一个好秘书。", "先把下属管严。"]], ["“赦小过”是什么意思？", "在细节问题上要宽容，选人要看大局。", ["什么错误都不能原谅。", "只用没有缺点的人。"]], ["刘邦为什么能成功？", "因为他能用张良、韩信、萧何这样的杰出人才。", ["因为他自己什么都会。", "因为他不需要人才。"]], ["作者认为管理者遇到问题时应该先做什么？", "先看看自己的左右，到底拥有什么样的人才。", ["马上换一个公司。", "先批评所有的员工。"]]]}, "hk4-l6": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 2", "kw": [{"h": "课文 不比为贵", "lines": [["", "生活中要有“不比为贵”的心态，也就是不和人攀比。学会接受自己，满足于自己从生活中所得到的。有些人总感到这不如意那不如意，并不是客观条件太差，而是由于攀比引起的心理不平衡。俗话说：人比人，气死人。因此，要想享受人生的欢乐与幸福，还有很重要的一点就是要学习“不比为贵”的心态。", "Shēnghuó zhōng yào yǒu “bù bǐ wéi guì” de xīntài, yě jiùshì bù hé rén pānbǐ. Xuéhuì jiēshòu zìjǐ, mǎnzú yú zìjǐ cóng shēnghuó zhōng suǒ dédào de. Yǒuxiē rén zǒng gǎndào zhè bùrúyì nà bùrúyì, bìng bùshì kèguān tiáojiàn tài chà, ér shì yóuyú pānbǐ yǐnqǐ de xīnlǐ bù pínghéng. Súhuà shuō: Rén bǐ rén, qì sǐ rén. Yīncǐ, yào xiǎng xiǎngshòu rénshēng de huānlè yǔ xìngfú, hái yǒu hěn zhòngyào de yì diǎn jiùshì yào xuéxí “bù bǐ wéi guì” de xīntài.", "Trong cuộc sống cần có tâm thế \"không so bề là quý\", tức là không so sánh với người khác. Học cách chấp nhận bản thân, hài lòng với những gì mình có được từ cuộc sống. Có những người luôn cảm thấy chỗ này không vừa ý, chỗ kia không như ý, thực ra không phải vì điều kiện khách quan quá kém, mà là do tâm lý mất cân bằng gây ra bởi sự so sánh. Tục ngữ có câu: \"Người so với người, tức chết người\". Vì vậy, để tận hưởng niềm vui và hạnh phúc của cuộc sống, có một điểm rất quan trọng là phải học tâm thế \"không so bề là quý\"."], ["", "文史作家郑逸梅先生的长寿秘诀便是“不比为贵”。郑先生常对人说：我不去跟人家比什么财富地位，也不会为缺少这些感到遗憾。我体验过自己的工作、生活的快乐，非常满足。正因为郑老有这样良好的心态，尽管他经历坎坷，却能始终保持坦然、乐观的精神。他一生办报，著述丰富，活到了90多岁高龄。", "Wénshǐ zuòjiā Zhèng Yìméi xiānsheng de chángshòu mìjué biàn shì “bù bǐ wéi guì”. Zhèng xiānsheng cháng duì rén shuō: Wǒ bú qù gēn rénjia bǐ shénme cáifù dìwèi, yě bú huì wèi quēshǎo zhèxiē gǎndào yíhàn. Wǒ tǐyàn guò zìjǐ de gōngzuò, shēnghuó de kuàilè, fēicháng mǎnzú. Zhèng yīnwèi Zhèng lǎo yǒu zhèyàng liánghǎo de xīntài, jǐnguǎn tā jīnglì kǎnkě, què néng shǐzhōng bǎochí tǎnrán, lèguān de jīngshén. Tā yīshēng bàn bào, zhùshù fēngfù, huó dào le 90 duō suì gāolíng.", "Bí quyết trường thọ của nhà văn sử học Trịnh Dật Mai chính là \"không so bề là quý\". Ông Trịnh thường nói với mọi người: Tôi không đi so sánh với người khác về giàu sang, địa vị, cũng không vì thiếu những thứ đó mà cảm thấy tiếc nuối. Tôi đã trải nghiệm niềm vui trong công việc và cuộc sống của mình, rất hài lòng. Chính vì cụ Trịnh có tâm thế tốt như vậy, mặc dù trải qua nhiều gian truân, nhưng ông vẫn luôn giữ được tinh thần thản nhiên, lạc quan. Cả đời ông làm báo, trước tác phong phú, sống tới hơn 90 tuổi cao."], ["", "著名科学家斯蒂芬·霍金的命运很不幸：口不能言，腿不能站，身不能动。可霍金却说：“我的手指还能活动；我的大脑还能思维；我有终生追求的理想；有我爱和爱我的亲人和朋友。”他病痛缠身仍感到充实而快乐，而他的健康心态使他成为当今最具传奇色彩的科学家。", "Zhùmíng kēxuéjiā Sīdìfēn·Huòjīn de mìngyùn hěn bùxìng: kǒu bùnéng yán, tuǐ bùnéng zhàn, shēn bùnéng dòng. Kě Huòjīn què shuō: “Wǒ de shǒuzhǐ hái néng huódòng; wǒ de dànǎo hái néng sīwéi; wǒ yǒu zhōngshēng zhuīqiú de lǐxiǎng; yǒu wǒ ài hé ài wǒ de qīnrén hé péngyou.” Tā bìngtòng chánshēn réng gǎndào chōngshí ér kuàilè, ér tā de jiànkāng xīntài shǐ tā chéngwéi dāngjīn zuì jù chuánqí sècǎi de kēxuéjiā.", "Số phận của nhà khoa học nổi tiếng Stephen Hawking rất bất hạnh: miệng không nói được, chân không đứng được, thân không cử động được. Nhưng Hawking lại nói: \"Ngón tay tôi vẫn còn hoạt động được; não tôi vẫn còn suy nghĩ được; tôi có lý tưởng theo đuổi cả đời; có người thân và bạn bè mà tôi yêu và yêu tôi.\" Ông bị bệnh tật giày vò nhưng vẫn cảm thấy phong phú và vui vẻ, và tâm thế lành mạnh của ông đã khiến ông trở thành nhà khoa học có màu sắc huyền thoại nhất hiện nay."], ["", "研究发现，脚踏实地的人往往比那些好高骛远的人快乐。因此，要想生活快乐，就要学会根据自己的实际情况来调整目标。虽然财富可以带给人幸福感，但并不是财富越多越幸福。研究表明，一旦人的基本生存需要得到满足后，财富的增加对幸福本身都不再具有任何特殊意义。另外，幸福的人总是不断地为自己树立一些目标，而目标的实现也能给我们带来幸福的感受。", "Yánjiū fāxiàn, jiǎotàshídì de rén wǎngwǎng bǐ nàxiē hàogāowùyuǎn de rén kuàilè. Yīncǐ, yào xiǎng shēnghuó kuàilè, jiù yào xuéhuì gēnjù zìjǐ de shíjì qíngkuàng lái tiáozhěng mùbiāo. Suīrán cáifù kěyǐ dài gěi rén xìngfú gǎn, dàn bìng bùshì cáifù yuè duō yuè xìngfú. Yánjiū biǎomíng, yídàn rén de jīběn shēngcún xūyào dédào mǎnzú hòu, cáifù de zēngjiā duì xìngfú běnshēn dōu bú zài jùyǒu rènhé tèshū yìyì. Lìngwài, xìngfú de rén zǒngshì búduàn de wèi zìjǐ shùlì yìxiē mùbiāo, ér mùbiāo de shíxiàn yě néng gěi wǒmen dài lái xìngfú de gǎnshòu.", "Nghiên cứu phát hiện rằng, những người thực tế, vững vàng thường vui vẻ hơn những người thích viển vông, cao xa. Vì vậy, muốn sống vui vẻ, phải học cách điều chỉnh mục tiêu dựa trên tình hình thực tế của bản thân. Tuy giàu sang có thể mang lại cho con người cảm giác hạnh phúc, nhưng không phải càng nhiều tiền thì càng hạnh phúc. Nghiên cứu chỉ ra rằng, một khi nhu cầu sinh tồn cơ bản của con người được đáp ứng, thì sự gia tăng của cải không còn mang ý nghĩa đặc biệt nào đối với bản thân hạnh phúc nữa. Ngoài ra, người hạnh phúc luôn không ngừng đặt ra cho mình một số mục tiêu, và việc đạt được mục tiêu cũng mang lại cho chúng ta cảm giác hạnh phúc."], ["", "美国华裔数学家王章程，就读于美国加州大学。毕业后，他的同学多数去了大财团、大公司，只有王章程一头扎进了研究室，一干就是十年。十年中，他的生活收入一直很低，而不少同学都成了收入不菲的大老板。而王先生从来不羡慕别人的财富，只对自己的事业感兴趣。35岁的时候，他攻克了两道世界级数学难题，从此研究成果不断出现，成为世界数学界的新星。面对荣誉，他十分平静，继续以自己的研究中得到满足。", "Měiguó Huáyì shùxuéjiā Wáng Zhāngchéng, jiùdú yú Měiguó Jiāzhōu Dàxué. Bìyè hòu, tā de tóngxué duōshù qù le dà cáituán, dà gōngsī, zhǐyǒu Wáng Zhāngchéng yì tóu zhā jìn le yánjiūshì, yí gàn jiù shì shí nián. Shí nián zhōng, tā de shēnghuó shōurù yìzhí hěn dī, ér bùshǎo tóngxué dōu chéng le shōurù bùfěi de dà lǎobǎn. Ér Wáng xiānsheng cónglái bù xiànmù biérén de cáifù, zhǐ duì zìjǐ de shìyè gǎn xìngqù. 35 suì de shíhou, tā gōngkè le liǎng dào shìjiè jí shùxué nántí, cóngcǐ yánjiū chéngguǒ búduàn chūxiàn, chéngwéi shìjiè shùxuéjiè de xīnxīng. Miànduì róngyù, tā shífēn píngjìng, jìxù yǐ zìjǐ de yánjiū zhōng dédào mǎnzú.", "Nhà toán học người Mỹ gốc Hoa Vương Chương Trình, theo học tại Đại học California (Mỹ). Sau khi tốt nghiệp, phần lớn bạn cùng lớp của ông đã vào các tập đoàn tài chính lớn, công ty lớn, chỉ có Vương Chương Trình một đầu lao vào phòng nghiên cứu, làm liền mười năm. Trong mười năm đó, thu nhập cuộc sống của ông luôn rất thấp, trong khi không ít bạn cùng lớp đã trở thành những ông chủ lớn có thu nhập cao. Nhưng ông Vương chưa bao giờ ngưỡng mộ tài sản của người khác, chỉ quan tâm đến sự nghiệp của mình. Năm 35 tuổi, ông đã giải được hai bài toán khó cấp thế giới, từ đó thành quả nghiên cứu liên tục xuất hiện, trở thành ngôi sao mới trong giới toán học thế giới. Đối diện với vinh dự, ông rất bình tĩnh, tiếp tục tìm thấy sự hài lòng từ nghiên cứu của mình."], ["", "生活中常常打扰我们，让我们感到不安的，往往是别人的生活方式。如果心中总是跟别人比来比去，羡慕别人的生活，就会给自己带来烦恼和迷茫，甚至失去自我。要珍惜自己获得的，过好自己的生活，脚踏实地地追求自己的人生理想，一定能享受到属于自己的快乐。", "Shēnghuó zhōng chángcháng dǎrǎo wǒmen, ràng wǒmen gǎndào bù'ān de, wǎngwǎng shì biérén de shēnghuó fāngshì. Rúguǒ xīnzhōng zǒng shì gēn biérén bǐ lái bǐ qù, xiànmù biérén de shēnghuó, jiù huì gěi zìjǐ dài lái fánnǎo hé míwáng, shènzhì shīqù zìwǒ. Yào zhēnxī zìjǐ huòdé de, guò hǎo zìjǐ de shēnghuó, jiǎotàshídì de zhuīqiú zìjǐ de rénshēng lǐxiǎng, yídìng néng xiǎngshòu dào shǔyú zìjǐ de kuàilè.", "Những điều thường quấy rầy chúng ta và khiến chúng ta bất an trong cuộc sống, thường là cách sống của người khác. Nếu trong lòng cứ so sánh với người khác, ngưỡng mộ cuộc sống của người khác, thì sẽ mang lại cho mình phiền não và mê mang, thậm chí đánh mất bản thân. Hãy trân trọng những gì mình có được, sống tốt cuộc sống của mình, theo đuổi lý tưởng cuộc đời một cách thực tế và vững chắc, nhất định sẽ được tận hưởng niềm vui thuộc về mình."]]}], "fn": [["“也就是” (yě jiùshì) → Cũng chính là / tức là", "", "Trong cuộc sống cần có tâm thế \"không so bề là quý\", tức là không so sánh với người khác.", "生活中要有“不比为贵”的心态，也就是不和人攀比。"], ["“并不是……，而是……” (bìng bùshì..., ér shì...) → Không phải là..., mà là...", "", "Không phải vì điều kiện khách quan quá kém, mà là do tâm lý mất cân bằng gây ra bởi sự so sánh.", "并不是客观条件太差，而是由于攀比引起的心理不平衡。"], ["“俗话说” (súhuà shuō) → Tục ngữ nói", "", "Tục ngữ nói: Người so với người, tức chết người.", "俗话说：人比人，气死人。"], ["“要想……” (yào xiǎng...) → Muốn... (thì)", "", "Muốn tận hưởng niềm vui và hạnh phúc của cuộc sống, thì còn một điểm rất quan trọng là...", "要想享受人生的欢乐与幸福，还有很重要的一点就是..."], ["“正因为……，尽管……，却……” (zhèng yīnwèi..., jǐnguǎn..., què...)", "", "Chính vì..., mặc dù..., nhưng... Chính vì cụ Trịnh có tâm thế tốt như vậy, mặc dù trải qua nhiều gian truân, nhưng vẫn luôn giữ được tinh thần thản nhiên, lạc quan.", "正因为郑老有这样良好的心态，尽管他经历坎坷，却能始终保持坦然、乐观的精神。"], ["“可……却……” (kě... què...) → Nhưng... lại... (nhấn mạnh sự trái ngược)", "", "Nhưng Hawking lại nói:...", "可霍金却说：..."], ["“越来越……” (yuè lái yuè...) → Càng ngày càng...", "", "Không phải càng nhiều của cải thì càng hạnh phúc.(Ở đây dùng cấu trúc: 越 + A + 越 + B = càng... càng...)", "并不是财富越多越幸福。"], ["“一旦……，就/都……” (yídàn..., jiù/dōu...) → Một khi..., thì...", "", "Một khi nhu cầu sinh tồn cơ bản của con người được đáp ứng, thì sự gia tăng của cải không còn mang ý nghĩa đặc biệt nào với hạnh phúc nữa.", "一旦人的基本生存需要得到满足后，财富的增加对幸福本身都不再具有任何特殊意义。"]], "adv": [["目标", "mùbiāo", "mục tiêu"], ["生存", "shēngcún", "sinh tồn"], ["需求", "xūqiú", "nhu cầu"], ["特殊意义", "tèshū yìyì", "ý nghĩa đặc biệt"], ["树立", "shùlì", "xây dựng, tạo lập, đặt ra"], ["实现", "shíxiàn", "thực hiện, đạt được"], ["华裔", "Huáyì", "người gốc Hoa, người Hoa hải ngoại"], ["就读于", "jiùdú yú", "theo học tại"], ["大财团", "dà cáituán", "tập đoàn tài chính lớn"], ["一头扎进", "yì tóu zhā jìn", "một đầu lao vào (dồn hết tâm sức)"], ["收入不菲", "shōurù bùfěi", "thu nhập không nhỏ, thu nhập cao"], ["攻克", "gōngkè", "công phá, giải quyết (khó khăn)"], ["难题", "nántí", "bài toán khó / vấn đề nan giải"], ["新星", "xīnxīng", "ngôi sao mới"], ["荣誉", "róngyù", "vinh dự, vinh quang"], ["平静", "píngjìng", "bình tĩnh, yên lặng"], ["打扰", "dǎrǎo", "quấy rầy, làm phiền"], ["不安", "bù'ān", "bất an, không yên"], ["方式", "fāngshì", "phương thức, cách thức"], ["烦恼", "fánnǎo", "phiền não, lo lắng"], ["迷茫", "míwáng", "mê mang, mơ hồ, lạc lối"], ["自我", "zìwǒ", "bản thân, cái tôi"], ["珍惜", "zhēnxī", "trân trọng, quý trọng"], ["获得", "huòdé", "đạt được, thu được"]], "ex2": [["“不比为贵”是什么意思？", "不和别人攀比，满足于自己从生活中得到的。", ["什么东西都不比较便宜。", "一定要比别人强。"]], ["郑逸梅先生长寿的秘诀是什么？", "不跟人家比财富地位，满足于工作和生活的快乐。", ["每天运动三个小时。", "只吃素菜。"]], ["霍金为什么仍然感到充实而快乐？", "他看到自己还能思维，有理想，有爱他的亲人朋友。", ["因为他很有钱。", "因为他的病好了。"]], ["研究发现财富和幸福有什么关系？", "基本需要满足以后，财富增加对幸福不再有特殊意义。", ["财富越多越幸福。", "没有钱的人最幸福。"]], ["王章程毕业后选择了什么？", "进研究室做了十年研究，不羡慕同学的财富。", ["去大公司当老板。", "回国开了一个饭馆。"]]]}, "hk4-l7": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 2", "kw": [{"h": "课文 说文解字", "lines": [["", "《说文解字》是中国第一部系统地分析汉字字形和考究字源的字书，也是流传最广的中文工具书。《说文解字》是两千年来中国文字学研究最具权威性的著作。", "“Shuōwén Jiězì” shì Zhōngguó dì-yī bù xìtǒng de fēnxī Hànzì zìxíng hé kǎojiū zìyuán de zìshū, yě shì liúchuán zuì guǎng de Zhōngwén gōngjùshū. “Shuōwén Jiězì” shì liǎng qiān nián lái Zhōngguó wénzìxué yánjiū zuì jù quánwēi xìng de zhùzuò.", "Thuyết Văn Giải Tự là cuốn sách chữ (từ điển) đầu tiên của Trung Quốc phân tích một cách có hệ thống hình dạng chữ Hán và khảo cứu nguồn gốc chữ, đồng thời cũng là công cụ tra cứu tiếng Trung phổ biến nhất. Thuyết Văn Giải Tự là tác phẩm có tính uy quyền nhất trong nghiên cứu văn tự học Trung Quốc suốt hai nghìn năm qua."], ["", "《说文解字》的作者许慎（约公元58年—约公元147年）是汉代有名的文字学家、语言学家，是中国文字学的开拓者。他的这部杰作成为后人阅读古籍，探讨古代文化，研究古文必不可少的桥梁和钥匙。", "“Shuōwén Jiězì” de zuòzhě Xǔ Shèn (yuē gōngyuán 58 nián — yuē gōngyuán 147 nián) shì Hàndài yǒumíng de wénzìxué jiā, yǔyánxué jiā, shì Zhōngguó wénzìxué de kāituòzhě. Tā de zhè bù jiézuò chéngwéi hòurén yuèdú gǔjí, tàntǎo gǔdài wénhuà, yánjiū gǔwén bì bùkě shǎo de qiáoliáng hé yàoshi.", "Tác giả của Thuyết Văn Giải Tự là Hứa Thận (khoảng năm 58 – khoảng năm 147 sau Công nguyên), là nhà văn tự học, nhà ngôn ngữ học nổi tiếng thời Hán, là người mở đường cho văn tự học Trung Quốc. Kiệt tác này của ông đã trở thành cầu nối và chìa khóa không thể thiếu cho người đời sau đọc sách cổ, tìm hiểu văn hóa cổ đại và nghiên cứu văn tự cổ."], ["", "《说文解字》，简称《说文》，是历史上第一部按照部首编排的汉语字典。原书作于公元100年到121年，现已失落，传至今日的大多是宋朝的版本，或是清朝的段玉裁注释本。全书共分540部首，收字9353个，另有异体字1163个，共10516字。", "“Shuōwén Jiězì”, jiǎnchēng “Shuōwén”, shì lìshǐ shàng dì-yī bù ànzhào bùshǒu biānpái de Hànyǔ zìdiǎn. Yuán shū zuò yú gōngyuán 100 nián dào 121 nián, xiàn yǐ shīluò, chuán zhì jīnrì de dàduō shì Sòngcháo de bǎnběn, huò shì Qīngcháo de Duàn Yùcái zhùshì běn. Quán shū gòng fēn 540 bùshǒu, shōu zì 9353 gè, lìng yǒu yìtǐzì 1163 gè, gòng 10516 zì.", "Thuyết Văn Giải Tự, gọi tắt là Thuyết Văn, là cuốn từ điển tiếng Hán đầu tiên trong lịch sử được sắp xếp theo bộ thủ. Nguyên bản được viết vào năm 100 đến 121 sau Công nguyên, nay đã thất truyền, phần lớn những bản truyền đến ngày nay là bản in đời Tống, hoặc bản chú giải của Đoàn Ngọc Tài đời Thanh. Toàn sách chia làm 540 bộ thủ, thu nhận 9353 chữ, ngoài ra có 1163 chữ dị thể, tổng cộng 10516 chữ."], ["", "《说文解字》总结了先秦、两汉的文学成果，给我们保存了汉字的形、音、义，是研究甲骨文、金文和古音等不可缺少的桥梁。特别是《说文》对字义的解释一般保存了最古的含义，对理解古书上的词义更有帮助。书中还有关于秦汉时期全国各地方言的介绍，这本书也成为了解中国古代方言的一本重要参考书籍。", "“Shuōwén Jiězì” zǒngjié le Xiānqín, Liǎng Hàn de wénxué chéngguǒ, gěi wǒmen bǎocún le Hànzì de xíng, yīn, yì, shì yánjiū jiǎgǔwén, jīnwén hé gǔyīn děng bùkě quēshǎo de qiáoliáng. Tèbié shì “Shuōwén” duì zìyì de jiěshì yìbān bǎocún le zuì gǔ de hányì, duì lǐjiě gǔshū shàng de cíyì gèng yǒu bāngzhù. Shū zhōng hái yǒu guānyú Qín-Hàn shíqī quánguó gè dì fāngyán de jièshào, zhè běn shū yě chéngwéi liǎojiě Zhōngguó gǔdài fāngyán de yì běn zhòngyào cānkǎo shūjí.", "Thuyết Văn Giải Tự đã tổng kết thành quả văn học thời Tiên Tần và Lưỡng Hán, bảo tồn cho chúng ta hình, âm, nghĩa của chữ Hán, là cầu nối không thể thiếu trong nghiên cứu giáp cốt văn, kim văn và cổ âm v.v... Đặc biệt, phần giải thích nghĩa chữ của Thuyết Văn thường bảo tồn được nghĩa cổ xưa nhất, rất hữu ích cho việc hiểu nghĩa từ trong sách cổ. Trong sách còn có giới thiệu về phương ngữ các vùng trên cả nước thời Tần – Hán, cuốn sách này cũng trở thành tài liệu tham khảo quan trọng để tìm hiểu phương ngữ cổ đại Trung Quốc."], ["", "除了语言学方面的价值，《说文解字》还保存了古代社会历史、文化等各方面的材料，是我们整理中国古代文化遗产的重要依据。《说文》中对字的各种含义的解释，反映了古代的政治、经济、文化、风俗习惯等等。如《说文》中这样解释“车”字：“车，舆轮之总名，夏后时奚仲所造”。根据《说文》的这个解释，可以肯定，在夏代已经有了“车”这种交通工具。又如我们从“姓”字是“女”字旁，以及“姜”、“姚”等“女”字旁的姓中，也可以观察到古代母系社会的一些生活情况。由此可见，《说文》反映了古代的一些社会历史情况，有助于我们了解古代丰富的文化，思考它的变化发展。", "Chúle yǔyánxué fāngmiàn de jiàzhí, “Shuōwén Jiězì” hái bǎocún le gǔdài shèhuì lìshǐ, wénhuà děng gè fāngmiàn de cáiliào, shì wǒmen zhěnglǐ Zhōngguó gǔdài wénhuà yíchǎn de zhòngyào yījù. “Shuōwén” zhōng duì zì de gè zhǒng hányì de jiěshì, fǎnyìng le gǔdài de zhèngzhì, jīngjì, wénhuà, fēngsú xíguàn děng děng. Rú “Shuōwén” zhōng zhèyàng jiěshì “chē” zì: “Chē, yú lún zhī zǒngmíng, Xià Hòu shí Xī Zhòng suǒ zào”. Gēnjù “Shuōwén” de zhège jiěshì, kěyǐ kěndìng, zài Xià dài yǐjīng yǒu le “chē” zhè zhǒng jiāotōng gōngjù. Yòu rú wǒmen cóng “xìng” zì shì “nǚ” zì páng, yǐjí “Jiāng”, “Yáo” děng “nǚ” zì páng de xìng zhōng, yě kěyǐ guānchá dào gǔdài mǔxì shèhuì de yìxiē shēnghuó qíngkuàng. Yóu cǐ kějiàn, “Shuōwén” fǎnyìng le gǔdài de yìxiē shèhuì lìshǐ qíngkuàng, yǒuzhù yú wǒmen liǎojiě gǔdài fēngfù de wénhuà, sīkǎo tā de biànhuà fāzhǎn.", "Ngoài giá trị về mặt ngôn ngữ học, Thuyết Văn Giải Tự còn bảo tồn các tư liệu về nhiều mặt như lịch sử xã hội, văn hóa thời cổ đại, là căn cứ quan trọng để chúng ta chỉnh lý di sản văn hóa cổ đại Trung Quốc. Phần giải thích các tầng nghĩa khác nhau của chữ trong Thuyết Văn phản ánh chính trị, kinh tế, văn hóa, phong tục tập quán thời cổ đại v.v... Ví dụ trong Thuyết Văn giải thích chữ “车” (xe) như sau: “Xe, là tên gọi chung của cỗ xe và bánh xe, do Hề Trọng thời nhà Hạ chế tạo”. Căn cứ vào giải thích này của Thuyết Văn, có thể khẳng định rằng thời nhà Hạ đã có phương tiện giao thông “xe”. Lại như từ chữ “姓” (họ) có bộ “女” (nữ), cùng với các họ như “姜”, “姚” cũng có bộ “女”, chúng ta cũng có thể quan sát được một số tình huống sinh hoạt của xã hội mẫu hệ cổ đại. Do đó có thể thấy, Thuyết Văn đã phản ánh một số tình hình lịch sử xã hội cổ đại, giúp ích cho chúng ta trong việc tìm hiểu văn hóa phong phú thời cổ đại và suy ngẫm về sự biến hóa phát triển của nó."]]}], "fn": [["“是……的” (shì... de) – cấu trúc nhấn mạnh", "", "Thuyết Văn Giải Tự là cuốn sách chữ đầu tiên của Trung Quốc phân tích có hệ thống hình dạng chữ Hán và khảo cứu nguồn gốc chữ. 是 + [đối tượng] + 的", "《说文解字》是中国第一部系统地分析汉字字形和考究字源的字书。"], ["“最有……” (zuì yǒu...) → Nhất / có... nhất", "", "Là tác phẩm có tính uy quyền nhất trong nghiên cứu văn tự học Trung Quốc suốt hai nghìn năm.", "是两千年来中国文字学研究最具权威性的著作。"], ["“成为……必不可少的……” (chéngwéi... bì bùkě shǎo de...)", "", "Trở thành... không thể thiếu... Trở thành cầu nối và chìa khóa không thể thiếu cho người đời sau đọc sách cổ, tìm hiểu văn hóa cổ đại và nghiên cứu văn tự cổ.", "成为后人阅读古籍，探讨古代文化，研究古文必不可少的桥梁和钥匙。"], ["“按照……” (ànzhào...) → Theo / căn cứ theo...", "", "Là cuốn từ điển tiếng Hán đầu tiên trong lịch sử được sắp xếp theo bộ thủ.", "是历史上第一部按照部首编排的汉语字典。"], ["“现已……” (xiàn yǐ...) → Hiện nay đã...", "", "Nguyên bản được viết từ năm 100 đến 121 sau CN, hiện đã thất truyền.", "原书作于公元100年到121年，现已失落。"], ["“或是……” (huò shì...) → Hoặc là...", "", "Phần lớn bản truyền đến nay là bản in đời Tống, hoặc bản chú giải của Đoàn Ngọc Tài đời Thanh.", "传至今日的大多是宋朝的版本，或是清朝的段玉裁注释本。"], ["“共……” (gòng...) → Tổng cộng...", "", "Toàn sách chia làm 540 bộ thủ, thu 9353 chữ, ngoài ra 1163 chữ dị thể, tổng cộng 10516 chữ.", "全书共分540部首，收字9353个，另有异体字1163个，共10516字。"], ["“特别是……” (tèbié shì...) → Đặc biệt là...", "", "Đặc biệt là phần giải thích nghĩa chữ của Thuyết Văn thường bảo tồn được nghĩa cổ xưa nhất.", "特别是《说文》对字义的解释一般保存了最古的含义。"]], "adv": [["形音义", "xíng yīn yì", "hình, âm, nghĩa (của chữ)"], ["甲骨文", "jiǎgǔwén", "văn tự giáp cốt (xương mai thú)"], ["金文", "jīnwén", "văn tự kim văn (trên đồ đồng)"], ["古音", "gǔyīn", "âm cổ"], ["含义", "hányì", "hàm nghĩa, ý nghĩa"], ["理解", "lǐjiě", "lý giải, hiểu"], ["词义", "cíyì", "nghĩa của từ"], ["秦汉", "Qín-Hàn", "thời Tần – Hán"], ["方言", "fāngyán", "phương ngữ, tiếng địa phương"], ["参考书籍", "cānkǎo shūjí", "sách tham khảo"], ["语言学", "yǔyánxué", "ngôn ngữ học"], ["价值", "jiàzhí", "giá trị"], ["材料", "cáiliào", "tài liệu, nguyên liệu"], ["整理", "zhěnglǐ", "chỉnh lý, sắp xếp"], ["文化遗产", "wénhuà yíchǎn", "di sản văn hóa"], ["依据", "yījù", "căn cứ"], ["反映", "fǎnyìng", "phản ánh"], ["政治", "zhèngzhì", "chính trị"], ["经济", "jīngjì", "kinh tế"], ["风俗习惯", "fēngsú xíguàn", "phong tục tập quán"], ["解释", "jiěshì", "giải thích"], ["舆轮", "yú lún", "xe và bánh xe (cỗ xe, bánh xe)"], ["总名", "zǒngmíng", "tên gọi chung"], ["夏后时", "Xià Hòu shí", "thời nhà Hạ (họ Hạ)"], ["奚仲", "Xī Zhòng", "Hề Trọng (nhân vật thời Hạ)"], ["根据", "gēnjù", "căn cứ vào"], ["肯定", "kěndìng", "khẳng định"], ["夏代", "Xià dài", "thời nhà Hạ"], ["交通工具", "jiāotōng gōngjù", "phương tiện giao thông"], ["姓", "xìng", "họ"], ["女字旁", "nǚ zì páng", "bộ nữ (nằm bên cạnh chữ)"], ["母系社会", "mǔxì shèhuì", "xã hội mẫu hệ"], ["观察", "guānchá", "quan sát"], ["由此可见", "yóu cǐ kějiàn", "do đó có thể thấy"], ["有助于", "yǒuzhù yú", "có ích cho, giúp ích cho"], ["丰富", "fēngfù", "phong phú"], ["思考", "sīkǎo", "suy nghĩ, suy ngẫm"], ["变化发展", "biànhuà fāzhǎn", "biến hóa phát triển"]], "ex2": [["《说文解字》是一部什么样的书？", "中国第一部系统分析汉字字形和字源的字书。", ["一本现代小说。", "一本英语词典。"]], ["《说文解字》的作者是谁？", "汉代的文字学家许慎。", ["唐代的李白。", "清代的段玉裁。"]], ["《说文解字》按照什么编排？收了多少字？", "按照540个部首编排，共10516字。", ["按照拼音编排，共3000字。", "按照笔画编排，共100字。"]], ["从《说文》对“车”字的解释可以知道什么？", "在夏代已经有了车这种交通工具。", ["汉代才有车。", "车是外国人发明的。"]]]}, "hk4-l8": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 9", "kw": [{"h": "课文 唐太宗纵囚", "lines": [["", "唐太宗李世民是中国历史上一位贤能的皇帝。公元633年的12月，唐太宗视察监狱，那里有390名被判处死刑的罪犯正在等待最后批准，准备执行死刑。唐太宗历来对死刑的判决非常慎重，因为这关乎人命。他规定死刑要审核三次，也就是向皇帝报告三次，后来因为错判过一个官员，他又把三次改成五次。现在这些关在监狱里的死刑犯，都是经过了五次审核，也就是真正犯有死罪的人。即使这样，唐太宗还是对他们进行最后的安慰。", "Táng Tàizōng Lǐ Shìmín shì Zhōngguó lìshǐ shàng yī wèi xiánnéng de huángdì. Gōngyuán 633 nián de 12 yuè, Táng Tàizōng shìchá jiānyù, nàlǐ yǒu 390 míng bèi pànchǔ sǐxíng de zuìfàn zhèngzài děngdài zuìhòu pīzhǔn, zhǔnbèi zhíxíng sǐxíng. Táng Tàizōng lìlái duì sǐxíng de pànjué fēicháng shènzhòng, yīnwèi zhè guānhu rénmìng. Tā guīdìng sǐxíng yào shěnhé sān cì, yě jiùshì xiàng huángdì bàogào sān cì, hòulái yīnwèi cuòpàn guò yī gè guānyuán, tā yòu bǎ sān cì gǎichéng wǔ cì. Xiànzài zhèxiē guān zài jiānyù lǐ de sǐxíngfàn, dōu shì jīngguòle wǔ cì shěnhé, yě jiùshì zhēnzhèng fàn yǒu sǐzuì de rén. Jíshǐ zhèyàng, Táng Tàizōng háishì duì tāmen jìnxíng zuìhòu de ānwèi.", "Đường Thái Tông Lý Thế Dân là một vị hoàng đế hiền năng trong lịch sử Trung Quốc. Tháng 12 năm 633 Công nguyên, Đường Thái Tông đi thị sát nhà ngục, ở đó có 390 phạm nhân bị kết án tử hình đang chờ phê chuẩn cuối cùng để chuẩn bị thi hành án. Đường Thái Tông xưa nay vốn rất thận trọng với các bản án tử hình, vì điều này liên quan đến tính mạng con người. Ông quy định án tử hình phải được thẩm tra ba lần, tức là báo cáo lên hoàng đế ba lần, sau này vì xử oan một vị quan, ông lại đổi ba lần thành năm lần. Những tử tù hiện đang bị giam trong ngục này đều đã trải qua năm lần thẩm tra, tức là những người thực sự phạm tội chết. Dù vậy, Đường Thái Tông vẫn tiến hành an ủi họ lần cuối."], ["", "唐太宗亲自问话时，死刑犯对判决都没有反对意见，但他们都表示，非常渴望能够回家最后看望一次亲人。唐太宗低头沉思了一会儿，作出了一个令人大吃一惊的决定：你们可以回家与亲人团聚，在亲情和关爱中度过人生中的最后一段时光，但必须遵守一个约定：第二年的九月初四必须返回监狱，接受死刑。", "Tángtàizōng qīnzì wènhuà shí, sǐxíngfàn duì pànjué dōu méiyǒu fǎnduì yìjiàn, dàn tāmen dōu biǎoshì, fēicháng kěwàng nénggòu huíjiā zuìhòu kànwàng yícì qīnrén. Tángtàizōng dītóu chénsī le yíhuìr, zuòchū le yíge lìngrén dàchīyìjīng de juédìng: Nǐmen kěyǐ huíjiā yǔ qīnrén tuánjù, zài qīnqíng hé guānài zhōng dùguò rénshēng zhōng de zuìhòu yíduàn shíguāng, dàn bìxū zūnshǒu yíge yuēdìng: Dìèrnián de jiǔyuèchū sì bìxū fǎnhuí jiānyù, jiēshòu sǐxíng.", "Đường Thái Tông đích thân hỏi chuyện, các tử tù đều không phản đối bản án, nhưng họ đều nói rất khao khát được về nhà gặp người thân lần cuối. Đường Thái Tông cúi đầu suy nghĩ một lúc, rồi đưa ra một quyết định khiến mọi người kinh ngạc: các ngươi được về nhà đoàn tụ với người thân, sống những ngày cuối đời trong tình thân và sự quan tâm, nhưng phải giữ một lời hẹn: mùng 4 tháng 9 năm sau phải quay lại nhà ngục chịu án tử."], ["", "罪犯们简直不敢相信自己的耳朵，他们都欢呼起来。官员们上前提醒唐太宗：“皇上，这些人都是死刑犯，到了约定的日子不回来怎么办？您要三思而后行啊！”唐太宗坚定地回答：“用诚心才能换忠心，我相信他们会对得起我的信任。”话虽这么说，可是所有人都将信将疑。", "Zuìfàn men jiǎnzhí bùgǎnxiāngxìn zìjǐ de ěrduǒ, tāmen dōu huānhū qǐlái. Guānyuán men shàngqián tíxǐng tángtàizōng: “Huángshàng, zhèxiē rén dōu shì sǐxíngfàn, dào le yuēdìng de rìzi bù huílái zěnmebàn? Nín yào sān sī ér hòu xíng a!” tángtàizōng jiāndìng dì huídá: “Yòng chéngxīn cáinéng huàn zhōngxīn, wǒ xiāngxìn tāmen huì duìdeqǐ wǒ de xìnrèn.” huà suī zhème shuō, kěshì suǒyǒurén dōu jiāngxìnjiāngyí.", "Các tội phạm đơn giản là không dám tin vào tai mình, họ đều hoan hô. Các quan viên tiến lên nhắc nhở Đường Thái Tông: \"Hoàng thượng, những người này đều là tử tù, đến ngày hẹn mà không quay lại thì làm thế nào? Người phải suy nghĩ kỹ rồi hãy làm ạ!\" Đường Thái Tông kiên định trả lời: \"Dùng lòng thành mới đổi được lòng trung, ta tin họ sẽ không phụ lòng tin của ta.\" Tuy nói vậy, nhưng mọi người đều bán tín bán nghi."], ["", "到了第二年（公元634年）九月初四这一天，四面八方的人都来到大理寺门口，因为这一天是唐太宗同390名死刑犯的死刑约定到期的日子，大家想看看那些罪犯们是否真的会履行约定，自动来送死。", "Dàole dì'èr nián (Gōngyuán 634 nián) jiǔyuè chūsì zhè yī tiān, sìmiànbāfāng de rén dōu lái dào Dàlǐsì ménkǒu, yīnwèi zhè yī tiān shì Táng Tàizōng tóng 390 míng sǐxíngfàn de sǐxíng yuēdìng dàoqī de rìzi, dàjiā xiǎng kànkan nàxiē zuìfànmen shìfǒu zhēn de huì lǚxíng yuēdìng, zìdòng lái sòngsǐ.", "Đến ngày mùng 4 tháng 9 năm thứ hai (năm 634 Công nguyên), người từ bốn phương tám hướng đều kéo đến trước cổng Đại Lý Tự, vì ngày này là ngày hết hạn giao ước tử hình giữa Đường Thái Tông và 390 tử tù, mọi người muốn xem những tội phạm đó có thực sự thực hiện giao ước, tự động đến chịu chết hay không."], ["", "令大家想不到的是，这一天死刑犯们真的一个接一个地回来了。约定的时间到了，数了一下人数，就差一个名叫徐福林的死刑犯还没到。大家的目光又都转向了唐太宗，这位年仅35岁的皇帝镇定地说：“再等等！”", "Lìng dàjiā xiǎngbudào de shì, zhè yī tiān sǐxíngfànmen zhēn de yī gè jiē yī gè de huílái le. Yuēdìng de shíjiān dào le, shǔle yīxià rénshù, jiù chà yī gè míng jiào Xú Fúlín de sǐxíngfàn hái méi dào. Dàjiā de mùguāng yòu dōu zhuǎnxiàngle Táng Tàizōng, zhè wèi nián jǐn 35 suì de huángdì zhèndìng de shuō: “Zài děngděng!”", "Điều khiến mọi người không ngờ là, ngày hôm đó các tử tù thực sự lần lượt quay trở về. Đến giờ hẹn, đếm số người, chỉ thiếu một tử tù tên là Từ Phúc Lâm chưa đến. Ánh mắt mọi người lại đổ dồn về phía Đường Thái Tông, vị hoàng đế chỉ mới 35 tuổi này bình tĩnh nói: \"Chờ thêm chút nữa!\""], ["", "这时，远远地传来了车轮的声音，一辆牛车急急地走过来，车上坐着的人正是徐福林。他有气无力，一脸病态。原来，他在返回京城的路上病倒了，只好雇了一辆牛车赶路，结果比约定的时间晚了一个小时。", "Zhèshí, yuǎnyuǎn de chuánláile chēlún de shēngyīn, yī liàng niúchē jíjí de zǒu guòlái, chē shàng zuòzhe de rén zhèngshì Xú Fúlín. Tā yǒuqìwúlì, yī liǎn bìngtài. Yuánlái, tā zài fǎnhuí jīngchéng de lùshang bìngdǎo le, zhǐhǎo gùle yī liàng niúchē gǎnlù, jiéguǒ bǐ yuēdìng de shíjiān wǎnle yī gè xiǎoshí.", "Lúc này, từ xa vọng lại tiếng bánh xe, một chiếc xe bò vội vã chạy tới, người ngồi trên xe chính là Từ Phúc Lâm. Ông ta yếu ớt không có sức lực, gương mặt đầy vẻ bệnh tật. Thì ra, trên đường trở về kinh thành ông ta bị ốm, đành phải thuê một chiếc xe bò để đi đường, kết quả là đến muộn hơn thời gian hẹn một tiếng đồng hồ."], ["", "唐太宗的脸上露出了欣慰的笑容。390名死刑犯能够遵守与唐太宗的死亡约定，他们的信用得到了最高的奖赏，他们全被赦免！没有人对此提出异议，因为用生命来守信诺言的人，应该得到这样的奖赏。", "Táng Tàizōng de liǎnshang lùchūle xīnwèi de xiàoróng. 390 míng sǐxíngfàn nénggòu zūnshǒu yǔ Táng Tàizōng de sǐwáng yuēdìng, tāmen de xìnyòng dédàole zuìgāo de jiǎngshǎng, tāmen quán bèi shèmiǎn! Méiyǒu rén duì cǐ tíchū yìyì, yīnwèi yòng shēngmìng lái shǒu xìn nuòyán de rén, yīnggāi dédào zhèyàng de jiǎngshǎng.", "Trên mặt Đường Thái Tông lộ ra nụ cười mãn nguyện. 390 tử tù có thể tuân thủ giao ước tử hình với Đường Thái Tông, chữ tín của họ đã nhận được phần thưởng cao nhất, họ đều được ân xá! Không ai phản đối điều này, vì những người dùng mạng sống để giữ lời hứa, nên nhận được phần thưởng như vậy."]]}], "fn": [["即使……还是…… (Jíshǐ... háishì...)", "", "Cho dù... vẫn... Dịch: Cho dù như vậy, Đường Thái Tông vẫn tiến hành an ủi họ lần cuối.", "即使这样，唐太宗还是对他们进行最后的安慰。"], ["令…… (Lìng...)", "", "Khiến cho... (thường dùng trong văn viết, mang tính trang trọng) Dịch: Điều khiến mọi người không ngờ là...", "令大家想不到的是..."], ["一个接一个 (Yī gè jiē yī gè)", "", "Lần lượt từng người một, nối tiếp nhau. Dịch: Các tử tù thực sự lần lượt từng người một quay trở về.", "死刑犯们真的一个接一个地回来了。"], ["是否 (Shìfǒu)", "", "Có phải... hay không (dùng để hỏi hoặc diễn tả sự nghi vấn trong câu trần thuật). Dịch: Mọi người muốn xem những tội phạm đó có thực sự thực hiện giao ước hay không.", "大家想看看那些罪犯们是否真的会履行约定。"], ["差……还没…… (Chà... hái méi...)", "", "Thiếu... vẫn chưa... Dịch: Chỉ thiếu một tử tù tên là Từ Phúc Lâm vẫn chưa đến.", "就差一个名叫徐福林的死刑犯还没到。"], ["用……来…… (Yòng... lái...)", "", "Dùng... để... Dịch: Những người dùng mạng sống để giữ lời hứa.", "用生命来守信诺言的人。"], ["因为…… (Yīnwèi...)", "", "Bởi vì... Dịch: Bởi vì những người dùng mạng sống để giữ lời hứa, nên nhận được phần thưởng như vậy.", "因为用生命来守信诺言的人，应该得到这样的奖赏。"], ["被 (Bèi) - Câu bị động", "", "Được/bị (chỉ hành động bị động). Dịch: Họ đều được ân xá!", "他们全被赦免！"]], "adv": [], "ex2": [["唐太宗为什么对死刑的判决非常慎重？", "因为这关乎人命，他规定死刑要审核五次。", ["因为他不喜欢工作。", "因为监狱太小了。"]], ["唐太宗作出了什么决定？", "让死刑犯回家与亲人团聚，第二年九月初四再回来。", ["马上执行死刑。", "把他们送到外国。"]], ["官员们对这个决定有什么看法？", "担心他们到时候不回来，劝皇上三思而后行。", ["都非常赞成。", "都想跟死刑犯一起回家。"]], ["徐福林为什么晚到了？", "他在路上病倒了，只好雇牛车赶路。", ["他逃跑了又回来。", "他忘了日子。"]], ["故事的结局是什么？", "390名死刑犯全被赦免了。", ["只有徐福林被赦免了。", "他们都被执行了死刑。"]]]}, "hk4-l9": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 9", "kw": [{"h": "课文 网络词语“囧”", "lines": [["", "“囧（jiǒng）”被众多网友称为“21世纪最牛的一个字”，在网络上的使用和传播速度极快、范围极大。究竟“囧”是什么意思，又源于何处？它在网上是如何迅速传播的？", "“Jiǒng” bèi zhòngduō wǎngyǒu chēng wéi “21 shìjì zuì niú de yī gè zì”, zài wǎngluò shàng de shǐyòng hé chuánbō sùdù jí kuài, fànwéi jí dà. Jiūjìng “jiǒng” shì shénme yìsi, yòu yuányú héchù? Tā zài wǎng shàng shì rúhé xùnsù chuánbō de?", "\"Quẫn\" (jiǒng) được đông đảo cư dân mạng gọi là \"chữ ngầu nhất thế kỷ 21\", tốc độ sử dụng và lan truyền trên mạng cực nhanh, phạm vi cực lớn. Rốt cuộc \"Quẫn\" có nghĩa là gì, và bắt nguồn từ đâu? Nó đã lan truyền nhanh chóng trên mạng như thế nào?"], ["", "“囧”在甲骨文中本有其字。据《古代汉语词典》解释，“囧”为象形字，外面的大方块表示房子，里面的小方块表示窗户，窗户可以照进阳光，所以本义为窗口光亮，引申为明亮、光明之义。在网络语言中，“囧”同样成了一个象形字，然而人们根据“囧”像一张表情沉重郁闷的人脸，而“囧”又与汉字“窘”发音相同，因此，用来表达一个人郁闷、窘迫的心理状态。", "“Jiǒng” zài jiǎgǔwén zhōng běn yǒu qí zì. Jù 《Gǔdài Hànyǔ Cídiǎn》 jiěshì, “jiǒng” wéi xiàngxíngzì, wàimiàn de dà fāngkuài biǎoshì fángzi, lǐmiàn de xiǎo fāngkuài biǎoshì chuānghu, chuānghu kěyǐ zhàojìn yángguāng, suǒyǐ běnyì wéi chuāngkǒu guāngliàng, yǐnshēn wéi míngliàng, guāngmíng zhī yì. Zài wǎngluò yǔyán zhōng, “jiǒng” tóngyàng chéngle yī gè xiàngxíngzì, rán'ér rénmen gēnjù “jiǒng” xiàng yī zhāng biǎoqíng chénzhòng yùmèn de rénliǎn, ér “jiǒng” yòu yǔ Hànzì “jiǒng” fāyīn xiāngtóng, yīncǐ, yòng lái biǎodá yī gè rén yùmèn, jiǒngpò de xīnlǐ zhuàngtài.", "\"Quẫn\" vốn có chữ này trong giáp cốt văn. Theo giải thích trong \"Từ điển Hán ngữ cổ đại\", \"Quẫn\" là chữ tượng hình, ô vuông lớn bên ngoài biểu thị ngôi nhà, ô vuông nhỏ bên trong biểu thị cửa sổ, cửa sổ có thể đón ánh sáng mặt trời chiếu vào, nên nghĩa gốc là cửa sổ sáng sủa, mở rộng ra thành nghĩa sáng sủa, quang minh. Trong ngôn ngữ mạng, \"Quẫn\" cũng trở thành một chữ tượng hình, tuy nhiên mọi người dựa vào việc \"Quẫn\" giống như một khuôn mặt người có biểu cảm nặng nề u uất, mà \"Quẫn\" lại có phát âm giống với chữ Hán \"Quẫn\" (窘 - khốn quẫn), vì thế, được dùng để biểu đạt trạng thái tâm lý u uất, khốn quẫn của một người."], ["", "网络语言之所以能很快为众多人所接受并迅速传播，正是由于其特征符合大众，特别是众多网民的需要和审美需求。“囧”也是如此。一个“囧”字，既有象形的图案，又有谐音的“窘”义，因此被网民迅速接受并使用。", "Wǎngluò yǔyán zhī suǒyǐ néng hěn kuài wéi zhòngduō rén suǒ jiēshòu bìng xùnsù chuánbō, zhèng shì yóuyú qí tèzhēng fúhé dàzhòng, tèbié shì zhòngduō wǎngmín de xūyào hé shěnměi xūqiú. “Jiǒng” yě shì rúcǐ. Yī gè “jiǒng” zì, jì yǒu xiàngxíng de tú'àn, yòu yǒu xiéyīn de “jiǒng” yì, yīncǐ bèi wǎngmín xùnsù jiēshòu bìng shǐyòng.", "Ngôn ngữ mạng có thể nhanh chóng được đông đảo mọi người tiếp nhận và lan truyền nhanh chóng, chính là do đặc trưng của nó phù hợp với nhu cầu và thẩm mỹ của đại chúng, đặc biệt là của đông đảo cư dân mạng. \"Quẫn\" cũng như vậy. Một chữ \"Quẫn\", vừa có hình vẽ tượng hình, lại vừa có nghĩa hài âm là \"quẫn\" (khốn quẫn), vì thế được cư dân mạng nhanh chóng tiếp nhận và sử dụng."], ["", "“囧”具有简洁实用的特点。在网络交际中，人们为了以快捷的方式交流，往往利用数字、汉字的谐音以及用单字来表达较复杂的意义。“囧”与“窘”谐音，仅一个字就可以表达哭笑不得、不得已、郁闷等多种意义，具有很强的实用性。", "“Jiǒng” jùyǒu jiǎnjié shíyòng de tèdiǎn. Zài wǎngluò jiāojì zhōng, rénmen wèile yǐ kuàijié de fāngshì jiāoliú, wǎngwǎng lìyòng shùzì, Hànzì de xiéyīn yǐjí yòng dānzì lái biǎodá jiào fùzá de yìyì. “Jiǒng” yǔ “jiǒng” xiéyīn, jǐn yī gè zì jiù kěyǐ biǎodá kūxiàobùdé, bùdéyǐ, yùmèn děng duō zhǒng yìyì, jùyǒu hěn qiáng de shíyòngxìng.", "\"Quẫn\" có đặc điểm đơn giản và thực dụng. Trong giao tiếp trên mạng, để giao lưu theo cách nhanh chóng, mọi người thường sử dụng chữ số, hài âm của chữ Hán và dùng một chữ đơn để biểu đạt ý nghĩa phức tạp hơn. \"Quẫn\" hài âm với \"quẫn\" (窘), chỉ một chữ đã có thể biểu đạt nhiều ý nghĩa như khóc cười không được, bất đắc dĩ, u uất, có tính thực dụng rất mạnh."], ["", "“囧”具有时尚风趣的特点。网民上网聊天，大多是为了减轻压力，发泄心中的烦恼，放松心情，而且他们大多是年轻人，因而时髦前卫的语言符合他们的审美需求。表示郁闷、哭笑不得的“囧”，在他们看来十分风趣。", "“Jiǒng” jùyǒu shíshàng fēngqù de tèdiǎn. Wǎngmín shàngwǎng liáotiān, dàduō shì wèile jiǎnqīng yālì, fāxiè xīnzhōng de fánnǎo, fàngsōng xīnqíng, érqiě tāmen dàduō shì niánqīngrén, yīn'ér shímáo qiánwèi de yǔyán fúhé tāmen de shěnměi xūqiú. Biǎoshì yùmèn, kūxiàobùdé de “jiǒng”, zài tāmen kànlái shífēn fēngqù.", "\"Quẫn\" có đặc điểm thời thượng và thú vị. Cư dân mạng lên mạng trò chuyện, phần lớn là để giảm bớt áp lực, giải tỏa nỗi phiền não trong lòng, thư giãn tâm trạng, hơn nữa họ phần lớn là người trẻ tuổi, do đó ngôn ngữ thời thượng tiên phong phù hợp với nhu cầu thẩm mỹ của họ. \"Quẫn\" biểu thị sự u uất, khóc cười không được, trong mắt họ vô cùng thú vị."], ["", "“囧”具有形象直观的特点，有利于更为直接地表达网民的意图。“囧”的“愁眉苦脸”的形象生动地展示了网友们的郁闷心情。", "“Jiǒng” jùyǒu xíngxiàng zhíguān de tèdiǎn, yǒulì yú gèng wéi zhíjiē de biǎodá wǎngmín de yìtú. “Jiǒng” de “chóuméikǔliǎn” de xíngxiàng shēngdòng de zhǎnshìle wǎngyǒumen de yùmèn xīnqíng.", "\"Quẫn\" có đặc điểm hình tượng trực quan, có lợi cho việc biểu đạt ý đồ của cư dân mạng một cách trực tiếp hơn. Hình tượng \"mặt mày ủ dột\" của \"Quẫn\" đã sinh động thể hiện tâm trạng u uất của các bạn cư dân mạng."], ["", "但是，我认为“囧”这类网络语言中的古代汉字还是越少越好，而且应限于在网络中使用，不要扩大到其他媒体。如果随便改变古代汉字的意义，那么可能有一天会影响到对古代的语言、古代的文化理解。以古求新的网络语言应当适可而止。", "Dànshì, wǒ rènwéi “jiǒng” zhè lèi wǎngluò yǔyán zhōng de gǔdài Hànzì háishì yuè shǎo yuè hǎo, érqiě yīng xiànyú zài wǎngluò zhōng shǐyòng, bùyào kuòdà dào qítā méitǐ. Rúguǒ suíbiàn gǎibiàn gǔdài Hànzì de yìyì, nàme kěnéng yǒu yī tiān huì yǐngxiǎng dào duì gǔdài de yǔyán, gǔdài de wénhuà lǐjiě. Yǐ gǔ qiú xīn de wǎngluò yǔyán yīngdāng shìkě'érzhǐ.", "Nhưng, tôi cho rằng những chữ Hán cổ trong ngôn ngữ mạng như \"Quẫn\" càng ít càng tốt, hơn nữa nên hạn chế sử dụng trong mạng, không nên mở rộng sang các phương tiện truyền thông khác. Nếu tùy tiện thay đổi ý nghĩa của chữ Hán cổ, thì có thể một ngày nào đó sẽ ảnh hưởng đến việc hiểu biết về ngôn ngữ cổ, văn hóa cổ. Ngôn ngữ mạng \"dùng cái cũ để tìm cái mới\" nên dừng lại đúng lúc."]]}], "fn": [["被……称为…… (Bèi... chēng wéi...)", "", "Được... gọi là... Dịch: \"Quẫn\" được đông đảo cư dân mạng gọi là \"chữ ngầu nhất thế kỷ 21\".", "“囧（jiǒng）”被众多网友称为“21世纪最牛的一个字”。"], ["究竟…… (Jiūjìng...)", "", "Rốt cuộc... (dùng để nhấn mạnh câu hỏi hoặc sự tò mò). Dịch: Rốt cuộc \"Quẫn\" có nghĩa là gì, và bắt nguồn từ đâu?", "究竟“囧”是什么意思，又源于何处？"], ["据……解释 (Jù... jiěshì)", "", "Theo... giải thích. Dịch: Theo giải thích trong \"Từ điển Hán ngữ cổ đại\"...", "据《古代汉语词典》解释..."], ["之所以……正是由于…… (Zhī suǒyǐ... zhèng shì yóuyú...)", "", "Sở dĩ... chính là do... Dịch: Ngôn ngữ mạng sở dĩ có thể nhanh chóng được đông đảo mọi người tiếp nhận và lan truyền nhanh chóng, chính là do đặc trưng của nó phù hợp với đại chúng...", "网络语言之所以能很快为众多人所接受并迅速传播，正是由于其特征符合大众..."], ["为……所…… (Wéi... suǒ...)", "", "Được/bị... (cấu trúc bị động trong văn viết). Dịch: Được đông đảo mọi người tiếp nhận.", "为众多人所接受。"], ["为了…… (Wèile...)", "", "Để... (chỉ mục đích). Dịch: Mọi người để giao lưu theo cách nhanh chóng...", "人们为了以快捷的方式交流..."], ["往往…… (Wǎngwǎng...)", "", "Thường thường... (chỉ quy luật hoặc thói quen). Dịch: Thường thường sử dụng chữ số, hài âm của chữ Hán...", "往往利用数字、汉字的谐音..."], ["仅……就…… (Jǐn... jiù...)", "", "Chỉ cần... là đã... Dịch: Chỉ một chữ đã có thể biểu đạt nhiều ý nghĩa như dở khóc dở cười, bất đắc dĩ, u uất.", "仅一个字就可以表达哭笑不得、不得已、郁闷等多种意义。"]], "adv": [], "ex2": [["“囧”的本义是什么？", "窗口光亮，引申为明亮、光明。", ["一个人在哭。", "一张桌子。"]], ["在网络语言中，“囧”表示什么？", "一个人郁闷、窘迫的心理状态。", ["非常高兴。", "很有钱。"]], ["“囧”为什么能很快被网民接受？", "既有象形的图案，又有谐音“窘”的意思。", ["因为政府要求使用。", "因为它笔画很多。"]], ["网民上网聊天大多是为了什么？", "减轻压力，发泄烦恼，放松心情。", ["学习古代汉语。", "找工作。"]], ["作者对“囧”这类网络语言有什么看法？", "越少越好，应限于网络中使用，适可而止。", ["应该写进所有的课本。", "越多越好。"]]]}, "hk4-l10": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 12", "kw": [{"h": "课文 谈谦虚", "lines": [["", "“满招损，谦受益”，这本来是中国一句老话，一直到了今天，还经常挂在人们嘴上。可见此话道出了一个真理，经过近三千年的检验，也说明它是可靠的。这句话适用于干一切工作的人，特别是做学问的人。", "“Mǎn zhāo sǔn, qiān shòu yì”, zhè běnlái shì Zhōngguó yī jù lǎohuà, yīzhí dào le jīntiān, hái jīngcháng guà zài rénmen zuǐ shàng. Kějiàn cǐ huà dào chū le yī gè zhēnlǐ, jīngguò jìn sānqiān nián de jiǎnyàn, yě shuōmíng tā shì kěkào de. Zhè jù huà shìyòng yú gàn yīqiè gōngzuò de rén, tèbié shì zuò xuéwèn de rén.", "“Khiêm tốn thì được lợi, kiêu ngạo thì chịu tổn hại”, đây vốn là một câu nói cổ của Trung Quốc, cho đến tận ngày nay vẫn thường được mọi người nhắc đến. Có thể thấy câu nói này đã nói lên một chân lý, trải qua gần ba ngàn năm kiểm nghiệm, cũng chứng minh nó là đáng tin cậy. Câu nói này áp dụng cho tất cả những người làm bất kỳ công việc gì, đặc biệt là những người làm học vấn."], ["", "根据我自己的思考与分析，谦虚有两种，一真一假。假谦虚的例子，真可以说是俯拾即是。中国人称自己的著作为拙作，自己的观点为愚见，这类谦虚的词，谁都知道是客气话，然而这种客气话不是真正的谦虚，也不会使任何人受益。", "Gēnjù wǒ zìjǐ de sīkǎo yǔ fēnxī, qiānxū yǒu liǎng zhǒng, yī zhēn yī jiǎ. Jiǎ qiānxū de lìzi, zhēn kěyǐ shuō shì fǔshíjíshì. Zhōngguó rén chēng zìjǐ de zhùzuò wéi zhuōzuò (zhuōzuò), zìjǐ de guāndiǎn wéi yújiàn (yújiàn), zhè lèi qiānxū de cí, shuí dōu zhīdào shì kèqì huà, rán'ér zhè zhǒng kèqì huà bùshì zhēnzhèng de qiānxū, yě bù huì shǐ rènhé rén shòuyì.", "Theo suy nghĩ và phân tích của bản thân tôi, khiêm tốn có hai loại, một thật một giả. Những ví dụ về khiêm tốn giả, thật có thể nói là “cúi xuống là nhặt được” (nhan nhản khắp nơi). Người Trung Quốc gọi tác phẩm của mình là “chuyết tác” (tác phẩm vụng về), quan điểm của mình là “ngu kiến” (ý kiến ngu dốt), những từ khiêm tốn như thế này, ai cũng biết là lời khách sáo, nhưng loại lời khách sáo này không phải là sự khiêm tốn thực sự, cũng sẽ không khiến bất kỳ ai được lợi."], ["", "我们要的是真正的谦虚，做学问更是如此。如果一个学者，不管是年轻的，还是中年的、老年的，觉得自己的学问已经够大了，没有必要再进行学习了，他就不会再进步。事实上，不管你搞哪一门学问，绝不会有搞得完全彻底一点问题也不留的。人即使能活上1000年，也是办不到的。因此，在做学问上谦虚，不但表示这个人有道德，也表示这个人是实事求是的。", "Wǒmen yào de shì zhēnzhèng de qiānxū, zuò xuéwèn gèng shì rúcǐ. Rúguǒ yī gè xuézhě, bùguǎn shì niánqīng de, háishì zhōngnián de, lǎonián de, juéde zìjǐ de xuéwèn yǐjīng gòu dà le, méiyǒu bìyào zài jìnxíng xuéxí le, tā jiù bù huì zài jìnbù. Shìshí shàng, bùguǎn nǐ gǎo nǎ yī mén xuéwèn, jué bù huì yǒu gǎo de wánquán chèdǐ yīdiǎn wèntí yě bù liú de. Rén jíshǐ néng huó shàng 1000 nián, yě shì bàn bù dào de. Yīncǐ, zài zuò xuéwèn shàng qiānxū, bùdàn biǎoshì zhège rén yǒu dàodé, yě biǎoshì zhège rén shì shìqiúshìshì de.", "Chúng ta cần là sự khiêm tốn thực sự, làm học vấn lại càng như vậy. Nếu một học giả, bất kể là trẻ tuổi, hay trung niên, hay già, cảm thấy học vấn của mình đã đủ lớn rồi, không cần thiết phải tiếp tục học nữa, thì anh ta sẽ không tiến bộ được nữa. Trên thực tế, bất kể bạn nghiên cứu môn học nào, tuyệt đối không thể có chuyện nghiên cứu triệt để hoàn toàn mà không để lại một vấn đề nào. Con người cho dù có thể sống đến 1000 năm, cũng không làm được điều đó. Vì vậy, khiêm tốn trong việc làm học vấn, không chỉ biểu thị người này có đạo đức, mà còn biểu thị người này là người thực sự cầu thị."], ["", "听说康有为说过，他年届三十，就把天下学问学完了。仅仅从这件事情上，就可以证明，康有为并不懂得什么叫做学问。现在有人称他为“国学大师”，我认为是可笑的。他至多只能算是一个革新家。在当今中国学术界，自认为了不起的人，到处都能看到；而真正虚怀若谷的人，却非常少见。有不少年轻的学者，写过几篇论文，出过几册专著，就傲气十足。这种态度不利于他们自己的进步，也不利于中国学术的发展。", "Tīngshuō Kāng Yǒuwéi shuōguò, tā niánjiè (jiè) sānshí, jiù bǎ tiānxià xuéwèn xué wán le. Jǐnjǐn cóng zhè jiàn shìqíng shàng, jiù kěyǐ zhèngmíng, Kāng Yǒuwéi bìng bù dǒngdé shénme jiào zuò xuéwèn. Xiànzài yǒu rén chēng tā wéi “guóxué dàshī”, wǒ rènwéi shì kěxiào de. Tā zhìduō zhǐnéng suàn shì yī gè géxīnjiā. Zài dāngjīn Zhōngguó xuéshùjiè, zì rènwéi liǎobùqǐ de rén, dàochù dōu néng kàndào; ér zhēnzhèng xūhuáiruògǔ de rén, què fēicháng shǎojiàn. Yǒu bùshǎo niánqīng de xuézhě, xiěguò jǐ piān lùnwén, chūguò jǐ cè zhuānzhù, jiù àoqì (àoqì) shízú. Zhè zhǒng tàidù bù lìyú tāmen zìjǐ de jìnbù, yě bù lìyú Zhōngguó xuéshù de fāzhǎn.", "Nghe nói Khang Hữu Vi đã từng nói, ông ta khi tuổi đời mới ba mươi, đã học hết học vấn thiên hạ rồi. Chỉ riêng từ sự việc này, đã có thể chứng minh, Khang Hữu Vi hoàn toàn không hiểu thế nào gọi là học vấn. Hiện nay có người gọi ông ta là “Quốc học đại sư”, tôi cho rằng thật là nực cười. Ông ta cùng lắm chỉ có thể được coi là một nhà cách tân. Trong giới học thuật Trung Quốc ngày nay, những người tự cho mình là ghê gớm, đâu đâu cũng có thể thấy; nhưng những người thực sự khiêm tốn (lòng rỗng như thung lũng) thì lại vô cùng hiếm thấy. Có không ít học giả trẻ tuổi, viết được vài bài luận văn, xuất bản được vài cuốn chuyên khảo, là đã kiêu ngạo đầy mình. Thái độ này không có lợi cho sự tiến bộ của bản thân họ, cũng không có lợi cho sự phát triển của học thuật Trung Quốc."], ["", "我自己怎样呢？我总觉得自己不行。我常常讲，我是样样通，样样松。我一生勤奋学习，天天都在读书写文章，但一遇到一个必须深入钻研的问题，就会觉得自己知识不够。一个人要有自知之明很难，我却觉得，自己有时谦虚得过了头，简直不是谦虚，而是心虚了。自己谦虚可以说是一个好现象，但是我心里又有极大的矛盾：我看待别人也有很高的标准，我觉得真正行的人非常少。我觉得好多人学不够勤奋，有的人天天虚度光阴。我经常处在这种心理矛盾中。别人对我的赞誉，我非常感激；但是我要劝大家，不要全信那些赞誉。有人要给我安上“国学大师”等头衔，那些高得惊人的帽子，我更是受之有愧。", "Wǒ zìjǐ zěnyàng ne? Wǒ zǒng juéde zìjǐ bùxíng. Wǒ chángcháng jiǎng, wǒ shì yàngyàng tōng, yàngyàng sōng. Wǒ yīshēng qínfèn xuéxí, tiāntiān dōu zài dúshū xiě wénzhāng, dàn yī yùdào yī gè bìxū shēnrù zuānyán de wèntí, jiù huì juéde zìjǐ zhīshì bùgòu. Yī gè rén yào yǒu zìzhīzhīmíng hěn nán, wǒ què juéde, zìjǐ yǒushí qiānxū de guò le tóu, jiǎnzhí bùshì qiānxū, ér shì xīnxū le. Zìjǐ qiānxū kěyǐ shuō shì yī gè hǎo xiànxiàng, dànshì wǒ xīnlǐ yòu yǒu jídà de máodùn: wǒ kàndài biérén yě yǒu hěn gāo de biāozhǔn, wǒ juéde zhēnzhèng xíng de rén fēicháng shǎo. Wǒ juéde hǎo duō rén xué bù gòu qínfèn, yǒu de rén tiāntiān xūdù guāngyīn. Wǒ jīngcháng chǔ zài zhè zhǒng xīnlǐ máodùn zhōng. Biérén duì wǒ de zànyù, wǒ fēicháng gǎnjī; dànshì wǒ yào quàn dàjiā, bùyào quán xìn nàxiē zànyù. Yǒu rén yào gěi wǒ ān shàng “guóxué dàshī” děng tóuxián, nàxiē gāo de jīngrén de màozi, wǒ gèng shì shòuzhīyǒukuì.", "Bản thân tôi thì thế nào? Tôi luôn cảm thấy mình không giỏi. Tôi thường nói, tôi là “môn nào cũng biết, môn nào cũng lỏng”. Cả đời tôi chăm chỉ học tập, ngày ngày đều đọc sách viết văn, nhưng hễ gặp phải một vấn đề cần phải nghiên cứu sâu, là lại cảm thấy kiến thức của mình không đủ. Một người có được sự tự biết mình là rất khó, nhưng tôi lại cảm thấy, đôi khi mình khiêm tốn quá mức, đơn giản không phải là khiêm tốn, mà là tự ti (chột dạ). Bản thân khiêm tốn có thể nói là một hiện tượng tốt, nhưng trong lòng tôi lại có mâu thuẫn cực lớn: Tôi nhìn nhận người khác cũng có tiêu chuẩn rất cao, tôi cảm thấy người thực sự giỏi rất ít. Tôi cảm thấy nhiều người học không đủ chăm chỉ, có người ngày ngày sống vô ích. Tôi thường xuyên ở trong trạng thái mâu thuẫn tâm lý này. Người khác khen ngợi tôi, tôi vô cùng biết ơn; nhưng tôi muốn khuyên mọi người, đừng tin hoàn toàn những lời khen ngợi đó. Có người muốn gán cho tôi danh hiệu “Quốc học đại sư” v.v., những chiếc mũ cao đến kinh người đó, tôi lại càng cảm thấy hổ thẹn khi nhận được."]]}], "fn": [["一真一假 (yī zhēn yī jiǎ)", "", "一 + A + 一 + B Biểu thị hai sự vật/tính chất đối lập nhau, tương ứng với “một... một...”, “vừa... vừa...”.", "谦虚有两种，一真一假。"], ["不管...还是... (bùguǎn... háishì...)", "", "不管 + [các lựa chọn] + 都/也... “Bất kể là... hay là...”, dùng để chỉ sự lựa chọn không ảnh hưởng đến kết quả.", "如果一个学者，不管是年轻的，还是中年的、老年的..."], ["即使...也... (jíshǐ... yě...)", "", "即使 + [giả thiết] + 也 + [kết quả] “Cho dù... cũng...”, biểu thị sự nhượng bộ.", "人即使能活上1000年，也是办不到的。"], ["不但...也... (bùdàn... yě...)", "", "不但 + A + 也 + B “Không những... mà còn...”, biểu thị quan hệ tiến thêm một bước.", "不但表示这个人有道德，也表示这个人是实事求是的。"], ["一...就... (yī... jiù...)", "", "一 + [hành động/điều kiện] + 就 + [kết quả] “Hễ... là...”, “vừa... là...”, biểu thị kết quả xảy ra ngay sau điều kiện.", "一遇到一个必须深入钻研的问题，就会觉得自己知识不够。"], ["简直 (jiǎnzhí)", "", "“Đơn giản là”, “quả thực là”, dùng để nhấn mạnh mức độ, thường mang ý nghĩa hơi cường điệu.", "简直不是谦虚，而是心虚了。"], ["受之有愧 (shòuzhīyǒukuì)", "", "Đây là một thành ngữ, có nghĩa là “nhận được mà cảm thấy hổ thẹn”, thường dùng để nói khiêm tốn khi nhận được lời khen hoặc danh hiệu.", "那些高得惊人的帽子，我更是受之有愧。"]], "adv": [], "ex2": [["“满招损，谦受益”经过多长时间的检验？", "近三千年。", ["三十年。", "三百年。"]], ["作者认为什么是假谦虚？", "把自己的著作叫“拙作”这类客气话。", ["认真向别人学习。", "承认自己知识不够。"]], ["为什么做学问要谦虚？", "学问永远学不完，觉得自己够了就不会进步。", ["因为谦虚可以得到奖金。", "因为老师要求。"]], ["作者怎么看康有为？", "他不懂什么叫做学问，至多是一个革新家。", ["他是真正的国学大师。", "他是最谦虚的学者。"]], ["作者心里有什么矛盾？", "自己很谦虚，但看待别人的标准也很高。", ["他想当国学大师，又不想学习。", "他不喜欢读书。"]]]}, "hk4-l11": {"page": "—", "src": "汉语阅读教程 · Đọc-Viết 4 · Bài 12", "kw": [{"h": "课文 《世界上最疼我的那个人去了》赏析", "lines": [["", "电影《世界上最疼我的那个人去了》根据同名小说改编，电影的剧情很简单，讲述的是一位女作家在老母亲生重病后，与母亲相处的最后一段日子中所发生的事情。这个简单的故事所展现出来的人物的内心活动，则令人回味，也是需要观众慢慢去领悟的。", "Diànyǐng 《Shìjiè shàng zuì téng wǒ de nàge rén qù le》 gēnjù tóngmíng xiǎoshuō gǎibiān, diànyǐng de jùqíng hěn jiǎndān, jiǎngshù de shì yī wèi nǚ zuòjiā zài lǎo mǔqīn shēng zhòngbìng hòu, yǔ mǔqīn xiāngchǔ de zuìhòu yī duàn rìzi zhōng suǒ fāshēng de shìqíng. Zhège jiǎndān de gùshì suǒ zhǎnxiàn chūlái de rénwù de nèixīn huódòng, zé lìng rén huíwèi, yě shì xūyào guānzhòng mànmàn qù lǐngwù de.", "Bộ phim \"Người thương tôi nhất trên thế gian đã ra đi\" được chuyển thể từ tiểu thuyết cùng tên, cốt truyện của phim rất đơn giản, kể về những sự việc xảy ra trong khoảng thời gian cuối cùng mà một nữ nhà văn sống cùng mẹ sau khi mẹ già bị bệnh nặng. Những hoạt động nội tâm của nhân vật được thể hiện qua câu chuyện đơn giản này khiến người ta phải suy ngẫm, và cũng cần khán giả từ từ lĩnh hội."], ["", "在作品中表现这样一段由母女二人构成的情感故事既容易，又困难。容易的是每个人都有母亲，演员的表演很容易引起观众的共鸣，然而，也正因为母女、母子之情是每个人都有切身体会的情感，如果表演分寸把握不好，效果会适得其反。", "Zài zuòpǐn zhōng biǎoxiàn zhèyàng yī duàn yóu mǔ nǚ èr rén gòuchéng de qínggǎn gùshì jì róngyì, yòu kùnnán. Róngyì de shì měi gè rén dōu yǒu mǔqīn, yǎnyuán de biǎoyǎn hěn róngyì yǐnqǐ guānzhòng de gòngmíng, rán'ér, yě zhèng yīnwèi mǔ nǚ, mǔ zǐ zhī qíng shì měi gè rén dōu yǒu qiètǐ huì de qínggǎn, rúguǒ biǎoyǎn fēncùn bǎwò bù hǎo, xiàoguǒ huì shìdéqífǎn.", "Việc thể hiện một câu chuyện tình cảm được tạo nên bởi hai mẹ con như thế này trong tác phẩm vừa dễ lại vừa khó. Cái dễ là vì mỗi người đều có mẹ, diễn xuất của diễn viên rất dễ gây được sự đồng cảm nơi khán giả, tuy nhiên, cũng chính vì tình mẫu tử, tình mẹ con là thứ tình cảm mà mỗi người đều có sự thấu hiểu sâu sắc, nếu không nắm bắt tốt mức độ diễn xuất, hiệu quả sẽ đi ngược lại mong muốn."], ["", "剧中的作家就像一面镜子。从她身上我们既看到自己对父母的爱，又清晰地照见自己的自私。在母亲生病的时候，许多人会像那位作家那样尽全力照顾母亲，希望母亲快点儿恢复健康，但内心更真实的愿望是尽快回到正常生活秩序中去。没有多少人会意识到最辛苦的是生病的母亲，每个人都一相情愿地认为来日方长，而手头的工作和自己读书的孩子似乎都比养育了自己的母亲更重要。", "Jù zhōng de zuòjiā jiù xiàng yī miàn jìngzi. Cóng tā shēnshang wǒmen jì kàndào zìjǐ duì fùmǔ de ài, yòu qīngxī de zhào jiàn zìjǐ de zìsī. Zài mǔqīn shēngbìng de shíhòu, xǔduō rén huì xiàng nà wèi zuòjiā nàyàng jìn quánlì zhàogù mǔqīn, xīwàng mǔqīn kuài diǎnr huīfù jiànkāng, dàn nèixīn gèng zhēnshí de yuànwàng shì jǐnkuài huídào zhèngcháng shēnghuó zhìxù zhōng qù. Méiyǒu duōshǎo rén huì yìshí dào zuì xīnkǔ de shì shēngbìng de mǔqīn, měi gè rén dōu yīxiāngqíngyuàn de rènwéi láirìfāngcháng, ér shǒutóu de gōngzuò hé zìjǐ dúshū de háizi sìhū dōu bǐ yǎngyù le zìjǐ de mǔqīn gèng zhòngyào.", "Nhà văn trong phim giống như một tấm gương. Từ cô ấy, chúng ta vừa nhìn thấy tình yêu của mình dành cho cha mẹ, lại vừa soi rõ được sự ích kỷ của bản thân. Khi mẹ bị bệnh, nhiều người sẽ giống như nhà văn đó, dốc hết sức chăm sóc mẹ, mong mẹ nhanh chóng hồi phục sức khỏe, nhưng mong muốn thực sự hơn trong lòng là sớm quay trở lại trật tự cuộc sống bình thường. Không có nhiều người ý thức được rằng người vất vả nhất chính là người mẹ bị bệnh, mỗi người đều tự cho mình là đúng mà nghĩ rằng ngày tháng còn dài, còn công việc trước mắt và đứa con đang đi học của mình dường như đều quan trọng hơn người mẹ đã nuôi nấng mình."], ["", "演员的出色表演令人感动，尤其是母亲的扮演者黄素影，她将一位经历了人生的风风雨雨、但仍坚强地面对生活的母亲表现得亲切感人。剧中的母亲始终担心给女儿添麻烦，自然而然地将自己的需求放在第二位。母亲一生中曾经受过苦难，有过感伤，而这一切都被她的平和、幽默所悄悄掩盖。", "Yǎnyuán de chūsè biǎoyǎn lìng rén gǎndòng, yóuqí shì mǔqīn de bànyǎnzhě Huáng Sùyǐng, tā jiāng yī wèi jīnglì le rénshēng de fēngfēngyǔyǔ, dàn réng jiānqiáng de miànduì shēnghuó de mǔqīn biǎoxiàn de qīnqiè gǎnrén. Jù zhōng de mǔqīn shǐzhōng dānxīn gěi nǚ'ér tiān máfan, zìrán'érrán de jiāng zìjǐ de xūqiú fàng zài dì èr wèi. Mǔqīn yīshēng zhōng céngjīng shòuguò kǔnàn, yǒuguò gǎnshāng, ér zhè yīqiè dōu bèi tā de pínghé, yōumò suǒ qiāoqiāo yǎngài.", "Diễn xuất xuất sắc của diễn viên khiến người ta cảm động, đặc biệt là người đóng vai mẹ - Hoàng Tố Ảnh, bà đã thể hiện một người mẹ đã trải qua những sóng gió của cuộc đời, nhưng vẫn kiên cường đối mặt với cuộc sống một cách vô cùng thân thiết và cảm động. Người mẹ trong phim luôn lo lắng làm phiền con gái, một cách tự nhiên đặt nhu cầu của bản thân xuống vị trí thứ hai. Cả đời người mẹ từng chịu đựng gian khổ, từng có những nỗi buồn, nhưng tất cả những điều đó đều được sự bình thản và hài hước của bà lặng lẽ che giấu đi."], ["", "整部影片的感情饱满，但很自然，许多地方导演加以控制，将情感表现得恰到好处。观众在被人物深深打动之后，会很自然地反思自己和亲人的关系，考虑生活中最重要的是什么。这也许正是导演真正的意图，她希望传达给观众一个简单而又重要的道理：亲情、友情是最珍贵的。", "Zhěng bù yǐngpiàn de gǎnqíng bǎomǎn, dàn hěn zìrán, xǔduō dìfāng dǎoyǎn jiāyǐ kòngzhì, jiāng qínggǎn biǎoxiàn de qiàdàohǎochù. Guānzhòng zài bèi rénwù shēnshēn dǎdòng zhīhòu, huì hěn zìrán de fǎnsī zìjǐ hé qīnrén de guānxì, kǎolǜ shēnghuó zhōng zuì zhòngyào de shì shénme. Zhè yěxǔ zhèng shì dǎoyǎn zhēnzhèng de yìtú, tā xīwàng chuándá gěi guānzhòng yī gè jiǎndān ér yòu zhòngyào de dàolǐ: qīnqíng, yǒuqíng shì zuì zhēnguì de.", "Tình cảm trong toàn bộ bộ phim rất đầy đặn, nhưng rất tự nhiên, nhiều chỗ đạo diễn đã kiểm soát, thể hiện tình cảm một cách vừa vặn. Sau khi bị nhân vật lay động sâu sắc, khán giả sẽ rất tự nhiên suy ngẫm về mối quan hệ giữa bản thân và người thân, cân nhắc xem điều quan trọng nhất trong cuộc sống là gì. Đây có lẽ chính là ý đồ thực sự của đạo diễn, cô ấy hy vọng truyền đạt đến khán giả một đạo lý đơn giản mà quan trọng: Tình thân, tình bạn là quý giá nhất."], ["", "本片虽然是导演的处女作，从导演的表达方式来看，她没有许多年轻导演所常有的自我中心意识，她只是以朴素的手法展开故事，展示人物命运。观众能够对剧中人物内心的痛苦感同身受，这样的感受来自于这部电影的创作者的诚意，而这种诚意正是艺术作品的核心。", "Běn piàn suīrán shì dǎoyǎn de chùnǚzuò, cóng dǎoyǎn de biǎodá fāngshì lái kàn, tā méiyǒu xǔduō niánqīng dǎoyǎn suǒ cháng yǒu de zìwǒ zhōngxīn yìshí, tā zhǐshì yǐ pǔsù de shǒufǎ zhǎnkāi gùshì, zhǎnshì rénwù mìngyùn. Guānzhòng nénggòu duì jù zhōng rénwù nèixīn de tòngkǔ gǎntóngshēnshòu, zhèyàng de gǎnshòu láizì yú zhè bù diànyǐng de chuàngzuòzhě de chéngyì, ér zhè zhǒng chéngyì zhèng shì yìshù zuòpǐn de héxīn.", "Bộ phim này tuy là tác phẩm đầu tay của đạo diễn, nhưng từ cách thể hiện của đạo diễn mà nói, cô ấy không có ý thức lấy bản thân làm trung tâm thường thấy ở nhiều đạo diễn trẻ, cô ấy chỉ dùng thủ pháp mộc mạc để triển khai câu chuyện,展示 số phận nhân vật. Khán giả có thể đồng cảm sâu sắc với nỗi đau trong lòng nhân vật trong phim, cảm giác như vậy đến từ sự chân thành của những người sáng tạo ra bộ phim này, và sự chân thành này chính là cốt lõi của tác phẩm nghệ thuật."]]}], "fn": [["既...又... (jì... yòu...)", "", "既 + A + 又 + B “Vừa... lại vừa...”, biểu thị hai tính chất cùng tồn tại.", "表现这样一段由母女二人构成的情感故事既容易，又困难。"], ["如果...会... (rúguǒ... huì...)", "", "如果 + [điều kiện] + 会 + [kết quả] “Nếu... thì sẽ...”, biểu thị điều kiện giả định.", "如果表演分寸把握不好，效果会适得其反。"], ["从...身上 (cóng... shēnshang)", "", "从 + [người/vật] + 身上 “Từ (nơi) ai đó”, “ở nơi ai đó”.", "从她身上我们既看到自己对父母的爱..."], ["被...所... (bèi... suǒ...)", "", "被 + [tác nhân] + 所 + [động từ] “Bị/được... bởi...”, cấu trúc bị động mang tính văn viết, nhấn mạnh hành động.", "而这一切都被她的平和、幽默所悄悄掩盖。"], ["在...之后 (zài... zhīhòu)", "", "在 + [sự việc] + 之后 “Sau khi...”, “sau...”.", "观众在被人物深深打动之后，会很自然地反思自己和亲人的关系..."], ["虽然...但/但是... (suīrán... dàn/dànshì...)", "", "虽然 + A + 但/但是 + B “Tuy... nhưng...”, biểu thị sự nhượng bộ.", "本片虽然是导演的处女作，从导演的表达方式来看，她没有许多年轻导演所常有的自我中心意识..."]], "adv": [], "ex2": [["这部电影讲的是什么故事？", "一位女作家在母亲生重病后与母亲相处的最后一段日子。", ["一位母亲去国外旅行。", "两个朋友一起创业。"]], ["为什么说表现母女的故事“既容易又困难”？", "容易引起共鸣，但分寸把握不好会适得其反。", ["因为演员太少。", "因为电影太长。"]], ["剧中的作家像一面镜子，让我们看到了什么？", "自己对父母的爱，也照见自己的自私。", ["自己的长相。", "别人的缺点。"]], ["剧中的母亲是一个什么样的人？", "坚强，总担心给女儿添麻烦，把自己的需求放在第二位。", ["非常自私。", "总是抱怨女儿。"]], ["导演想传达什么道理？", "亲情、友情是最珍贵的。", ["工作比家人更重要。", "钱是最重要的。"]]]}});
})(window.CONTENT);
